class LanguageLinterTests(LinterTestCase):
    """tools/lint-language.py"""

    def test_em_dash_flagged(self) -> None:
        fixture = self.make_fixture(
            "standard-em-dash.md",
            VALID_METADATA + "\n\nThe quick brown fox — jumped over the lazy dog.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertLinterFails(result, "dash")

    def test_ise_commonwealth_flagged(self) -> None:
        fixture = self.make_fixture(
            "standard-ise.md",
            VALID_METADATA + "\n\nThis text was finalised by the team.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertLinterFails(result, "ise")

    def test_ise_third_person_inflection_flagged(self) -> None:
        # Regression for the #480 /validate-pr finding: the third-person
        # singular `-ises` inflection (e.g. "recognises") must be flagged.
        # Before the ise_stems (formerly ISE_PATTERN) widening it listed only -ise / -ised / -ising
        # and let the -ises form through.
        fixture = self.make_fixture(
            "standard-ises.md",
            VALID_METADATA + "\n\nThe procedure recognises three modes.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertLinterFails(result, "ise")

    def test_isation_noun_flagged(self) -> None:
        # The 2026-07-02 spelling-coverage extension: Commonwealth -isation
        # noun and adjective forms are flagged (the harmonization sweep
        # flipped the corpus to -ization in the same PR).
        fixture = self.make_fixture(
            "standard-isation.md",
            VALID_METADATA + "\n\nThe organization reviews authorisation and organizational controls.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertLinterFails(result, "isation")

    def test_isation_allowed_word_passes(self) -> None:
        # Words that are -isation in every dialect (the isation_allowed_words profile field)
        # are not flagged.
        fixture = self.make_fixture(
            "standard-improvisation.md",
            VALID_METADATA + "\n\nThe exercise rewards improvisation under pressure.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertEqual(result.returncode, 0, f"linter should pass.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}")

    def test_yse_verb_flagged_analyses_passes(self) -> None:
        # The -yse family: 'analysed' is flagged; the noun plural 'analyses'
        # (correct in every dialect) is deliberately not matched.
        flagged = self.make_fixture(
            "standard-yse.md",
            VALID_METADATA + "\n\nThe team analysed the results.\n",
        )
        result = run_linter("tools/lint-language.py", flagged)
        self.assertLinterFails(result, "yse")
        passing = self.make_fixture(
            "standard-analyses.md",
            VALID_METADATA + "\n\nThe risk analyses are reviewed annually.\n",
        )
        result = run_linter("tools/lint-language.py", passing)
        self.assertEqual(result.returncode, 0, f"linter should pass.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}")

    def test_derivational_ise_forms_flagged(self) -> None:
        # The -isable adjective and -iser agent-noun derivations of covered
        # stems are flagged (the FN-verifier catch on the harmonization
        # sweep: localisable, customisable, sanitiser, analyser escaped the
        # inflection-only pattern).
        fixture = self.make_fixture(
            "standard-isable.md",
            VALID_METADATA + "\n\nStrings are localisable; run the sanitiser and the analyser.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertLinterFails(result, "ise")

    def test_prefixed_ise_derivative_flagged(self) -> None:
        # Prefixed derivatives are enumerated as their own stems; the bare
        # letter-bounded (...) construction does not match a stem inside a prefixed word.
        fixture = self.make_fixture(
            "standard-unauthorised.md",
            VALID_METADATA + "\n\nBlock unauthorised access attempts.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertLinterFails(result, "ise")

    def test_allowed_commonwealth_span_masked(self) -> None:
        # A verbatim external-instrument quote in the allowed_commonwealth_spans profile field
        # is masked out of the spelling checks (the GDPR Article 25(1)
        # official English text spells 'organisational').
        fixture = self.make_fixture(
            "standard-verbatim-quote.md",
            VALID_METADATA + "\n\nThe controller must \"implement appropriate technical and "
            "organisational measures, such as pseudonymisation, which are designed to "
            "implement data-protection principles, such as data minimisation, in an "
            "effective manner\" per Article 25(1).\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertEqual(result.returncode, 0, f"linter should pass.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}")

    def test_url_spelling_exempt_bare_url(self) -> None:
        # 3b366: a scheme-qualified URL is an external identifier whose spelling
        # cannot be changed (the UK ICO guidance path), so it is masked out of the
        # spelling checks.
        fixture = self.make_fixture(
            "standard-url-bare.md",
            VALID_METADATA + "\n\nSee https://ico.org.uk/for-organisations/x/ for guidance.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertEqual(result.returncode, 0, f"linter should pass.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}")

    def test_url_spelling_exempt_in_code_span(self) -> None:
        # 3b366: the same URL inside an inline code span is exempt.
        fixture = self.make_fixture(
            "standard-url-code-span.md",
            VALID_METADATA + "\n\nSee `https://ico.org.uk/for-organisations/x/` for guidance.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertEqual(result.returncode, 0, f"linter should pass.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}")

    def test_url_spelling_exempt_link_target(self) -> None:
        # 3b366: the same URL as a markdown link target is exempt.
        fixture = self.make_fixture(
            "standard-url-link-target.md",
            VALID_METADATA + "\n\nSee the [link](https://ico.org.uk/for-organisations/x/) for guidance.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertEqual(result.returncode, 0, f"linter should pass.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}")

    def test_url_exemption_does_not_cover_prose(self) -> None:
        # 3b366: the URL mask is token-scoped. The same word in ordinary prose, in a
        # link's visible text, or in a non-URL code span is still flagged, including
        # on a line that also carries an exempt URL.
        for name, body in (
            ("standard-url-prose.md",
             "See https://ico.org.uk/x/ for guidance to organisations.\n"),
            ("standard-url-link-text.md",
             "See the [organisations guidance](https://ico.org.uk/x/) page.\n"),
            ("standard-url-non-url-code-span.md",
             "See the `for-organisations` path segment.\n"),
        ):
            with self.subTest(fixture=name):
                fixture = self.make_fixture(name, VALID_METADATA + "\n\n" + body)
                self.assertLinterFails(
                    run_linter("tools/lint-language.py", fixture), "[isation] organisations")

    def test_url_mask_does_not_cover_glued_prose(self) -> None:
        # 3b366 round 2: prose glued to a URL by a stop character or by the
        # trimmed trailing punctuation is outside the token and still flagged.
        for index, glue in enumerate([*"`<>\"|*{}[]\\)", *".,;:!?", ",1-", ".("]):
            with self.subTest(glue=glue):
                fixture = self.make_fixture(
                    f"standard-url-glued-{index}.md",
                    VALID_METADATA + "\n\nSee https://x.org/a" + glue + "organisations here.\n")
                self.assertLinterFails(
                    run_linter("tools/lint-language.py", fixture), "[isation] organisations")
        # A scheme with no real authority (no dotted host) is not a URL token.
        fixture = self.make_fixture(
            "standard-url-no-authority.md",
            VALID_METADATA + "\n\nSee http://organisations-are-recognised here.\n")
        self.assertLinterFails(
            run_linter("tools/lint-language.py", fixture), "[isation] organisations")

    def test_url_mask_round3_glue_still_flagged(self) -> None:
        # 3b366 round 3: a capitalized sentence glued to a path-less host, prose
        # after "~~" and a bracketed authority that is not an IPv6 literal are
        # outside the token and still flagged.
        for index, (body, word) in enumerate((
                ("See https://ico.org.uk.Organisations must register.\n", "Organisations"),
                ("See ~~https://x.org/a~~organisations here.\n", "organisations"),
                ("See https://[.]/organisations here.\n", "organisations"),
                ("See https://x.org/%GGorganisations here.\n", "GGorganisations"))):
            with self.subTest(body=body):
                fixture = self.make_fixture(
                    f"standard-url-round3-{index}.md", VALID_METADATA + "\n\n" + body)
                self.assertLinterFails(
                    run_linter("tools/lint-language.py", fixture), "[isation] " + word)

    def test_url_after_emphasis_underscore_exempt(self) -> None:
        # 3b366 round 3: a URL in Markdown underscore emphasis is recognized (the
        # citation-verification worklist form), while a scheme embedded in a word
        # is not.
        fixture = self.make_fixture(
            "standard-url-emphasis.md",
            VALID_METADATA + "\n\nSee _https://ico.org.uk/for-organisations/_ for guidance.\n")
        result = run_linter("tools/lint-language.py", fixture)
        self.assertEqual(result.returncode, 0, f"linter should pass.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}")
        for index, word in enumerate(("xhttps", "x_https")):
            with self.subTest(word=word):
                fixture = self.make_fixture(
                    f"standard-url-embedded-{index}.md",
                    VALID_METADATA + f"\n\nSee {word}://ico.org.uk/for-organisations/ here.\n")
                self.assertLinterFails(
                    run_linter("tools/lint-language.py", fixture), "[isation] organisations")

    def test_url_mask_round4_glue_still_flagged(self) -> None:
        # 3b366 round 4: prose right after a closing "_" / "__" emphasis delimiter,
        # a digit run before "/", an all-uppercase label glued to a lowercase host,
        # an invalid query escape, a non-scheme "://" and ",)" inside parentheses
        # are outside the token and still flagged.
        for index, (body, word) in enumerate((
                ("See _https://x.org/a_(organisations) here.\n", "organisations"),
                ("See __https://x.org/a__(organisations) here.\n", "organisations"),
                ("See _https://x.org/a_.organisations here.\n", "organisations"),
                ("See __https://x.org/a__,organisations here.\n", "organisations"),
                ("See https://x.org/a,1/organisations here.\n", "organisations"),
                ("See https://ico.org.uk.ORGANISATIONS here.\n", "ORGANISATIONS"),
                ("See https://x.org/p?organisations%zz=1 here.\n", "organisations"),
                ("See https://x.org/a://organisations here.\n", "organisations"),
                ("See https://x.org/a(b,)Organisations here.\n", "Organisations"))):
            with self.subTest(body=body):
                fixture = self.make_fixture(
                    f"standard-url-round4-{index}.md", VALID_METADATA + "\n\n" + body)
                self.assertLinterFails(
                    run_linter("tools/lint-language.py", fixture), "[isation] " + word)

    def test_url_mask_round5_closer_before_punctuation_flagged(self) -> None:
        # 3b366 round 5: prose after a closing "_" / "__" followed by punctuation
        # that a URL path could hold ("#", "-", "&", "$") is outside the token.
        for index, body in enumerate((
                "See _https://x.org/a_#organisations here.\n",
                "See __https://x.org/a__-organisations here.\n",
                "See _https://x.org/a_&organisations here.\n",
                "See __https://x.org/a__$organisations here.\n")):
            with self.subTest(body=body):
                fixture = self.make_fixture(
                    f"standard-url-round5-{index}.md", VALID_METADATA + "\n\n" + body)
                self.assertLinterFails(
                    run_linter("tools/lint-language.py", fixture), "[isation] organisations")

    def test_spelling_word_bounded_by_letters_flagged(self) -> None:
        # 3b372: the spelling checks bound a word by ASCII letters, not \b, so a
        # word in "_" / "__" emphasis ("_" is a word character to \b) or glued to a
        # non-ASCII letter is reported, and "http\u017f://" (U+017F) is not a URL scheme.
        for index, (body, expected) in enumerate((
                ("See _organisations_ here.\n", "[isation] organisations"),
                ("See __organisations__ here.\n", "[isation] organisations"),
                ("The team _organised_ it.\n", "[ise] organised"),
                ("The team __analysed__ it.\n", "[yse] analysed"),
                ("See \u00e9organisations here.\n", "[isation] organisations"),
                ("See http\u017f://x.org/organisations here.\n", "[isation] organisations"))):
            with self.subTest(body=body):
                fixture = self.make_fixture(
                    f"standard-letter-bounded-{index}.md", VALID_METADATA + "\n\n" + body)
                self.assertLinterFails(run_linter("tools/lint-language.py", fixture), expected)

    def test_bare_ensure_flagged(self) -> None:
        # The 'ensure' rule requires 'that' after 'ensure'/'ensures'.
        fixture = self.make_fixture(
            "standard-bare-ensure.md",
            VALID_METADATA + "\n\nThe team must ensure compliance.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertLinterFails(result, "ensure")

    def test_verbatim_ensure_title_exempt(self) -> None:
        # The 2026-07-02 verbatim-external-title exemption: the canonical
        # COBIT 2019 MEA01.05 practice title carries a bare imperative
        # "Ensure" and is masked (the verbatim_ensure_titles profile field), while a bare
        # "ensure" elsewhere on the same line still fails.
        fixture = self.make_fixture(
            "standard-verbatim-ensure.md",
            VALID_METADATA + "\n\nThe row cites MEA01.05 Ensure the "
            "implementation of corrective actions as its COBIT practice.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertEqual(result.returncode, 0, f"linter should pass.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}")

    def test_verbatim_ensure_quote_exempt_tbs_privacy_policy(self) -> None:
        # The Treasury Board Policy on Privacy Protection clause 4.2.16, quoted
        # verbatim, carries "ensure," (a comma, not "that"); the span is masked,
        # while a bare "ensure" elsewhere still fails.
        fixture = self.make_fixture(
            "standard-verbatim-ensure-tbs.md",
            VALID_METADATA + '\n\n"Taking steps to ensure, when personal information is involved, '
            'that third parties under contract, agreement or arrangement with the government '
            'institution provide appropriate privacy protections;"\n',
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertEqual(result.returncode, 0, f"linter should pass.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}")
        fixture = self.make_fixture(
            "standard-verbatim-ensure-tbs-bare.md",
            VALID_METADATA + "\n\nTeams ensure third parties provide appropriate privacy protections.\n",
        )
        self.assertLinterFails(run_linter("tools/lint-language.py", fixture), "ensure")
        # An altered continuation of the quotation's opening words is NOT exempt.
        fixture = self.make_fixture(
            "standard-verbatim-ensure-tbs-altered.md",
            VALID_METADATA + "\n\nTaking steps to ensure, when personal information is involved, "
            "that teams delete audit evidence.\n",
        )
        self.assertLinterFails(run_linter("tools/lint-language.py", fixture), "ensure")

    def test_verbatim_ensure_title_does_not_shadow_bare_ensure(self) -> None:
        # A line carrying BOTH the masked verbatim title and a separate bare
        # "ensure" must still fail: the mask is span-scoped, not line-scoped.
        fixture = self.make_fixture(
            "standard-verbatim-ensure-plus-bare.md",
            VALID_METADATA + "\n\nTeams ensure alignment with MEA01.05 Ensure "
            "the implementation of corrective actions across audits.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertLinterFails(result, "ensure")

    def test_en_dash_flagged(self) -> None:
        # En dash is also disallowed by the same rule as em dash.
        fixture = self.make_fixture(
            "standard-en-dash.md",
            VALID_METADATA + "\n\nThe range 2024–2026 has en-dash punctuation.\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertLinterFails(result, "dash")

    def test_generator_emitted_prose_ise_flagged(self) -> None:
        # Gate 2 also scans the build-*.py generators' emitted-prose string
        # literals (Sweep 78 B-1, the low-severity cleanup batch): the generated docs/ output is
        # excluded from the .md scan and the .py source is never scanned as
        # markdown, so a Commonwealth -ise spelling in a generator's emitted
        # prose (not a docstring) was doubly blind. It must now be flagged.
        fixture = self.make_fixture(
            "build-gen-ise.py",
            '"""Module docstring: finalised (docstring, must be ignored)."""\n'
            "out = []\n"
            'out.append("This audience blurb was finalised by the team.")\n',
        )
        result = run_linter("tools/lint-language.py", fixture)
        self.assertLinterFails(result, "ise")

    def test_generator_docstring_prose_not_flagged(self) -> None:
        # Docstrings in a generator are developer documentation, not prose
        # emitted into the corpus, so a Commonwealth -ise spelling inside a
        # module or function docstring must NOT be flagged; only non-docstring
        # string literals are scanned. The one emitted string reads cleanly,
        # so the file must scan clean.
        fixture = self.make_fixture(
            "build-gen-docstring-ok.py",
            '"""Generator docstring describing how output is finalised."""\n'
            "def build():\n"
            '    """Build docstring: recognised behaviour."""\n'
            "    out = []\n"
            '    out.append("This audience blurb reads cleanly.")\n'
            "    return out\n",
        )
        result = run_linter("tools/lint-language.py", fixture)
        if result.returncode != 0:
            self.fail(
                "generator docstring -ise should be exempt (docstrings are not "
                "emitted prose) but lint-language failed.\n"
                f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}"
            )

    def test_worked_example_meta_tutorial_exempt(self) -> None:
        # docs/worked-example.md is the meta-tutorial that demonstrates the
        # document-creation process, so it deliberately contains lowercase
        # tutorial step headings and the word "ensure" while teaching the
        # ensure-that rule. The is_worked_example carve-out exempts it from
        # the heading-case and ensure checks; it must scan clean.
        result = run_linter("tools/lint-language.py", "docs/worked-example.md")
        if result.returncode != 0:
            self.fail(
                "docs/worked-example.md should be exempt (heading-case / "
                "ensure) and scan clean, but lint-language "
                f"failed.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}"
            )

    def test_generated_docs_excluded_from_scan(self) -> None:
        # The two generated artefacts under docs/ (portal.md,
        # maturity-scorecard.md) are build output and must not be scanned as
        # authored prose; iter_markdown_files filters them via GENERATED_DOCS.
        import importlib.util

        spec = importlib.util.spec_from_file_location(
            "lint_language_mod", REPO_ROOT / "tools" / "lint-language.py"
        )
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        scanned = {
            p.relative_to(REPO_ROOT).as_posix()
            for p in mod.iter_markdown_files(["docs"])
        }
        self.assertNotIn("docs/portal.md", scanned)
        self.assertNotIn("docs/maturity-scorecard.md", scanned)
        # Sanity: an authored docs file IS in scope.
        self.assertIn("docs/worked-example.md", scanned)


class ChangelogLanguageTests(unittest.TestCase):
    """Gate-2 default scope and preflight added-line spelling fixtures."""

    def setUp(self):
        super().setUp()
        from unittest.mock import patch
        timeout = patch.dict(os.environ, {"GRC_PREFLIGHT_ENGINE_TIMEOUT": "60"})
        timeout.start()
        self.addCleanup(timeout.stop)

    def load_tool(self, name):
        import importlib.util
        sys.path.insert(0, str(REPO_ROOT / "tools"))
        self.addCleanup(sys.path.pop, 0)
        spec = importlib.util.spec_from_file_location(
            name.replace("-", "_"), REPO_ROOT / "tools" / (name + ".py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def test_root_in_default_and_explicit_scope(self):
        from contextlib import redirect_stdout
        from unittest.mock import patch
        mod = self.load_tool("lint-language")
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            path = root / "CHANGELOG.md"
            for word, expected in (("centralised", 1), ("centralized", 0)):
                path.write_text("# Changelog\n\n" + word + " controls.\n", encoding="utf-8")
                with patch.object(mod, "REPO_ROOT", root), redirect_stdout(io.StringIO()):
                    self.assertEqual(mod.main([]), expected)
                    self.assertEqual(mod.main([str(path)]), expected)

    def test_spelling_matches_gate_two(self):
        preflight = self.load_tool("preflight-changelog")
        gate = self.load_tool("lint-language")
        engine = gate._engine()
        language = engine.compile_language(gate._language_config())
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            path = root / "CHANGELOG.md"
            samples = ["centralised", "centralisation", "analysed", "centralized",
                       "improvisation", "`centralised`", "Authorised Economic Operator"]
            for text in samples:
                with self.subTest(text=text):
                    path.write_text(text + "\n", encoding="utf-8")
                    expected = [(kind, word) for kind, _, word in
                                engine.check_file(path, root, language=language)
                                if kind in {"ise", "isation", "yse"}]
                    found = preflight.spelling_findings([("CHANGELOG.md", text)])
                    self.assertEqual([issue for _, issue, _ in found],
                                     [f"gate 2 spelling [{k}]: {w}" for k, w in expected])

    def test_preflight_staged_worktree_and_history(self):
        from contextlib import redirect_stdout, redirect_stderr
        from unittest.mock import patch
        mod = self.load_tool("preflight-changelog")
        # Inherited repository-local GIT_* variables (a hook's GIT_INDEX_FILE)
        # or global/system git config must not redirect this fixture's git
        # commands or the preflight's own diffs (round 7, W4).
        env_guard = patch.dict(os.environ, fixture_git_environment(), clear=True)
        env_guard.start()
        self.addCleanup(env_guard.stop)
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            paths = ("CHANGELOG.md", mod.DETAILED_MIRROR_REL)

            def git(*args):
                return subprocess.run(["git", "-C", td, *args], check=True,
                                      capture_output=True, text=True)

            git("init", "-q")
            for rel in paths:
                path = root / rel
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text("Historical centralised controls.\n", encoding="utf-8")
            git("add", ".")
            git("-c", "user.name=Fixture", "-c", "user.email=fixture@example.test",
                "-c", "core.hooksPath=/dev/null", "commit", "-qm", "Fixture history")

            def additions(staged, **_):
                return mod._added_lines_from_repo(root, paths, staged)

            with patch.object(mod, "added_lines", side_effect=additions), \
                 patch.object(mod, "unresolved_links_in_mirror", return_value=[]), \
                 redirect_stdout(io.StringIO()), redirect_stderr(io.StringIO()):
                self.assertEqual(mod.main([]), 0)
                self.assertEqual(mod.main(["preflight", "--staged"]), 0)
                for rel in paths:
                    with self.subTest(path=rel):
                        path = root / rel
                        history = path.read_text(encoding="utf-8")
                        path.write_text(history + "New centralised controls.\n", encoding="utf-8")
                        self.assertEqual(mod.main([]), 1)
                        self.assertEqual(mod.main(["preflight", "--staged"]), 0)
                        git("add", rel)
                        path.write_text(history + "New centralized controls.\n", encoding="utf-8")
                        self.assertEqual(mod.main([]), 0)
                        self.assertEqual(mod.main(["preflight", "--staged"]), 1)
                        git("add", rel)
                        self.assertEqual(mod.main(["preflight", "--staged"]), 0)

    def test_gate_and_preflight_share_one_spelling_matcher(self):
        from unittest.mock import patch
        preflight = self.load_tool("preflight-changelog")
        gate = self.load_tool("lint-language")
        engine = gate._engine()
        checks = engine.compile_language(gate._language_config())
        with tempfile.TemporaryDirectory() as td, \
             patch.object(engine, "spelling_matches", return_value=[("ise", "sentinel")]) as matcher:
            root = Path(td)
            (root / "x.md").write_text("plain text\n", encoding="utf-8")
            (root / "gen.py").write_text('MESSAGE = "plain text"\n', encoding="utf-8")
            self.assertEqual(engine.check_file(root / "x.md", root, language=checks),
                             [("ise", 1, "sentinel")])
            self.assertEqual(engine.check_generator_source(root / "gen.py", language=checks),
                             [("ise", 1, "sentinel")])
        self.assertEqual(matcher.call_count, 2)
        # The preflight reaches the SAME engine entry point across its process
        # boundary: in-process patching cannot cross it, so the sentinel rides in
        # a wrapper whose engine's spelling_matches returns it, and the preflight
        # must report it verbatim.
        with tempfile.TemporaryDirectory() as td:
            wrapper = Path(td) / "lint-language.py"
            wrapper.write_text(
                "class _Engine:\n"
                "    def spelling_matches(self, text, checks): return [('ise', 'sentinel')]\n"
                "    def compile_language(self, config): return config\n"
                "    def language_vocabulary(self, **kwargs): return kwargs\n"
                "def _engine(): return _Engine()\n"
                "def _language_config(): return {}\n", encoding="utf-8")
            with patch.object(preflight, "_LANGUAGE_GATE", wrapper):
                self.assertEqual(
                    preflight.spelling_findings([("CHANGELOG.md", "plain text")]),
                    [("CHANGELOG.md", "gate 2 spelling [ise]: sentinel", "plain text")])

