class VersionBumpRecencyTests(LinterTestCase):
    """tools/lint-version-bump-recency.py"""

    def test_runs_clean_on_corpus_at_head(self) -> None:
        # Smoke test: the linter is a git-history-aware corpus check;
        # the first regression-level assertion is that it runs clean on
        # the current HEAD.
        result = run_linter("tools/lint-version-bump-recency.py")
        self.assertEqual(
            result.returncode,
            0,
            f"linter exited {result.returncode} on the corpus HEAD; "
            f"all versioned documents should pass.\n"
            f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}",
        )

    def test_stale_version_after_body_change_flagged(self) -> None:
        # Real failure-detection test (closing the gate-36 discipline
        # gap for this git-history-aware gate). Build a synthetic git
        # repo with two commits: first creates a versioned doc at
        # Version 1.0.0; second modifies the body without bumping
        # Version. Assert the linter fires.
        import shutil
        import subprocess as sp
        import tempfile

        tmp = Path(tempfile.mkdtemp(prefix="lint-recency-test-"))
        try:
            sp.run(["git", "init", "-q", "-b", "main", str(tmp)], check=True)
            sp.run(["git", "-C", str(tmp), "config", "user.email", "test@test"], check=True)
            sp.run(["git", "-C", str(tmp), "config", "user.name", "Test"], check=True)

            # The linter requires a §6 inventory in
            # governance/specification-audit-programme.md to derive the
            # canonical gate count. Provide a minimal stub.
            spec_dir = tmp / "governance"
            spec_dir.mkdir()
            (spec_dir / "specification-audit-programme.md").write_text(
                "# Stub\n\n## 6. Gate inventory (current)\n\n| # | Gate | Script |\n| - | - | - |\n| 1 | Stub | `tools/stub.py` |\n",
                encoding="utf-8",
            )

            target = tmp / "doc.md"
            target.write_text(
                "# Test Doc\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\n## Body\n\nOriginal body content.\n",
                encoding="utf-8",
            )
            sp.run(["git", "-C", str(tmp), "add", "-A"], check=True)
            sp.run(["git", "-C", str(tmp), "commit", "-q", "-m", "Initial"], check=True)

            target.write_text(
                "# Test Doc\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\n## Body\n\nModified body content.\n",
                encoding="utf-8",
            )
            sp.run(["git", "-C", str(tmp), "add", "-A"], check=True)
            sp.run(["git", "-C", str(tmp), "commit", "-q", "-m", "Modify body without Version bump"], check=True)

            result = sp.run(
                [sys.executable, str(REPO_ROOT / "tools/lint-version-bump-recency.py"), "--root", str(tmp)],
                capture_output=True, text=True, cwd=str(tmp),
            )
            self.assertEqual(
                result.returncode,
                1,
                f"linter should have FAILED on synthetic body-without-Version-bump fixture; got exit {result.returncode}.\n"
                f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}",
            )
            self.assertIn(
                "doc.md",
                result.stdout,
                f"expected doc.md in failure output but did not find it.\nstdout:\n{result.stdout}",
            )
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def _recency_bom_repo(self, commits: list[dict[str, str]]) -> Path:
        """A throwaway git repo with one commit per mapping of relative path to text (3b89)."""
        import shutil
        import subprocess as sp
        import tempfile

        tmp = Path(tempfile.mkdtemp(prefix="lint-recency-bom-"))
        self.addCleanup(shutil.rmtree, tmp, True)
        sp.run(["git", "init", "-q", "-b", "main", str(tmp)], check=True)
        sp.run(["git", "-C", str(tmp), "config", "user.email", "test@test"], check=True)
        sp.run(["git", "-C", str(tmp), "config", "user.name", "Test"], check=True)
        for n, files in enumerate(commits):
            for rel, text in files.items():
                # 3b89 round 2: fixtures now sit under .claude/, references/, node_modules/.
                (tmp / rel).parent.mkdir(parents=True, exist_ok=True)
                (tmp / rel).write_text(text, encoding="utf-8")
            sp.run(["git", "-C", str(tmp), "add", "-A"], check=True)
            sp.run(["git", "-C", str(tmp), "commit", "-q", "-m", f"commit {n}"], check=True)
        return tmp

    def _run_recency_bom(self, root: Path, *paths: str):
        import subprocess as sp

        return sp.run(
            [sys.executable, str(REPO_ROOT / "tools/lint-version-bump-recency.py"),
             "--root", str(root), *paths],
            capture_output=True, text=True, cwd=str(root),
        )

    def test_bom_prefixed_version_on_line_1_refused_not_skipped(self) -> None:
        # P-TODO 3b89: a UTF-8 BOM before a line-1 **Version:** made head_version return None,
        # so the document left scope silently and a body change without a bump passed (exit 0).
        bom = "\ufeff"
        meta = "**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\n# Doc\n\n"
        root = self._recency_bom_repo([
            {
                "doc.md": bom + meta + "Original body.\n",
                "clean.md": "# Clean\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\nBody.\n",
            },
            {"doc.md": bom + meta + "Modified body without a Version bump.\n"},
        ])
        result = self._run_recency_bom(root)
        self.assertEqual(result.returncode, 1, result.stdout + result.stderr)
        fails = [line for line in result.stdout.splitlines() if line.startswith("FAIL ")]
        self.assertEqual(len(fails), 1, result.stdout)
        self.assertTrue(fails[0].startswith("FAIL doc.md: "), fails)
        self.assertIn("byte-order mark", fails[0])
        self.assertIn("1 markdown file(s) begin with a UTF-8 byte-order mark", result.stderr)

    def test_bom_refusal_covers_exempt_and_unversioned_files_but_not_mid_text_feff(self) -> None:
        # 3b89: the refusal precedes the recency exemptions and the Version filter (a BOM hides
        # the Version itself), applies to explicit paths too, and only a LEADING U+FEFF is a BOM.
        bom = "\ufeff"
        root = self._recency_bom_repo([{
            "CHANGELOG.md": bom + "# Changelog\n",
            "notes.md": bom + "# Notes\n\nNo metadata here.\n",
            "mid.md": "# Mid\n\n**Version:** 1.0.0\\\n\nA zero-width" + bom + "no-break space.\n",
        }])
        walk = self._run_recency_bom(root)
        self.assertEqual(walk.returncode, 1, walk.stdout + walk.stderr)
        refused = sorted(
            line.split(":", 1)[0] for line in walk.stdout.splitlines() if line.startswith("FAIL ")
        )
        self.assertEqual(refused, ["FAIL CHANGELOG.md", "FAIL notes.md"], walk.stdout)
        explicit = self._run_recency_bom(root, str(root / "notes.md"))
        self.assertEqual(explicit.returncode, 1, explicit.stdout + explicit.stderr)
        self.assertIn("FAIL notes.md: ", explicit.stdout)
        mid = self._run_recency_bom(root, str(root / "mid.md"))
        self.assertEqual(mid.returncode, 0, mid.stdout + mid.stderr)
        self.assertIn("OK: 1 versioned document(s) scanned", mid.stdout)

    def test_bom_refusal_covers_recency_exempt_directories(self) -> None:
        # 3b89 round 2 (r1 codex F1 / claude F1): the walk applied the recency-only
        # DEFAULT_EXEMPT_DIRS skip before the BOM check, so a BOM file under .claude/ or
        # references/, trees the push-time checks D2 and D4 DO read, was never refused.
        # Round 3 (r2 codex F2 / claude F1): the BOM scope covers the D2/D4 markdown scope
        # and is a superset of it. It applies only the directory exclusions those gates
        # share (.corpus-management/, .git/, node_modules/, __pycache__/, each at the
        # repository root), not their per-file EXEMPT_FILES, so a BOM CHANGELOG.md is
        # refused too (test_bom_refusal_covers_exempt_and_unversioned_files_...).
        bom = "\ufeff"
        root = self._recency_bom_repo([{
            ".claude/skills/x/SKILL.md": bom + "**Version:** 1.0.0\\\n\n# Skill\n\nBody.\n",
            "references/ops.md": bom + "# Ops\n\nNo metadata here.\n",
            "node_modules/pkg/README.md": bom + "# Pkg\n",
            "clean.md": "# Clean\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\nBody.\n",
        }])
        walk = self._run_recency_bom(root)
        self.assertEqual(walk.returncode, 1, walk.stdout + walk.stderr)
        refused = sorted(
            line.split(":", 1)[0] for line in walk.stdout.splitlines() if line.startswith("FAIL ")
        )
        self.assertEqual(
            refused, ["FAIL .claude/skills/x/SKILL.md", "FAIL references/ops.md"], walk.stdout,
        )
        self.assertIn("2 markdown file(s) begin with a UTF-8 byte-order mark", walk.stderr)

    def test_bom_walk_and_explicit_path_modes_agree(self) -> None:
        # 3b89 round 2: quick-guard.sh passes changed files explicitly while CI walks, so
        # both modes classify through the same function and must give any path the same
        # verdict: a BOM file under a recency-exempt tree is refused in both, one under a
        # shared D2/D4 exclusion is out of scope in both, and a non-BOM file under a
        # recency-exempt tree is a recency target in neither (its stale body is not a
        # finding on either surface).
        bom = "\ufeff"
        meta = "**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\n# Doc\n\n"
        root = self._recency_bom_repo([
            {
                ".claude/CLAUDE.md": bom + "# Config\n",
                "node_modules/pkg/README.md": bom + "# Pkg\n",
                "references/versioned.md": meta + "Original body.\n",
            },
            {"references/versioned.md": meta + "Modified body without a Version bump.\n"},
        ])
        walk = self._run_recency_bom(root)
        explicit = self._run_recency_bom(
            root,
            str(root / ".claude/CLAUDE.md"),
            str(root / "node_modules/pkg/README.md"),
            str(root / "references/versioned.md"),
        )
        for mode, result in (("walk", walk), ("explicit", explicit)):
            self.assertEqual(result.returncode, 1, mode + ": " + result.stdout + result.stderr)
            fails = [line.split(":", 1)[0] for line in result.stdout.splitlines()
                     if line.startswith("FAIL ")]
            self.assertEqual(fails, ["FAIL .claude/CLAUDE.md"], mode + ": " + result.stdout)
            self.assertIn(
                "1 markdown file(s) begin with a UTF-8 byte-order mark", result.stderr, mode,
            )

    def test_bom_symlink_gets_the_same_verdict_in_both_modes(self) -> None:
        # 3b89 round 3 (r2 codex F1): explicit mode resolved a symlink before classifying
        # it while the walk classified the link's own path, so a BOM link.md pointing into
        # node_modules/ failed the walk (exit 1) and passed an explicit run (exit 0). Both
        # modes now take the stricter reading: a link is refused when EITHER its own path
        # or its target lies in the BOM scope, and is reported under its own name. The
        # links are left untracked: the BOM check reads the filesystem, not the index.
        bom = "\ufeff"
        root = self._recency_bom_repo([{
            "node_modules/pkg/payload.md": bom + "# Payload\n",
            "target.md": bom + "# Target\n",
            "clean.md": "# Clean\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\nBody.\n",
        }])
        (root / "link.md").symlink_to("node_modules/pkg/payload.md")
        (root / "node_modules/back.md").symlink_to("../target.md")
        walk = self._run_recency_bom(root)
        explicit = self._run_recency_bom(root, *(
            str(root / rel) for rel in
            ("link.md", "node_modules/back.md", "target.md", "node_modules/pkg/payload.md")
        ))
        for mode, result in (("walk", walk), ("explicit", explicit)):
            self.assertEqual(result.returncode, 1, mode + ": " + result.stdout + result.stderr)
            fails = sorted(line.split(":", 1)[0] for line in result.stdout.splitlines()
                           if line.startswith("FAIL "))
            self.assertEqual(
                fails, ["FAIL link.md", "FAIL node_modules/back.md", "FAIL target.md"],
                mode + ": " + result.stdout,
            )
            self.assertIn(
                "3 markdown file(s) begin with a UTF-8 byte-order mark", result.stderr, mode,
            )
        # The link alone, given relative to the cwd as quick-guard.sh passes a changed file:
        # refused under its own name, where it used to pass.
        alone = self._run_recency_bom(root, "link.md")
        self.assertEqual(alone.returncode, 1, alone.stdout + alone.stderr)
        self.assertIn("FAIL link.md: ", alone.stdout)

    def test_bom_scope_exclusions_are_root_anchored_in_both_modes(self) -> None:
        # 3b89 round 3 (r2 claude F2): the shared D2/D4 directory exclusions are anchored
        # at the repository root, as the gates' path.startswith(prefix) is. A pin, not a
        # fix: the pre-round-3 code anchored them the same way, so this test passes
        # before and after round 3 and exists to catch a future de-anchoring (r3 claude
        # N3). D2 and D4 read a nested docs/node_modules/ file, so a BOM file there is
        # refused in both modes; a BOM file under the root .corpus-management/ is out of
        # scope in both modes.
        bom = "\ufeff"
        root = self._recency_bom_repo([{
            "docs/node_modules/x.md": bom + "# Nested\n",
            ".corpus-management/x.md": bom + "# Store\n",
        }])
        walk = self._run_recency_bom(root)
        explicit = self._run_recency_bom(
            root, str(root / "docs/node_modules/x.md"), str(root / ".corpus-management/x.md"),
        )
        for mode, result in (("walk", walk), ("explicit", explicit)):
            self.assertEqual(result.returncode, 1, mode + ": " + result.stdout + result.stderr)
            fails = [line.split(":", 1)[0] for line in result.stdout.splitlines()
                     if line.startswith("FAIL ")]
            self.assertEqual(fails, ["FAIL docs/node_modules/x.md"], mode + ": " + result.stdout)
            self.assertIn(
                "1 markdown file(s) begin with a UTF-8 byte-order mark", result.stderr, mode,
            )

    def test_dangling_symlink_walk_skips_but_explicit_mode_refuses(self) -> None:
        # 3b89 round 3 (r3 claude N2 / codex F1): a pinned, documented divergence, not a
        # fix. The walk's classify_markdown skips a dangling link (is_file is False), so
        # a tree holding one still walks clean; explicit mode never reaches
        # classification, because guard_explicit_paths_cwd refuses the missing resolved
        # target with exit 2. The guard's refusal predates round 3 and fails closed, so
        # it stays; this test passes before and after round 3 and pins both sides.
        root = self._recency_bom_repo([{
            "clean.md": "# Clean\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\nBody.\n",
        }])
        (root / "l_dang.md").symlink_to("nope.md")
        walk = self._run_recency_bom(root)
        self.assertEqual(walk.returncode, 0, walk.stdout + walk.stderr)
        self.assertIn("OK: 1 versioned document(s) scanned", walk.stdout)
        explicit = self._run_recency_bom(root, "l_dang.md")
        self.assertEqual(explicit.returncode, 2, explicit.stdout + explicit.stderr)
        self.assertIn("does not exist", explicit.stderr)
        self.assertNotIn("FAIL", explicit.stdout)

    def test_link_to_bom_file_outside_root_walk_fails_explicit_mode_refuses(self) -> None:
        # 3b89 round 3 (r3 claude N2 / codex F1): the other divergent symlink class,
        # pinned, not fixed. An in-root link to a BOM file OUTSIDE --root is in the BOM
        # scope under its own name, so the walk refuses it (FAIL l_out.md, exit 1);
        # explicit mode exits 2 first, guard_explicit_paths_cwd refusing the resolved
        # outside target. Both verdicts are refusals; explicit mode's is the stricter,
        # fail-closed one, and it predates round 3 and stays.
        import shutil
        import tempfile

        bom = "\ufeff"
        root = self._recency_bom_repo([{
            "clean.md": "# Clean\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\nBody.\n",
        }])
        outside = Path(tempfile.mkdtemp(prefix="lint-recency-bom-outside-"))
        self.addCleanup(shutil.rmtree, outside, True)
        (outside / "ext.md").write_text(bom + "# Outside\n", encoding="utf-8")
        (root / "l_out.md").symlink_to(outside / "ext.md")
        walk = self._run_recency_bom(root)
        self.assertEqual(walk.returncode, 1, walk.stdout + walk.stderr)
        fails = [line.split(":", 1)[0] for line in walk.stdout.splitlines()
                 if line.startswith("FAIL ")]
        self.assertEqual(fails, ["FAIL l_out.md"], walk.stdout)
        self.assertIn("1 markdown file(s) begin with a UTF-8 byte-order mark", walk.stderr)
        explicit = self._run_recency_bom(root, "l_out.md")
        self.assertEqual(explicit.returncode, 2, explicit.stdout + explicit.stderr)
        self.assertIn("outside this linter's tree", explicit.stderr)
        self.assertNotIn("FAIL", explicit.stdout)

    def test_explicit_symlink_is_recency_queried_under_its_own_name(self) -> None:
        # 3b89 round 3 (r3 claude N1): classifying an explicit symlink as named also
        # changes which recency history it queries. Pre-round-3 explicit mode resolved
        # the link first, so a link argument to a stale versioned document reported
        # FAIL under the TARGET's name (exit 1 here). Now the link is recency-queried
        # under its own name, exactly as the walk queries it: the untracked link
        # docs/l_v2.md has no history of its own and is skipped, and .claude/l_v.md is
        # skipped by the recency-exempt parts check on its own spelling, so the
        # explicit run exits 0. The stale target itself is still caught whenever it is
        # walked or named directly. Fails on the pre-round-3 code (exit 1, not 0).
        meta = "**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\n# Doc\n\n"
        root = self._recency_bom_repo([
            {"docs/v.md": meta + "Original body.\n"},
            {"docs/v.md": meta + "Modified body without a Version bump.\n"},
        ])
        (root / "docs/l_v2.md").symlink_to("v.md")
        (root / ".claude").mkdir()
        (root / ".claude/l_v.md").symlink_to("../docs/v.md")
        explicit = self._run_recency_bom(root, "docs/l_v2.md", ".claude/l_v.md")
        self.assertEqual(explicit.returncode, 0, explicit.stdout + explicit.stderr)
        self.assertNotIn("FAIL", explicit.stdout)
        self.assertIn("OK: 1 versioned document(s) scanned", explicit.stdout)
        direct = self._run_recency_bom(root, "docs/v.md")
        self.assertEqual(direct.returncode, 1, direct.stdout + direct.stderr)
        self.assertIn("FAIL docs/v.md: ", direct.stdout)
        walk = self._run_recency_bom(root)
        self.assertEqual(walk.returncode, 1, walk.stdout + walk.stderr)
        # The walk's COMPLETE failure set, exactly (3b89 round 5, r4 codex F3): a walk
        # that resolved the links before querying would report the stale target's
        # history under docs/l_v2.md too, and an assertIn would still pass.
        walk_fails = [line.split(":", 1)[0] for line in walk.stdout.splitlines()
                      if line.startswith("FAIL ")]
        self.assertEqual(walk_fails, ["FAIL docs/v.md"], walk.stdout)

    def test_symlink_loop_is_a_finding_never_a_crash_or_skip(self) -> None:
        # 3b89 round 5 (r4 gemini): node_modules/loop.md -> loop.md is out of the BOM
        # scope by its own path, so classify_markdown resolved it; non-strict resolve()
        # raises on a loop through Python 3.12 (CI runs 3.11), crashing the walk, and
        # on 3.13+ returns the loop unresolved, where is_file() is False and the walk
        # skipped it silently. The gate now detects a loop by its stat errno (ELOOP,
        # version-independent) and refuses it as a finding: never a crash, never a skip.
        root = self._recency_bom_repo([{
            "clean.md": "# Clean\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\nBody.\n",
        }])
        (root / "node_modules").mkdir()
        (root / "node_modules/loop.md").symlink_to("loop.md")
        (root / "l_loop.md").symlink_to("node_modules/loop.md")
        walk = self._run_recency_bom(root)
        self.assertEqual(walk.returncode, 1, walk.stdout + walk.stderr)
        self.assertNotIn("Traceback", walk.stderr)
        fails = sorted(line.split(":", 1)[0] for line in walk.stdout.splitlines()
                       if line.startswith("FAIL "))
        self.assertEqual(fails, ["FAIL l_loop.md", "FAIL node_modules/loop.md"], walk.stdout)
        self.assertIn("2 markdown path(s) are symlink loops", walk.stderr)
        # An explicit loop argument never reaches classification: the guard cannot
        # resolve it to an existing path inside --root and the run exits 2 (fail
        # closed; the message is version-dependent, so only the channel is pinned).
        explicit = self._run_recency_bom(root, "node_modules/loop.md")
        self.assertEqual(explicit.returncode, 2, explicit.stdout + explicit.stderr)
        self.assertNotIn("FAIL", explicit.stdout)
        self.assertNotIn("Traceback", explicit.stderr)

    @unittest.skipIf(os.geteuid() == 0, "root ignores directory permission bits")

    @unittest.skipIf(os.geteuid() == 0, "root ignores directory permission bits")
    def test_unreadable_directory_fails_the_walk_closed(self) -> None:
        # 3b89 round 5 (r4 gemini): Path.rglob suppresses the traversal error on an
        # existing-but-unlistable directory, so a BOM file inside one passed unseen
        # (fail open; main behaved the same). The walk now uses os.walk with a raising
        # onerror, the guardrails tools/_walk.py pattern, and exits 2 naming the
        # directory instead of reporting OK over a subtree it never read. Round 6:
        # the message says "path", not "directory" (r5 claude F2: the same handler
        # fires for an unreadable regular file, so the old wording called a file a
        # directory).
        root = self._recency_bom_repo([{
            "clean.md": "# Clean\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\nBody.\n",
            "docs/hidden/doc.md": "\ufeff# Hidden\n",
        }])
        (root / "docs/hidden").chmod(0o000)
        self.addCleanup((root / "docs/hidden").chmod, 0o755)
        walk = self._run_recency_bom(root)
        self.assertEqual(walk.returncode, 2, walk.stdout + walk.stderr)
        self.assertIn("cannot read a path", walk.stderr)
        self.assertIn("docs/hidden", walk.stderr)
        self.assertNotIn("OK:", walk.stdout)

    @unittest.skipIf(os.geteuid() == 0, "root ignores directory permission bits")
    def test_unsearchable_directory_child_fails_closed_in_both_modes(self) -> None:
        # 3b89 round 6 (r5 claude F1 / codex F1): a directory with read but not
        # execute permission (mode 0444) is listable, so os.walk's raising onerror
        # never fires; stat on each child then fails with EACCES, which is_file()
        # swallowed, so a BOM file inside classified as a skip and the walk
        # reported OK over it (fail open). classify_markdown's fail-closed stat
        # now raises on any stat error other than ENOENT and the walk exits 2
        # naming the child. Explicit mode fails closed too: the guard cannot stat
        # the argument, so it refuses it with exit 2 (the guard's message is
        # version-dependent, exists() raising through Python 3.12 and returning
        # False on 3.13+, so only the exit code, the absence of a verdict and the
        # absence of a traceback are pinned on that side).
        root = self._recency_bom_repo([{
            "clean.md": "# Clean\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\nBody.\n",
            "docs/hidden/doc.md": "\ufeff# Hidden\n",
        }])
        (root / "docs/hidden").chmod(0o444)
        self.addCleanup((root / "docs/hidden").chmod, 0o755)
        walk = self._run_recency_bom(root)
        self.assertEqual(walk.returncode, 2, walk.stdout + walk.stderr)
        self.assertIn("cannot read a path", walk.stderr)
        self.assertIn("docs/hidden/doc.md", walk.stderr)
        self.assertNotIn("OK:", walk.stdout)
        self.assertNotIn("Traceback", walk.stderr)
        explicit = self._run_recency_bom(root, "docs/hidden/doc.md")
        self.assertEqual(explicit.returncode, 2, explicit.stdout + explicit.stderr)
        self.assertNotIn("FAIL", explicit.stdout)
        self.assertNotIn("OK:", explicit.stdout)
        self.assertNotIn("Traceback", explicit.stderr)

    @unittest.skipIf(os.geteuid() == 0, "root ignores file permission bits")
    def test_unreadable_regular_file_fails_closed_in_both_modes(self) -> None:
        # 3b89 round 6 (r5 claude F2): a regular file at mode 000 passes the stat
        # (stat needs only search permission on the parents) and fails at read.
        # The walk already exited 2, but through a message that called the file a
        # directory; explicit mode let the PermissionError escape as a traceback
        # with exit 1, the findings code. Both modes now exit 2 through the one
        # "cannot read a path" handler, with no traceback.
        root = self._recency_bom_repo([{
            "clean.md": "# Clean\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\nBody.\n",
            "sealed.md": "# Sealed\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\nBody.\n",
        }])
        (root / "sealed.md").chmod(0o000)
        self.addCleanup((root / "sealed.md").chmod, 0o644)
        for mode, result in (
            ("walk", self._run_recency_bom(root)),
            ("explicit", self._run_recency_bom(root, "sealed.md")),
        ):
            self.assertEqual(result.returncode, 2, mode + ": " + result.stdout + result.stderr)
            self.assertIn("cannot read a path", result.stderr, mode)
            self.assertIn("sealed.md", result.stderr, mode)
            self.assertNotIn("Traceback", result.stderr, mode)
            self.assertNotIn("FAIL", result.stdout, mode)
            self.assertNotIn("OK:", result.stdout, mode)


def _assert_historical_blob_missing(test: unittest.TestCase, clone: Path, first: str) -> None:
    """Verify a partial-clone fixture without reading or fetching its historical blob."""
    blob = subprocess.run(
        ["git", "-C", str(clone), "rev-parse", f"{first}:governance/x.md"],
        capture_output=True, text=True, check=True,
    ).stdout.strip()
    listed = subprocess.run(
        ["git", "-C", str(clone), "rev-list", "--objects", "--missing=print", first],
        capture_output=True, check=True,
    ).stdout.split(b"\n")
    test.assertIn(b"?" + blob.encode(), listed,
                  "fixture must omit the historical blob; clone is not partial")


class DateCobumpOnPrTests(LinterTestCase):
    """tools/check-date-cobump-on-pr.py (delta gate D4).

    A per-PR delta gate, so the fixtures build a synthetic two-commit
    git repo (base then head) and run the gate over the range, the same
    shape VersionBumpRecencyTests uses. Committer dates are pinned via
    GIT_*_DATE so the bump-commit-date comparison is deterministic.
    """

    HEAD_DATE = "2026-06-26T12:00:00+00:00"

    def _build_repo(self, base_doc: str, head_doc: str):
        import shutil
        import subprocess as sp
        import tempfile

        tmp = Path(tempfile.mkdtemp(prefix="lint-cobump-test-"))
        env = dict(os.environ)
        # Pin both commit dates to 2026-06-26 UTC so the gate's
        # bump-commit-date (committer date) is deterministic.
        env["GIT_AUTHOR_DATE"] = self.HEAD_DATE
        env["GIT_COMMITTER_DATE"] = self.HEAD_DATE
        sp.run(["git", "init", "-q", "-b", "main", str(tmp)], check=True)
        sp.run(["git", "-C", str(tmp), "config", "user.email", "test@test"], check=True)
        sp.run(["git", "-C", str(tmp), "config", "user.name", "Test"], check=True)
        target = tmp / "doc.md"
        target.write_text(base_doc, encoding="utf-8")
        sp.run(["git", "-C", str(tmp), "add", "-A"], check=True, env=env)
        sp.run(["git", "-C", str(tmp), "commit", "-q", "-m", "Initial"], check=True, env=env)
        base_sha = sp.run(
            ["git", "-C", str(tmp), "rev-parse", "HEAD"],
            capture_output=True, text=True, check=True,
        ).stdout.strip()
        target.write_text(head_doc, encoding="utf-8")
        sp.run(["git", "-C", str(tmp), "add", "-A"], check=True, env=env)
        sp.run(["git", "-C", str(tmp), "commit", "-q", "-m", "Second"], check=True, env=env)
        return tmp, base_sha, shutil

    def _run(self, tmp: Path, base_sha: str):
        import subprocess as sp

        return sp.run(
            [
                sys.executable,
                str(REPO_ROOT / "tools/check-date-cobump-on-pr.py"),
                base_sha,
                "HEAD",
            ],
            capture_output=True, text=True, cwd=str(tmp),
        )

    def test_version_bump_without_date_cobump_flagged(self) -> None:
        # Version bumps 1.0.0 -> 1.0.1 but Date stays 2026-06-25 while the
        # bump commit is dated 2026-06-26: the gate must fire.
        base = "# Doc\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-25\\\n\n## Body\n\nA.\n"
        head = "# Doc\n\n**Version:** 1.0.1\\\n**Date:** 2026-06-25\\\n\n## Body\n\nB.\n"
        tmp, base_sha, shutil = self._build_repo(base, head)
        try:
            result = self._run(tmp, base_sha)
            self.assertEqual(
                result.returncode, 1,
                f"gate should FAIL on Version-bump-without-Date-cobump; got "
                f"{result.returncode}.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
            )
            self.assertIn("doc.md", result.stdout + result.stderr)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_partial_clone_declines_scope_error(self) -> None:
        # Convergence with the aid (D4 partial-clone hardening): in a partial clone (a promisor
        # remote) a base blob may be unavailable; reading it would be misread as an added file
        # and silently clear a stale bump (a harmful false-OK). D4 now detects the promisor
        # remote and exits 2, matching the aid, and must NOT lazy-fetch (write pack files).
        import subprocess as sp, tempfile, glob, shutil as _sh

        def _doc(v, d):
            return f"# Doc\n\n**Version:** {v}\\\n**Date:** {d}\\\n\n## Body\n\nx.\n"

        src = Path(tempfile.mkdtemp(prefix="cobump-pcsrc-"))
        parent = Path(tempfile.mkdtemp(prefix="cobump-pcclone-"))
        clone = parent / "pc"
        try:
            sp.run(["git", "init", "-q", "-b", "main", str(src)], check=True)
            # Keep object-store assertions independent of automatic packing.
            sp.run(["git", "-C", str(src), "config", "gc.auto", "0"], check=True)
            sp.run(["git", "-C", str(src), "config", "gc.autoDetach", "false"], check=True)
            sp.run(["git", "-C", str(src), "config", "maintenance.auto", "false"], check=True)
            sp.run(["git", "-C", str(src), "config", "user.email", "t@test"], check=True)
            sp.run(["git", "-C", str(src), "config", "user.name", "T"], check=True)
            # enable server-side filtering so --filter=blob:none genuinely omits blobs (else the
            # clone quietly keeps every blob and the no-lazy-fetch assertion is vacuous).
            sp.run(["git", "-C", str(src), "config", "uploadpack.allowFilter", "true"], check=True)
            d = src / "governance"; d.mkdir()
            (d / "x.md").write_text(_doc("1.0.0", "2026-06-24"), encoding="utf-8")
            sp.run(["git", "-C", str(src), "add", "-A"], check=True)
            sp.run(["git", "-C", str(src), "commit", "-q", "-m", "c1"], check=True)
            (d / "x.md").write_text(_doc("1.1.0", "2026-06-25"), encoding="utf-8")
            sp.run(["git", "-C", str(src), "add", "-A"], check=True)
            sp.run(["git", "-C", str(src), "commit", "-q", "-m", "c2"], check=True)
            first = sp.run(["git", "-C", str(src), "rev-parse", "HEAD~1"],
                           capture_output=True, text=True, check=True).stdout.strip()
            cl = sp.run(["git", "clone", "-q", "--config", "gc.auto=0",
                         "--config", "gc.autoDetach=false", "--config", "maintenance.auto=false",
                         "--filter=blob:none", "--no-local",
                         "file://" + str(src), str(clone)], capture_output=True, text=True)
            if cl.returncode != 0:
                self.skipTest("partial clone unsupported in this environment")
            sp.run(["git", "-C", str(clone), "config", "user.email", "t@test"], check=True)
            sp.run(["git", "-C", str(clone), "config", "user.name", "T"], check=True)
            (clone / "governance" / "x.md").write_text(_doc("2.0.0", "2026-06-25"), encoding="utf-8")
            sp.run(["git", "-C", str(clone), "add", "-A"], check=True)
            sp.run(["git", "-C", str(clone), "commit", "-q", "-m", "c3"], check=True)
            # confirm the base blob is genuinely absent (a real partial clone), else the test
            # proves nothing about lazy-fetch.
            _assert_historical_blob_missing(self, clone, first)
            before = set(glob.glob(str(clone / ".git" / "objects" / "pack" / "*")))
            r = self._run(clone, first)
            after = set(glob.glob(str(clone / ".git" / "objects" / "pack" / "*")))
            self.assertEqual(r.returncode, 2,
                             f"D4 must decline (exit 2) in a partial clone.\n{r.stdout}\n{r.stderr}")
            self.assertEqual(after - before, set(), "D4 must not lazy-fetch (write pack files)")
        finally:
            _sh.rmtree(src, ignore_errors=True); _sh.rmtree(parent, ignore_errors=True)

    def test_partial_clone_via_extensions_config_declines(self) -> None:
        # Regression guard for the extensions.partialClone detection (the B1 fix): git's canonical
        # partial-clone marker is ``extensions.partialClone=<remote>``, which a repo can carry with
        # ``remote.*.promisor`` UNSET. That config must still make D4 decline (exit 2) without
        # lazy-fetching, or the harmful false-OK survives for it.
        import subprocess as sp, tempfile, glob, shutil as _sh

        def _doc(v, d):
            return f"# Doc\n\n**Version:** {v}\\\n**Date:** {d}\\\n\n## Body\n\nx.\n"

        src = Path(tempfile.mkdtemp(prefix="cobump-extsrc-"))
        parent = Path(tempfile.mkdtemp(prefix="cobump-extclone-"))
        clone = parent / "pc"
        try:
            sp.run(["git", "init", "-q", "-b", "main", str(src)], check=True)
            # Keep object-store assertions independent of automatic packing.
            sp.run(["git", "-C", str(src), "config", "gc.auto", "0"], check=True)
            sp.run(["git", "-C", str(src), "config", "gc.autoDetach", "false"], check=True)
            sp.run(["git", "-C", str(src), "config", "maintenance.auto", "false"], check=True)
            sp.run(["git", "-C", str(src), "config", "user.email", "t@test"], check=True)
            sp.run(["git", "-C", str(src), "config", "user.name", "T"], check=True)
            sp.run(["git", "-C", str(src), "config", "uploadpack.allowFilter", "true"], check=True)
            d = src / "governance"; d.mkdir()
            (d / "x.md").write_text(_doc("1.0.0", "2026-06-24"), encoding="utf-8")
            sp.run(["git", "-C", str(src), "add", "-A"], check=True)
            sp.run(["git", "-C", str(src), "commit", "-q", "-m", "c1"], check=True)
            (d / "x.md").write_text(_doc("1.1.0", "2026-06-25"), encoding="utf-8")
            sp.run(["git", "-C", str(src), "add", "-A"], check=True)
            sp.run(["git", "-C", str(src), "commit", "-q", "-m", "c2"], check=True)
            first = sp.run(["git", "-C", str(src), "rev-parse", "HEAD~1"],
                           capture_output=True, text=True, check=True).stdout.strip()
            cl = sp.run(["git", "clone", "-q", "--config", "gc.auto=0",
                         "--config", "gc.autoDetach=false", "--config", "maintenance.auto=false",
                         "--filter=blob:none", "--no-local",
                         "file://" + str(src), str(clone)], capture_output=True, text=True)
            if cl.returncode != 0:
                self.skipTest("partial clone unsupported in this environment")
            # drive detection through extensions.partialClone ONLY (remote.*.promisor unset)
            sp.run(["git", "-C", str(clone), "config", "--unset-all", "remote.origin.promisor"],
                   capture_output=True)
            sp.run(["git", "-C", str(clone), "config", "core.repositoryformatversion", "1"], check=True)
            sp.run(["git", "-C", str(clone), "config", "extensions.partialClone", "origin"], check=True)
            sp.run(["git", "-C", str(clone), "config", "user.email", "t@test"], check=True)
            sp.run(["git", "-C", str(clone), "config", "user.name", "T"], check=True)
            (clone / "governance" / "x.md").write_text(_doc("2.0.0", "2026-06-25"), encoding="utf-8")
            sp.run(["git", "-C", str(clone), "add", "-A"], check=True)
            sp.run(["git", "-C", str(clone), "commit", "-q", "-m", "c3"], check=True)
            _assert_historical_blob_missing(self, clone, first)
            before = set(glob.glob(str(clone / ".git" / "objects" / "pack" / "*")))
            r = self._run(clone, first)
            after = set(glob.glob(str(clone / ".git" / "objects" / "pack" / "*")))
            self.assertEqual(r.returncode, 2,
                             f"D4 must decline (exit 2) for an extensions.partialClone repo.\n{r.stdout}\n{r.stderr}")
            self.assertIn("extensions.partialClone", r.stderr)
            self.assertEqual(after - before, set(), "D4 must not lazy-fetch (write pack files)")
        finally:
            _sh.rmtree(src, ignore_errors=True); _sh.rmtree(parent, ignore_errors=True)

    def test_version_and_date_cobumped_not_flagged(self) -> None:
        # Version bumps and Date co-bumps to the 2026-06-26 commit date:
        # the gate must pass.
        base = "# Doc\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-25\\\n\n## Body\n\nA.\n"
        head = "# Doc\n\n**Version:** 1.0.1\\\n**Date:** 2026-06-26\\\n\n## Body\n\nB.\n"
        tmp, base_sha, shutil = self._build_repo(base, head)
        try:
            result = self._run(tmp, base_sha)
            self.assertEqual(
                result.returncode, 0,
                f"gate should PASS when Version and Date co-bump; got "
                f"{result.returncode}.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
            )
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_body_change_without_version_bump_out_of_scope(self) -> None:
        # Version unchanged (body edited, stale Date): D4 has nothing to
        # assert (D2 governs the missing-bump case), so it must pass.
        base = "# Doc\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\n## Body\n\nA.\n"
        head = "# Doc\n\n**Version:** 1.0.0\\\n**Date:** 2026-06-20\\\n\n## Body\n\nB.\n"
        tmp, base_sha, shutil = self._build_repo(base, head)
        try:
            result = self._run(tmp, base_sha)
            self.assertEqual(
                result.returncode, 0,
                f"gate should PASS when Version did not bump; got "
                f"{result.returncode}.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
            )
        finally:
            shutil.rmtree(tmp, ignore_errors=True)


class PreflightVersionDateTests(LinterTestCase):
    """tools/preflight-version-date.py (pre-commit D4 Version/Date co-bump predictor aid).

    The aid predicts `git commit` by inspecting the STAGED (index) content against a base ref,
    so fixtures stage their changes and inject "today" via the PREFLIGHT_VD_TODAY env seam.
    """

    TODAY = "2026-06-26"

    def _repo(self):
        import subprocess as sp
        import tempfile
        import shutil
        tmp = Path(tempfile.mkdtemp(prefix="preflight-vd-test-"))
        sp.run(["git", "init", "-q", "-b", "main", str(tmp)], check=True)
        # Keep object-store assertions independent of automatic packing.
        sp.run(["git", "-C", str(tmp), "config", "gc.auto", "0"], check=True)
        sp.run(["git", "-C", str(tmp), "config", "gc.autoDetach", "false"], check=True)
        sp.run(["git", "-C", str(tmp), "config", "maintenance.auto", "false"], check=True)
        sp.run(["git", "-C", str(tmp), "config", "user.email", "t@test"], check=True)
        sp.run(["git", "-C", str(tmp), "config", "user.name", "T"], check=True)
        return tmp, sp, shutil

    @staticmethod
    def _doc(ver: str, date: str | None = None) -> str:
        dline = f"**Date:** {date}\\\n" if date is not None else ""
        return f"# Doc\n\n**Version:** {ver}\\\n{dline}\n## Body\n\nwords words words.\n"

    def _commit(self, sp, tmp, msg: str) -> str:
        sp.run(["git", "-C", str(tmp), "add", "-A"], check=True)
        sp.run(["git", "-C", str(tmp), "commit", "-q", "-m", msg], check=True)
        return sp.run(
            ["git", "-C", str(tmp), "rev-parse", "HEAD"],
            capture_output=True, text=True, check=True,
        ).stdout.strip()

    def _stage(self, sp, tmp):
        sp.run(["git", "-C", str(tmp), "add", "-A"], check=True)

    def _run_at(self, cwd, base: str, *extra: str):
        import subprocess as sp
        env = dict(os.environ)
        env["PREFLIGHT_VD_TODAY"] = self.TODAY
        return sp.run(
            [sys.executable, str(REPO_ROOT / "tools/preflight-version-date.py"), "--base", base, *extra],
            capture_output=True, text=True, cwd=str(cwd), env=env,
        )

    def _run(self, tmp, base: str, *extra: str):
        return self._run_at(tmp, base, *extra)

    def _doc_path(self, tmp):
        d = tmp / "governance"
        d.mkdir(exist_ok=True)
        return d / "standard-x.md"

    def _d4(self, tmp, base_sha: str, head_sha: str, env=None):
        """Run the real D4 gate (check-date-cobump-on-pr.py) over base..head; return its rc.
        The aid's contract is to PREDICT this exactly, so parity tests compare the two rcs."""
        import subprocess as sp
        return sp.run(
            [sys.executable, str(REPO_ROOT / "tools/check-date-cobump-on-pr.py"), base_sha, head_sha],
            capture_output=True, text=True, cwd=str(tmp), env=env,
        ).returncode

    def test_staged_version_bump_stale_date_flagged(self) -> None:
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.0.1", "2026-06-25"), encoding="utf-8")  # stale
            self._stage(sp, tmp)
            r = self._run(tmp, base)
            self.assertEqual(r.returncode, 1, f"{r.stdout}\n{r.stderr}")
            self.assertIn("standard-x.md", r.stdout)
            self.assertIn(self.TODAY, r.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_staged_version_bump_today_date_clear(self) -> None:
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.0.1", self.TODAY), encoding="utf-8")
            self._stage(sp, tmp)
            self.assertEqual(self._run(tmp, base).returncode, 0)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_no_version_change_clear(self) -> None:
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-01-01"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.0.0", "2026-01-01").replace("words words words.", "edited."), encoding="utf-8")
            self._stage(sp, tmp)  # body-only change, Version unchanged, stale Date -> out of scope
            self.assertEqual(self._run(tmp, base).returncode, 0)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_staged_missing_date_flagged(self) -> None:
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.0.1", None), encoding="utf-8")  # Version bumped, Date gone
            self._stage(sp, tmp)
            r = self._run(tmp, base)
            self.assertEqual(r.returncode, 1, f"{r.stdout}\n{r.stderr}")
            self.assertIn("missing", r.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_uses_index_not_working_tree(self) -> None:
        # The aid predicts `git commit` (the index): a staged stale bump whose Date fix was NOT
        # re-staged must STILL flag (reading the working tree would falsely pass). (gemini R4.)
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.0.1", "2026-06-25"), encoding="utf-8")  # stale
            self._stage(sp, tmp)  # stage the stale bump
            doc.write_text(self._doc("1.0.1", self.TODAY), encoding="utf-8")  # fix Date in working tree ONLY
            r = self._run(tmp, base)
            self.assertEqual(r.returncode, 1, f"index still stale -> must flag.\n{r.stdout}\n{r.stderr}")
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_exempt_changelog_ignored(self) -> None:
        tmp, sp, shutil = self._repo()
        try:
            (tmp / "CHANGELOG.md").write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            (tmp / "CHANGELOG.md").write_text(self._doc("1.0.1", "2026-06-25"), encoding="utf-8")
            self._stage(sp, tmp)  # CHANGELOG.md is D4-exempt -> no finding
            self.assertEqual(self._run(tmp, base).returncode, 0)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_unresolvable_base_scope_error(self) -> None:
        tmp, sp, shutil = self._repo()
        try:
            self._doc_path(tmp).write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            self._commit(sp, tmp, "base")
            r = self._run(tmp, "no-such-ref-xyz")
            self.assertEqual(r.returncode, 2, f"{r.stdout}\n{r.stderr}")
            self.assertIn("SCOPE ERROR", r.stderr)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_divergent_upstream_base_still_flagged(self) -> None:
        # merge-base(base, HEAD) is used, so an independently-advanced upstream base cannot hide
        # the co-bump against the ancestor (matches D4's range).
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            anc = self._commit(sp, tmp, "ancestor")
            doc.write_text(self._doc("1.1.0", "2026-06-24"), encoding="utf-8")
            up = self._commit(sp, tmp, "upstream advances")
            sp.run(["git", "-C", str(tmp), "checkout", "-q", "-b", "feat", anc], check=True)
            doc.write_text(self._doc("1.1.0", "2026-06-25"), encoding="utf-8")  # stale bump
            self._stage(sp, tmp)
            r = self._run(tmp, up)  # base=upstream(1.1.0); merge-base=ancestor(1.0.0) -> must flag
            self.assertEqual(r.returncode, 1, f"{r.stdout}\n{r.stderr}")
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_added_and_deleted_files_skipped(self) -> None:
        # added / deleted files are out of D4's co-bump scope (a new file's Date is gate-31's remit).
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            (tmp / "governance" / "new.md").write_text(self._doc("1.0.0", "2026-06-25"), encoding="utf-8")
            self._stage(sp, tmp)  # staged addition of a new, stale-dated doc
            self.assertEqual(self._run(tmp, base).returncode, 0)
            sp.run(["git", "-C", str(tmp), "rm", "-q", str(doc)], check=True)  # staged deletion
            self.assertEqual(self._run(tmp, base).returncode, 0)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_rm_cached_edited_file_skipped(self) -> None:
        # `git rm --cached` untracks a file but leaves an edited copy on disk; the prospective
        # commit DELETES it, so the aid (reading the index) must skip it, not flag (codex R4 FP).
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.1.0", "2026-06-25"), encoding="utf-8")  # edit on disk
            sp.run(["git", "-C", str(tmp), "rm", "--cached", "-q", str(doc)], check=True)  # untrack
            self.assertEqual(self._run(tmp, base).returncode, 0)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_pending_merge_scope_error(self) -> None:
        tmp, sp, shutil = self._repo()
        try:
            self._doc_path(tmp).write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            sp.run(["git", "-C", str(tmp), "checkout", "-q", "-b", "a"], check=True)
            (tmp / "governance" / "a.md").write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            self._commit(sp, tmp, "a")
            sp.run(["git", "-C", str(tmp), "checkout", "-q", "main"], check=True)
            (tmp / "governance" / "b.md").write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            self._commit(sp, tmp, "b")
            sp.run(["git", "-C", str(tmp), "checkout", "-q", "a"], check=True)
            sp.run(["git", "-C", str(tmp), "merge", "--no-commit", "--no-ff", "main"], capture_output=True)
            r = self._run(tmp, base)
            self.assertEqual(r.returncode, 2, f"{r.stdout}\n{r.stderr}")
            self.assertIn("merge", r.stderr.lower())
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_unmerged_conflict_scope_error(self) -> None:
        tmp, sp, shutil = self._repo()
        try:
            c = tmp / "governance" / "c.md"
            c.parent.mkdir(exist_ok=True)
            c.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            sp.run(["git", "-C", str(tmp), "checkout", "-q", "-b", "a"], check=True)
            c.write_text(self._doc("1.1.0", "2026-06-24"), encoding="utf-8"); self._commit(sp, tmp, "a")
            sp.run(["git", "-C", str(tmp), "checkout", "-q", "main"], check=True)
            c.write_text(self._doc("1.2.0", "2026-06-24"), encoding="utf-8"); self._commit(sp, tmp, "b")
            sp.run(["git", "-C", str(tmp), "checkout", "-q", "a"], check=True)
            sp.run(["git", "-C", str(tmp), "merge", "main"], capture_output=True)  # unmerged
            self.assertEqual(self._run(tmp, base).returncode, 2)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_non_utf8_filename_scope_error(self) -> None:
        tmp, sp, shutil = self._repo()
        try:
            (tmp / "governance").mkdir(exist_ok=True)
            bad = os.path.join(str(tmp).encode(), b"governance/bad\xff.md")
            with open(bad, "wb") as fh:
                fh.write(self._doc("1.0.0", "2026-06-24").encode())
            base = self._commit(sp, tmp, "base")
            with open(bad, "wb") as fh:
                fh.write(self._doc("2.0.0", "2026-06-25").encode())
            self._stage(sp, tmp)
            r = self._run(tmp, base)
            self.assertEqual(r.returncode, 2, f"{r.stdout}\n{r.stderr}")
            self.assertNotIn("Traceback", r.stderr)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_version_field_gained_and_lost_flagged(self) -> None:
        tmp, sp, shutil = self._repo()
        try:
            gained = tmp / "governance" / "gain.md"
            lost = tmp / "governance" / "lose.md"
            gained.parent.mkdir(exist_ok=True)
            gained.write_text("# D\n\n**Date:** 2026-06-24\\\n\n## B\nx.\n", encoding="utf-8")
            lost.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            gained.write_text(self._doc("1.0.0", "2026-06-25"), encoding="utf-8")  # GAINS Version
            lost.write_text("# D\n\n**Date:** 2026-06-25\\\n\n## B\ny.\n", encoding="utf-8")  # LOSES Version
            self._stage(sp, tmp)
            r = self._run(tmp, base)
            self.assertEqual(r.returncode, 1, f"{r.stdout}\n{r.stderr}")
            self.assertIn("gain.md", r.stdout)
            self.assertIn("lose.md", r.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_strict_today_override_rejected(self) -> None:
        tmp, sp, shutil = self._repo()
        try:
            import subprocess as sp2
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.0.1", "2026-06-25"), encoding="utf-8")
            self._stage(sp, tmp)
            env = dict(os.environ)
            env["PREFLIGHT_VD_TODAY"] = "20260625"  # basic ISO form -> rejected -> real UTC
            r = sp2.run(
                [sys.executable, str(REPO_ROOT / "tools/preflight-version-date.py"), "--base", base],
                capture_output=True, text=True, cwd=str(tmp), env=env,
            )
            self.assertEqual(r.returncode, 1, f"override should be rejected -> real UTC.\n{r.stdout}\n{r.stderr}")
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_read_only_no_index_rewrite(self) -> None:
        # -c diff.autoRefreshIndex=false keeps `git diff` from rewriting the .git/index stat cache.
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.0.1", "2026-06-25"), encoding="utf-8")
            self._stage(sp, tmp)
            os.utime(doc)  # bump mtime so a refresh would rewrite the stat cache
            index = tmp / ".git" / "index"
            before = index.read_bytes()
            self._run(tmp, base)
            self.assertEqual(index.read_bytes(), before, "the aid must not rewrite .git/index")
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_nested_subdir_with_diff_relative(self) -> None:
        # --no-relative must defeat diff.relative=true from a nested subdir with the affected file
        # OUTSIDE the invocation directory.
        tmp, sp, shutil = self._repo()
        try:
            sp.run(["git", "-C", str(tmp), "config", "diff.relative", "true"], check=True)
            doc = self._doc_path(tmp)
            other = tmp / "operations"
            other.mkdir()
            (other / "here.md").write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.0.1", "2026-06-25"), encoding="utf-8")  # stale bump in governance/
            self._stage(sp, tmp)
            r = self._run_at(other, base)  # run from operations/, affected file in governance/
            self.assertEqual(r.returncode, 1, f"{r.stdout}\n{r.stderr}")
            self.assertIn("standard-x.md", r.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)


    def test_multi_commit_untouched_file_not_flagged(self) -> None:
        # gemini/codex R5: a document bumped+dated in an EARLIER branch commit and NOT staged for
        # the current commit must NOT be flagged (the aid enumerates staged-vs-HEAD, not vs base).
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.1.0", "2026-06-25"), encoding="utf-8")  # earlier bump, dated then
            self._commit(sp, tmp, "earlier bump")
            (tmp / "governance" / "unrelated.md").write_text(self._doc("1.0.0", self.TODAY), encoding="utf-8")
            self._stage(sp, tmp)  # stage only the unrelated file
            self.assertEqual(self._run(tmp, base).returncode, 0)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_body_edit_of_earlier_bump_flagged(self) -> None:
        # the flip side: a file bumped in an earlier commit, then body-edited + staged in THIS
        # commit, whose Date is still the earlier day -> D4 flags it (this commit touched it and its
        # Version differs from base), so the aid must too (uses merge-base for the Version event).
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.1.0", "2026-06-25"), encoding="utf-8")
            self._commit(sp, tmp, "earlier bump")
            doc.write_text(self._doc("1.1.0", "2026-06-25") + "an edit.\n", encoding="utf-8")  # body edit, Date stale
            self._stage(sp, tmp)
            self.assertEqual(self._run(tmp, base).returncode, 1)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_standalone_unmerged_scope_error(self) -> None:
        # codex R5 mutation gap: unmerged index entries WITHOUT MERGE_HEAD (e.g. a conflicted
        # cherry-pick/rebase, or synthetic stages) must still scope-error via the ls-files guard.
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            blob = sp.run(["git", "-C", str(tmp), "rev-parse", "HEAD:governance/standard-x.md"],
                          capture_output=True, text=True, check=True).stdout.strip()
            info = "".join(f"100644 {blob} {stage}\tgovernance/standard-x.md\n" for stage in (1, 2, 3))
            sp.run(["git", "-C", str(tmp), "update-index", "--index-info"], input=info, text=True, check=True)
            self.assertFalse((tmp / ".git" / "MERGE_HEAD").exists())  # no MERGE_HEAD, only unmerged stages
            self.assertEqual(self._run(tmp, base).returncode, 2)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_undecodable_index_content_scope_error(self) -> None:
        # codex R5 P2: a staged blob that is not valid UTF-8 is an inspection failure -> scope error,
        # never a silent clear of a real staged stale bump.
        tmp, sp, shutil = self._repo()
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            with open(doc, "wb") as fh:
                fh.write(self._doc("1.1.0", "2026-06-25").encode() + b"caf\xe9\n")  # trailing Latin-1
            self._stage(sp, tmp)
            r = self._run(tmp, base)
            self.assertEqual(r.returncode, 2, f"{r.stdout}\n{r.stderr}")
            self.assertNotIn("Traceback", r.stderr)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_fsmonitor_hook_not_executed(self) -> None:
        # codex R5 P2: a configured core.fsmonitor hook can write files; the aid disables fsmonitor
        # for every git subprocess (GIT_CONFIG_*), so the hook must not run.
        tmp, sp, shutil = self._repo()
        try:
            hook = tmp / "fsm.sh"
            hook.write_text("#!/bin/sh\ntouch fsmonitor-ran\n", encoding="utf-8")
            os.chmod(hook, 0o755)
            sp.run(["git", "-C", str(tmp), "config", "core.fsmonitor", str(hook)], check=True)
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.1.0", "2026-06-25"), encoding="utf-8")
            self._stage(sp, tmp)
            marker = tmp / "fsmonitor-ran"
            if marker.exists():
                marker.unlink()
            self._run(tmp, base)
            self.assertFalse(marker.exists(), "the aid must not trigger a repo-configured fsmonitor hook")
            # also defeat an inherited GIT_CONFIG_PARAMETERS fsmonitor (higher precedence than a
            # GIT_CONFIG_* env override; only a command-line -c outranks it). And GIT_CONFIG_COUNT=""
            # must not crash the aid. (codex R6.)
            import subprocess as sp2
            for extra in ({"GIT_CONFIG_PARAMETERS": f"'core.fsmonitor={hook}'"}, {"GIT_CONFIG_COUNT": ""}):
                if marker.exists():
                    marker.unlink()
                env = dict(os.environ); env["PREFLIGHT_VD_TODAY"] = self.TODAY; env.update(extra)
                r = sp2.run(
                    [sys.executable, str(REPO_ROOT / "tools/preflight-version-date.py"), "--base", base],
                    capture_output=True, text=True, cwd=str(tmp), env=env,
                )
                self.assertFalse(marker.exists(), f"fsmonitor hook ran under {extra}")
                self.assertNotIn("Traceback", r.stderr, f"crash under {extra}")
        finally:
            shutil.rmtree(tmp, ignore_errors=True)


    def test_partial_clone_scope_error(self) -> None:
        # codex R7: in a partial clone (a promisor remote) a base blob may be absent; the aid must
        # NOT lazy-fetch it (that writes pack files) and must scope-error (2) instead.
        import subprocess as sp, tempfile, glob
        src = Path(tempfile.mkdtemp(prefix="preflight-vd-pcsrc-"))
        parent = Path(tempfile.mkdtemp(prefix="preflight-vd-pcclone-"))
        clone = parent / "pc"
        try:
            sp.run(["git", "init", "-q", "-b", "main", str(src)], check=True)
            # Keep object-store assertions independent of automatic packing.
            sp.run(["git", "-C", str(src), "config", "gc.auto", "0"], check=True)
            sp.run(["git", "-C", str(src), "config", "gc.autoDetach", "false"], check=True)
            sp.run(["git", "-C", str(src), "config", "maintenance.auto", "false"], check=True)
            sp.run(["git", "-C", str(src), "config", "user.email", "t@test"], check=True)
            sp.run(["git", "-C", str(src), "config", "user.name", "T"], check=True)
            sp.run(["git", "-C", str(src), "config", "uploadpack.allowFilter", "true"], check=True)
            d = src / "governance"; d.mkdir()
            (d / "x.md").write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            sp.run(["git", "-C", str(src), "add", "-A"], check=True)
            sp.run(["git", "-C", str(src), "commit", "-q", "-m", "c1"], check=True)
            (d / "x.md").write_text(self._doc("1.1.0", "2026-06-25"), encoding="utf-8")
            sp.run(["git", "-C", str(src), "add", "-A"], check=True)
            sp.run(["git", "-C", str(src), "commit", "-q", "-m", "c2"], check=True)
            first = sp.run(["git", "-C", str(src), "rev-parse", "HEAD~1"],
                           capture_output=True, text=True, check=True).stdout.strip()
            cl = sp.run(["git", "clone", "-q", "--config", "gc.auto=0",
                         "--config", "gc.autoDetach=false", "--config", "maintenance.auto=false",
                         "--filter=blob:none", "--no-local",
                         "file://" + str(src), str(clone)], capture_output=True, text=True)
            if cl.returncode != 0:
                self.skipTest("partial clone unsupported in this environment")
            sp.run(["git", "-C", str(clone), "config", "user.email", "t@test"], check=True)
            sp.run(["git", "-C", str(clone), "config", "user.name", "T"], check=True)
            (clone / "governance" / "x.md").write_text(self._doc("2.0.0", "2026-06-25"), encoding="utf-8")
            sp.run(["git", "-C", str(clone), "add", "-A"], check=True)
            _assert_historical_blob_missing(self, clone, first)
            before = set(glob.glob(str(clone / ".git" / "objects" / "pack" / "*")))
            r = self._run_at(clone, first)
            after = set(glob.glob(str(clone / ".git" / "objects" / "pack" / "*")))
            self.assertEqual(r.returncode, 2, f"{r.stdout}\n{r.stderr}")
            self.assertEqual(after - before, set(), "the aid must not lazy-fetch (write pack files)")
        finally:
            import shutil as _sh
            _sh.rmtree(src, ignore_errors=True); _sh.rmtree(parent, ignore_errors=True)

    def _assert_filename_parity(self, name: str) -> None:
        # round-8 codex/gemini: the aid must predict D4 EXACTLY for any filename. Both enumerate
        # with -z (never quoted), so a stale-dated bump of `name` must FLAG in both (aid rc 1, D4
        # rc 1), regardless of core.quotePath. The pre-fix isascii()/quoted-path handling diverged.
        tmp, sp, shutil = self._repo()
        try:
            doc = tmp / "governance" / name
            doc.parent.mkdir(exist_ok=True)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.1.0", "2026-06-25"), encoding="utf-8")  # stale bump
            self._stage(sp, tmp)
            aid_rc = self._run(tmp, base).returncode
            head = self._commit(sp, tmp, "head")
            d4_rc = self._d4(tmp, base, head)
            self.assertEqual(aid_rc, 1, f"aid must flag stale bump of {name!r}")
            self.assertEqual(d4_rc, 1, f"D4 must flag stale bump of {name!r}")
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_non_ascii_filename_flagged_matches_d4(self) -> None:
        # round-8: an accented .md name; under core.quotePath=false the old isascii() skip was a
        # FALSE NEGATIVE (aid cleared while D4 flagged). Now both flag.
        self._assert_filename_parity("politique-securité.md")

    def test_quote_char_filename_flagged_matches_d4(self) -> None:
        # round-8: an ASCII name containing a double-quote. Git quotes it by default so D4's old
        # endswith(".md") wrongly exempted it (FALSE POSITIVE for the aid); -z fixes both.
        self._assert_filename_parity('a"b.md')

    def test_git_trace2_event_writes_nothing(self) -> None:
        # round-8 codex: an inherited GIT_TRACE2_EVENT=<path> made the aid's git subprocesses WRITE
        # a trace file, breaking the read-only contract. The module-init scrub of GIT_TRACE* must
        # stop that write.
        import subprocess as sp2, tempfile, os as _os
        tmp, sp, shutil = self._repo()
        trace = Path(tempfile.mkdtemp(prefix="preflight-vd-trace-")) / "trace.json"
        try:
            doc = self._doc_path(tmp)
            doc.write_text(self._doc("1.0.0", "2026-06-24"), encoding="utf-8")
            base = self._commit(sp, tmp, "base")
            doc.write_text(self._doc("1.0.1", "2026-06-25"), encoding="utf-8")
            self._stage(sp, tmp)
            env = dict(_os.environ)
            env["PREFLIGHT_VD_TODAY"] = self.TODAY
            env["GIT_TRACE2_EVENT"] = str(trace)
            env["GIT_TRACE"] = str(trace.parent / "trace-legacy.txt")
            sp2.run([sys.executable, str(REPO_ROOT / "tools/preflight-version-date.py"),
                     "--base", base], capture_output=True, text=True, cwd=str(tmp), env=env)
            self.assertFalse(trace.exists(), "GIT_TRACE2_EVENT file must not be written by the aid")
            self.assertFalse((trace.parent / "trace-legacy.txt").exists(),
                             "GIT_TRACE file must not be written by the aid")
        finally:
            shutil.rmtree(tmp, ignore_errors=True)
            shutil.rmtree(trace.parent, ignore_errors=True)

