    def test_non_utf8_toplevel_keeps_real_verdict_and_refusal(self) -> None:
        # 3b540 round 8 (r7 review WARN-2): the top level a gate reads for
        # its refusal's repo= field is diagnostic only. In a repository whose
        # top-level path holds a byte that is not valid UTF-8 (0xff), that
        # read raised UnicodeDecodeError and D1-D5, D7, D9, D11, D13 and
        # tension-scan exited 1 with a traceback (D15 failed open); it now
        # degrades to a placeholder as D12's _toplevel does, so a real range
        # gets each gate's real verdict and a collapsed range its refusal.
        # Since 3b564, D5, D9, D13 and tension-scan decode the top level with
        # os.fsdecode instead, so their refusal names the real top level and
        # their top-level comparison always runs: they run as copies inside
        # the fixture, their own REPO_ROOT. Mutation killed: dropping
        # UnicodeDecodeError from the except clause in
        # lint_common.pr_range_resolution, or reading the top level as
        # strict text again in D5, D9, D13 or tension-scan (a traceback, or
        # the placeholder where the real path belongs). Skipped where the
        # filesystem refuses the name.
        import subprocess as sp

        parent = Path(tempfile.mkdtemp(prefix="non-utf8-top-")).resolve()
        self.addCleanup(shutil.rmtree, parent, ignore_errors=True)
        top = os.path.join(os.fsencode(parent), b"repo-\xff")
        try:
            os.mkdir(top)
        except OSError as exc:
            self.skipTest(f"the filesystem cannot hold a non-UTF-8 name: {exc}")

        def git(*args):
            sp.run([b"git", b"-C", top, *map(os.fsencode, args)],
                   check=True, capture_output=True)

        def write(rel, content):
            with open(os.path.join(top, os.fsencode(rel)), "wb") as fh:
                fh.write(content)

        git("init", "-q", "-b", "main")
        git("config", "user.email", "test@test")
        git("config", "user.name", "Test")
        write("README.md", b"# Repo\n")
        write("CHANGELOG.md", b"# Changelog\n\nOld entry.\n")
        git("add", "-A")
        git("commit", "-q", "-m", "Initial")
        git("update-ref", "refs/remotes/origin/main", "HEAD")
        git("checkout", "-q", "-b", "feat")
        write("CHANGELOG.md", b"# Changelog\n\nNew entry.\n\nOld entry.\n")
        git("commit", "-q", "-am", "feat: a change")
        # D5, D9, D13 and tension-scan refuse a top level other than their
        # own script's repository (3b564), so they run as untracked copies
        # inside the fixture (with lint_common, which they import).
        os.mkdir(os.path.join(top, b"tools"))
        for name in ("lint_common.py", "check-retired-section-orphan-on-pr.py",
                     "check-stranded-control-code-on-pr.py", "check-todo-rotation-on-pr.py",
                     "tension-scan.py"):
            write(f"tools/{name}", (REPO_ROOT / "tools" / name).read_bytes())

        tools = os.fsencode(REPO_ROOT / "tools")
        own = os.path.join(top, b"tools")
        # Their refusal names the decoded top level; stderr's
        # backslashreplace prints the undecodable byte as \udcff.
        own_repo = ("repo=" + os.fsdecode(top)).encode("utf-8", "backslashreplace").decode("utf-8")
        for directory, script, verdict in (
            (tools, "check-changelog-on-pr.py", "OK: CHANGELOG.md is in the diff"),
            (tools, "check-version-bump-on-pr.py", "OK: 0 changed versioned document(s)"),
            (tools, "check-changelog-dash-on-pr.py", "OK: no em/en dashes"),
            (tools, "check-date-cobump-on-pr.py", "OK: 0 document(s) bumped Version"),
            (own, "check-todo-rotation-on-pr.py", "OK: no TODO-item closure asserted"),
            (tools, "check-changelog-length-on-pr.py", "OK: no compact root CHANGELOG.md"),
            (tools, "check-narrative-corpus-mixed-diff-on-pr.py", "neither surface touched"),
            (own, "tension-scan.py", "0 rewritten block(s) since"),
            (tools, "check-alignment-register-on-pr.py", "is absent at feat; nothing to check"),
            (own, "check-retired-section-orphan-on-pr.py", "D9 OK: no TODO section closed"),
            (own, "check-stranded-control-code-on-pr.py", "D13 OK: no corpus document changed"),
        ):
            path = os.path.join(directory, os.fsencode(script))
            advisory = script == "check-alignment-register-on-pr.py"  # D15 exits 0
            for label, head, rc in (("real", "feat", 0),
                                    ("collapsed", "origin/main", 0 if advisory else 2)):
                with self.subTest(gate=script, range=label):
                    r = sp.run([sys.executable, path, "origin/main", head],
                               capture_output=True, cwd=top, encoding="utf-8",
                               errors="backslashreplace")
                    self.assertEqual(r.returncode, rc,
                                     f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                    self.assertNotIn("Traceback", r.stderr)
                    if label == "real":
                        self.assertIn(verdict, r.stdout)
                    else:
                        self.assertIn("CANNOT-EVALUATE", r.stdout + r.stderr)
                        self.assertIn(own_repo if directory == own else "repo=(no work tree)",
                                      r.stdout + r.stderr)

    def _inject_oserror(self, script, cwd, tail, *args, nth=None):
        """Run ``script`` with ``args`` in-process, subprocess.check_output
        raising OSError (EAGAIN) on each git call whose argv ends with
        ``tail`` -- or, given ``nth``, on the nth such call only (3b577
        round 3); stderr carries one INJECTED line per raise. A simulation of
        git failing to run, not a real fault (3b540 round 9)."""
        import subprocess as sp

        driver = (
            "import errno, json, os, runpy, subprocess, sys\n"
            "tail = json.loads(os.environ['INJECT_TAIL'])\n"
            "nth = json.loads(os.environ['INJECT_NTH'])\n"
            "seen = [0]\n"
            "real = subprocess.check_output\n"
            "def check_output(cmd, *a, **k):\n"
            "    if [str(c) for c in cmd][-len(tail):] == tail:\n"
            "        seen[0] += 1\n"
            "        if nth is None or seen[0] == nth:\n"
            "            print('INJECTED', file=sys.stderr)\n"
            "            raise OSError(errno.EAGAIN, 'injected')\n"
            "    return real(cmd, *a, **k)\n"
            "subprocess.check_output = check_output\n"
            "sys.argv = sys.argv[1:]\n"
            "sys.path.insert(0, os.path.dirname(os.path.abspath(sys.argv[0])))\n"
            "runpy.run_path(sys.argv[0], run_name='__main__')\n"
        )
        return sp.run(
            [sys.executable, "-c", driver, str(script), *args],
            capture_output=True, text=True, cwd=str(cwd),
            env={**os.environ, "INJECT_TAIL": json.dumps(tail),
                 "INJECT_NTH": json.dumps(nth)},
        )

    def test_toplevel_oserror_keeps_real_verdict_and_refusal(self) -> None:
        # 3b540 round 9 (r8 review NOTE-2): git failing to run at all
        # (OSError) on the one top-level read a gate makes for its refusal's
        # repo= field degrades to the placeholder, as UnicodeDecodeError does
        # above, so a real range keeps each gate's real verdict and a
        # collapsed range its refusal. The OSError is injected on that single
        # git call. Mutation killed: dropping OSError from the top-level
        # read's except clause in lint_common.pr_range_resolution (reached
        # through D1), D5, D9, D13 or tension-scan, which then exits 1 with a
        # traceback. Since 3b564 the placeholder skips only the top-level
        # comparison of D5, D9 and tension-scan (their git-directory check
        # still runs), and they run as copies inside the fixture, their own
        # REPO_ROOT. 3b572 round 3: D13 no longer degrades; its top-level
        # read refuses with exit 2 naming the OSError on a real range, a
        # collapsed range, and a core.worktree naming another directory,
        # which only the skipped comparison refuses, so the degraded read
        # passed it with "D13 OK" and exit 0. Mutation killed: restoring
        # D13's placeholder.
        import errno
        import subprocess as sp

        tmp, git = self._repo()
        git("checkout", "-q", "-b", "feat")
        (tmp / "CHANGELOG.md").write_text(
            "# Changelog\n\nNew entry.\n\nOld entry.\n", encoding="utf-8")
        git("commit", "-q", "-am", "feat: a change")
        tools, own = REPO_ROOT / "tools", self._own_copies(tmp / "tools")
        for directory, script, verdict in (
            (tools, "check-changelog-on-pr.py", "OK: CHANGELOG.md is in the diff"),
            (own, "check-todo-rotation-on-pr.py", "OK: no TODO-item closure asserted"),
            (own, "tension-scan.py", "0 rewritten block(s) since"),
            (own, "check-retired-section-orphan-on-pr.py", "D9 OK: no TODO section closed"),
        ):
            for label, head, rc in (("real", "feat", 0), ("collapsed", "origin/main", 2)):
                with self.subTest(gate=script, range=label):
                    r = self._inject_oserror(directory / script, tmp,
                                             ["rev-parse", "--show-toplevel"],
                                             "origin/main", head)
                    self.assertEqual(r.returncode, rc,
                                     f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                    self.assertEqual(r.stderr.count("INJECTED"), 1, r.stderr)
                    self.assertNotIn("Traceback", r.stderr)
                    if label == "real":
                        self.assertIn(verdict, r.stdout)
                    else:
                        self.assertIn("CANNOT-EVALUATE", r.stderr)
                        self.assertIn("repo=(no work tree)", r.stderr)
        d13 = own / "check-stranded-control-code-on-pr.py"
        elsewhere = Path(tempfile.mkdtemp(prefix="d13-elsewhere-")).resolve()
        self.addCleanup(shutil.rmtree, elsewhere, ignore_errors=True)
        for label, head, worktree in (("real", "feat", None), ("collapsed", "origin/main", None),
                                      ("core.worktree elsewhere", "feat", elsewhere)):
            with self.subTest(gate=d13.name, range=label):
                if worktree is not None:
                    git("config", "core.worktree", str(worktree))
                    # Uninjected, the top-level comparison refuses this layout.
                    plain = sp.run([sys.executable, str(d13), "origin/main", head],
                                   capture_output=True, text=True, cwd=str(tmp))
                    self.assertEqual(plain.returncode, 2,
                                     f"stdout:\n{plain.stdout}\nstderr:\n{plain.stderr}")
                    self.assertIn("ERROR: git reports the work tree top level", plain.stderr)
                r = self._inject_oserror(d13, tmp, ["rev-parse", "--show-toplevel"],
                                         "origin/main", head)
                out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                self.assertEqual(r.returncode, 2, out)
                self.assertEqual(r.stderr.count("INJECTED"), 1, r.stderr)
                self.assertNotIn("Traceback", r.stderr)
                self.assertIn("ERROR: git could not be run reading the top level "
                              f"(base=origin/main, head={head}): [Errno {errno.EAGAIN}] injected",
                              r.stderr)
                self.assertNotIn("D13 OK", r.stdout)
                self.assertNotIn("CANNOT-EVALUATE", r.stderr)
                self.assertNotIn("(no work tree)", r.stderr)

    def test_head_sha_oserror_never_reads_collapsed_range_clean(self) -> None:
        # 3b540 round 9 (r8 review NOTE-1): the head SHA pr_range_resolution
        # reads decides the collapse, so that read degrades on a
        # CalledProcessError only. Had an OSError there degraded to the echoed
        # ref name, the name would never equal the merge base and a collapsed
        # range would read as a real one: D3 and D7 printed a clean "not
        # modified" pass (exit 0) at round 8. 3b577 (3b540 post-merge review
        # W1): the OSError, injected on that single git call, raises
        # PrRangeError, so the gate refuses with exit 2 instead of escaping
        # as a traceback (exit 1, which the round-9 non-zero check accepted).
        # Mutations killed: adding OSError back to the degrading clause, or
        # dropping the PrRangeError clause.
        tmp, _git = self._repo()
        for script in ("check-changelog-dash-on-pr.py", "check-changelog-length-on-pr.py"):
            with self.subTest(gate=script):
                r = self._inject_oserror(REPO_ROOT / "tools" / script, tmp,
                                         ["rev-parse", "--verify", "HEAD^{commit}"],
                                         "origin/main", "HEAD")
                self.assertEqual(r.stderr.count("INJECTED"), 1, r.stderr)
                self.assertEqual(r.returncode, 2,
                                 f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                self.assertNotIn("Traceback", r.stderr)
                self.assertIn("CANNOT-EVALUATE", r.stderr)
                self.assertNotIn("OK", r.stdout)

    def test_empty_range_message_head_sha_failure_never_tracebacks(self) -> None:
        # 3b577 round 3 (r2 reviews, codex E1 / claude F2): on a net-empty
        # named range D1, D2, D4 and D11 compose their refusal with
        # empty_pr_range_message, which reads the head SHA a second time,
        # outside the gates' resolve_pr_range handler. The OSError, injected
        # on that second read only (the first, in resolve_pr_range, succeeds),
        # raised PrRangeError there and each gate exited 1 with a traceback;
        # the SHA is diagnostic once the range is found empty, so it now
        # degrades to a placeholder and the gate refuses with exit 2.
        # Mutation killed: dropping the PrRangeError clause in
        # empty_pr_range_message.
        tmp, git = self._repo()
        git("checkout", "-q", "-b", "feat-empty")
        git("commit", "-q", "--allow-empty", "-m", "empty")
        for script in ("check-changelog-on-pr.py", "check-version-bump-on-pr.py",
                       "check-date-cobump-on-pr.py",
                       "check-narrative-corpus-mixed-diff-on-pr.py"):
            with self.subTest(gate=script):
                r = self._inject_oserror(REPO_ROOT / "tools" / script, tmp,
                                         ["rev-parse", "--verify", "feat-empty^{commit}"],
                                         "origin/main", "feat-empty", nth=2)
                self.assertEqual(r.stderr.count("INJECTED"), 1, r.stderr)
                self.assertEqual(r.returncode, 2,
                                 f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                self.assertNotIn("Traceback", r.stderr)
                self.assertIn("CANNOT-EVALUATE: refs were named but no files changed",
                              r.stderr)
                self.assertIn("head=feat-empty -> (head SHA unread)", r.stderr)
                self.assertIn(f"repo={tmp}", r.stderr)
                self.assertNotIn("OK", r.stdout)

    def _run_with_git_fault(self, script, cwd, k, kind, *args, env=None):
        """Run ``script`` with ``args`` in-process, subprocess.run (which
        check_output also calls) failing the ``k``-th git call only: OSError
        (EAGAIN) for ``oserror``; UnicodeDecodeError for ``decode``, injected
        only into a call that decodes text, the one place it can arise; exit
        status 128 for ``nonzero``; nothing for ``none``. stderr carries an
        INJECTED line naming the faulted call and a final ``GIT-CALLS <n>``
        line counting the run's git calls. A simulation of git failing, not
        a real fault (3b577 round 4, the r3 review's harness)."""
        import subprocess as sp

        driver = (
            "import errno, os, runpy, subprocess, sys\n"
            "k, kind = int(os.environ['FAULT_K']), os.environ['FAULT_KIND']\n"
            "seen = [0]\n"
            "real = subprocess.run\n"
            "def run(cmd, *a, **kw):\n"
            "    argv = [os.fsdecode(c) for c in cmd]\n"
            "    if argv[:1] != ['git']:\n"
            "        return real(cmd, *a, **kw)\n"
            "    seen[0] += 1\n"
            "    text = any(kw.get(n) for n in ('text', 'universal_newlines',\n"
            "                                   'encoding', 'errors'))\n"
            "    if seen[0] != k or kind == 'none' or (kind == 'decode' and not text):\n"
            "        return real(cmd, *a, **kw)\n"
            "    print('INJECTED', kind, ' '.join(argv), file=sys.stderr)\n"
            "    if kind == 'oserror':\n"
            "        raise OSError(errno.EAGAIN, 'injected')\n"
            "    if kind == 'decode':\n"
            "        raise UnicodeDecodeError('utf-8', b'\\xff', 0, 1, 'injected')\n"
            "    out = '' if text else b''\n"
            "    if kw.get('check'):\n"
            "        raise subprocess.CalledProcessError(128, cmd, output=out)\n"
            "    return subprocess.CompletedProcess(cmd, 128, out, out)\n"
            "subprocess.run = run\n"
            "sys.argv = sys.argv[1:]\n"
            "sys.path.insert(0, os.path.dirname(os.path.abspath(sys.argv[0])))\n"
            "try:\n"
            "    runpy.run_path(sys.argv[0], run_name='__main__')\n"
            "finally:\n"
            "    print('GIT-CALLS', seen[0], file=sys.stderr)\n"
        )
        return sp.run(
            [sys.executable, "-c", driver, str(script), *args],
            capture_output=True, text=True, cwd=str(cwd),
            env={**os.environ, **(env or {}), "FAULT_K": str(k), "FAULT_KIND": kind},
        )

    def test_d1_d2_d4_d11_d12_never_traceback_on_any_git_call_fault(self) -> None:
        # The gates whose git calls 3b577 changed are D1, D2, D4, D11 and D12,
        # walked here, and D15, walked by
        # test_d15_git_call_fault_never_reports_a_clean_or_altered_result; D3
        # and D7 share only the resolver, and their own git calls are neither
        # changed nor walked (backlog 3b591) (3b577 round 6).
        # 3b577 round 4 (r3 review, claude F3, class-wide): the r3 review
        # failed the k-th git call of D1, D2, D4 and D11 for every k and
        # found tracebacks (exit 1) on OSError and UnicodeDecodeError at the
        # merge-base call in lint_common.resolve_pr_range, each gate's git
        # diff and D4's git config reads. Walking the paths below reached
        # more at e41b151b4: D1's git log reads (the per-commit one on a
        # nonzero exit too), D2's git show reads and D4's git cat-file and
        # git log reads. Each now refuses with exit 2, never a traceback.
        # This walks every git call of each gate, D12 included, on a real
        # range (a versioned document bumped, the floor raised, CHANGELOG.md
        # untouched, so D1 reaches its git log reads and D2 and D4 their
        # blob reads), a
        # net-empty range (the empty_pr_range_message reads) and D12's
        # argless form, failing that one call with OSError, a decode error
        # where text is decoded, or exit 128. No run may print a traceback.
        # An OSError or a decode error must refuse (exit 2), except on the
        # top-level read some refusals only quote, which may keep the run's
        # real verdict; a nonzero exit is a documented answer at some sites
        # (the head-SHA read, which then echoes the ref name, say), so its
        # verdict is not pinned.
        tmp, git = self._repo()
        doc = tmp / "governance" / "doc.md"
        doc.parent.mkdir(parents=True, exist_ok=True)
        doc.write_text("# Doc\n\n**Version:** 1.0.0\\\n**Date:** 2026-01-01\n\nBody.\n",
                       encoding="utf-8")
        floor = tmp / "tools" / "todo-number-floor.json"
        floor.parent.mkdir(parents=True, exist_ok=True)
        floor.write_text('{"2": 32}\n', encoding="utf-8")
        git("add", "-A")
        git("commit", "-q", "-m", "versioned doc and floor")
        git("update-ref", "refs/remotes/origin/main", "HEAD")
        git("checkout", "-q", "-b", "feat-real")
        doc.write_text("# Doc\n\n**Version:** 1.0.1\\\n**Date:** 2026-01-02\n\nBody, more.\n",
                       encoding="utf-8")
        floor.write_text('{"2": 33}\n', encoding="utf-8")
        git("commit", "-q", "-am", "bump the doc and raise the floor")
        git("checkout", "-q", "-b", "feat-empty", "main")
        git("commit", "-q", "--allow-empty", "-m", "empty")
        git("checkout", "-q", "main")
        # The untracked file keeps D12's argless range non-collapsed, so the
        # run reaches the untracked listing and the floor reads.
        (tmp / "NEW.md").write_text("New.\n", encoding="utf-8")
        runs = [(script, args) for script in (
            "check-changelog-on-pr.py", "check-version-bump-on-pr.py",
            "check-date-cobump-on-pr.py", "check-narrative-corpus-mixed-diff-on-pr.py",
            "check-todo-floor-monotonic-on-pr.py",
        ) for args in (("origin/main", "feat-real"), ("origin/main", "feat-empty"))]
        runs.append(("check-todo-floor-monotonic-on-pr.py", ()))
        env = {"GITHUB_BASE_REF": "main"}
        for script, args in runs:
            path = REPO_ROOT / "tools" / script
            base = self._run_with_git_fault(path, tmp, 0, "none", *args, env=env)
            self.assertNotIn("Traceback", base.stderr, base.stderr)
            self.assertIn(base.returncode, (0, 1, 2), base.stderr)
            calls = int(base.stderr.rsplit("GIT-CALLS ", 1)[1].split()[0])
            self.assertGreater(calls, 2, base.stderr)
            for kind in ("oserror", "decode", "nonzero"):
                for k in range(1, calls + 1):
                    with self.subTest(gate=script, args=args, kind=kind, k=k):
                        r = self._run_with_git_fault(path, tmp, k, kind, *args, env=env)
                        out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                        self.assertNotIn("Traceback", r.stderr, out)
                        injected = [line for line in r.stderr.splitlines()
                                    if line.startswith("INJECTED ")]
                        if not injected:
                            # A decode fault only fits a call that decodes text.
                            self.assertEqual(kind, "decode", out)
                            self.assertEqual(r.returncode, base.returncode, out)
                            continue
                        self.assertEqual(len(injected), 1, out)
                        if kind == "nonzero":
                            self.assertIn(r.returncode, (0, 1, 2), out)
                        elif injected[0].endswith(" rev-parse --show-toplevel"):
                            self.assertIn(r.returncode, (base.returncode, 2), out)
                        else:
                            self.assertEqual(r.returncode, 2, out)

    def _inject_git_exit(self, script, cwd, prefix, *args, nth=1, env=None, status=128):
        """Run ``script`` with ``args`` in-process, subprocess.run (which
        check_output also calls) answering the ``nth`` git call whose
        arguments, after any leading ``-c <name>=<value>`` pairs, begin with
        ``prefix`` with exit status ``status`` (128 unless given; 3b577 round
        6) and no output instead of running it; stderr carries an INJECTED
        line naming that call. A simulation of a git read failing, not a
        real fault (3b577 round 5)."""
        import subprocess as sp

        driver = (
            "import json, os, runpy, subprocess, sys\n"
            "prefix = json.loads(os.environ['INJECT_PREFIX'])\n"
            "nth = int(os.environ['INJECT_NTH'])\n"
            "status = int(os.environ['INJECT_STATUS'])\n"
            "seen = [0]\n"
            "real = subprocess.run\n"
            "def run(cmd, *a, **kw):\n"
            "    argv = [os.fsdecode(c) for c in cmd]\n"
            "    rest = argv[1:]\n"
            "    while rest[:1] == ['-c']:\n"
            "        rest = rest[2:]\n"
            "    if argv[:1] != ['git'] or rest[:len(prefix)] != prefix:\n"
            "        return real(cmd, *a, **kw)\n"
            "    seen[0] += 1\n"
            "    if seen[0] != nth:\n"
            "        return real(cmd, *a, **kw)\n"
            "    print('INJECTED', ' '.join(argv), file=sys.stderr)\n"
            "    text = any(kw.get(n) for n in ('text', 'universal_newlines',\n"
            "                                   'encoding', 'errors'))\n"
            "    out = '' if text else b''\n"
            "    if kw.get('check') and status:\n"
            "        raise subprocess.CalledProcessError(status, cmd, output=out)\n"
            "    return subprocess.CompletedProcess(cmd, status, out, out)\n"
            "subprocess.run = run\n"
            "sys.argv = sys.argv[1:]\n"
            "sys.path.insert(0, os.path.dirname(os.path.abspath(sys.argv[0])))\n"
            "runpy.run_path(sys.argv[0], run_name='__main__')\n"
        )
        return sp.run(
            [sys.executable, "-c", driver, str(script), *args],
            capture_output=True, text=True, cwd=str(cwd),
            env={**os.environ, **(env or {}), "INJECT_PREFIX": json.dumps(prefix),
                 "INJECT_NTH": str(nth), "INJECT_STATUS": str(status)},
        )

    def _criss_cross_range(self):
        """A criss-cross history whose head makes a real change for every
        gate family on lint_common.resolve_pr_range (3b577 round 5). On
        _repo's root plus a versioned document, main commits A1 and feat
        commits B1; each side then merges the other's commit, so
        origin/main (main's merge) and feat have A1 and B1 as merge bases.
        feat then adds a CHANGELOG.md entry (D1, D3, D7), bumps the versioned
        document with its Date set to today's UTC date (D2, D4) and adds an
        unregistered citation to the corpus document (D11, D15). Returns
        (path, git runner, A1, B1)."""
        import datetime

        tmp, git = self._repo()
        doc = tmp / "governance" / "doc.md"
        doc.write_text("# Doc\n\n**Version:** 1.0.0\\\n**Date:** 2026-01-01\n\nBody.\n",
                       encoding="utf-8")
        git("add", "-A")
        git("commit", "-q", "-m", "versioned doc")
        git("update-ref", "refs/remotes/origin/main", "HEAD")
        git("branch", "feat")
        (tmp / "README.md").write_text("# Repo\n\nA1.\n", encoding="utf-8")
        git("commit", "-q", "-am", "A1")
        a1 = git("rev-parse", "HEAD")
        git("checkout", "-q", "feat")
        (tmp / "notes.txt").write_text("B1.\n", encoding="utf-8")
        git("add", "notes.txt")
        git("commit", "-q", "-m", "B1")
        b1 = git("rev-parse", "HEAD")
        git("checkout", "-q", "main")
        git("merge", "-q", "--no-edit", b1)
        git("update-ref", "refs/remotes/origin/main", "HEAD")
        git("checkout", "-q", "feat")
        git("merge", "-q", "--no-edit", a1)
        today = datetime.datetime.now(datetime.timezone.utc).date().isoformat()
        doc.write_text(f"# Doc\n\n**Version:** 1.0.1\\\n**Date:** {today}\n\nBody, more.\n",
                       encoding="utf-8")
        (tmp / "CHANGELOG.md").write_text("# Changelog\n\nNew entry.\n\nOld entry.\n",
                                          encoding="utf-8")
        (tmp / self.DOC_REL).write_text(self.DOC_HEAD, encoding="utf-8")
        git("commit", "-q", "-am", "feat: the change")
        return tmp, git, a1, b1

    def test_shared_resolver_refuses_a_criss_cross_range(self) -> None:
        # 3b577 round 5 (r4 report, outside its brief): resolve_pr_range ran
        # git merge-base without --all, so in a criss-cross history D1, D2,
        # D3, D4, D7, D11 and D15 diffed the head against git's single pick
        # of the two merge bases and gave that one's verdict (at 9255c0936
        # every gate below printed its verdict here). Each of them diffs
        # against one merge base, so the shared resolver now refuses more
        # than one, naming both: the strict gates with exit 2 and the
        # advisory D15 with its fail-open NOTE (exit 0). The control merges
        # origin/main into feat, the remedy the refusal names: the range then
        # has one merge base and every gate evaluates it.
        tmp, git, a1, b1 = self._criss_cross_range()
        self.assertEqual(sorted(git("merge-base", "--all", "origin/main", "feat").split()),
                         sorted([a1, b1]), "the fixture must have two merge bases")
        d15 = "check-alignment-register-on-pr.py"
        for script in (*self.STRICT_SHARED, d15):
            with self.subTest(gate=script):
                r = self._gate(script, tmp, "origin/main", "feat")
                out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                self.assertNotIn("Traceback", r.stderr, out)
                said = r.stdout if script == d15 else r.stderr
                self.assertEqual(r.returncode, 0 if script == d15 else 2, out)
                self.assertIn("origin/main and feat have 2 merge bases", said)
                self.assertIn(a1, said)
                self.assertIn(b1, said)
                self.assertIn("a criss-cross history", said)
                if script == d15:
                    self.assertIn("D15 NOTE: CANNOT-EVALUATE", r.stdout)
                    self.assertNotIn("D15 OK", r.stdout)
                    self.assertNotIn("D15 WARN", r.stdout)
                else:
                    self.assertIn("CANNOT-EVALUATE", r.stderr)
                    self.assertNotIn("OK", r.stdout)
        git("merge", "-q", "--no-edit", "origin/main")
        self.assertEqual(git("merge-base", "--all", "origin/main", "feat"),
                         git("rev-parse", "origin/main"))
        verdicts = {
            "check-changelog-on-pr.py": "OK: CHANGELOG.md is in the diff",
            "check-version-bump-on-pr.py": "OK: 1 changed versioned document(s)",
            "check-narrative-corpus-mixed-diff-on-pr.py": "OK: corpus document(s) changed",
            d15: "D15 WARN security/standard-example.md",
        }
        for script in (*self.STRICT_SHARED, d15):
            with self.subTest(gate=script, control="one merge base"):
                r = self._gate(script, tmp, "origin/main", "feat")
                out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                self.assertNotIn("Traceback", r.stderr, out)
                self.assertIn(r.returncode, (0, 1), out)
                self.assertNotIn("CANNOT-EVALUATE", r.stdout + r.stderr, out)
                self.assertNotIn("merge bases", r.stdout + r.stderr, out)
                if script in verdicts:
                    self.assertIn(verdicts[script], r.stdout, out)

    def test_shared_resolver_refuses_a_merge_base_run_that_prints_none(self) -> None:
        # 3b577 round 6 (r5 report, an untested branch): git merge-base --all
        # exits 1 with no output when base and head share no history, which
        # the resolver's CalledProcessError clause refuses; a run that exits
        # 0 and prints no merge base leaves the range just as undetermined,
        # so the resolver refuses it too, never indexing an empty list (a
        # traceback). The real git prints a merge base for this range, so
        # the read is injected to exit 0 with no output. D1, D2, D3, D4, D7
        # and D11 refuse with exit 2, and D15 with its fail-open NOTE (exit
        # 0); the control, the same harness injecting nothing, evaluates the
        # range in every gate.
        import datetime

        tmp, git = self._repo()
        doc = tmp / "governance" / "doc.md"
        doc.parent.mkdir(parents=True, exist_ok=True)
        doc.write_text("# Doc\n\n**Version:** 1.0.0\\\n**Date:** 2026-01-01\n\nBody.\n",
                       encoding="utf-8")
        git("add", "-A")
        git("commit", "-q", "-m", "versioned doc")
        git("update-ref", "refs/remotes/origin/main", "HEAD")
        git("checkout", "-q", "-b", "feat")
        today = datetime.datetime.now(datetime.timezone.utc).date().isoformat()
        doc.write_text(f"# Doc\n\n**Version:** 1.0.1\\\n**Date:** {today}\n\nBody, more.\n",
                       encoding="utf-8")
        (tmp / "CHANGELOG.md").write_text("# Changelog\n\nNew entry.\n\nOld entry.\n",
                                          encoding="utf-8")
        (tmp / self.DOC_REL).write_text(self.DOC_HEAD, encoding="utf-8")
        git("commit", "-q", "-am", "feat: the change")
        d15 = "check-alignment-register-on-pr.py"
        verdicts = {
            "check-changelog-on-pr.py": "OK: CHANGELOG.md is in the diff",
            "check-version-bump-on-pr.py": "OK: 1 changed versioned document(s)",
            "check-narrative-corpus-mixed-diff-on-pr.py": "OK: corpus document(s) changed",
            d15: "D15 WARN security/standard-example.md",
        }
        for script in (*self.STRICT_SHARED, d15):
            path = REPO_ROOT / "tools" / script
            with self.subTest(gate=script, control=True):
                r = self._inject_git_exit(path, tmp, ["no-such-call"], "origin/main", "feat")
                out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                self.assertNotIn("Traceback", r.stderr, out)
                self.assertIn(r.returncode, (0, 1), out)
                self.assertNotIn("CANNOT-EVALUATE", r.stdout + r.stderr, out)
                if script in verdicts:
                    self.assertIn(verdicts[script], r.stdout, out)
            with self.subTest(gate=script):
                r = self._inject_git_exit(path, tmp, ["merge-base", "--all"],
                                          "origin/main", "feat", status=0)
                out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                said = r.stdout if script == d15 else r.stderr
                self.assertEqual(r.stderr.count("INJECTED"), 1, out)
                self.assertNotIn("Traceback", r.stderr, out)
                self.assertEqual(r.returncode, 0 if script == d15 else 2, out)
                self.assertIn("CANNOT-EVALUATE: git merge-base --all origin/main feat "
                              "printed no merge base", said, out)
                if script == d15:
                    self.assertIn("D15 NOTE: CANNOT-EVALUATE", r.stdout, out)
                    self.assertNotIn("D15 OK", r.stdout, out)
                    self.assertNotIn("D15 WARN", r.stdout, out)
                else:
                    self.assertNotIn("OK", r.stdout, out)

    def test_failed_blob_or_log_read_refuses_never_reads_absent(self) -> None:
        # 3b577 round 5 (r4 report, outside its brief): D2's git_show, D4's
        # blob_at and D4's bump-date git log read every nonzero git exit as
        # "absent at that revision" or "no range commit touched the file"
        # and skipped it, so a read that failed passed the file unchecked: at
        # 9255c0936 each git show, cat-file and git log fault below gave a
        # clean OK (exit 0), D4's over a stale Date its control FAILs. Absence
        # is now git's own answer only -- git ls-tree listing no entry, git
        # log exiting 0 with no output -- and any other failure, the listing's
        # own included, refuses with exit 2. governance/new.md, which the head
        # adds, is absent at the merge base by git's own answer, so it reads
        # as an added file in the control and is never named.
        tmp, git = self._repo()
        doc = tmp / "governance" / "doc.md"
        doc.write_text("# Doc\n\n**Version:** 1.0.0\\\n**Date:** 2026-01-01\n\nBody.\n",
                       encoding="utf-8")
        git("add", "-A")
        git("commit", "-q", "-m", "versioned doc")
        git("update-ref", "refs/remotes/origin/main", "HEAD")
        git("checkout", "-q", "-b", "feat")
        # Version bumped with the Date left stale: D2 passes it, D4 FAILs it.
        doc.write_text("# Doc\n\n**Version:** 1.0.1\\\n**Date:** 2026-01-01\n\nBody, more.\n",
                       encoding="utf-8")
        (tmp / "governance" / "new.md").write_text(
            "# New\n\n**Version:** 1.0.0\\\n**Date:** 2026-01-01\n\nNew.\n", encoding="utf-8")
        git("add", "-A")
        git("commit", "-q", "-m", "bump doc.md, add new.md")
        d2 = REPO_ROOT / "tools" / "check-version-bump-on-pr.py"
        d4 = REPO_ROOT / "tools" / "check-date-cobump-on-pr.py"
        for script, rc, verdict in ((d2, 0, "OK: 1 changed versioned document(s)"),
                                    (d4, 1, "FAIL governance/doc.md: Version bumped")):
            with self.subTest(gate=script.name, control=True):
                r = self._gate(script.name, tmp, "origin/main", "feat")
                out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                self.assertEqual(r.returncode, rc, out)
                self.assertIn(verdict, r.stdout + r.stderr, out)
                self.assertNotIn("new.md", r.stdout + r.stderr, out)
        for script, prefix, nth, phrase in (
            (d2, ["ls-tree"], 1, "ERROR: git show failed for governance/doc.md"),
            (d2, ["show"], 1, "ERROR: git show failed for governance/doc.md"),
            (d2, ["show"], 2, "ERROR: git show failed for governance/doc.md"),
            (d4, ["ls-tree"], 1, "ERROR: git cat-file failed for governance/doc.md"),
            (d4, ["cat-file", "blob"], 1, "ERROR: git cat-file failed for governance/doc.md"),
            (d4, ["cat-file", "blob"], 2, "ERROR: git cat-file failed for governance/doc.md"),
            (d4, ["log", "-1"], 1, "ERROR: git log failed for governance/doc.md"),
        ):
            with self.subTest(gate=script.name, call=prefix, nth=nth):
                r = self._inject_git_exit(script, tmp, prefix, "origin/main", "feat", nth=nth)
                out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                self.assertEqual(r.stderr.count("INJECTED"), 1, out)
                self.assertEqual(r.returncode, 2, out)
                self.assertIn(phrase, r.stderr, out)
                self.assertNotIn("Traceback", r.stderr, out)
                self.assertNotIn("OK", r.stdout, out)

    def test_md_gitlink_reads_as_absent_never_as_a_failed_read(self) -> None:
        # 3b577 round 6 (r5 reviews, codex ERROR and claude W1): round 5's
        # git_show_strict ran git show on every entry git ls-tree listed, and
        # git show cannot read a gitlink whose commit the repository does not
        # hold (exit 128), so at 5741f435d D2 refused (exit 2) a PR that adds,
        # updates, deletes or converts to a gitlink the .md path
        # security/sub.md; D15 printed its fail-open NOTE in place of its
        # WARN when the PR leaves that gitlink at the head, and its sibling
        # probe skipped its listing over a .md gitlink the head keeps
        # unchanged. A listed entry that is not a blob is no file, so it
        # now reads as absent, as D4's blob_at reads it, and the probe lists
        # only blobs: each PR below gets D2's OK and D15's WARN and probe
        # listing (exit 0). A listed blob whose read fails still refuses in
        # D2 (exit 2) and skips D15's check with a NOTE.
        reg = AlignmentRegisterOnPrTests
        sub = "security/sub.md"
        g1, g2 = "1" * 40, "2" * 40
        document = "# Sub\n\nA document before it became a submodule.\n"

        def build(at_base, at_head):
            tmp, git = self._repo()

            def put(value):
                # sub.md as absent (None), a document (text) or a gitlink to a
                # commit the repository does not hold (an object id). git add
                # -A never runs while a gitlink is staged: its path has no
                # directory in the work tree, which would stage it as deleted.
                git("rm", "-q", "--cached", "--ignore-unmatch", sub)
                (tmp / sub).unlink(missing_ok=True)
                if value is None:
                    return
                if value.startswith("#"):
                    (tmp / sub).write_text(value, encoding="utf-8")
                    git("add", sub)
                else:
                    git("update-index", "--add", "--cacheinfo", f"160000,{value},{sub}")

            aliases = tmp / reg.ALIASES
            aliases.parent.mkdir(parents=True, exist_ok=True)
            doc = tmp / "governance" / "doc.md"
            doc.parent.mkdir(parents=True, exist_ok=True)
            (tmp / self.REGISTER_REL).write_text(reg._register(reg, reg.TSA_ROWS),
                                                 encoding="utf-8")
            aliases.write_text(reg._aliases("TSA Pipeline Security Directives"),
                               encoding="utf-8")
            (tmp / self.DOC_REL).write_text(reg._doc(*reg.SIBLING_DOC), encoding="utf-8")
            doc.write_text("# Doc\n\n**Version:** 1.0.0\\\n**Date:** 2026-01-01\n\nBody.\n",
                           encoding="utf-8")
            git("add", "-A")
            put(at_base)
            git("commit", "-q", "-m", "register, aliases, corpus and sub.md")
            git("update-ref", "refs/remotes/origin/main", "HEAD")
            git("checkout", "-q", "-b", "feat")
            aliases.write_text(reg._aliases("TSA Pipeline Security Directives",
                                            "US TSA Pipeline Security Directives"),
                               encoding="utf-8")
            (tmp / "security" / "other.md").write_text(
                reg._doc("| NIST SP 800-57 Part 1 Rev. 5 | Key management | Keys |"),
                encoding="utf-8")
            doc.write_text("# Doc\n\n**Version:** 1.0.1\\\n**Date:** 2026-01-01\n\nBody, more.\n",
                           encoding="utf-8")
            git("add", reg.ALIASES, "security/other.md", "governance/doc.md")
            put(at_head)
            git("commit", "-q", "-m", "alias key, an unregistered citation, a bump and sub.md")
            want = [] if at_head is None else ["blob" if at_head.startswith("#") else "commit"]
            self.assertEqual(git("ls-tree", "feat", "--", sub).split()[1:2], want,
                             "the fixture must list sub.md as built")
            return tmp

        def lines(out, start):
            return [line for line in out.splitlines() if line.startswith(start)]

        d2 = REPO_ROOT / "tools" / "check-version-bump-on-pr.py"
        d15 = REPO_ROOT / "tools" / "check-alignment-register-on-pr.py"
        for pr, at_base, at_head in (
            ("adds a gitlink", None, g1),
            ("updates a gitlink", g1, g2),
            ("deletes a gitlink", g1, None),
            ("converts a document to a gitlink", document, g1),
            ("keeps a gitlink unchanged", g1, g1),
        ):
            tmp = build(at_base, at_head)
            with self.subTest(pr=pr, gate="D2"):
                r = self._gate(d2.name, tmp, "origin/main", "feat")
                out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                self.assertEqual(r.returncode, 0, out)
                self.assertIn("OK: 1 changed versioned document(s)", r.stdout, out)
                self.assertNotIn("ERROR", r.stderr, out)
                self.assertNotIn("Traceback", r.stderr, out)
            with self.subTest(pr=pr, gate="D15"):
                r = self._gate(d15.name, tmp, "origin/main", "feat")
                out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                self.assertEqual(r.returncode, 0, out)
                warns = lines(r.stdout, "D15 WARN ")
                self.assertEqual(len(warns), 1, out)
                self.assertIn("security/other.md", warns[0], out)
                self.assertIn("D15 SIBLING-PROBE: 1 unregistered", r.stdout, out)
                self.assertNotIn("D15 NOTE", r.stdout, out)
                self.assertNotIn("D15 OK", r.stdout, out)
            # A git show of a listed blob: D2's first, governance/doc.md at
            # the merge base, and D15's second, after its register read,
            # governance/doc.md at the head.
            for script, nth, rc, phrase in (
                (d2, 1, 2, "ERROR: git show failed for governance/doc.md"),
                (d15, 2, 0, "D15 NOTE: cannot read governance/doc.md at feat"),
            ):
                with self.subTest(pr=pr, gate=script.name, failed_read=nth):
                    r = self._inject_git_exit(script, tmp, ["show"], "origin/main", "feat",
                                              nth=nth)
                    out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                    self.assertEqual(r.stderr.count("INJECTED"), 1, out)
                    self.assertEqual(r.returncode, rc, out)
                    self.assertIn(phrase, r.stdout + r.stderr, out)
                    self.assertNotIn("Traceback", r.stderr, out)
                    self.assertNotIn("OK", r.stdout, out)
                    self.assertNotIn("D15 WARN", r.stdout, out)

    def test_partial_clone_config_read_failure_declines(self) -> None:
        # 3b577 round 5 (the preflight aid's shared helper path):
        # promisor_remote_reason, which D4 runs and preflight-version-date.py
        # shares (passing its own git wrapper), read every nonzero git config
        # exit as "not set", so a config read that failed passed as "not a
        # partial clone" and both went on to read blobs (exit 0 here at
        # 9255c0936). The failure is injected at the config read alone. With
        # git 2.53, a config file git cannot parse (exit 128) reaches this
        # read in the aid, whose MERGE_HEAD and unmerged-index reads pass
        # over a failed read, but D4's merge-base read refuses on it first;
        # and a bad value only some commands parse, such as
        # log.showSignature=notabool, leaves git config at exit 1 and fails
        # git log and git show instead (3b577 round 6).
        # Exit 1 is git config's own "not set" answer, which the real git
        # gives in each control; any other nonzero exit now declines (exit 2).
        tmp, git = self._repo()
        doc = tmp / "governance" / "doc.md"
        doc.write_text("# Doc\n\n**Version:** 1.0.0\\\n**Date:** 2026-01-01\n\nBody.\n",
                       encoding="utf-8")
        git("add", "-A")
        git("commit", "-q", "-m", "versioned doc")
        git("update-ref", "refs/remotes/origin/main", "HEAD")
        git("checkout", "-q", "-b", "feat")
        (tmp / "README.md").write_text("# Repo\n\nMore.\n", encoding="utf-8")
        git("commit", "-q", "-am", "docs only")
        # A staged bump dated "today" for the aid, which reads the index.
        doc.write_text("# Doc\n\n**Version:** 1.0.1\\\n**Date:** 2026-06-26\n\nBody, more.\n",
                       encoding="utf-8")
        git("add", "-A")
        d4 = (REPO_ROOT / "tools" / "check-date-cobump-on-pr.py", ("origin/main", "feat"),
              "OK: 0 document(s) bumped Version")
        aid = (REPO_ROOT / "tools" / "preflight-version-date.py", ("--base", "origin/main"),
               "OK: every staged document")
        env = {"PREFLIGHT_VD_TODAY": "2026-06-26"}
        for script, args, verdict in (d4, aid):
            with self.subTest(tool=script.name, control=True):
                r = self._inject_git_exit(script, tmp, ["no-such-call"], *args, env=env)
                out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                self.assertEqual(r.returncode, 0, out)
                self.assertIn(verdict, r.stdout, out)
            for prefix, call in (
                (["config", "--get", "extensions.partialClone"],
                 "git config --get extensions.partialClone failed (exit 128)"),
                (["config", "--get-regexp"],
                 "git config --get-regexp remote.*.promisor failed (exit 128)"),
            ):
                with self.subTest(tool=script.name, call=prefix):
                    r = self._inject_git_exit(script, tmp, prefix, *args, env=env)
                    out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                    self.assertEqual(r.stderr.count("INJECTED"), 1, out)
                    self.assertEqual(r.returncode, 2, out)
                    self.assertIn(call, r.stderr, out)
                    self.assertIn("cannot read partial-clone config reliably", r.stderr, out)
                    self.assertNotIn("Traceback", r.stderr, out)
                    self.assertNotIn("OK", r.stdout, out)

    def test_d15_git_call_fault_never_reports_a_clean_or_altered_result(self) -> None:
        # 3b577 round 5 (D15's own git call sites): main() turns any exception
        # into the fail-open NOTE (exit 0), so no fault tracebacks, but four
        # reads took a nonzero exit as an answer. The per-file diff and head
        # read took it as "deleted in the PR" (at 9255c0936 that printed a
        # clean "D15 OK" over a head whose added citation WARNs), the register
        # read as "absent", and the sibling probe's reads as an absent alias
        # file or register, or dropped a corpus document from its scan (an
        # altered listing). This walks every git call D15 makes on a range
        # that adds an unregistered citation and an alias key, failing that
        # one call with OSError, a decode error where text is decoded, or exit
        # 128. Every run exits 0 with no traceback, no "D15 OK" and no absent
        # register; its WARN lines are the control's or a NOTE says the check
        # was skipped; and its probe listing is the control's or a NOTE says
        # the probe did not run.
        reg = AlignmentRegisterOnPrTests
        tmp, git = self._repo()
        aliases = tmp / reg.ALIASES
        aliases.parent.mkdir(parents=True, exist_ok=True)
        (tmp / self.REGISTER_REL).write_text(reg._register(reg, reg.TSA_ROWS), encoding="utf-8")
        aliases.write_text(reg._aliases("TSA Pipeline Security Directives"), encoding="utf-8")
        (tmp / self.DOC_REL).write_text(reg._doc(*reg.SIBLING_DOC), encoding="utf-8")
        git("add", "-A")
        git("commit", "-q", "-m", "register, aliases and corpus")
        git("update-ref", "refs/remotes/origin/main", "HEAD")
        git("checkout", "-q", "-b", "feat")
        aliases.write_text(reg._aliases("TSA Pipeline Security Directives",
                                        "US TSA Pipeline Security Directives"), encoding="utf-8")
        (tmp / "security" / "other.md").write_text(
            reg._doc("| NIST SP 800-57 Part 1 Rev. 5 | Key management | Keys |"),
            encoding="utf-8")
        git("add", "-A")
        git("commit", "-q", "-m", "alias key and an unregistered citation")
        path = REPO_ROOT / "tools" / "check-alignment-register-on-pr.py"
        args = ("origin/main", "feat")

        def lines(out, start):
            return [line for line in out.splitlines() if line.startswith(start)]

        base = self._run_with_git_fault(path, tmp, 0, "none", *args)
        self.assertEqual(base.returncode, 0, base.stderr)
        warns = lines(base.stdout, "D15 WARN ")
        siblings = lines(base.stdout, "D15 SIBLING")
        self.assertEqual(len(warns), 1, base.stdout)
        self.assertIn("security/other.md", warns[0])
        self.assertIn("D15 SIBLING-PROBE: 1 unregistered", base.stdout)
        self.assertNotIn("D15 OK", base.stdout)
        self.assertNotIn("D15 NOTE", base.stdout)
        calls = int(base.stderr.rsplit("GIT-CALLS ", 1)[1].split()[0])
        self.assertGreater(calls, 10, base.stderr)
        for kind in ("oserror", "decode", "nonzero"):
            for k in range(1, calls + 1):
                with self.subTest(kind=kind, k=k):
                    r = self._run_with_git_fault(path, tmp, k, kind, *args)
                    out = f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}"
                    self.assertNotIn("Traceback", r.stderr, out)
                    self.assertEqual(r.returncode, 0, out)
                    if not any(line.startswith("INJECTED ") for line in r.stderr.splitlines()):
                        # A decode fault only fits a call that decodes text.
                        self.assertEqual(kind, "decode", out)
                        self.assertEqual(r.stdout, base.stdout, out)
                        continue
                    self.assertNotIn("D15 OK", r.stdout, out)
                    # The register is present at feat: a failed read is never "absent".
                    self.assertNotIn("is absent at", r.stdout, out)
                    noted = bool(lines(r.stdout, "D15 NOTE: "))
                    if lines(r.stdout, "D15 WARN ") != warns:
                        self.assertTrue(noted, out)
                    if lines(r.stdout, "D15 SIBLING") != siblings:
                        self.assertTrue(noted, out)
                        self.assertNotIn("D15 SIBLING-PROBE:", r.stdout, out)

    NO_WORK_TREE_GATES = (
        ("check-todo-rotation-on-pr.py", "OK:"),
        ("check-retired-section-orphan-on-pr.py", "D9 OK"),
        ("check-stranded-control-code-on-pr.py", "D13 OK"),
        ("tension-scan.py", "rewritten block"),
    )

    def _retire_and_cite(self):
        """The fixture of _no_work_tree_env and the 3b564 tests: branch feat
        deletes TODO row 9.99 and commits tools/x.py citing it, so D9's real
        verdict on main..feat is FAIL. Returns (path, git runner), checked out
        at feat."""
        tmp, git = self._repo()
        rows = "# TODO\n\n## Priority 1\n\n| 9.98 | Keep | x |\n"
        (tmp / "TODO.md").write_text(rows + "| 9.99 | Retire | x |\n", encoding="utf-8")
        git("add", "-A")
        git("commit", "-q", "-m", "TODO rows")
        git("checkout", "-q", "-b", "feat")
        (tmp / "TODO.md").write_text(rows, encoding="utf-8")
        (tmp / "tools").mkdir()
        (tmp / "tools" / "x.py").write_text("# see §9.99 for detail\n", encoding="utf-8")
        git("add", "-A")
        git("commit", "-q", "-m", "retire 9.99 and cite it")
        return tmp, git

    def _no_work_tree_env(self):
        """``(holder, env)`` for a run with no work tree: ``env`` names, in
        GIT_DIR, a bare clone (in ``holder``) of a head that deletes TODO row
        9.99 and commits a file citing it. The control, D9 run from a normal
        checkout of that head, FAILs (3b540 round 9)."""
        import subprocess as sp

        tmp, git = self._retire_and_cite()
        d9 = "check-retired-section-orphan-on-pr.py"
        for name in ("lint_common.py", d9):
            (tmp / "tools" / name).write_bytes((REPO_ROOT / "tools" / name).read_bytes())
        r = sp.run([sys.executable, str(tmp / "tools" / d9), "main", "feat"],
                   capture_output=True, text=True, cwd=str(tmp))
        self.assertEqual(r.returncode, 1, f"control:\nstdout:\n{r.stdout}\nstderr:\n{r.stderr}")
        self.assertIn("LIVE orphan reference(s) to section(s) this PR retired (9.99)", r.stderr)

        holder = Path(tempfile.mkdtemp(prefix="no-work-tree-")).resolve()
        self.addCleanup(shutil.rmtree, holder, ignore_errors=True)
        bare = holder / "repo.git"
        sp.run(["git", "clone", "-q", "--bare", str(tmp), str(bare)],
               check=True, capture_output=True)
        env = {k: v for k, v in os.environ.items() if k != "GIT_WORK_TREE"}
        env["GIT_DIR"] = str(bare)
        return holder, env

    def test_no_work_tree_refuses_exit2(self) -> None:
        # 3b540 round 9 (r8 review WARN-1): git refusing the top-level read
        # because there is no work tree (GIT_DIR naming a bare repository) is
        # a refusal, exit 2, as before round 8, not a placeholder. D9's orphan
        # scan reads the working tree, so without one it scanned this
        # checkout instead of the head and printed "D9 OK" for a head that
        # deletes TODO row 9.99 and commits a file citing it; the control, a
        # normal checkout of the same head, FAILs. At round 8 D5, D9, D13 and
        # tension-scan all exited 0 here.
        import subprocess as sp

        holder, env = self._no_work_tree_env()
        for script, clean in self.NO_WORK_TREE_GATES:
            with self.subTest(gate=script):
                r = sp.run([sys.executable, str(REPO_ROOT / "tools" / script), "main", "feat"],
                           capture_output=True, text=True, cwd=str(holder), env=env)
                self.assertEqual(r.returncode, 2, f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                self.assertIn("work tree", r.stderr)
                self.assertNotIn("Traceback", r.stderr)
                self.assertNotIn(clean, r.stdout)

    def test_pre_2_25_empty_toplevel_refuses_exit2(self) -> None:
        # 3b559: before git 2.25, rev-parse --show-toplevel printed nothing
        # and exited 0 outside a work tree, so the refusal above held only on
        # git 2.25 or later. The PATH shim delegates to the real git and, when
        # the real --show-toplevel read fails, prints nothing and exits 0 as
        # that older git did, marking that it fired. Without the empty-result
        # check D5, D9, D13 and tension-scan each printed their clean verdict
        # (exit 0) here, D9's "D9 OK" over the head the control FAILs; each
        # now refuses with exit 2. Mutation killed: dropping the empty-result
        # check from any one of the four.
        import subprocess as sp

        real_git = shutil.which("git")
        self.assertIsNotNone(real_git)
        holder, env = self._no_work_tree_env()
        shim_dir = Path(tempfile.mkdtemp(prefix="gitshim-")).resolve()
        self.addCleanup(shutil.rmtree, shim_dir, ignore_errors=True)
        shim = shim_dir / "git"
        fired = shim_dir / "fired"
        shim.write_text(
            "#!/bin/sh\n"
            'for a in "$@"; do\n'
            '  if [ "$a" = "--show-toplevel" ]; then\n'
            f'    "{real_git}" "$@" 2>/dev/null && exit 0\n'
            f'    : > "{fired}"\n'
            "    exit 0\n"
            "  fi\n"
            "done\n"
            f'exec "{real_git}" "$@"\n',
            encoding="utf-8",
        )
        shim.chmod(0o755)
        env["PATH"] = f"{shim_dir}{os.pathsep}{env['PATH']}"
        for script, clean in self.NO_WORK_TREE_GATES:
            with self.subTest(gate=script):
                fired.unlink(missing_ok=True)
                r = sp.run([sys.executable, str(REPO_ROOT / "tools" / script), "main", "feat"],
                           capture_output=True, text=True, cwd=str(holder), env=env)
                self.assertTrue(fired.exists(), "the shim never emulated the empty top level")
                self.assertEqual(r.returncode, 2, f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                self.assertIn("printed an empty top level (no work tree)", r.stderr)
                self.assertNotIn("Traceback", r.stderr)
                self.assertNotIn(clean, r.stdout)

    def _assert_real_verdicts(self, tools, cwd, base, head, env=None, label=""):
        import subprocess as sp

        for script, rc, verdict, _clean in self.OWN_TOP_GATES:
            with self.subTest(gate=script, run=label):
                r = sp.run([sys.executable, str(tools / script), base, head],
                           capture_output=True, text=True, cwd=str(cwd), env=env)
                self.assertEqual(r.returncode, rc, f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                self.assertIn(verdict, r.stdout + r.stderr)
                self.assertNotIn("not this script's repository", r.stderr)

    def test_foreign_work_tree_refuses_exit2(self) -> None:
        # 3b564: GIT_DIR naming a bare clone of the head plus GIT_WORK_TREE
        # naming another directory gives git a work tree, so the top-level
        # read succeeds, but it names that directory, not the script's
        # repository. D9 then scanned this checkout and printed "D9 OK" over
        # a head whose own control run FAILs (git 2.53); D5, D13 and
        # tension-scan printed their clean passes. Each gate now refuses with
        # exit 2 unless the top level resolves to its own REPO_ROOT. Mutation
        # killed: dropping the REPO_ROOT comparison from any one gate.
        import subprocess as sp

        tmp, git = self._retire_and_cite()
        self._assert_real_verdicts(self._own_copies(tmp / "tools"), tmp, "main", "feat",
                                   label="control")
        holder = Path(tempfile.mkdtemp(prefix="foreign-work-tree-")).resolve()
        self.addCleanup(shutil.rmtree, holder, ignore_errors=True)
        bare = holder / "repo.git"
        sp.run(["git", "clone", "-q", "--bare", str(tmp), str(bare)],
               check=True, capture_output=True)
        elsewhere = holder / "elsewhere"
        elsewhere.mkdir()
        env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
        env.update(GIT_DIR=str(bare), GIT_WORK_TREE=str(elsewhere))
        for script, _rc, _verdict, clean in self.OWN_TOP_GATES:
            with self.subTest(gate=script):
                r = sp.run([sys.executable, str(REPO_ROOT / "tools" / script), "main", "feat"],
                           capture_output=True, text=True, cwd=str(holder), env=env)
                self.assertEqual(r.returncode, 2, f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                self.assertIn("not this script's repository", r.stderr)
                self.assertIn(str(elsewhere), r.stderr)
                self.assertNotIn("Traceback", r.stderr)
                self.assertNotIn(clean, r.stdout)

    def test_own_git_dir_other_work_tree_refuses_exit2(self) -> None:
        # 3b564 (r1 review W1, W2): with GIT_DIR naming the gate's own
        # repository, so the git-directory check passes, GIT_WORK_TREE at a
        # subdirectory of REPO_ROOT, at its parent, at REPO_ROOT + "-x", or
        # at a directory whose name is not valid UTF-8 is a top level other
        # than REPO_ROOT, and each gate's own copy refuses it with exit 2. At
        # round 1 the last skipped the comparison (a placeholder replaced a
        # top level the strict decode refused), so all four exited 0.
        # Mutations killed, in any one gate: also accepting a top level
        # inside REPO_ROOT, an ancestor of it, or a path that merely starts
        # with it; and reading the top level as strict text with the
        # placeholder again.
        import subprocess as sp

        tmp, git = self._retire_and_cite()
        tools = self._own_copies(tmp / "tools")
        holder = Path(tempfile.mkdtemp(prefix="own-git-dir-")).resolve()
        self.addCleanup(shutil.rmtree, holder, ignore_errors=True)
        prefix = Path(str(tmp) + "-x")
        self.addCleanup(shutil.rmtree, prefix, ignore_errors=True)
        cases = [("subdirectory", tmp / "sub"), ("parent", tmp.parent), ("prefix", prefix)]
        undecodable = os.path.join(os.fsencode(holder), b"elsewhere-\xff")
        try:
            os.mkdir(undecodable)
        except OSError:
            pass  # the filesystem refuses the name; the other cases still run
        else:
            cases.append(("not UTF-8", Path(os.fsdecode(undecodable))))
        (tmp / "sub").mkdir()
        prefix.mkdir()
        base_env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
        for label, work_tree in cases:
            env = dict(base_env, GIT_DIR=str(tmp / ".git"), GIT_WORK_TREE=str(work_tree))
            for script, _rc, _verdict, clean in self.OWN_TOP_GATES:
                with self.subTest(gate=script, work_tree=label):
                    r = sp.run([sys.executable, str(tools / script), "main", "feat"],
                               capture_output=True, cwd=str(tmp), env=env,
                               encoding="utf-8", errors="backslashreplace")
                    self.assertEqual(r.returncode, 2, f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                    self.assertIn("work tree top level", r.stderr)
                    self.assertIn("not this script's repository", r.stderr)
                    self.assertNotIn("Traceback", r.stderr)
                    self.assertNotIn(clean, r.stdout)

    def test_foreign_git_dir_refuses_exit2(self) -> None:
        # 3b564 (r1 review E1): GIT_DIR naming another repository while git's
        # top level is still the gate's own REPO_ROOT passes the top-level
        # comparison: a non-bare foreign GIT_DIR alone (git takes the current
        # directory, or -C REPO_ROOT, as the top level), a bare GIT_DIR plus
        # GIT_WORK_TREE=REPO_ROOT, and a foreign GIT_DIR whose own
        # core.worktree is REPO_ROOT. REPO_ROOT here is a checkout of main,
        # without the citing file, so D9 read its range from the foreign
        # repository, scanned REPO_ROOT and printed "D9 OK" over a head whose
        # own control run FAILs; D5, D13 and tension-scan printed their clean
        # passes. Run from REPO_ROOT, each gate now refuses with exit 2
        # through lint_common.require_own_git_dir. Mutation killed: dropping
        # that call from any one gate.
        import subprocess as sp

        tmp, git = self._retire_and_cite()
        tools = self._own_copies(tmp / "tools")
        self._assert_real_verdicts(tools, tmp, "main", "feat", label="control")
        holder = Path(tempfile.mkdtemp(prefix="foreign-git-dir-")).resolve()
        self.addCleanup(shutil.rmtree, holder, ignore_errors=True)
        bare = holder / "repo.git"
        sp.run(["git", "clone", "-q", "--bare", str(tmp), str(bare)],
               check=True, capture_output=True)
        for name in ("clone", "configured"):
            sp.run(["git", "clone", "-q", str(tmp), str(holder / name)],
                   check=True, capture_output=True)
            git("branch", "-q", "main", "origin/main", cwd=holder / name)
        git("config", "core.worktree", str(tmp), cwd=holder / "configured")
        git("checkout", "-q", "main")
        base_env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
        for label, git_dir, extra in (
            ("non-bare GIT_DIR alone", holder / "clone" / ".git", {}),
            ("bare GIT_DIR plus GIT_WORK_TREE", bare, {"GIT_WORK_TREE": str(tmp)}),
            ("GIT_DIR with core.worktree", holder / "configured" / ".git", {}),
        ):
            env = dict(base_env, GIT_DIR=str(git_dir), **extra)
            for script, _rc, _verdict, clean in self.OWN_TOP_GATES:
                with self.subTest(gate=script, setup=label):
                    r = sp.run([sys.executable, str(tools / script), "main", "feat"],
                               capture_output=True, text=True, cwd=str(tmp), env=env)
                    self.assertEqual(r.returncode, 2, f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                    self.assertIn(f"git reads the git directory {str(git_dir)!r}", r.stderr)
                    self.assertNotIn("work tree top level", r.stderr)
                    self.assertNotIn("Traceback", r.stderr)
                    self.assertNotIn(clean, r.stdout)

    def test_linked_worktree_hook_git_dir(self) -> None:
        # 3b564 (r1 review E1): git exports GIT_DIR, naming the worktree's
        # own git directory, to the hooks of a linked worktree. D9 and D13
        # anchor git to their own REPO_ROOT with -C, so the main checkout's
        # copies still read a top level of REPO_ROOT there while git read
        # the worktree's refs, and the main checkout's D9 printed "D9 OK"
        # over a head whose own control run FAILs. A real pre-commit hook in
        # the worktree runs both trees' copies: the main checkout's refuse
        # with exit 2 (D9 and D13 through require_own_git_dir; D5 and
        # tension-scan run git from the hook's directory, the worktree, so
        # their top-level comparison refuses too), and the worktree's own
        # copies keep their real verdicts. Mutation killed: dropping the
        # require_own_git_dir call from D9 or D13.
        import subprocess as sp

        tmp, git = self._retire_and_cite()
        main_tools = self._own_copies(tmp / "tools")
        wt = Path(str(tmp) + "-wt")
        self.addCleanup(shutil.rmtree, wt, ignore_errors=True)
        git("worktree", "add", "-q", "-b", "feat-wt", str(wt), "feat")
        wt_tools = self._own_copies(wt / "tools")
        git("checkout", "-q", "main")
        holder = Path(tempfile.mkdtemp(prefix="worktree-hook-")).resolve()
        self.addCleanup(shutil.rmtree, holder, ignore_errors=True)
        results = holder / "results.json"
        runs = [(where, str(tools / g[0])) for where, tools in
                (("main checkout", main_tools), ("worktree", wt_tools)) for g in self.OWN_TOP_GATES]
        hook = holder / "hooks" / "pre-commit"
        hook.parent.mkdir()
        hook.write_text(
            f"#!{sys.executable} -I\n"
            "import json, os, subprocess, sys\n"
            "out = {'GIT_DIR': os.environ.get('GIT_DIR'), 'runs': []}\n"
            f"for where, script in {runs!r}:\n"
            "    r = subprocess.run([sys.executable, script, 'main', 'feat-wt'],\n"
            "                       capture_output=True, text=True)\n"
            "    out['runs'].append([where, os.path.basename(script), r.returncode,\n"
            "                        r.stdout, r.stderr])\n"
            f"with open({str(results)!r}, 'w', encoding='utf-8') as fh:\n"
            "    json.dump(out, fh)\n",
            encoding="utf-8",
        )
        hook.chmod(0o755)
        git("config", "core.hooksPath", str(hook.parent))
        env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
        sp.run(["git", "-C", str(wt), "commit", "-q", "--allow-empty", "-m", "hook run"],
               check=True, capture_output=True, env=env)
        out = json.loads(results.read_text(encoding="utf-8"))
        self.assertIsNotNone(out["GIT_DIR"], "git exported no GIT_DIR to the worktree's hook")
        self.assertEqual((wt / out["GIT_DIR"]).resolve(),
                         Path(git("rev-parse", "--absolute-git-dir", cwd=wt)).resolve())
        self.assertEqual(len(out["runs"]), 2 * len(self.OWN_TOP_GATES))
        expected = {g[0]: g for g in self.OWN_TOP_GATES}
        for where, script, rc, stdout, stderr in out["runs"]:
            _script, real_rc, verdict, clean = expected[script]
            with self.subTest(gate=script, copy=where):
                if where == "main checkout":
                    self.assertEqual(rc, 2, f"stdout:\n{stdout}\nstderr:\n{stderr}")
                    self.assertNotIn(clean, stdout)
                    self.assertNotIn("Traceback", stderr)
                    if script in ("check-retired-section-orphan-on-pr.py",
                                  "check-stranded-control-code-on-pr.py"):
                        self.assertIn("git reads the git directory", stderr)
                else:
                    self.assertEqual(rc, real_rc, f"stdout:\n{stdout}\nstderr:\n{stderr}")
                    self.assertIn(verdict, stdout + stderr)
                    self.assertNotIn("not this script's repository", stderr)

    def test_relative_or_empty_toplevel_refuses_exit2(self) -> None:
        # 3b564: a top level that is relative was accepted as long as git
        # exited 0. A shim git prints one for rev-parse --show-toplevel (and
        # delegates every other call), with each gate run as its own copy
        # from its own top level, so only the reported top level is wrong.
        # "." and "elsewhere" resolve against the current directory, here
        # the gate's own REPO_ROOT for ".", so the comparison alone would
        # accept it; each gate also requires an absolute top level, as git
        # always prints. An empty one is 3b559's missing work tree and keeps
        # that refusal, which runs first. The absolute case is the shim's
        # control. Mutation killed: dropping the comparison, or only its
        # is_absolute half, from any one gate.
        import subprocess as sp

        tmp, git = self._retire_and_cite()
        tools = self._own_copies(tmp / "tools")
        shims = Path(tempfile.mkdtemp(prefix="toplevel-shim-")).resolve()
        self.addCleanup(shutil.rmtree, shims, ignore_errors=True)
        real_git = shutil.which("git")
        for label, printed in (("relative", "elsewhere"), ("dot", "."), ("empty", ""),
                               ("absolute", str(tmp))):
            shim = shims / label / "git"
            shim.parent.mkdir()
            shim.write_text(
                f"#!{sys.executable} -I\n"
                "import os, sys\n"
                "if '--show-toplevel' in sys.argv[1:]:\n"
                f"    print({printed!r})\n"
                "    sys.exit(0)\n"
                f"os.execv({real_git!r}, [{real_git!r}, *sys.argv[1:]])\n",
                encoding="utf-8",
            )
            shim.chmod(0o755)
            env = dict(os.environ)
            env["PATH"] = str(shim.parent) + os.pathsep + env.get("PATH", "")
            if label == "absolute":
                self._assert_real_verdicts(tools, tmp, "main", "feat", env=env, label=label)
                continue
            for script, rc, verdict, _clean in self.OWN_TOP_GATES:
                with self.subTest(gate=script, top=label):
                    r = sp.run([sys.executable, str(tools / script), "main", "feat"],
                               capture_output=True, text=True, cwd=str(tmp), env=env)
                    self.assertEqual(r.returncode, 2, f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                    if label == "empty":
                        self.assertIn("printed an empty top level (no work tree)", r.stderr)
                    else:
                        self.assertIn("not this script's repository", r.stderr)
                        self.assertIn(repr(printed), r.stderr)
                    self.assertNotIn("Traceback", r.stderr)
                    self.assertNotIn(verdict, r.stdout + r.stderr)

    def test_non_absolute_git_dir_refuses_exit2(self) -> None:
        # 3b564 (r2 review W1): git rev-parse echoes an option it does not
        # know and exits 0, so a git without --absolute-git-dir would print
        # the flag itself for both of require_own_git_dir's reads. A shim git
        # prints the flag for that one query (and delegates every other
        # call, so the top level is the real one). realpath resolved both
        # values against the current directory, they compared equal, and all
        # four gates kept their verdicts with the git directory unconfirmed;
        # each now refuses with exit 2 because neither read is an absolute
        # path. Mutation killed: dropping that check from
        # lint_common.require_own_git_dir.
        import subprocess as sp

        tmp, git = self._retire_and_cite()
        tools = self._own_copies(tmp / "tools")
        shims = Path(tempfile.mkdtemp(prefix="git-dir-shim-")).resolve()
        self.addCleanup(shutil.rmtree, shims, ignore_errors=True)
        real_git = shutil.which("git")
        shim = shims / "git"
        shim.write_text(
            f"#!{sys.executable} -I\n"
            "import os, sys\n"
            "if '--absolute-git-dir' in sys.argv[1:]:\n"
            "    print('--absolute-git-dir')\n"
            "    sys.exit(0)\n"
            f"os.execv({real_git!r}, [{real_git!r}, *sys.argv[1:]])\n",
            encoding="utf-8",
        )
        shim.chmod(0o755)
        env = dict(os.environ)
        env["PATH"] = str(shims) + os.pathsep + env.get("PATH", "")
        for script, _rc, verdict, _clean in self.OWN_TOP_GATES:
            with self.subTest(gate=script):
                r = sp.run([sys.executable, str(tools / script), "main", "feat"],
                           capture_output=True, text=True, cwd=str(tmp), env=env)
                self.assertEqual(r.returncode, 2, f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                self.assertIn("could not confirm that git reads this script's repository",
                              r.stderr)
                self.assertIn("printed '--absolute-git-dir' and '--absolute-git-dir'", r.stderr)
                self.assertNotIn("Traceback", r.stderr)
                self.assertNotIn(verdict, r.stdout + r.stderr)

    def test_run_from_other_clone(self) -> None:
        # 3b564 (r2 review W2): run from inside another clone whose top level
        # is the gate's own REPO_ROOT, once through GIT_WORK_TREE=REPO_ROOT
        # and once through that clone's own core.worktree naming it, with no
        # GIT_DIR. D5 and tension-scan run git from the current directory,
        # so they would read the other clone's refs; require_own_git_dir with
        # from_cwd refuses them with exit 2, naming that clone's git
        # directory. D9 and D13 run git with -C REPO_ROOT, so they read their
        # own repository and keep their real verdicts. Mutations killed:
        # require_own_git_dir ignoring from_cwd (always -C repo_root), D5 or
        # tension-scan calling it without from_cwd, and D9 calling it with
        # from_cwd.
        import subprocess as sp

        tmp, git = self._retire_and_cite()
        tools = self._own_copies(tmp / "tools")
        holder = Path(tempfile.mkdtemp(prefix="other-clone-")).resolve()
        self.addCleanup(shutil.rmtree, holder, ignore_errors=True)
        for name in ("clone", "configured"):
            sp.run(["git", "clone", "-q", str(tmp), str(holder / name)],
                   check=True, capture_output=True)
            git("branch", "-q", "main", "origin/main", cwd=holder / name)
        git("config", "core.worktree", str(tmp), cwd=holder / "configured")
        base_env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
        for label, cwd, extra in (
            ("GIT_WORK_TREE", holder / "clone", {"GIT_WORK_TREE": str(tmp)}),
            ("core.worktree", holder / "configured", {}),
        ):
            env = dict(base_env, **extra)
            for script, rc, verdict, clean in self.OWN_TOP_GATES:
                with self.subTest(gate=script, setup=label):
                    r = sp.run([sys.executable, str(tools / script), "main", "feat"],
                               capture_output=True, text=True, cwd=str(cwd), env=env)
                    if script in ("check-todo-rotation-on-pr.py", "tension-scan.py"):
                        self.assertEqual(r.returncode, 2, f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                        self.assertIn(f"git reads the git directory {str(cwd / '.git')!r}",
                                      r.stderr)
                        self.assertNotIn("work tree top level", r.stderr)
                        self.assertNotIn(clean, r.stdout)
                    else:
                        self.assertEqual(r.returncode, rc, f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                        self.assertIn(verdict, r.stdout + r.stderr)
                        self.assertNotIn("not this script's repository", r.stderr)
                    self.assertNotIn("Traceback", r.stderr)

    def test_gitfile_alias_refuses_exit2(self) -> None:
        # 3b564 (r3 review W1): a main-tree alias whose .git is a file naming
        # the checkout's git directory. git takes the alias as the top level
        # and reads that git directory, so the top-level comparison and both
        # git-directory reads passed: run from the alias, D9 printed "D9 OK:
        # 1 section(s) retired; no LIVE orphan references" over a head whose
        # own control run FAILs, and D5, D13 and tension-scan printed their
        # clean passes. tools/git-hooks/pre-push refuses the alias because it
        # is not a work tree registered with that git directory; each gate
        # now refuses it the same way, with exit 2, through
        # lint_common.require_own_git_dir. A linked worktree of the same
        # repository, whose .git file is registered, keeps its real
        # verdicts. Mutations killed: dropping the registration check,
        # accepting any .git file, and ignoring the linked worktree's gitdir
        # file (the worktree then refuses). Round 6 (r5 review W1) adds aliases
        # that take the checkout's objects and refs while git reports the
        # alias's own git directory, each of which the gates and pre-push
        # passed at 8f9b4b468: a .git directory whose commondir file names
        # the checkout's git directory, a .git directory whose objects and
        # refs are symbolic links into it, and a .git file naming a git
        # directory with such a commondir file, either a separate one whose
        # own config sets core.worktree to the alias or one whose gitdir file
        # names the alias's .git (not in the checkout's worktrees directory).
        # Mutations killed (helper and pre-push each): dropping the
        # common-directory comparison from each layout's branch, and dropping
        # the objects or refs symbolic-link check. Round 7 (r6 review N1)
        # adds an alias linking objects alone and one linking refs alone, so
        # dropping either half of that check is killed; f0da1931d refused
        # both.
        import subprocess as sp

        tmp, git = self._retire_and_cite()
        self._assert_real_verdicts(self._own_copies(tmp / "tools"), tmp, "main", "feat",
                                   label="control")
        holder = Path(tempfile.mkdtemp(prefix="gitfile-alias-")).resolve()
        self.addCleanup(shutil.rmtree, holder, ignore_errors=True)
        env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
        linked_parts = {"objects and refs symbolic links": ("objects", "refs"),
                        "objects symbolic link": ("objects",), "refs symbolic link": ("refs",)}
        for layout in ("gitfile", "commondir", *linked_parts,
                       "gitfile to a separate commondir", "gitfile to a linked commondir"):
            alias = holder / layout.replace(" ", "-")
            sp.run(["git", "clone", "-q", "-b", "main", str(tmp), str(alias)],
                   check=True, capture_output=True)
            git_dir = alias / ".git"
            if layout in linked_parts:
                if "refs" not in linked_parts[layout]:
                    # The alias keeps its own refs, so give it the range's head.
                    git("branch", "-q", "feat", "origin/feat", cwd=alias)
                for part in linked_parts[layout]:
                    shutil.rmtree(git_dir / part)
                    (git_dir / part).symlink_to(tmp / ".git" / part)
                if "refs" in linked_parts[layout]:
                    (git_dir / "packed-refs").unlink()
            else:
                shutil.rmtree(git_dir)
            if layout == "gitfile":
                git_dir = tmp / ".git"
                (alias / ".git").write_text(f"gitdir: {git_dir}\n", encoding="utf-8")
            elif layout not in linked_parts:
                if layout != "commondir":
                    git_dir = holder / f"{alias.name}.git"
                    (alias / ".git").write_text(f"gitdir: {git_dir}\n", encoding="utf-8")
                git_dir.mkdir()
                (git_dir / "HEAD").write_text("ref: refs/heads/main\n", encoding="utf-8")
                (git_dir / "commondir").write_text(f"{tmp / '.git'}\n", encoding="utf-8")
                if layout == "gitfile to a separate commondir":
                    (git_dir / "config").write_text(f"[core]\n\tworktree = {alias}\n",
                                                    encoding="utf-8")
                elif layout == "gitfile to a linked commondir":
                    (git_dir / "gitdir").write_text(f"{alias / '.git'}\n", encoding="utf-8")
            tools = self._own_copies(alias / "tools")
            self.assertEqual(git("rev-parse", "--show-toplevel", cwd=alias), str(alias))
            self.assertEqual(git("rev-parse", "--absolute-git-dir", cwd=alias), str(git_dir))
            self.assertEqual(git("rev-parse", "main", cwd=alias), git("rev-parse", "main"))
            with self.subTest(layout=layout, gate="pre-push"):
                hook = sp.run(["sh", str(REPO_ROOT / "tools" / "git-hooks" / "pre-push"),
                               "origin", "x"], capture_output=True, text=True, cwd=str(alias),
                              env=env, stdin=sp.DEVNULL)
                self.assertEqual(hook.returncode, 1, hook.stderr)
                self.assertIn("pre-push: refusing redirected work tree", hook.stderr)
            for script, _rc, _verdict, clean in self.OWN_TOP_GATES:
                with self.subTest(layout=layout, gate=script):
                    r = sp.run([sys.executable, str(tools / script), "main", "feat"],
                               capture_output=True, text=True, cwd=str(alias), env=env)
                    self.assertEqual(r.returncode, 2, f"stdout:\n{r.stdout}\nstderr:\n{r.stderr}")
                    self.assertIn(f"is not a work tree registered with the git directory "
                                  f"{str(git_dir)!r}", r.stderr)
                    self.assertNotIn("work tree top level", r.stderr)
                    self.assertNotIn("Traceback", r.stderr)
                    self.assertNotIn(clean, r.stdout)
        wt = Path(str(tmp) + "-wt")
        self.addCleanup(shutil.rmtree, wt, ignore_errors=True)
        git("worktree", "add", "-q", "-b", "feat-wt", str(wt), "feat")
        self.assertTrue((wt / ".git").is_file())
        self._assert_real_verdicts(self._own_copies(wt / "tools"), wt, "main", "feat-wt",
                                   env=env, label="registered worktree")

    def test_own_toplevel_keeps_real_verdicts(self) -> None:
        # 3b564: the top-level and git-directory comparisons keep every real
        # verdict where git reads the gate's own repository: a normal
        # checkout, a run from a subdirectory (D5 and tension-scan run git
        # from the current directory), a root reached through a symbolic
        # link, and a linked worktree and a submodule each running their own
        # copies.
        import subprocess as sp

        tmp, git = self._retire_and_cite()
        tools = self._own_copies(tmp / "tools")
        self._assert_real_verdicts(tools, tmp, "main", "feat", label="checkout")
        self._assert_real_verdicts(tools, tmp / "tools", "main", "feat", label="subdirectory")
        links = Path(tempfile.mkdtemp(prefix="own-root-link-")).resolve()
        self.addCleanup(shutil.rmtree, links, ignore_errors=True)
        link = links / "root"
        link.symlink_to(tmp)
        self._assert_real_verdicts(link / "tools", link, "main", "feat", label="symlinked root")
        wt = Path(str(tmp) + "-wt")
        self.addCleanup(shutil.rmtree, wt, ignore_errors=True)
        git("worktree", "add", "-q", "-b", "feat-wt", str(wt), "feat")
        self._assert_real_verdicts(self._own_copies(wt / "tools"), wt, "main", "feat-wt",
                                   label="linked worktree")
        sup = Path(tempfile.mkdtemp(prefix="own-superproject-")).resolve()
        self.addCleanup(shutil.rmtree, sup, ignore_errors=True)
        sp.run(["git", "init", "-q", "-b", "main", str(sup)], check=True, capture_output=True)
        sp.run(["git", "-C", str(sup), "-c", "protocol.file.allow=always", "submodule", "add",
                "-q", str(tmp), "sub"], check=True, capture_output=True)
        sub = sup / "sub"
        self._assert_real_verdicts(self._own_copies(sub / "tools"), sub, "origin/main",
                                   "origin/feat", label="submodule")


