class RegressionGateGuardPinTests(unittest.TestCase):
    """The gate 36 guard module is on disk AND is handed to the child
    (3b525 rounds 2 and 3).

    The completeness and refusal guards for the gate runner live in
    tests/test_regression_gate.py (plus the runner's own in-process
    self-check and the child driver's argv re-check), so a run-list
    regression that drops THIS module cannot also drop them. These
    tests are the reciprocal, in a module whose presence does not
    depend on that one: deleting tests/test_regression_gate.py from
    disk fails here, and so does a filter that keeps the file on disk
    but drops it from the module list the runner's main() actually
    hands to the child subprocess.
    """

    def test_regression_gate_guard_module_is_on_disk(self) -> None:
        self.assertTrue(
            (REPO_ROOT / "tests" / "test_regression_gate.py").is_file())

    def test_runner_hands_guard_module_to_the_child(self) -> None:
        """main()'s executed child argv (not discovery alone) covers
        every on-disk tests/test_*.py, including the guard module, so
        a filter applied at the child launch fails here as well as in
        tests/test_regression_gate.py (each module guards the other)."""
        import contextlib
        import runpy
        runner = runpy.run_path(
            str(REPO_ROOT / "tools" / "run-linter-regression.py"))
        commands = []

        class _FakeProc:
            def __init__(self, cmd):
                commands.append(list(cmd))
                # main() writes the per-run nonce to the child's stdin
                # (3b525 round 3, F1: never on argv).
                self.stdin = io.BytesIO()
                self.stderr = io.BytesIO(b"")

            def wait(self):
                return 2

        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            runner["main"](popen=lambda cmd, **kwargs: _FakeProc(cmd))
        self.assertEqual(len(commands), 1)
        # Command shape: [sys.executable, "-c", driver, *modules].
        executed = commands[0][3:]
        expected = sorted(
            "tests." + path.name[:-3]
            for path in (REPO_ROOT / "tests").iterdir()
            if path.is_file() and path.name.startswith("test_")
            and path.name.endswith(".py"))
        self.assertEqual(executed, expected,
                         "gate 36 runner's executed module list does not "
                         "cover every tests/test_*.py file")
        self.assertIn("tests.test_regression_gate", executed)
        self.assertIn("tests.test_linters", executed)


class VerificationGuardrailSelfTests(unittest.TestCase):


    """The RM-10 enforcers' own self-tests, wired into the suite.

    Added by PR #635 (the 2026-07-04 worker QA run's validated
    GR-GAP-3): the PreToolUse pipe-blocking hook's ``--self-test`` and
    the ``tail-safe.sh`` wrapper's ``--self-test`` were wired into no
    runner, CI, or regression surface, so a broken enforcer failed
    nothing. Running them here makes the regression suite (and every
    pre-push guard run that chains it) fail loud when either enforcer
    regresses.
    """

    def _run_selftest(self, cmd, timeout=None):
        import subprocess as sp

        return sp.run(
            cmd, capture_output=True, text=True, cwd=str(REPO_ROOT), timeout=timeout
        )

    def test_block_on_open_findings_hook_self_test(self) -> None:
        """The open-findings guard's own self-test, wired at introduction.

        A guard nobody tests is the shape this whole class of failure takes, so the hook that
        enforces disposition is itself enforced here.
        """
        result = self._run_selftest(
            [sys.executable, str(REPO_ROOT / ".claude" / "hooks" / "block-on-open-findings.py"),
             "--self-test"]
        )
        self.assertEqual(result.returncode, 0,
                         f"hook --self-test failed.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}")
        self.assertIn("self-test: ", result.stdout)

    def test_skill_verdict_carrier_completeness_gate(self) -> None:
        """Gate 97 (verdict-carrier-completeness) self-test PLUS the live census.

        The --self-test proves both checks (missing-field, exception-contradiction), the
        exempt-marker states, and the environmental exits. The live run against the real
        matrix-fit/claim-fit pairs at exit 0 is the standing negative test (a future PR that
        drops a required verdict field from a carrier turns this red), per the audit suite's
        census convention. Origin: PR #1926 (P-1.56) cost four QA rounds on exactly this class.
        """
        tool = REPO_ROOT / "tools" / "lint-skill-verdict-carrier-completeness.py"
        st = self._run_selftest([sys.executable, str(tool), "--self-test"])
        self.assertEqual(st.returncode, 0,
                         f"gate 97 --self-test failed.\nstdout:\n{st.stdout}\nstderr:\n{st.stderr}")
        self.assertIn("self-test case(s) passed", st.stdout)
        census = self._run_selftest([sys.executable, str(tool)])
        self.assertEqual(census.returncode, 0,
                         f"gate 97 live census is not clean; a verdict carrier lost a required "
                         f"field.\nstdout:\n{census.stdout}\nstderr:\n{census.stderr}")
        # A never-match carrier_signal would pass the tool vacuously; assert the live run
        # actually MATCHED carriers (non-vacuity), so a broken signal on the real manifest
        # turns this red in CI.
        m = re.search(r"(\d+) carrier unit\(s\) checked", census.stdout)
        self.assertIsNotNone(m, f"census did not report a carrier count.\n{census.stdout}")
        self.assertGreater(int(m.group(1)), 0,
                           "gate 97 matched ZERO carriers on the real manifest; its "
                           "carrier_signal is vacuous.")

