class PrePushGuardTests(unittest.TestCase):
    """tools/pre-push-guard.sh exit-code chain.

    Pins the improvement-log #438/#439 regression class: the guard must
    propagate a failing runner's exit code (captured from the BARE
    command, not an `if ! cmd` test) and must not run the second runner
    after the first fails. The fixture copies the real guard into a temp
    tree beside stub runners.
    """

    def _build_guard_dir(self, first_rc: int, second_rc: int, web_rc=None, manifest_rc=None,
                         manifest_drift_line: bool = False):
        import shutil
        import stat
        import tempfile

        tmp = Path(tempfile.mkdtemp(prefix="lint-guard-test-"))
        tools = tmp / "tools"
        tools.mkdir()
        shutil.copy(REPO_ROOT / "tools" / "pre-push-guard.sh", tools / "pre-push-guard.sh")
        for name in ("install-git-hooks.sh", "lint_common.py"):
            shutil.copy(REPO_ROOT / "tools" / name, tools / name)
        (tools / "run_all_audits.sh").write_text(
            f"#!/bin/bash\nexit {first_rc}\n", encoding="utf-8"
        )
        (tools / "run-pr-time-checks.sh").write_text(
            "#!/bin/bash\ntouch \"$(dirname \"$0\")/../second-ran.marker\"\n"
            f"exit {second_rc}\n",
            encoding="utf-8",
        )
        if web_rc is not None:
            web = tmp / ".web"
            web.mkdir()
            (web / "build.py").write_text(
                f"import sys\nsys.exit({web_rc})\n", encoding="utf-8"
            )
        if manifest_rc is not None:
            drift = ("print('build-reference-manifest --check: DRIFT, stub', file=sys.stderr)\n"
                     if manifest_drift_line else "")
            (tools / "build-reference-manifest.py").write_text(
                f"import sys\n{drift}sys.exit({manifest_rc})\n", encoding="utf-8"
            )
        for name in ("pre-push-guard.sh", "run_all_audits.sh", "run-pr-time-checks.sh"):
            path = tools / name
            path.chmod(path.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
        return tmp, shutil

    def _run_guard(self, tmp: Path, allow_pipe: bool = True, allow_dirty: bool = True,
                   extra_env=None):
        import os
        import subprocess as sp

        # capture_output wires the guard's stdout to a PIPE, which the
        # RM-10 self-defence (PR #620) refuses by design; the
        # documented override is the sanctioned way to run a deliberate,
        # judged pipe, which is exactly what this harness capture is. The
        # refusal path itself is pinned by test_piped_stdout_refused.
        env = dict(os.environ)
        if allow_pipe:
            env["PRE_PUSH_GUARD_ALLOW_PIPE"] = "1"
        else:
            env.pop("PRE_PUSH_GUARD_ALLOW_PIPE", None)
        # The fixture dir is not a git repo (or is deliberately dirty), which the
        # dirty-tracked-tree attestation check refuses; the runner-chaining tests
        # are orthogonal to that check, so they bypass it via the documented
        # override. The dirty / fail-closed behaviour has its own tests below.
        if allow_dirty:
            env["PRE_PUSH_GUARD_ALLOW_DIRTY"] = "1"
        else:
            env.pop("PRE_PUSH_GUARD_ALLOW_DIRTY", None)
        if extra_env:
            env.update(extra_env)
        return sp.run(
            ["bash", str(tmp / "tools" / "pre-push-guard.sh")],
            capture_output=True, text=True, cwd=str(tmp), env=env,
        )

    def test_first_runner_failure_blocks_and_skips_second(self) -> None:
        tmp, shutil = self._build_guard_dir(first_rc=7, second_rc=0)
        try:
            result = self._run_guard(tmp)
            self.assertEqual(
                result.returncode, 7,
                f"guard should exit with the first runner's code; got "
                f"{result.returncode}.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
            )
            self.assertIn("FAILED at run_all_audits.sh", result.stdout)
            self.assertFalse(
                (tmp / "second-ran.marker").exists(),
                "second runner must not run after the first fails",
            )
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_second_runner_failure_blocks(self) -> None:
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=5)
        try:
            result = self._run_guard(tmp)
            self.assertEqual(
                result.returncode, 5,
                f"guard should exit with the second runner's code; got "
                f"{result.returncode}.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
            )
            self.assertIn("FAILED at run-pr-time-checks.sh", result.stdout)
            self.assertTrue((tmp / "second-ran.marker").exists())
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_both_runners_green_passes(self) -> None:
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=0)
        try:
            result = self._run_guard(tmp)
            self.assertEqual(
                result.returncode, 0,
                f"guard should exit 0 when both runners pass; got "
                f"{result.returncode}.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
            )
            self.assertIn("Safe to push", result.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_web_check_failure_blocks(self) -> None:
        # CLW-2/3/4/5/7 r2 (codex MED-NEW-1): the conditional third check propagates its
        # own non-zero exit; the two runners passing is not sufficient.
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=0, web_rc=9)
        try:
            result = self._run_guard(tmp)
            self.assertEqual(
                result.returncode, 9,
                f"guard should exit with the web check's code; got "
                f"{result.returncode}.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
            )
            self.assertIn("FAILED at .web/build.py --check", result.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_all_three_checks_green_passes(self) -> None:
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=0, web_rc=0)
        try:
            result = self._run_guard(tmp)
            self.assertEqual(result.returncode, 0, result.stdout)
            self.assertIn("Safe to push", result.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_manifest_drift_is_advisory_only(self) -> None:
        # P-TODO 3b62: reference-manifest drift is reported after the three checks, never
        # blocking: the guard still exits 0 and says the push is safe.
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=0, manifest_rc=1,
                                            manifest_drift_line=True)
        try:
            result = self._run_guard(tmp)
            self.assertEqual(result.returncode, 0, result.stdout)
            self.assertIn("ADVISORY: docs/reference-acquisition-manifest.md has drifted", result.stdout)
            self.assertIn("Safe to push", result.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_manifest_exit_1_without_drift_line_is_not_drift(self) -> None:
        # An interpreter-level failure also exits 1; without the generator's DRIFT line it is
        # reported as "could not run", never as drift with a regeneration instruction.
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=0, manifest_rc=1)
        try:
            result = self._run_guard(tmp)
            self.assertEqual(result.returncode, 0, result.stdout)
            self.assertNotIn("has drifted", result.stdout)
            self.assertIn("reference-manifest check could not run (rc=1", result.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_manifest_builder_missing_is_reported_not_blocking(self) -> None:
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=0)
        try:
            result = self._run_guard(tmp)
            self.assertEqual(result.returncode, 0, result.stdout)
            self.assertIn("reference-manifest check could not run (rc=2", result.stdout)
            self.assertIn("Safe to push", result.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_manifest_advisory_survives_inherited_errexit(self) -> None:
        # With errexit inherited through SHELLOPTS, the advisory's non-zero status must not end
        # the guard before its PASS line.
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=0, manifest_rc=1,
                                            manifest_drift_line=True)
        try:
            result = self._run_guard(tmp, extra_env={"SHELLOPTS": "errexit"})
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
            self.assertIn("has drifted", result.stdout)
            self.assertIn("Safe to push", result.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_manifest_in_sync_prints_no_advisory(self) -> None:
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=0, manifest_rc=0)
        try:
            result = self._run_guard(tmp)
            self.assertEqual(result.returncode, 0, result.stdout)
            self.assertNotIn("pre-push guard ADVISORY", result.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_manifest_builder_internal_error_exits_3(self) -> None:
        # P-TODO 3b62: build-reference-manifest.py maps an unexpected exception to exit 3, so its
        # exit 1 means --check DRIFT only (Python's own uncaught-exception exit is also 1).
        import subprocess as sp
        import tempfile
        # The crash is injected at resolve_sibling (called inside main), so the test does not
        # depend on any catalogue shape the generator might learn to tolerate (3b63 made a
        # titleless entry render cleanly, which this test used to rely on to raise).
        with tempfile.TemporaryDirectory() as td:
            code = (
                "import sys; sys.path.insert(0, 'tools')\n"
                "import lint_common\n"
                "def _boom(name):\n"
                "    raise RuntimeError('injected')\n"
                "lint_common.resolve_sibling = _boom\n"
                "import runpy\n"
                "sys.argv = ['build-reference-manifest.py', '--check']\n"
                "runpy.run_path('tools/build-reference-manifest.py', run_name='__main__')\n"
            )
            r = sp.run([sys.executable, "-c", code], cwd=str(REPO_ROOT),
                       capture_output=True, text=True)
        self.assertEqual(r.returncode, 3, r.stdout + r.stderr)
        self.assertIn("internal error", r.stderr)
        self.assertNotIn("DRIFT", r.stderr)

    def test_piped_stdout_refused(self) -> None:
        """RM-10 self-defence (PR #620): piped stdout without the
        override refuses with exit 3 before any runner runs."""
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=0)
        try:
            result = self._run_guard(tmp, allow_pipe=False)
            self.assertEqual(
                result.returncode, 3,
                f"guard should refuse piped stdout with exit 3; got "
                f"{result.returncode}.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
            )
            self.assertIn("REFUSING", result.stderr)
            self.assertFalse(
                (tmp / "second-ran.marker").exists(),
                "no runner may run on the refusal path",
            )
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_unattestable_tree_fails_closed(self) -> None:
        """Attestation-soundness (git-add-drop 2b): when `git status` errors
        (the fixture dir is not a git repo), the guard must FAIL CLOSED (exit 5),
        not read an empty status as a clean tree. Pins codex's fail-open finding."""
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=0)
        try:
            result = self._run_guard(tmp, allow_dirty=False)
            self.assertEqual(
                result.returncode, 5,
                f"guard must fail closed (exit 5) when git status errors; got "
                f"{result.returncode}.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
            )
            self.assertFalse(
                (tmp / "second-ran.marker").exists(),
                "no runner may run on the refusal path",
            )
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_dirty_tracked_tree_refused(self) -> None:
        """A modified tracked file makes the working tree differ from HEAD, so
        the guard must refuse (exit 5) before running the gates."""
        import subprocess as sp
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=0)
        try:
            for args in (["init", "-q"], ["config", "user.email", "t@t"],
                         ["config", "user.name", "t"], ["add", "-A"],
                         ["commit", "-q", "-m", "init"]):
                sp.run(["git", "-C", str(tmp), *args], check=True,
                       capture_output=True, text=True)
            # dirty a tracked file
            (tmp / "tools" / "run_all_audits.sh").write_text(
                "#!/bin/bash\nexit 0\n# dirtied\n", encoding="utf-8")
            result = self._run_guard(tmp, allow_dirty=False)
            self.assertEqual(
                result.returncode, 5,
                f"guard must refuse (exit 5) a dirty tracked tree; got "
                f"{result.returncode}.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
            )
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_allow_dirty_override_proceeds(self) -> None:
        """PRE_PUSH_GUARD_ALLOW_DIRTY=1 bypasses the dirty/unattestable-tree
        check (with a visible console notice) and the guard proceeds."""
        tmp, shutil = self._build_guard_dir(first_rc=0, second_rc=0)
        try:
            result = self._run_guard(tmp, allow_dirty=True)
            self.assertEqual(
                result.returncode, 0,
                f"guard should proceed (exit 0) with the ALLOW_DIRTY override; got "
                f"{result.returncode}.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
            )
            self.assertIn("PRE_PUSH_GUARD_ALLOW_DIRTY", result.stderr)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)


class ExternalOverlayLicenseTests(LinterTestCase):
    """tools/lint-external-overlay-license.py (gate 42): the two-layout audit over the
    rule-source directories and the five registered addyosmani skill directories."""

    MIT_TEXT = "MIT License\n\nCopyright (c) test\n"
    SKILLS = (
        "addyosmani-ci-cd-and-automation",
        "addyosmani-code-review-and-quality",
        "addyosmani-context-engineering",
        "addyosmani-security-and-hardening",
        "addyosmani-using-agent-skills",
    )

    def test_runs_clean_on_corpus_at_head(self) -> None:
        # Smoke test: external overlay licence consistency holds at HEAD.
        result = run_linter("tools/lint-external-overlay-license.py")
        self.assertEqual(
            result.returncode, 0,
            f"linter exited {result.returncode} on HEAD; "
            f"external overlay licence consistency should hold.\n"
            f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}",
        )

    # -- fixture plumbing: a synthetic repo root holding the clean two-rule /
    # five-skill layout, mutated per test, checked in-process with the gate
    # module's globals pointed at the fixture root.

    def _fixture_root(self) -> Path:
        root = Path(tempfile.mkdtemp(prefix="ext-overlay-lic-", dir=FIXTURE_DIR))
        self.addCleanup(_force_rmtree, root)
        return root

    def _build_layout(self, root: Path) -> None:
        for source in ("kariedo", "tikitribe"):
            d = root / ".claude" / "rules" / "external" / source
            d.mkdir(parents=True)
            (d / "LICENSE").write_text(self.MIT_TEXT, encoding="utf-8")
            (d / "PROVENANCE.txt").write_text("# Overlay provenance\n", encoding="utf-8")
            (d / "rule.md").write_text("# external rule\n", encoding="utf-8")
        for name in self.SKILLS:
            d = root / ".claude" / "skills" / name
            d.mkdir(parents=True)
            (d / "LICENSE").write_text(self.MIT_TEXT, encoding="utf-8")
            (d / "SKILL.md").write_text(
                f"---\nname: {name}\ndescription: fixture\n---\n\nbody\n",
                encoding="utf-8",
            )
            (d / "PROVENANCE.md").write_text("# Overlay provenance\n", encoding="utf-8")
        # An unrelated first-party skill must stay outside the gate.
        d = root / ".claude" / "skills" / "clean-language"
        d.mkdir(parents=True)
        (d / "SKILL.md").write_text(
            "---\nname: clean-language\n---\n\n**License:** CC BY-SA 4.0\n",
            encoding="utf-8",
        )

    def _findings(self, mutate=None):
        root = self._fixture_root()
        self._build_layout(root)
        if mutate is not None:
            mutate(root)
        mod = load_linter_module(
            "tools/lint-external-overlay-license.py",
            f"_ext_overlay_lic_{self._testMethodName}",
        )
        mod.REPO_ROOT = root
        mod.EXTERNAL_OVERLAY_DIR = root / ".claude" / "rules" / "external"
        return mod.check()

    def test_clean_two_rule_five_skill_layout_passes(self) -> None:
        # The project-licence claim planted in the unrelated clean-language
        # skill proves unrelated skills are not enrolled.
        self.assertEqual(self._findings(), [])

    def test_rule_provenance_text_is_required_and_licence_audited(self) -> None:
        for source in ("kariedo", "tikitribe"):
            relative = f".claude/rules/external/{source}/PROVENANCE.txt"
            with self.subTest(source=source):
                findings = self._findings(lambda root: (root / relative).unlink())
                self.assertEqual([f.kind for f in findings], ["missing-rule-provenance"])
                self.assertEqual(findings[0].location, relative)
                findings = self._findings(lambda root: (root / relative).write_text(
                    "**License:** CC BY-SA 4.0\n", encoding="utf-8"))
                self.assertEqual([f.kind for f in findings],
                                 ["external-file-claims-project-licence"])
                self.assertEqual(findings[0].location, relative)

