class ClaudeRulesSyncCompilerOwnershipTests(LinterTestCase):
    """tools/lint-claude-rules-sync.py: compiler-owned recognition (compile PR-2).

    The completeness check recognizes a local rule file as compiler-owned ONLY
    through a valid entry in the Corpus-Management ownership register (never a
    directory skip): a covered file passes (its byte-integrity is gate 99's
    job), an uncovered file under the reserved subdirectory still fails as
    unmapped, and an ownership entry that contests a mirrored path, sits
    outside the reserved subdirectory, or claims a block under .claude/rules/
    is itself a finding. An unparseable register is an internal error (2).
    """

    OWNED_FILE_ENTRY = (
        "schema_version = 1\n\n[[owned_targets]]\n"
        'rule = "gen-rule"\nkind = "file"\n'
        'target = ".claude/rules/corpus-management/generated-rule.md"\n'
    )
    OWNED_TREE_ENTRY = (
        "schema_version = 1\n\n[[owned_targets]]\n"
        'rule = "gen-tree"\nkind = "tree"\n'
        'target = ".claude/rules/corpus-management"\n'
    )
    EMPTY_REGISTER = "schema_version = 1\nowned_targets = []\n"

    def _make_root(self, ownership_toml, owned_local):
        # Unique per-call scratch dir + self-registered cleanup so two concurrent
        # suite runs cannot delete or overwrite each other's tree (P-1.86;
        # the fixed-dir + `if exists: rmtree` pattern raced on this fleet-concurrent
        # machine; mirrors the #2292 _make_synthetic fix + _force_rmtree).
        root = Path(tempfile.mkdtemp(prefix="synthetic-claude-rules-ownership-", dir=FIXTURE_DIR))
        self.addCleanup(_force_rmtree, root)
        (root / ".claude" / "rules").mkdir(parents=True)
        (root / "guardrails" / "core").mkdir(parents=True)
        (root / ".claude" / "rules" / "secrets.md").write_text(
            "# Title\n\nIdentical body.\n", encoding="utf-8")
        (root / "guardrails" / "core" / "secrets.md").write_text(
            "# Title\n\nIdentical body.\n", encoding="utf-8")
        if ownership_toml is not None:
            reg_dir = root / ".corpus-management" / "core"
            reg_dir.mkdir(parents=True)
            (reg_dir / "ownership.toml").write_text(ownership_toml, encoding="utf-8")
        if owned_local:
            d = root / ".claude" / "rules" / "corpus-management"
            d.mkdir(parents=True)
            (d / "generated-rule.md").write_text(
                "<!-- GENERATED by corpus-management -->\n\n# Generated rule\n",
                encoding="utf-8")
        return root, {".claude/rules/secrets.md": "guardrails/core/secrets.md"}

    def _run_patched(self, ownership_toml, owned_local):
        mod = ClaudeRulesSyncTests._load_module()
        root, fake_map = self._make_root(ownership_toml, owned_local)
        saved = mod.MIRROR_MAP
        try:
            mod.MIRROR_MAP = fake_map
            import contextlib, io
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                rc = mod.main(["--root", str(root)])
            return rc, buf.getvalue()
        finally:
            mod.MIRROR_MAP = saved

    def test_compiler_owned_file_recognized(self):
        rc, out = self._run_patched(self.OWNED_FILE_ENTRY, owned_local=True)
        self.assertEqual(rc, 0, f"a register-covered file must not be unmapped:\n{out}")

    def test_owned_tree_coverage_recognized(self):
        rc, out = self._run_patched(self.OWNED_TREE_ENTRY, owned_local=True)
        self.assertEqual(rc, 0, f"a file inside a register-covered tree must pass:\n{out}")

    def test_uncovered_file_fails(self):
        # The reserved subdirectory is NOT a skip: with no covering register
        # entry, a hand-dropped file there still fails loud.
        rc, out = self._run_patched(self.EMPTY_REGISTER, owned_local=True)
        self.assertEqual(rc, 1, out)
        self.assertIn("unmapped local rule file", out)

    def test_mirror_map_overlap_fails(self):
        entry = self.OWNED_FILE_ENTRY.replace(
            ".claude/rules/corpus-management/generated-rule.md",
            ".claude/rules/secrets.md")
        rc, out = self._run_patched(entry, owned_local=False)
        self.assertEqual(rc, 1, out)
        self.assertIn("ownership overlap", out)

    def test_block_kind_under_rules_fails(self):
        entry = self.OWNED_FILE_ENTRY.replace('kind = "file"', 'kind = "block"')
        rc, out = self._run_patched(entry, owned_local=False)
        self.assertEqual(rc, 1, out)
        self.assertIn("block-kind", out)

    def test_index_kind_under_rules_fails(self):
        # 3b607: the rule index ships in the corpus-management skill, so an
        # index-kind entry under .claude/rules/ is a finding (the former
        # INDEX.md path included); the skill-directory target is not ours.
        for target, expected in ((".claude/rules/corpus-management/INDEX.md", 1),
                                 (".claude/rules/corpus-management/generated-rule.md", 1),
                                 (".claude/skills/corpus-management/rule-index.md", 0)):
            with self.subTest(target=target):
                entry = self.OWNED_FILE_ENTRY.replace(
                    'kind = "file"', 'kind = "index"').replace(
                    ".claude/rules/corpus-management/generated-rule.md", target)
                rc, out = self._run_patched(entry, owned_local=False)
                self.assertEqual(rc, expected, out)
                if expected:
                    self.assertIn("index-kind", out)

    def test_outside_reservation_fails(self):
        entry = self.OWNED_FILE_ENTRY.replace(
            ".claude/rules/corpus-management/generated-rule.md",
            ".claude/rules/governance/new-generated.md")
        rc, out = self._run_patched(entry, owned_local=False)
        self.assertEqual(rc, 1, out)
        self.assertIn("outside the reserved", out)

    def test_unparseable_register_exits_2(self):
        mod = ClaudeRulesSyncTests._load_module()
        root, fake_map = self._make_root("owned_targets = [broken", owned_local=False)
        saved = mod.MIRROR_MAP
        try:
            mod.MIRROR_MAP = fake_map
            rc = mod.main(["--root", str(root)])
            self.assertEqual(rc, 2, "an unparseable ownership register is an internal error")
        finally:
            mod.MIRROR_MAP = saved


class TodoStalenessTests(LinterTestCase):
    """tools/lint-todo-staleness.py"""

    def test_runs_clean_on_corpus_at_head(self) -> None:
        # Smoke test: TODO.md at HEAD has no stale patterns.
        result = run_linter("tools/lint-todo-staleness.py")
        self.assertEqual(
            result.returncode, 0,
            f"linter exited {result.returncode} on HEAD; "
            f"TODO.md should have no stale patterns.\n"
            f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}",
        )

    def _load_module(self):
        # Hyphenated filename; load via importlib.
        import importlib.util
        tools_dir = str(REPO_ROOT / "tools")
        if tools_dir not in sys.path:
            sys.path.insert(0, tools_dir)
        spec = importlib.util.spec_from_file_location(
            "_lint_todo_staleness",
            REPO_ROOT / "tools/lint-todo-staleness.py",
        )
        assert spec is not None and spec.loader is not None
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def test_queued_pr_already_merged_detected(self) -> None:
        # Positive test: a TODO line marks PR #999 as "Next" while PR
        # #999 has merged. Use the module's check_file via tempfile.
        mod = self._load_module()
        fixture_dir = Path(tempfile.mkdtemp(prefix="todo-staleness-merged-", dir=FIXTURE_DIR))
        try:
            path = fixture_dir / "TODO.md"
            path.write_text(
                "# TODO\n\n"
                "**Next, PR #999: do something important.**\n",
                encoding="utf-8",
            )
            # Pretend PR #999 has merged.
            findings = mod.check_file(path, merged={999}, latest=None)
            self.assertTrue(
                findings,
                f"linter should flag queued PR #999 as already-merged; "
                f"got findings={findings}",
            )
            self.assertIn("queued-PR-merged", findings[0])
        finally:
            import shutil
            shutil.rmtree(fixture_dir, ignore_errors=True)

    def test_queued_pr_not_yet_merged_passes(self) -> None:
        # Negative test: same line, but PR #999 has NOT merged. No finding.
        mod = self._load_module()
        fixture_dir = Path(tempfile.mkdtemp(prefix="todo-staleness-not-merged-", dir=FIXTURE_DIR))
        try:
            path = fixture_dir / "TODO.md"
            path.write_text(
                "# TODO\n\n"
                "**Next, PR #999: do something important.**\n",
                encoding="utf-8",
            )
            findings = mod.check_file(path, merged=set(), latest=None)
            self.assertEqual(
                findings, [],
                f"linter should not flag a queued PR that has not "
                f"merged; got findings={findings}",
            )
        finally:
            import shutil
            shutil.rmtree(fixture_dir, ignore_errors=True)

    def test_sweep_cursor_behind_history_detected(self) -> None:
        # Positive test: TODO claims Sweep 5 iter 2 but history has Sweep
        # 11 iter 1. Should flag.
        mod = self._load_module()
        fixture_dir = Path(tempfile.mkdtemp(prefix="todo-staleness-cursor-", dir=FIXTURE_DIR))
        try:
            path = fixture_dir / "TODO.md"
            path.write_text(
                "# TODO\n\n"
                "- **Last validation sweep**: Sweep 5 iteration 2.\n",
                encoding="utf-8",
            )
            findings = mod.check_file(
                path, merged=set(), latest=(11, 1)
            )
            self.assertTrue(
                findings,
                f"linter should flag cursor (5, 2) when history is "
                f"at (11, 1); got findings={findings}",
            )
            self.assertIn("sweep-cursor-stale", findings[0])
        finally:
            import shutil
            shutil.rmtree(fixture_dir, ignore_errors=True)

    def test_sweep_cursor_current_passes(self) -> None:
        # Negative test: cursor matches latest history row. No finding.
        mod = self._load_module()
        fixture_dir = Path(tempfile.mkdtemp(prefix="todo-staleness-cursor-current-", dir=FIXTURE_DIR))
        try:
            path = fixture_dir / "TODO.md"
            path.write_text(
                "# TODO\n\n"
                "- **Last validation sweep**: Sweep 11 iteration 1.\n",
                encoding="utf-8",
            )
            findings = mod.check_file(
                path, merged=set(), latest=(11, 1)
            )
            self.assertEqual(
                findings, [],
                f"linter should not flag a current cursor; "
                f"got findings={findings}",
            )
        finally:
            import shutil
            shutil.rmtree(fixture_dir, ignore_errors=True)


