    def test_findings_cell_handoff_classification(self) -> None:
        # The parser classifies a SKIPPED-handoff Findings cell as 'handoff'
        # and a SUBSUMED cell as 'subsumption', from field 4. The
        # maintainer-exception marker is recognized in BOTH spellings (the
        # -ised rows predate the Canadian-spelling harmonization; new rows
        # follow the house -ized convention; regex widened 2026-07-02).
        mod = self._load_module()
        text = (
            "| Date | PR | Touched | Findings | Hot-fix | Detail | Summary |\n"
            "|---|---|---|---|---|---|---|\n"
            "| 2026-06-25 | 99 | x | **`/validate-pr` SKIPPED (handoff-PR "
            "exception, loop-break)** | none | - | s |\n"
            "| 2026-06-25 | 98 | x | **NOT run; SUBSUMED by Sweep 42** | none | - | s |\n"
            "| 2026-06-25 | 97 | x | **0 findings (clean)** | none | - | s |\n"
            "| 2026-06-25 | 96 | x | **maintainer-authorised exception: "
            "carved out with rationale** | none | - | s |\n"
            "| 2026-06-25 | 95 | x | **maintainer-authorized exception: "
            "carved out with rationale** | none | - | s |\n"
        )
        status = mod.parse_validate_pr_status(text)
        self.assertEqual(status.get(99), "handoff")
        self.assertEqual(status.get(98), "subsumption")
        self.assertEqual(status.get(97), "normal")
        self.assertEqual(status.get(96), "subsumption")
        self.assertEqual(status.get(95), "subsumption")

    def test_incidental_not_run_prose_does_not_exempt_row(self) -> None:
        # 3.158 fail-open: a subsumption/exemption marker must be a DELIBERATE
        # disposition, not incidental "not run" prose anywhere in the Findings
        # cell. An ordinary row that mentions "do not run --prune" / "did not
        # run the grep" is 'normal', not 'subsumption'; a genuinely-pending
        # row carrying such prose is caught as 'pending' (it would otherwise
        # escape Check 1, the fail-open). A deliberate all-caps
        # "**NOT RUN (no independent party)**" disposition at the cell start
        # still classifies as 'subsumption'.
        mod = self._load_module()
        text = (
            "| Date | PR | Touched | Findings | Hot-fix | Detail | Summary |\n"
            "|---|---|---|---|---|---|---|\n"
            "| 2026-08-02 | 90 | x | **RETURNED: SHIP; F-1 do not run --prune "
            "on it** | none | - | s |\n"
            "| 2026-08-02 | 91 | x | **SHIP; did not run the grep by hand** | "
            "none | - | s |\n"
            "| 2026-08-02 | 92 | x | DISPATCHED to worker; did not run yet, "
            "pending delivery | none | - | s |\n"
            "| 2026-08-02 | 93 | x | **NOT RUN (no independent party "
            "available).** | none | - | s |\n"
        )
        status = mod.parse_validate_pr_status(text)
        self.assertEqual(status.get(90), "normal",
                         "incidental 'do not run' must not exempt (3.158)")
        self.assertEqual(status.get(91), "normal",
                         "incidental 'did not run' must not exempt (3.158)")
        self.assertEqual(status.get(92), "pending",
                         "pending row with incidental 'did not run' must be "
                         "caught as pending, not exempted (3.158 fail-open)")
        self.assertEqual(status.get(93), "subsumption",
                         "deliberate all-caps 'NOT RUN (...)' stays exempt")

    def test_pending_maintainer_authorized_prose_does_not_exempt_row(self) -> None:
        # Sweep-142 dual-family catch of the 3.158 RESIDUAL: the maintainer-exception
        # marker must be the DELIBERATE phrase "maintainer-authorized exception", not a
        # bare "maintainer-authorized <noun>" anywhere in the cell. A genuinely-pending
        # row that reads "DISPATCHED: maintainer-authorized the reviewer; RESULT PENDING"
        # must classify as 'pending' (the earlier bare `maintainer[-\s]authori[sz]\w*`
        # .search matched the phrase anywhere and pre-empted the pending check, the
        # fail-open); the deliberate "...exception" phrase still exempts.
        mod = self._load_module()
        text = (
            "| Date | PR | Touched | Findings | Hot-fix | Detail | Summary |\n"
            "|---|---|---|---|---|---|---|\n"
            "| 2026-08-02 | 94 | x | **DISPATCHED: maintainer-authorized the "
            "reviewer; RESULT PENDING** | none | - | s |\n"
            "| 2026-08-02 | 95 | x | **maintainer-authorized exception: carved "
            "out with rationale** | none | - | s |\n"
            "| 2026-08-02 | 96 | x | **DISPATCHED: maintainer-authorized the "
            "reviewer; exception request pending; RESULT PENDING** | none | - | s |\n"
            "| 2026-08-02 | 97 | x | **maintainer-authorized standing exception: "
            "carved out** | none | - | s |\n"
        )
        status = mod.parse_validate_pr_status(text)
        self.assertEqual(status.get(94), "pending",
                         "pending row with incidental 'maintainer-authorized <noun>' "
                         "must be caught as pending, not exempted (3.158 residual)")
        self.assertEqual(status.get(95), "subsumption",
                         "deliberate 'maintainer-authorized exception' stays exempt")
        self.assertEqual(status.get(96), "pending",
                         "CROSS-CLAUSE 'maintainer-authorized ...; exception request "
                         "pending' must NOT exempt a pending row (codex vpr HOLD: the "
                         "[^.|]{0,40} bridge let a semicolon-separated exception through)")
        self.assertEqual(status.get(97), "subsumption",
                         "multi-word 'maintainer-authorized standing exception' stays exempt")

    def test_codespan_aware_split_reads_findings_past_inline_pipe(self) -> None:
        # 3.159: a Findings cell containing an inline `| pending |` code span
        # must not shift columns. The naive split("|") breaks the row into the
        # wrong cells (reading the Findings cell as just a backtick); the
        # code-span-aware split_markdown_row keeps the span in cell index 4, so
        # the row's DISPATCHED token is seen and it classifies 'pending'
        # (whereas the naive split would fail-open to 'normal').
        mod = self._load_module()
        row = (
            "| 2026-08-01 | PR #2000 | tools/example.py | "
            "`| pending |` then DISPATCHED | none | none | synthetic |"
        )
        self.assertEqual(mod.cells(row)[4], "`| pending |` then DISPATCHED")
        self.assertEqual(mod.parse_validate_pr_status(row), {2000: "pending"})
        naive_c4 = [c.strip() for c in row.split("|")][4]
        self.assertEqual(naive_c4, "`")
        self.assertFalse(mod.PENDING_FINDINGS.search(naive_c4),
                         "the naive split loses the DISPATCHED token (the fail-open)")

    def test_codespan_split_handles_double_backtick_span(self) -> None:
        # 3.159 (dual-family finding): a MULTI-backtick code span containing a
        # pipe must also stay in one cell. The run-aware split matches the
        # backtick-run length, so a double-backtick span `` a|b `` does not
        # shift columns (the earlier single-toggle design mis-split it).
        mod = self._load_module()
        row = "| 2026-08-01 | PR #2002 | a.py | ``x|y`` DISPATCHED | none | none | s |"
        self.assertEqual(mod.cells(row)[4], "``x|y`` DISPATCHED")
        self.assertEqual(mod.parse_validate_pr_status(row), {2002: "pending"})

    def test_codespan_split_leaves_ordinary_rows_unchanged(self) -> None:
        # 3.159: a row with no inline code-span pipe splits identically to the
        # naive split, so the change is a strict superset (no behaviour change
        # on ordinary rows).
        mod = self._load_module()
        row = "| 2026-08-01 | PR #2001 | a.py | RETURNED | none | none | clean |"
        self.assertEqual(mod.cells(row), [c.strip() for c in row.split("|")])
        self.assertEqual(mod.parse_validate_pr_status(row), {2001: "normal"})

    def test_multi_row_pr_newest_row_wins(self) -> None:
        # 3.150 item 3: the ledger is newest-first; for a PR with more than one row the FIRST
        # (newest) row wins. A newer RETURNED row above an older DISPATCHED row classifies
        # `normal`, not `pending` (a latent false-BLOCK the old last-row-wins assignment allowed).
        mod = self._load_module()
        text = (
            "| Date | PR | Touched | Findings | Hot-fix | Detail | Summary |\n"
            "|---|---|---|---|---|---|---|\n"
            "| 2026-08-02 | 500 | x | **RETURNED: SHIP, clean** | none | - | s |\n"
            "| 2026-08-01 | 500 | x | DISPATCHED to worker, pending | none | - | s |\n"
        )
        self.assertEqual(mod.parse_validate_pr_status(text).get(500), "normal")

    # ---- GATE50-UNIQUE: per-PR row integrity (duplicate / stale IN-PROGRESS rows).

    _NEW_HDR = "| Date | PR | Families | Tier | Disposition |\n|---|---|---|---|---|\n"

    def _hist(self, mod, body: str) -> list:
        return mod.row_integrity_findings(mod._history_row_records(self._NEW_HDR + body), "history")

    def test_row_integrity_stale_in_progress_beside_final_flags_both_orders(self) -> None:
        # The #2490 reproduction: a pre-compaction IN-PROGRESS row left beside the final row.
        mod = self._load_module()
