    # ---- the 2026-08-10 roll-up parser. Codex WARNING 4: all 44 tests passed while the
    # parser carried two live errors, because no test exercised any new branch.
    def test_parse_changelog_prs_reads_every_live_header_shape(self) -> None:
        """The six PR-bearing shapes enumerated from the live CHANGELOG, plus the legacy long
        form, which is NOT in the live file and is covered because the parser still accepts it.
        Seven cases, not six: the count in an earlier version of this docstring was wrong."""
        mod = self._load_module()
        cases = [
            ("**2026-08-10 | 2026.08.171 | PR #1472** - singular", {1472}),
            ("**2026-08-09 | 2026.08.170 | PRs #1465-#1470 (6 PRs)** - daily roll-up",
             set(range(1465, 1471))),
            ("**2026-08-05 | 2026.08.115 | PRs #1387-#1399 and #1401-#1417 (30 PRs)** - multi",
             set(range(1387, 1400)) | set(range(1401, 1418))),
            ("**Week of 2026-06-29 (PRs #667-#865)**", set(range(667, 866))),
            ("**Week of 2026-06-22 (PRs #451-#666 and #900-#902)**",
             set(range(451, 667)) | {900, 901, 902}),
            ("**Week of 2026-06-15 (PRs #38-#135, #137-#186 and #200-#201)**",
             set(range(38, 136)) | set(range(137, 187)) | {200, 201}),
            ("## 2026-07-02, Library Version 2026.07.40, PR #552", {552}),
        ]
        for text, expected in cases:
            self.assertEqual(mod.parse_changelog_prs(text), expected, text[:60])

    def test_parse_changelog_prs_ignores_non_headers(self) -> None:
        # Prose mentioning a PR number must not widen the audit universe.
        mod = self._load_module()
        # The first two are the only lines in the LIVE file that could plausibly over-match, and
        # they are what this fixture exists to pin; the invented prose that stood here before
        # passed against the broken parser too, so it discriminated nothing.
        for text in ("**2026-07-29 | MILESTONE:** a milestone line with no version cell #1234\n",
                     "**Week of 2026-06-01 (versions 2026.05.138 to 2026.06.17)**\n",
                     "This paragraph mentions PR #1234 in passing.\n",
                     "- a bullet about #1234\n",
                     "**Bold text #1234** but not an entry header\n"):
            self.assertEqual(mod.parse_changelog_prs(text), set(), text[:50])

    def test_headers_read_raw_lookalikes_widen_the_audit_loudly(self) -> None:
        """The 2026-09-30 no-masking ruling (r4; replacing the W5 fenced/commented strip).

        parse_changelog_prs reads the RAW text: a fenced or commented header lookalike counts
        toward the audit universe like any real header, so an example can only ADD loud row
        demands (a missing-row finding on a phantom PR), never remove one -- the safe direction,
        and the mirror image of the store-scope ceiling, which reads the SAME raw text with the
        same cell grammar, so ``max(changelog)`` still never exceeds the ceiling. The legacy
        form's prose-tail precision is unchanged.
        """
        mod = self._load_module()
        self.assertEqual(
            mod.parse_changelog_prs("```\n**2026-01-01 | 1.0.0 | PRs #9000-#9005 (6 PRs)**\n```\n"),
            {9000, 9001, 9002, 9003, 9004, 9005},
            "a fenced lookalike is a real header: more demands, never fewer")
        self.assertEqual(
            mod.parse_changelog_prs("<!--\n**2026-01-01 | 1.0.0 | PR #9004** - x\n-->\n"),
            {9004}, "a commented-out header is a real header too")
        self.assertEqual(
            mod.parse_changelog_prs(
                "## 2026-07-02, Library Version 2026.07.40, PR #552 - follow-up to PR #999\n"),
            {552}, "the legacy form must not consume PR mentions in its prose tail")

    def test_max_header_span_bounds_the_WHOLE_header_not_each_token(self) -> None:
        """Codex WARNING 1 / claude WARNING 4: three in-bound tokens, one absurd header."""
        mod = self._load_module()
        big = "**2026-01-01 | 1.0.0 | PRs #1-#5000 and #5001-#10000 and #10001-#15000 (x PRs)**"
        got = mod.parse_changelog_prs(big)
        # Exact set, not a bound plus two spot checks: an implementation returning only
        # {1, 15000} would satisfy those and drop four endpoints the header names.
        self.assertEqual(got, {1, 5000, 5001, 10000, 10001, 15000})

    def test_inverted_range_keeps_endpoints_rather_than_vanishing(self) -> None:
        # A malformed range must narrow the audit, not silently drop the PRs the header names.
        mod = self._load_module()
        self.assertEqual(
            mod.parse_changelog_prs("**2026-01-01 | 1.0.0 | PRs #500-#400 (x PRs)**"), {400, 500})

    def test_parse_changelog_prs_on_the_live_file_is_not_degenerate(self) -> None:
        """The defect this repairs: the parser returned ONE PR from the live file.

        Asserts the SHAPE, because a bare count drifts AND is too weak: an endpoint-only parser
        would pass a loose count while contributing no interior at all. The interior members below
        come from the live `#1442-#1464` header, so this fails for a singular-only parser and for
        an endpoint-only one. The count stays as a secondary guard.
        """
        mod = self._load_module()
        live = (REPO_ROOT / "CHANGELOG.md").read_text(encoding="utf-8")
        prs = mod.parse_changelog_prs(live)
        self.assertTrue({1444, 1455, 1460} <= prs,
                        "a rolled-up range must contribute its INTERIOR, not just endpoints")
        self.assertGreater(len(prs), 100,
                           "a singular-only parser returns ~1 here; a range-aware one returns many")

    def test_bypass_log_all_rows_present_passes(self) -> None:
        # Check 6: every in-window merged PR has a row: no flag.
        mod = self._load_module()
        self.assertEqual(
            mod.bypass_log_findings({1170, 1171, 1172, 1175}, {1170, 1171, 1172}), [],
            "a complete bypass log must not flag",
        )

    def test_bypass_log_missing_row_flagged(self) -> None:
        # Check 6: the #1170-#1174 class, five merges that shipped with no row.
        mod = self._load_module()
        findings = mod.bypass_log_findings({1170, 1171, 1172, 1175}, {1170, 1172})
        self.assertTrue(findings, "an unlogged in-window merge should flag")
        self.assertIn("bypass-log", findings[0])
        self.assertIn("#1171", findings[0])
        # P-1.69-adjacent (resolve_working display fix): the message names the resolve_working
        # relpath, never the retired public .working/ prefix (the store has no working/ subdir).
        self.assertIn("merge-bypass-log.md", findings[0])
        self.assertNotIn(".working/merge-bypass", findings[0])

    def test_bypass_log_highest_pr_exempt(self) -> None:
        # Check 6: the highest-numbered PR is in flight; its own row is written after its
        # merge, so demanding it here would make every PR fail its own gate.
        mod = self._load_module()
        self.assertEqual(
            mod.bypass_log_findings({1170, 1175}, {1170}), [],
            "the highest-numbered PR must be exempt as in-flight",
        )

    def test_bypass_log_floor_is_the_registers_own_oldest_row(self) -> None:
        # Check 6: a log that starts partway through history is not retroactively in breach.
        mod = self._load_module()
        self.assertEqual(
            mod.bypass_log_findings({900, 1173, 1174, 1175}, {1173, 1174}), [],
            "PRs older than the log's own oldest row are out of scope",
        )

    def test_bypass_log_empty_is_a_noop_not_a_storm(self) -> None:
        # Check 6: an empty or absent log has no floor to anchor, so flagging would sweep the
        # whole corpus history and break an adopter fork that deleted `.working/`.
        mod = self._load_module()
        self.assertEqual(
            mod.bypass_log_findings({329, 900, 1174, 1175}, set()), [],
            "an empty bypass log must no-op rather than flag every PR since inception",
        )

    def test_bypass_log_row_parser_ignores_non_rows(self) -> None:
        # Check 6: only a real data row counts, so prose mentioning a PR number does not
        # silently satisfy the parity.
        mod = self._load_module()
        text = (
            "| 2026-07-25 | #1174 | green | `gh pr merge --admin` | j | c |\n"
            "Prose mentioning #9999 must not count as a row.\n"
            "| --- | --- | --- | --- | --- | --- |\n"
        )
        self.assertEqual(mod.parse_bypass_prs(text), {1174})

    def test_bypass_log_declared_own_pr_below_merged_prs_is_exempt(self) -> None:
        # Check 6 / 3b145: the #2653 class. A rebased branch carried merged #2654-#2665 above
        # its own unmerged #2653, so #2653 fell below max_pr and its own pre-push guard demanded
        # a bypass row that may only record an OBSERVED merge. With the declared own PR passed,
        # exactly that PR is exempt and the window stays green.
        mod = self._load_module()
        self.assertEqual(
            mod.bypass_log_findings({2600, 2653, 2654, 2665}, {2600, 2654}, own_pr=2653), [],
            "the branch's declared own PR must be exempt even below later-merged PRs",
        )

    def test_bypass_log_no_declaration_keeps_the_loud_false_positive(self) -> None:
        # Check 6 / 3b145 guard: with no certain declaration (own_pr=None, the default), the
        # out-of-order PR still flags. Fail-closed, per the 2026-08-10 precedent: a demand is
        # only ever dropped on a certain own-PR declaration, never on an absent or uncertain one.
        mod = self._load_module()
        findings = mod.bypass_log_findings({2600, 2653, 2654, 2665}, {2600, 2654})
        self.assertTrue(findings, "without a declaration the out-of-order PR must still flag")
        self.assertIn("#2653", findings[0])

    def test_bypass_log_own_pr_exemption_never_reaches_any_other_pr(self) -> None:
        # Check 6 / 3b145 guard: merged PRs with no row, both BELOW (#2650) and ABOVE (#2660)
        # the declared own PR, still fail; only the one declared PR is exempt.
        mod = self._load_module()
        findings = mod.bypass_log_findings({2600, 2650, 2653, 2660, 2665}, {2600}, own_pr=2653)
        self.assertEqual(len(findings), 2, findings)
        self.assertTrue(any("#2650" in f for f in findings),
                        "a merged PR below the own PR with no row must still flag")
        self.assertTrue(any("#2660" in f for f in findings),
                        "a merged PR above the own PR with no row must still flag")
        self.assertFalse(any("#2653" in f for f in findings),
                         "the declared own PR must never be flagged")

    def test_bypass_log_own_pr_not_in_window_is_inert(self) -> None:
        # Check 6 / 3b145: an own_pr that matches nothing in the window exempts nothing
        # (the exemption is an identity match, never a widening), and an own PR that
        # already has a row changes nothing.
        mod = self._load_module()
        findings = mod.bypass_log_findings({2600, 2653, 2665}, {2600}, own_pr=9999)
        self.assertEqual(len(findings), 1, findings)
        self.assertIn("#2653", findings[0])
        self.assertEqual(
            mod.bypass_log_findings({2600, 2653, 2665}, {2600, 2653}, own_pr=2653), [],
        )

    def test_register_row_order_ascending_passes(self) -> None:
        # Check 5: a run-table in strictly ascending run-number order: no flag.
        mod = self._load_module()
        text = "| r1 | 2026-07-10 |\n| r2 | 2026-07-11 |\n| r3 | 2026-07-13 |\n"
