class ResolveSiblingTests(unittest.TestCase):
    """lint_common.resolve_sibling / sibling_placeholder_present, and the
    advisory tools' graceful degradation when a sibling repo is absent on a
    portable clone (PR #996). resolve_sibling reads the module
    global lint_common.REPO_ROOT at call time, so the tests drive the logic
    by monkeypatching that global to a temp tree with / without siblings.
    """

    def setUp(self) -> None:
        self._clear_grc_store()

    def _lc(self):
        tools_dir = str(REPO_ROOT / "tools")
        if tools_dir not in sys.path:
            sys.path.insert(0, tools_dir)
        import lint_common
        return lint_common

    def _load_ref_holds(self, unique: str):
        import importlib.util
        tools_dir = str(REPO_ROOT / "tools")
        if tools_dir not in sys.path:
            sys.path.insert(0, tools_dir)
        spec = importlib.util.spec_from_file_location(
            unique, REPO_ROOT / "tools/ref-holds.py")
        assert spec is not None and spec.loader is not None
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def test_unknown_name_raises(self) -> None:
        lc = self._lc()
        with self.assertRaises(ValueError):
            lc.resolve_sibling("bogus")
        with self.assertRaises(ValueError):
            lc.sibling_placeholder_present("bogus")

    def test_resolve_real_sibling_and_absent(self) -> None:
        lc = self._lc()
        with tempfile.TemporaryDirectory() as td:
            root = Path(td) / "grc_library"
            root.mkdir()
            orig = lc.REPO_ROOT
            try:
                lc.REPO_ROOT = root
                # No sibling checkout yet -> None (portable-clone state).
                self.assertIsNone(lc.resolve_sibling("ref"))
                # Create the real sibling next to the repo root -> returned.
                (Path(td) / "grc_library_ref").mkdir()
                self.assertEqual(
                    lc.resolve_sibling("ref"), Path(td) / "grc_library_ref")
            finally:
                lc.REPO_ROOT = orig

    def _clear_grc_store(self):
        # The store default is <repo-parent>/private; an exported GRC_STORE would override
        # it and break temp-root isolation. Clear it for the duration of a resolver test.
        prev = os.environ.pop("GRC_STORE", None)
        if prev is not None:
            self.addCleanup(os.environ.__setitem__, "GRC_STORE", prev)

    def test_resolve_working_prefers_private_then_local_then_none(self) -> None:
        # resolve_working (with no store present): grc_library_private/.working/<rel>
        # preferred, then the in-repo .working/<rel>, else None.
        lc = self._lc()
        with tempfile.TemporaryDirectory() as td:
            root = Path(td) / "grc_library"
            root.mkdir()
            orig = lc.REPO_ROOT
            try:
                lc.REPO_ROOT = root
                # Neither private nor local -> None (public CI / adopter clone).
                self.assertIsNone(lc.resolve_working("x.md"))
                # In-repo .working/x.md present -> the local fallback.
                (root / ".working").mkdir()
                (root / ".working" / "x.md").write_text("local", encoding="utf-8")
                self.assertEqual(
                    lc.resolve_working("x.md"), root / ".working" / "x.md")
                # Private sibling .working/x.md present -> PREFERRED over local.
                priv = Path(td) / "grc_library_private" / ".working"
                priv.mkdir(parents=True)
                (priv / "x.md").write_text("private", encoding="utf-8")
                self.assertEqual(lc.resolve_working("x.md"), priv / "x.md")
                # A rel present only in local (not private) -> local fallback,
                # even with the private sibling present.
                (root / ".working" / "y.md").write_text("local-y", encoding="utf-8")
                self.assertEqual(
                    lc.resolve_working("y.md"), root / ".working" / "y.md")
            finally:
                lc.REPO_ROOT = orig

    def test_resolve_working_prefers_store_over_private_and_local(self) -> None:
        # adopt-with-overlay migration (option B): the fleet-standard store <repo-parent>/private
        # is preferred over both the private sibling .working/ and the in-repo .working/.
        lc = self._lc()
        with tempfile.TemporaryDirectory() as td:
            root = Path(td) / "grc_library"
            root.mkdir()
            orig = lc.REPO_ROOT
            try:
                lc.REPO_ROOT = root
                store = Path(td) / "private"          # <repo-parent>/private
                store.mkdir()
                (store / "x.md").write_text("store", encoding="utf-8")
                # store wins over both fallbacks
                (root / ".working").mkdir()
                (root / ".working" / "x.md").write_text("local", encoding="utf-8")
                priv = Path(td) / "grc_library_private" / ".working"
                priv.mkdir(parents=True)
                (priv / "x.md").write_text("private", encoding="utf-8")
                self.assertEqual(lc.resolve_working("x.md"), store / "x.md")
                # a file only in the sibling (partial store) falls back correctly
                (priv / "y.md").write_text("priv-y", encoding="utf-8")
                self.assertEqual(lc.resolve_working("y.md"), priv / "y.md")
                # resolve_working_dir returns the store when it exists
                self.assertEqual(lc.resolve_working_dir(), store)
            finally:
                lc.REPO_ROOT = orig

    def test_store_root_absolute_and_relative_env(self) -> None:
        # _store_root: absolute GRC_STORE used as-is; relative resolved against the repo
        # root (not the process CWD), so its meaning is CWD-independent.
        lc = self._lc()
        with tempfile.TemporaryDirectory() as td:
            root = Path(td) / "grc_library"
            root.mkdir()
            absdir = Path(td) / "elsewhere"
            try:
                os.environ["GRC_STORE"] = str(absdir)
                self.assertEqual(lc._store_root(root), absdir)
                os.environ["GRC_STORE"] = "rel-store"
                self.assertEqual(lc._store_root(root), (root / "rel-store").resolve())
            finally:
                os.environ.pop("GRC_STORE", None)
            # default when unset: <repo-parent>/private
            self.assertEqual(lc._store_root(root), root.parent / "private")
            # a store that resolves INSIDE the public repo is REJECTED by _store_dir
            # (private content must never land in the public checkout); reads fall back.
            (root / "private").mkdir()
            try:
                os.environ["GRC_STORE"] = "private"   # -> <repo>/private (in-repo)
                self.assertIsNone(lc._store_dir(root))
                self.assertEqual(lc.private_store_roots(root), [])
                os.environ["GRC_STORE"] = "."          # -> the repo root itself
                self.assertIsNone(lc._store_dir(root))
                self.assertEqual(lc.private_store_roots(root), [])
            finally:
                os.environ.pop("GRC_STORE", None)

    def test_private_store_roots_and_for_write_private_prefer_store(self) -> None:
        # private_store_roots lists the store then the sibling (both private); a NEW
        # private-required record is written to the store (option B unification).
        lc = self._lc()
        with tempfile.TemporaryDirectory() as td:
            root = Path(td) / "grc_library"
            root.mkdir()
            orig = lc.REPO_ROOT
            try:
                lc.REPO_ROOT = root
                store = Path(td) / "private"; store.mkdir()
                priv = Path(td) / "grc_library_private"; (priv / ".working").mkdir(parents=True)
                roots = lc.private_store_roots(root)
                self.assertEqual(roots[0], store.resolve())
                self.assertIn(priv.resolve(), roots)
                # a new private-required file goes to the store
                self.assertEqual(
                    lc.resolve_working_for_write_private("new-priv.md", repo_root=root),
                    store / "new-priv.md")
            finally:
                lc.REPO_ROOT = orig

    def test_placeholder_present_and_absent(self) -> None:
        lc = self._lc()
        with tempfile.TemporaryDirectory() as td:
            root = Path(td) / "grc_library"
            root.mkdir()
            orig = lc.REPO_ROOT
            try:
                lc.REPO_ROOT = root
                self.assertFalse(lc.sibling_placeholder_present("scratch"))
                (root / ".scratch").mkdir()
                self.assertTrue(lc.sibling_placeholder_present("scratch"))
            finally:
                lc.REPO_ROOT = orig

    def test_ref_holds_graceful_on_adopter_clone(self) -> None:
        # ADOPTER clone with grc_library_ref genuinely absent -> exit 0 (advisory
        # no-op), even with NO .ref placeholder (a fresh adopter clone has none;
        # deep-assessment 3.183(3)). Gated on the detect-env operator identity,
        # injected here as adopter.
        lc = self._lc()
        mod = self._load_ref_holds("_ref_holds_graceful")
        mod._operator_is_adopter = lambda: True
        with tempfile.TemporaryDirectory() as td:
            root = Path(td) / "grc_library"
            root.mkdir()
            orig = lc.REPO_ROOT
            try:
                lc.REPO_ROOT = root
                self.assertEqual(mod.main(["ref-holds.py", "anything"]), 0)
            finally:
                lc.REPO_ROOT = orig

    def test_ref_holds_maintainer_absent_ref_stays_loud(self) -> None:
        # MAINTAINER (or undetermined identity) with grc_library_ref genuinely
        # absent -> exit 2 (LOUD), the 1.19.7 loud gate /orch relies on. Identity
        # injected here as NON-adopter (the fail-safe default of the real helper
        # too, since a maintainer origin classifies as maintainer).
        lc = self._lc()
        mod = self._load_ref_holds("_ref_holds_broken")
        mod._operator_is_adopter = lambda: False
        with tempfile.TemporaryDirectory() as td:
            root = Path(td) / "grc_library"
            root.mkdir()
            orig = lc.REPO_ROOT
            try:
                lc.REPO_ROOT = root
                self.assertEqual(mod.main(["ref-holds.py", "anything"]), 2)
            finally:
                lc.REPO_ROOT = orig

    def test_ref_holds_errors_on_corrupt_sibling(self) -> None:
        # A real ../grc_library_ref dir that EXISTS but lacks its index (a
        # corrupt/partial checkout) must still exit 2 EVEN for an adopter: the
        # graceful branch is gated on resolve_sibling("ref") is None, so a broken
        # ref is surfaced, not masked, regardless of operator identity.
        lc = self._lc()
        mod = self._load_ref_holds("_ref_holds_corrupt")
        mod._operator_is_adopter = lambda: True
        with tempfile.TemporaryDirectory() as td:
            root = Path(td) / "grc_library"
            root.mkdir()
            (Path(td) / "grc_library_ref").mkdir()  # exists but has no INDEX/catalogue
            orig = lc.REPO_ROOT
            try:
                lc.REPO_ROOT = root
                self.assertEqual(mod.main(["ref-holds.py", "anything"]), 2)
            finally:
                lc.REPO_ROOT = orig

    def test_operator_is_adopter_fails_safe_on_probe_error(self) -> None:
        # The identity helper must fail SAFE (return False -> loud exit 2) if the
        # detect-env probe cannot run at all, so a probe malfunction can NEVER
        # silently no-op a maintainer's missing grc_library_ref (the 1.19.7 loud
        # gate). Force the importlib load to raise and assert False. Environment-
        # independent (does not depend on this clone's origin classification).
        import importlib.util as _iu
        mod = self._load_ref_holds("_ref_holds_failsafe")
        orig = _iu.spec_from_file_location
        try:
            def _boom(*a, **k):
                raise RuntimeError("forced probe failure")
            _iu.spec_from_file_location = _boom
            self.assertFalse(mod._operator_is_adopter())
        finally:
            _iu.spec_from_file_location = orig

    def test_identity_is_adopter_pure_decision(self) -> None:
        # The pure decision must require a POSITIVELY-READ, non-maintainer origin.
        # A None origin_url is NOT adopter: detect-env swallows a git-origin probe
        # FAILURE (e.g. a subprocess timeout) into a None origin, so keying on the
        # classification alone would let a maintainer's git timeout silently no-op
        # the missing-_ref HALT (regression guard for that fail-loud violation).
        mod = self._load_ref_holds("_ref_holds_puredecision")
        f = mod._identity_is_adopter
        # fork / private origin -> adopter (graceful)
        self.assertTrue(f({"origin_url": "https://github.com/someone/grc_library",
                           "origin_is_maintainer_repo": False}))
        # maintainer origin -> NOT adopter (loud)
        self.assertFalse(f({"origin_url": "https://github.com/jposluns/grc_library",
                            "origin_is_maintainer_repo": True}))
        # git-origin probe FAILURE / genuinely absent origin -> NOT adopter (loud)
        self.assertFalse(f({"origin_url": None, "origin_is_maintainer_repo": False}))
        # missing fields -> NOT adopter (loud, fail-safe)
        self.assertFalse(f({}))
        # truthy origin_url with the maintainer flag MISSING (a partial probe
        # result) -> NOT adopter: the flag must be EXPLICITLY False, so an
        # ambiguous/partial identity REFUSES rather than permits (guard-input).
        self.assertFalse(f({"origin_url": "https://github.com/jposluns/grc_library"}))
        # flag present but None -> NOT adopter (loud)
        self.assertFalse(f({"origin_url": "https://github.com/x/grc_library",
                            "origin_is_maintainer_repo": None}))
        # a NON-STRING truthy origin_url (probe_identity yields str|None, so this
        # is non-producible, but the decision fails safe anyway) -> NOT adopter
        self.assertFalse(f({"origin_url": 1, "origin_is_maintainer_repo": False}))
        # empty-string origin -> NOT adopter (loud)
        self.assertFalse(f({"origin_url": "", "origin_is_maintainer_repo": False}))

    def test_resolve_working_dir_prefers_private_then_local_then_none(self) -> None:
        # resolve_working_dir: the .working DIRECTORY, private preferred, in-repo
        # fallback, else None (the tree-walker analogue of resolve_working).
        lc = self._lc()
        with tempfile.TemporaryDirectory() as td:
            root = (Path(td) / "grc_library")
            root.mkdir()
            root_r = root.resolve()
            orig = lc.REPO_ROOT
            try:
                lc.REPO_ROOT = root
                self.assertIsNone(lc.resolve_working_dir())
                (root / ".working").mkdir()
                self.assertEqual(lc.resolve_working_dir(), root_r / ".working")
                priv = (Path(td) / "grc_library_private" / ".working")
                priv.mkdir(parents=True)
                self.assertEqual(lc.resolve_working_dir(), priv.resolve())
            finally:
                lc.REPO_ROOT = orig

    def test_resolve_working_for_write_existing_then_private_then_local(self) -> None:
        # resolve_working_for_write: an existing file wins; else the private
        # sibling when that repo dir exists; else the in-repo .working. Never None.
        lc = self._lc()
        with tempfile.TemporaryDirectory() as td:
            root = (Path(td) / "grc_library")
            root.mkdir()
            (root / ".working").mkdir()
            root_r = root.resolve()
            orig = lc.REPO_ROOT
            try:
                lc.REPO_ROOT = root
                # No private sibling, file absent -> in-repo .working target.
                self.assertEqual(
                    lc.resolve_working_for_write("new.md"),
                    root_r / ".working" / "new.md")
                # Existing in-repo file wins, even once the private sibling appears.
                (root / ".working" / "log.md").write_text("x", encoding="utf-8")
                priv = (Path(td) / "grc_library_private" / ".working")
                priv.mkdir(parents=True)
                self.assertEqual(
                    lc.resolve_working_for_write("log.md"),
                    root_r / ".working" / "log.md")
                # Absent in both, private repo dir exists -> private target.
                self.assertEqual(
                    lc.resolve_working_for_write("fresh.md"),
                    priv.resolve() / "fresh.md")
                # Present in private -> that existing private path.
                (priv / "p.md").write_text("x", encoding="utf-8")
                self.assertEqual(
                    lc.resolve_working_for_write("p.md"),
                    priv.resolve() / "p.md")
            finally:
                lc.REPO_ROOT = orig

    def test_resolve_working_for_write_no_split_when_private_working_absent(self) -> None:
        # The split-tree guard: the private REPO exists but its `.working/` does NOT
        # (the pre-move state on the maintainer machine). A NEW file must resolve
        # IN-REPO, never split off into the private sibling ahead of the content move.
        lc = self._lc()
        with tempfile.TemporaryDirectory() as td:
            root = (Path(td) / "grc_library")
            root.mkdir()
            (root / ".working").mkdir()
            (Path(td) / "grc_library_private").mkdir()  # private REPO present, .working ABSENT
            root_r = root.resolve()
            orig = lc.REPO_ROOT
            try:
                lc.REPO_ROOT = root
                self.assertEqual(
                    lc.resolve_working_for_write("np.md"),
                    root_r / ".working" / "np.md")
            finally:
                lc.REPO_ROOT = orig


class WorkingResolveNoOpTests(unittest.TestCase):
    """The six .working-reading gates rewired in PR #1227 (50/59/78/60/43/51)
    must NO-OP with exit 0 and an honest skip line when resolve_working returns
    None (the .working move to the private sibling and then the operational store: the
    tree is absent in public CI and in an adopter clone). The other fixtures
    exercise only the EXPLICIT --root path; this class binds the DEFAULT
    resolve_working path so a broken default resolver, or a missing no-op
    branch, cannot pass silently (codex verify of PR #1227, Medium finding).
    """

    def _load(self, fname: str):
        import importlib.util
        tools_dir = str(REPO_ROOT / "tools")
        if tools_dir not in sys.path:
            sys.path.insert(0, tools_dir)
        spec = importlib.util.spec_from_file_location(
            "noop_" + fname.replace("-", "_").replace(".py", ""),
            REPO_ROOT / "tools" / fname)
        assert spec is not None and spec.loader is not None
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def _assert_noop(self, fname, call):
        import io
        import contextlib
        mod = self._load(fname)
        orig_rw = mod.resolve_working
        orig_argv = sys.argv
        buf = io.StringIO()
        try:
            mod.resolve_working = lambda rel: None
            sys.argv = [fname]
            with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
                rc = call(mod)
        finally:
            mod.resolve_working = orig_rw
            sys.argv = orig_argv
        out = buf.getvalue()
        self.assertEqual(
            rc, 0,
            f"{fname} must no-op (exit 0) when resolve_working returns None "
            f"(absent .working/ in public CI / an adopter clone); got {rc}.\n{out}")
        self.assertTrue(
            ("not present" in out) or ("skipped" in out) or ("skipping" in out),
            f"{fname} must print an honest skip line rather than a false-clean "
            f"result over zero files.\n{out}")

    def test_gate50_bookkeeping_parity_noop(self):
        self._assert_noop("lint-bookkeeping-parity.py", lambda m: m.main())

    def test_gate59_changelog_mirror_noop(self):
        self._assert_noop(
            "lint-changelog-mirror-header-parity.py", lambda m: m.main([]))

    def test_gate78_number_permanence_noop(self):
        self._assert_noop("lint-todo-number-permanence.py", lambda m: m.main([]))

    def test_gate60_guardrail_cadence_noop(self):
        self._assert_noop("lint-guardrail-cadence.py", lambda m: m.main([]))

    def test_gate43_followup_ageing_noop(self):
        # Gate 43's NORMAL OK line ALSO contains "skipped" ("a target that is
        # not present is skipped"), so the generic skip-substring check cannot
        # distinguish the no-op from a scan of a present target. Assert instead
        # that resolve_working->None makes it scan ZERO targets ("0 of N"); a
        # removed/broken default-resolver branch would read the present in-repo
        # `.working/` file and scan 1 of N, failing this. (codex validate-pr-1227.)
        import io
        import contextlib
        mod = self._load("lint-followup-ageing.py")
        orig_rw, orig_argv = mod.resolve_working, sys.argv
        buf = io.StringIO()
        try:
            mod.resolve_working = lambda rel: None
            sys.argv = ["lint-followup-ageing.py"]
            with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
                rc = mod.main()
        finally:
            mod.resolve_working, sys.argv = orig_rw, orig_argv
        out = buf.getvalue()
        self.assertEqual(rc, 0, f"gate 43 must no-op (exit 0) on resolve_working->None.\n{out}")
        self.assertIn(
            "0 of", out,
            "gate 43 no-op must scan ZERO targets (`0 of N`); a broken default "
            f"resolver reading the present `.working/` file would scan `1 of N`.\n{out}")

    def test_gate51_working_prose_hygiene_noop(self):
        self._assert_noop("lint-working-prose-hygiene.py", lambda m: m.main([]))

    def test_gate51_display_path_external_is_absolute(self):
        # display_path renders an ABSOLUTE path for a file OUTSIDE the repo (the
        # operational store or private-sibling fallback post-migration), so relative_to(REPO_ROOT) does not
        # raise ValueError on every finding; a repo-internal path stays relative.
        mod = self._load("lint-working-prose-hygiene.py")
        outside = Path("/tmp") / "grc_library_private" / ".working" / "x.md"
        self.assertEqual(mod.display_path(outside), outside.as_posix())
        inside = mod.REPO_ROOT / "README.md"
        self.assertEqual(mod.display_path(inside), "README.md")


class StoreDegradedNoticeTests(unittest.TestCase):
    """3b635: a gate that skips (exit 0) because the private store is absent prints exactly one
    `DEGRADED:` line on stdout saying the pass attests nothing about what it skipped, and prints
    none when a fixture store supplies the input. Only the GitHub Actions run is authoritative
    (specification section 4), and these gates degrade there, so the line is what keeps a green
    run from reading as a pass. Each case patches the module's own resolver names, the
    WorkingResolveNoOpTests idiom, so neither the maintainer's real store nor its absence leaks
    in; gate 107 uses its --root fixture layout, whose sibling slot is the degraded-path selector.
    Every gate prints the line through lint_common.print_degraded, which also prints a GitHub
    Actions warning annotation when GITHUB_ACTIONS is "true", so each case runs the absent store
    with GITHUB_ACTIONS unset and set: the plain line appears either way, the annotation only
    when set.
    """

    _load = WorkingResolveNoOpTests._load
    ANNOTATION = "::warning title="

    def setUp(self) -> None:
        self.store = Path(tempfile.mkdtemp(prefix="degraded-store-"))
        self.addCleanup(shutil.rmtree, self.store, True)

    def _write(self, rel: str, text: str) -> Path:
        path = self.store / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        return path

    def _present(self, rel: str) -> "Path | None":
        cand = self.store / rel
        return cand if cand.exists() else None

    @staticmethod
    def _github_env(github: bool):
        """Patch os.environ so GITHUB_ACTIONS is "true" or absent (CI itself sets it)."""
        from unittest.mock import patch
        env = {k: v for k, v in os.environ.items() if k != "GITHUB_ACTIONS"}
        if github:
            env["GITHUB_ACTIONS"] = "true"
        return patch.dict(os.environ, env, clear=True)

    def _run(self, fname: str, call, absent: bool, github: bool = False,
             **patches) -> tuple[int, str, str]:
        import io
        import contextlib
        from unittest.mock import patch
        mod = self._load(fname)
        if "resolve_working" not in patches and hasattr(mod, "resolve_working"):
            patches["resolve_working"] = (lambda rel: None) if absent else self._present
        buf, err = io.StringIO(), io.StringIO()
        with contextlib.ExitStack() as stack:
            for name, value in patches.items():
                stack.enter_context(patch.object(mod, name, value))
            stack.enter_context(patch.object(sys, "argv", [fname]))
            stack.enter_context(self._github_env(github))
            stack.enter_context(contextlib.redirect_stdout(buf))
            stack.enter_context(contextlib.redirect_stderr(err))
            rc = call(mod)
        return rc, buf.getvalue(), err.getvalue()

    def _assert_degraded(self, gate: str, label: str, out: str, github: bool) -> None:
        lines = [ln for ln in out.splitlines() if ln.startswith("DEGRADED:")]
        notes = [ln for ln in out.splitlines() if ln.startswith(self.ANNOTATION)]
        self.assertEqual(len(lines), 1, f"{label}: expected one DEGRADED line\n{out}")
        self.assertIn("attests nothing", lines[0])
        self.assertTrue(lines[0].startswith(f"DEGRADED: {gate} skipped "), lines[0])
        if github:
            self.assertEqual(notes, [f"::warning title={gate} degraded::{lines[0]}"],
                             f"{label}: GITHUB_ACTIONS=true needs one annotation\n{out}")
        else:
            self.assertEqual(notes, [], f"{label}: no annotation outside GitHub Actions\n{out}")

    def _assert_clean(self, label: str, out: str) -> None:
        self.assertNotIn("DEGRADED:", out, f"{label}: a present store is not degraded\n{out}")
        self.assertNotIn(self.ANNOTATION, out, f"{label}: a present store is not degraded\n{out}")

    def _check(self, gate: str, fname: str, call, *, absent_patches=None,
               present_patches=None) -> None:
        for github in (False, True):
            rc, out, err = self._run(fname, call, True, github, **(absent_patches or {}))
            self.assertEqual(rc, 0, f"{fname}: the absent-store skip must still exit 0\n{out}{err}")
            self._assert_degraded(gate, f"{fname} (GITHUB_ACTIONS={github})", out, github)
        rc, out, err = self._run(fname, call, False, True, **(present_patches or {}))
        self.assertEqual(rc, 0, f"{fname}: the fixture-store run must pass\n{out}{err}")
        self._assert_clean(fname, out)

    def test_helper_annotation_only_when_github_actions_is_true(self) -> None:
        import io
        import contextlib
        from unittest.mock import patch
        from lint_common import print_degraded
        for value, annotated in ((None, False), ("false", False), ("1", False), ("true", True)):
            buf = io.StringIO()
            env = {k: v for k, v in os.environ.items() if k != "GITHUB_ACTIONS"}
            if value is not None:
                env["GITHUB_ACTIONS"] = value
            with patch.dict(os.environ, env, clear=True), contextlib.redirect_stdout(buf):
                print_degraded("gate 0", "gate 0 skipped x (100%); this pass attests nothing.")
            expected = ["DEGRADED: gate 0 skipped x (100%); this pass attests nothing."]
            if annotated:
                # Workflow-command escaping: a % in the message is written %25.
                expected.append("::warning title=gate 0 degraded::"
                                "DEGRADED: gate 0 skipped x (100%25); this pass attests nothing.")
            self.assertEqual(buf.getvalue().splitlines(), expected, f"GITHUB_ACTIONS={value!r}")

    def test_flip_a_silent_helper_fails_the_check(self) -> None:
        # Deliberate flip: the helper stops printing (print is shadowed in lint_common's own
        # globals, the module every gate's print_degraded comes from). _check must then fail,
        # so the cases above cannot pass with a helper that prints nothing.
        from unittest.mock import patch
        self._write("overnight-pr.md", "# Overnight\n\n**Status:** stub\n")
        helper_globals = self._load("lint-overnight-file.py").print_degraded.__globals__
        with patch.dict(helper_globals, {"print": lambda *a, **k: None}):
            with self.assertRaises(AssertionError):
                self._check("gate 46", "lint-overnight-file.py", lambda m: m.main())
        self._check("gate 46", "lint-overnight-file.py", lambda m: m.main())

