class AllowlistSpecParityTests(unittest.TestCase):
    """Gate 101 (3b31b): allow-list and citation-verification section 7.1 parity."""

    SPEC_HEAD = "# S\n\n### 7.1 Initial allow-list\n\n"

    @classmethod
    def setUpClass(cls) -> None:
        cls.mod = load_linter_module("tools/lint-allowlist-spec-parity.py", "allowlist_parity_mod")

    def spec(self, domains: list[str], block: str | None = None) -> str:
        """Section 7.1 with its json citation-publishers block (3b31b redesign: no table parsing)."""
        import json

        if block is None:
            entries = [{"publisher": f"P{i}", "domains": [d], "covers": "x"} for i, d in enumerate(domains)]
            block = "```json citation-publishers\n" + json.dumps(entries) + "\n```\n"
        return self.SPEC_HEAD + block + "\n### 7.2 Additions\n"

    def allow(self, body: str) -> str:
        return "ALLOW_LIST = {\n" + body + "}\n"

    def floor(self, n: int = 0):
        from unittest import mock

        return mock.patch.object(self.mod, "MIN_SPEC_DOMAINS", n)

    def test_suffix_matching_is_gate_24s_own_matcher(self) -> None:
        """3b52c: gate 101 delegates to gate 24's is_allowed, so the two cannot drift; the label
        boundary still holds (a near-miss host is not a subdomain)."""
        from unittest import mock

        self.assertTrue(self.mod.covered("sub.iso.org", {"iso.org"}))
        self.assertTrue(self.mod.covered("iso.org", {"iso.org"}))
        self.assertFalse(self.mod.covered("evil-iso.org", {"iso.org"}))
        self.assertFalse(self.mod.covered("iso.org.evil.com", {"iso.org"}))
        engine = self.mod._link_engine()
        with mock.patch.object(engine, "is_allowed", return_value=True) as spy:
            self.assertTrue(self.mod.covered("x.example", {"y.example"}))
        spy.assert_called_once_with("x.example", allow_list={"y.example"})

    def test_live_repository_passes(self) -> None:
        result = run_linter("tools/lint-allowlist-spec-parity.py")
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_unmarked_uncovered_entry_fails(self) -> None:
        with self.floor():
            allow = self.mod.allow_entries(self.allow('    "iso.org", "vendor.example",\n'))
            findings = self.mod.check(allow, self.mod.spec_domains(self.spec(["iso.org"])))
        self.assertEqual(len(findings), 1)
        self.assertIn("vendor.example", findings[0])

    def test_same_line_markers_pass(self) -> None:
        body = ('    "iso.org",\n'
                '    "vendor.example",  # non-publisher: a tool vendor\n'
                '    "pub.example",  # pending-publisher: register entry to come\n')
        with self.floor():
            findings = self.mod.check(self.mod.allow_entries(self.allow(body)),
                                      self.mod.spec_domains(self.spec(["iso.org"])))
        self.assertEqual(findings, [])

    def test_preceding_line_comment_does_not_mark(self) -> None:
        body = '    # non-publisher: a group of vendors\n    "vendor.example",\n'
        with self.floor():
            findings = self.mod.check(self.mod.allow_entries(self.allow(body)),
                                      self.mod.spec_domains(self.spec(["vendor.org"])))
        self.assertTrue(any("vendor.example" in f for f in findings))

    def test_marker_needs_a_reason(self) -> None:
        body = '    "vendor.example",  # non-publisher:\n'
        with self.floor():
            findings = self.mod.check(self.mod.allow_entries(self.allow(body)),
                                      self.mod.spec_domains(self.spec(["iso.org"])))
        self.assertTrue(any("vendor.example" in f for f in findings))

    def check_body(self, body: str, domains: list[str], tail: str = "") -> list[str]:
        with self.floor():
            return self.mod.check(self.mod.allow_entries(self.allow(body) + tail),
                                  self.mod.spec_domains(self.spec(domains)))

    def test_hash_inside_string_is_not_a_marker(self) -> None:
        # codex r1: an escaped quote must not let string content forge a marker.
        body = '    "iso.org", "unlisted.example", "bad\\"# non-publisher: forged",\n'
        findings = self.check_body(body, ["iso.org"])
        self.assertTrue(any("unlisted.example" in f for f in findings))

    def test_second_assignment_is_an_input_error(self) -> None:
        with self.assertRaises(self.mod.InputError):
            self.mod.allow_entries(self.allow('    "iso.org",\n') + 'ALLOW_LIST = {"x.example"}\n')

    def test_mutating_call_is_an_input_error(self) -> None:
        with self.assertRaises(self.mod.InputError):
            self.mod.allow_entries(self.allow('    "iso.org",\n') + 'ALLOW_LIST.add("x.example")\n')

    def test_augmented_assignment_is_an_input_error(self) -> None:
        with self.assertRaises(self.mod.InputError):
            self.mod.allow_entries(self.allow('    "iso.org",\n') + 'ALLOW_LIST |= {"x.example"}\n')

    def test_unsupported_uses_are_input_errors(self) -> None:
        # codex r2: alias mutation, slice store and a match-pattern capture.
        for tail in ('alias = ALLOW_LIST\nalias.add("x.example")\n',
                     'ALLOW_LIST[:] = ["x.example"]\n',
                     'match {"x.example"}:\n    case ALLOW_LIST:\n        pass\n',
                     'import os as ALLOW_LIST\n',
                     'def f(ALLOW_LIST):\n    return 1\n'):
            with self.subTest(tail=tail), self.assertRaises(self.mod.InputError):
                self.mod.allow_entries(self.allow('    "iso.org",\n') + tail)

    def test_chained_definition_is_an_input_error(self) -> None:
        # r3 (all three families): ALLOW_LIST = alias = {...}; alias.add(...).
        for src in ('ALLOW_LIST = alias = {\n    "iso.org",\n}\nalias.add("x.example")\n',
                    'alias = ALLOW_LIST = {\n    "iso.org",\n}\n'):
            with self.subTest(src=src), self.assertRaises(self.mod.InputError):
                self.mod.allow_entries(src)

    def test_call_argument_use_is_allowed(self) -> None:
        entries = self.mod.allow_entries(self.allow('    "iso.org",\n') + 'scan(allow_list=ALLOW_LIST)\nscan(ALLOW_LIST)\n')
        self.assertEqual([e for e, _, _ in entries], ["iso.org"])

    def test_read_only_use_is_allowed(self) -> None:
        entries = self.mod.allow_entries(self.allow('    "iso.org",\n') + 'X = ALLOW_LIST.copy()\n')
        self.assertEqual([e for e, _, _ in entries], ["iso.org"])

    def test_noncanonical_spelling_fails(self) -> None:
        findings = self.check_body('    "ISO.ORG",\n', ["iso.org"])
        self.assertTrue(any("canonical" in f for f in findings))

    def test_stale_marker_on_covered_entry_fails(self) -> None:
        findings = self.check_body('    "iso.org",  # pending-publisher: row to come\n', ["iso.org"])
        self.assertTrue(any("stale marker" in f for f in findings))

    def test_suffix_covered_subdomain_passes(self) -> None:
        with self.floor():
            findings = self.mod.check(self.mod.allow_entries(self.allow('    "iso.org", "www.iso.org",\n')),
                                      self.mod.spec_domains(self.spec(["iso.org"])))
        self.assertEqual(findings, [])

    def test_reverse_unadmitted_spec_domain_fails(self) -> None:
        with self.floor():
            findings = self.mod.check(self.mod.allow_entries(self.allow('    "iso.org",\n')),
                                      self.mod.spec_domains(self.spec(["iso.org", "iec.ch"])))
        self.assertEqual(len(findings), 1)
        self.assertIn("iec.ch", findings[0])

    def test_block_input_errors(self) -> None:
        # The section 7.1 source of record fails loud (tools/citation_publishers.py rules).
        good = '[{"publisher": "ISO", "domains": ["iso.org"], "covers": "x"}]'
        shapes = {
            "missing block": "No block here.\n",
            "wrong info string": "```json\n" + good + "\n```\n",
            "two blocks": ("```json citation-publishers\n" + good + "\n```\n") * 2,
            "malformed JSON": "```json citation-publishers\n[{\"publisher\": \"ISO\",]\n```\n",
            "duplicate domain": "```json citation-publishers\n"
                '[{"publisher": "A", "domains": ["iso.org"], "covers": "x"},'
                ' {"publisher": "B", "domains": ["iso.org"], "covers": "y"}]\n```\n',
            "non-canonical domain": "```json citation-publishers\n"
                '[{"publisher": "ISO", "domains": ["ISO.org"], "covers": "x"}]\n```\n',
            "empty publisher": "```json citation-publishers\n"
                '[{"publisher": "", "domains": ["iso.org"], "covers": "x"}]\n```\n',
            "unclosed block": "```json citation-publishers\n" + good + "\n",
            # r10 codex: a second block in any fence style is counted, never silently ignored.
            "second block, tildes": "```json citation-publishers\n" + good + "\n```\n"
                "~~~json citation-publishers\n" + good + "\n~~~\n",
            "second block, indented": "```json citation-publishers\n" + good + "\n```\n"
                "  ```json citation-publishers\n" + good + "\n  ```\n",
            "second block, four backticks": "```json citation-publishers\n" + good + "\n```\n"
                "````json citation-publishers\n" + good + "\n````\n",
            "second block, trailing space": "```json citation-publishers\n" + good + "\n```\n"
                "```json citation-publishers  \n" + good + "\n```\n",
            "non-canonical single opener": "~~~json citation-publishers\n" + good + "\n~~~\n",
            "nested in an outer fence": "````\n```json citation-publishers\n" + good + "\n```\n````\n",
            "indented heading ends the section": "  ### 7.2 Outside\n\n```json citation-publishers\n"
                + good + "\n```\n",
            "domain with a trailing newline": "```json citation-publishers\n"
                '[{"publisher": "ISO", "domains": ["iso.org\\n"], "covers": "x"}]\n```\n',
            "over-long DNS label": "```json citation-publishers\n"
                '[{"publisher": "ISO", "domains": ["' + "a" * 64 + '.org"], "covers": "x"}]\n```\n',
        }
        for name, block in shapes.items():
            with self.subTest(name), self.floor(), self.assertRaises(self.mod.InputError):
                self.mod.spec_domains(self.spec([], block=block))

    def test_deeply_indented_loose_opener_is_still_counted(self) -> None:
        # 3b83 round-4 QA: LOOSE_OPEN_RE stays BROAD on purpose, one of the deliberately broad
        # fence screens in the pack README's 3b83 entry, beside the approvals-register refusal (see
        # test_indented_fence_line_still_refuses_register). A citation-publishers opener indented
        # four or eight spaces, or by a tab (where CommonMark reads indented code, not a fence),
        # is still COUNTED: beside the canonical block it fails loud as a duplicate ("found 2",
        # the assertion a detector narrowed to 0-3 would fail by parsing the duplicate silently),
        # and standing alone it still raises InputError rather than parsing anything.
        good = '[{"publisher": "ISO", "domains": ["iso.org"], "covers": "x"}]'
        canonical = "```json citation-publishers\n" + good + "\n```\n"
        for indent in ("    ", "        ", "\t"):
            dup = canonical + indent + "```json citation-publishers\n" + good + "\n" + indent + "```\n"
            with self.subTest(indent=repr(indent)), self.floor(), self.assertRaisesRegex(self.mod.InputError, "found 2"):
                self.mod.spec_domains(self.spec([], block=dup))
            lone = indent + "```json citation-publishers\n" + good + "\n```\n"
            with self.subTest(indent=repr(indent), lone=True), self.floor(), self.assertRaises(self.mod.InputError):
                self.mod.spec_domains(self.spec([], block=lone))

    def test_line_endings_and_longer_closing_fence_are_accepted(self) -> None:
        good = '[{"publisher": "ISO", "domains": ["iso.org"], "covers": "x"}]'
        crlf = self.spec([], block="```json citation-publishers\n" + good + "\n```\n").replace("\n", "\r\n")
        longer = self.spec([], block="```json citation-publishers\n" + good + "\n````\n")
        with self.floor():
            self.assertEqual(self.mod.spec_domains(crlf), {"iso.org"})
            self.assertEqual(self.mod.spec_domains("\ufeff" + longer), {"iso.org"})

    def test_table_shapes_no_longer_matter(self) -> None:
        # The nine-round class is gone: the gate never reads the table, so a table in any shape
        # (or none at all) beside a valid block changes nothing.
        text = self.spec(["iso.org", "iec.ch"]).replace(
            "### 7.2", "| stray | `evil.example` |\nIEC | `iec.ch`\n--- | ---\n\n### 7.2")
        with self.floor():
            self.assertEqual(self.mod.spec_domains(text), {"iso.org", "iec.ch"})

    def test_build_cli_refuses_crlf_and_cr_bytes(self) -> None:
        """Round-11 codex P2: the CLI must see the RAW bytes, so a CRLF or CR specification is
        refused (exit 2) rather than silently normalized by text-mode newline translation."""
        import importlib.util
        import tempfile
        from unittest import mock
        spec = importlib.util.spec_from_file_location(
            "build_citation_publishers", REPO_ROOT / "tools" / "build-citation-publishers.py")
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        live = (REPO_ROOT / "governance" / "specification-citation-verification.md").read_bytes()
        with tempfile.TemporaryDirectory() as tmp:
            for name, data in (("crlf", live.replace(b"\n", b"\r\n")), ("cr", live.replace(b"\n", b"\r")),
                               ("bom", b"\xef\xbb\xbf" + live), ("non-utf8", live + b"\xff\xfe")):
                path = Path(tmp) / (name + ".md")
                path.write_bytes(data)
                with mock.patch.object(mod, "SPEC", path), mock.patch("sys.stderr"):
                    self.assertEqual(mod.main(["--check"]), 2, name)
            path = Path(tmp) / "lf.md"
            path.write_bytes(live)
            with mock.patch.object(mod, "SPEC", path), mock.patch("sys.stdout"):
                self.assertEqual(mod.main(["--check"]), 0)

    def test_build_tool_self_test_and_live_check(self) -> None:
        for args in (["--self-test"], ["--check"]):
            result = run_linter("tools/build-citation-publishers.py", *args)
            self.assertEqual(result.returncode, 0, " ".join(args) + result.stdout + result.stderr)

    def test_domain_floor_is_an_input_error(self) -> None:
        with self.floor(5), self.assertRaises(self.mod.InputError):
            self.mod.spec_domains(self.spec(["iso.org"]))

    def test_missing_allow_list_is_an_input_error(self) -> None:
        with self.assertRaises(self.mod.InputError):
            self.mod.allow_entries("OTHER = {\"a.org\"}\n")


class UnwiredToolSelfTests(LinterTestCase):
    """Wire the remaining tool ``--self-test`` suites into CI.

    Several project tools ship a ``--self-test`` that guards pure decision/parsing logic but was
    never exercised in CI (the same gap ``TokenSpendToolTests`` closed for the token-spend tool). Each ``--self-test`` below was verified to run on inline fixtures with no sibling /
    config / network read at test time, so it is CI-safe; a regression in the guarded logic would
    otherwise reach CI green. (``audit-cross-repo-references.py`` is deferred: its self-test reads
    real paths and needs a CI-safety pass first.)
    """

    def test_audit_matrix_semantic_fit_self_test_passes(self) -> None:
        result = run_linter("tools/audit-matrix-semantic-fit.py", "--self-test")
        self.assertEqual(
            result.returncode, 0,
            f"audit-matrix-semantic-fit.py --self-test failed.\n"
            f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}",
        )

    def test_matrix_code_parse_self_test_passes(self) -> None:
        # P-1.62 I10: the shared canonical control-code parser both matrix aids import.
        result = run_linter("tools/matrix_code_parse.py", "--self-test")
        self.assertEqual(
            result.returncode, 0,
            f"matrix_code_parse.py --self-test failed.\n"
            f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}",
        )

    def test_audit_stranded_matrix_code_self_test_passes(self) -> None:
        # P-1.62 I10: new coverage , the stranded aid now shares matrix_code_parse,
        # so its self-test enters the gated suite alongside semantic-fit's.
        result = run_linter("tools/audit-stranded-matrix-code.py", "--self-test")
        self.assertEqual(
            result.returncode, 0,
            f"audit-stranded-matrix-code.py --self-test failed.\n"
            f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}",
        )

    def test_statusline_next_pr_self_test_passes(self) -> None:
        result = run_linter("tools/statusline-next-pr.py", "--self-test")
        self.assertEqual(
            result.returncode, 0,
            f"statusline-next-pr.py --self-test failed.\n"
            f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}",
        )

    def test_audit_claim_precision_self_test_passes(self) -> None:
        result = run_linter("tools/audit-claim-precision.py", "--self-test")
        self.assertEqual(
            result.returncode, 0,
            f"audit-claim-precision.py --self-test failed.\n"
            f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}",
        )

    def test_audit_claim_precision_sample_mode_cold_start(self) -> None:
        import json, tempfile, os
        with tempfile.TemporaryDirectory() as td:
            rec = os.path.join(td, "sweeps.jsonl")          # absent -> cold start
            result = run_linter("tools/audit-claim-precision.py",
                                "--sample", "--n", "5", "--sweeps-record", rec, "--json")
            self.assertEqual(result.returncode, 0,
                             f"--sample failed.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}")
            d = json.loads(result.stdout)
            self.assertEqual(d["cycle"], 1)                  # cold start
            self.assertLessEqual(d["n_drawn"], 5)            # <= N
            self.assertEqual(d["mode"], "coverage-sweep")

    def test_audit_claim_precision_sample_rejects_docs(self) -> None:
        result = run_linter("tools/audit-claim-precision.py",
                            "--sample", "--docs", "privacy/x.md")
        self.assertNotEqual(result.returncode, 0)            # argparse error: global-only


    def test_lint_worklist_register_drift_self_test_passes(self) -> None:
        """P-1.65: the worklist-vs-register drift tool's inline unit suite (pure register /
        header-signature parsers, exact/alias/ambiguous/no-map/broken id mapping, the
        comparable-vs-descriptor version classifier that suppresses the false positives, the
        fabricated-supersedes catch, the q2-only bounded rewriter, and the write scope guard).
        Operates on inline strings only, no register / worklist / sidecar / network read, so
        it is CI-safe."""
        result = run_linter("tools/audit-worklist-register-drift.py", "--self-test")
        self.assertEqual(
            result.returncode, 0,
            f"audit-worklist-register-drift.py --self-test failed.\n"
            f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}",
        )

    def test_lint_worklist_register_drift_check_live_tree_exit_semantics(self) -> None:
        """P-1.65: run --check against the LIVE register + batch worklists and assert exit-code
        semantics: the tool must run cleanly on real data (no traceback / argparse error) and
        return exactly 0 (no drift) or 1 (drift found), never 2+. This exercises the
        header-signature parser against the full real worklists without coupling the assertion
        to the current drift state (which the maintainer will fix over time)."""
        result = run_linter("tools/audit-worklist-register-drift.py", "--check")
        self.assertIn(
            result.returncode, (0, 1),
            f"--check on the live tree returned {result.returncode} (expected 0 or 1).\n"
            f"stdout:\n{result.stdout}\nstderr:\n{result.stderr}",
        )
        self.assertNotIn(
            "Traceback", result.stderr,
            f"--check on the live tree raised:\n{result.stderr}",
        )
        # The parser found and summarized at least the two prototyped verification tables.
        self.assertIn("verification rows", result.stdout)

    def test_lint_worklist_register_drift_check_exit_codes_on_fixtures(self) -> None:
        """P-1.65: lock the --check exit-code contract deterministically on controlled fixtures,
        independent of the live tree. A clean worklist -> exit 0; a drifting worklist (stale
        aliased version + fabricated supersede) -> exit 1 with the drift surfaced; and the
        descriptor register value is reported UNVERIFIABLE, never DRIFT (the false-positive fix)."""
        import os
        import tempfile

        register = (
            "| Standard ID | Current version | Publication date | Topic | Superseded versions | Upstream check location | Last verified (UTC) |\n"
            "| --- | --- | --- | --- | --- | --- | --- |\n"
            "| ISO/IEC 27033-1 | 2015 | 2015 | Network security | 2013 | http://x | verified 2026-01-01 |\n"
            "| EU eIDAS | Regulation 910/2014 as amended by Regulation 2024/1183 (eIDAS 2) | 2024-04 (amend) | Trust services | - | http://x | verified 2026-01-01 |\n"
            "| CSA STAR | continuous | 2026-01 | Cloud registry | - | http://x | verified 2026-01-01 |\n"
        )
        clean_wl = (
            "| Standard ID | Publisher | Expected primary URL | Field(s) to verify | Expected value (from register) | Notes |\n"
            "| --- | --- | --- | --- | --- | --- |\n"
            "| ISO/IEC 27033-1 | ISO | `u` | all | Current: 2015; published 2015; topic: Network security; supersedes 2013 |  |\n"
        )
        drift_wl = (
            "| Standard ID | Publisher | Expected primary URL | Field(s) to verify | Expected value (from register) | Notes |\n"
            "| --- | --- | --- | --- | --- | --- |\n"
            "| ISO/IEC 27033 | ISO | `u` | all | Current: 2020; topic: Network security; no superseded versions recorded |  |\n"
            "| EU eIDAS | ISO | `u` | all | Regulation 2024/1183; supersedes Regulation 910/2014 (eIDAS 1) |  |\n"
            "| CSA STAR | ISO | `u` | all | continuous registry snapshot |  |\n"
        )
        with tempfile.TemporaryDirectory() as td:
            reg_p = os.path.join(td, "register.md")
            clean_p = os.path.join(td, "clean.md")
            drift_p = os.path.join(td, "drift.md")
            with open(reg_p, "w", encoding="utf-8") as fh:
                fh.write(register)
            with open(clean_p, "w", encoding="utf-8") as fh:
                fh.write(clean_wl)
            with open(drift_p, "w", encoding="utf-8") as fh:
                fh.write(drift_wl)

            ok = run_linter("tools/audit-worklist-register-drift.py",
                            "--check", "--register", reg_p, "--worklist", clean_p)
            self.assertEqual(
                ok.returncode, 0,
                f"clean fixture should exit 0.\nstdout:\n{ok.stdout}\nstderr:\n{ok.stderr}",
            )

            bad = run_linter("tools/audit-worklist-register-drift.py",
                             "--check", "--register", reg_p, "--worklist", drift_p)
            self.assertEqual(
                bad.returncode, 1,
                f"drift fixture should exit 1.\nstdout:\n{bad.stdout}\nstderr:\n{bad.stderr}",
            )
            self.assertIn("DRIFT", bad.stdout)
            self.assertIn("27033", bad.stdout)              # aliased stale-version true positive
            self.assertIn("UNVERIFIABLE", bad.stdout)       # descriptor register value, not DRIFT
