    def _rc(self, name, todo, done, ptodo=None):
        root, result = self._run(name, todo, done, ptodo=ptodo)
        try:
            return result.returncode, result.stdout + result.stderr
        finally:
            shutil.rmtree(root, ignore_errors=True)

