        self.assertIn("1 updated", first.stdout)
        check = self._run(root, "--check")
        self.assertEqual(check.returncode, 0, check.stdout + check.stderr)
        after_first = (root / "HANDBOOK.md").read_bytes()
        second = self._run(root)
