    PAREN_START = ("start = TARGET_START.match(unit, match.end()).end()", "start = match.end()")
    REBASED_START = (("TARGET_START.match(base, i).end()", "i"),
                     ("TARGET_START.match(text, j).end()", "j"))
    WHITESPACE_RULES = (PAREN_START,) + REBASED_START
