class OpenFindingsRowSetDispositionTests(unittest.TestCase):
    """tools/open-findings-row.py --set-disposition: one existing row's Disposition cell, changed in place
    and checked with the guard's own functions as a new row is, so a hand edit from ROUTED to FIXED can no
    longer write a disposition the guard rejects. Every ledger is a synthetic temp-dir file."""

    LEDGER = OpenFindingsRowTests.LEDGER
    FIXED = "FIXED #2800 (f2a53df9f) [class-exempt: singleton]"
    OPEN_A = "| 2026-10-02 | warning | [OPEN-A] first open | probe | "
    UNBORDERED = LEDGER.replace(OPEN_A + "ROUTED 3b330 |", OPEN_A + "ROUTED 3b330")
    # The target row with and without a trailing border pipe: every refusal is held to both (3b678 r3),
    # except check_row's id-not-in-row and id-invalid, which this mode cannot reach: the target row is the
    # one whose Finding cell leads with the id, only the last cell is rewritten, and an invalid id is
    # refused before check_row runs (test_refuses_invalid_id).
    SHAPES = (("bordered", LEDGER), ("unbordered", UNBORDERED))

    def setUp(self) -> None:
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        self.dir = Path(self._tmp.name)
        self.ledger = self.dir / "open-findings.md"
        self.ledger.write_text(self.LEDGER, encoding="utf-8")

    def run_tool(self, cell: str | bytes, fid: str, *args: str) -> tuple[int, str, str]:
        data = cell if isinstance(cell, bytes) else (cell + "\n").encode("utf-8")
        done = subprocess.run(
            [sys.executable, "-I", str(OpenFindingsRowTests.TOOL), "--ledger", str(self.ledger),
             "--set-disposition", "--id", fid, *args],
            input=data, capture_output=True, cwd=str(REPO_ROOT), timeout=300)
        return done.returncode, done.stdout.decode("utf-8", "replace"), done.stderr.decode("utf-8", "replace")

    def assertRefused(self, cell: str | bytes, code: str, fid: str = "OPEN-A") -> None:
        before = (self.ledger.read_bytes(), os.stat(self.ledger).st_mtime_ns)
        rc, out, err = self.run_tool(cell, fid)
        self.assertEqual(rc, 1, out + err)
        self.assertIn(f"refused: {code}", err)
        self.assertIn("result: REFUSED", out)
        self.assertEqual((self.ledger.read_bytes(), os.stat(self.ledger).st_mtime_ns), before)
        self.assertEqual(sorted(os.listdir(self.dir)), ["open-findings.md"])
        self.assertNotIn(fid, out + err)

    def test_sets_open_row_and_reports_lines_only(self) -> None:
        rc, out, err = self.run_tool(self.FIXED, "OPEN-A")
        self.assertEqual(rc, 0, out + err)
        self.assertEqual(out.splitlines()[1:2], ["target: line 12 (open)"])
        self.assertIn("merge-guard: before allow, after allow", out)
        self.assertEqual(out.splitlines()[-1], "result: WROTE")
        self.assertEqual(self.ledger.read_text(encoding="utf-8"),
                         self.LEDGER.replace(self.OPEN_A + "ROUTED 3b330 |", self.OPEN_A + self.FIXED + " |"))
        self.assertNotIn("OPEN-A", out + err)
        self.assertNotIn("2800", out + err)
        self.assertEqual(sorted(os.listdir(self.dir)), ["open-findings.md"])

    def test_every_other_line_is_byte_identical(self) -> None:
        # CRLF line ends, trailing spaces after the border pipe and a row with no trailing border pipe.
        text = self.LEDGER.replace("| ROUTED TODO 3.73 |", "| ROUTED TODO 3.73 |  ")
        text = text.replace("| probe | ROUTED 3b330 |", "| probe | ROUTED 3b330").replace("\n", "\r\n")
        self.ledger.write_bytes(text.encode("utf-8"))
        for fid, at in (("OPEN-B", 12), ("OPEN-A", 11), ("CLOSED-A", 19)):
            with self.subTest(fid=fid):
                before = self.ledger.read_bytes().split(b"\r\n")
                rc, out, err = self.run_tool(self.FIXED, fid)
                self.assertEqual(rc, 0, out + err)
                after = self.ledger.read_bytes().split(b"\r\n")
                self.assertEqual(len(after), len(before))
                self.assertEqual(after[:at] + after[at + 1:], before[:at] + before[at + 1:])
                body = before[at].rstrip()
                stem = body[:-1] if body.endswith(b"|") else body
                cell = b"| " + self.FIXED.encode("utf-8") + (b" |" if stem != body else b"")
                self.assertEqual(after[at], stem[:stem.rfind(b"|")] + cell + before[at][len(body):])
        self.assertNotIn(b"\n", self.ledger.read_bytes().replace(b"\r\n", b""))

    def test_closed_today_row_dry_run_writes_nothing(self) -> None:
        before = (self.ledger.read_bytes(), os.stat(self.ledger).st_mtime_ns)
        rc, out, err = self.run_tool(self.FIXED, "CLOSED-A", "--dry-run")
        self.assertEqual(rc, 0, out + err)
        self.assertIn("target: line 20 (closed)", out)
        self.assertEqual(out.splitlines()[-1], "result: WOULD-WRITE")
        self.assertEqual((self.ledger.read_bytes(), os.stat(self.ledger).st_mtime_ns), before)

    def test_attested_class_clause_goes_through_the_matcher(self) -> None:
        import secrets
        token = "zzq-" + secrets.token_hex(24)
        rc, out, err = self.run_tool(f'FIXED #2800 [class: "{token}" @ 0]', "OPEN-A", "--dry-run")
        self.assertEqual(rc, 0, out + err)
        self.assertIn("class-attestation class", out)
        self.assertIn("class-count: reproduced 0 = attested 0", out)

    def test_refuses_no_matching_row(self) -> None:
        for shape, text in self.SHAPES:
            self.ledger.write_text(text, encoding="utf-8")
            for fid in ("NOPE-1", "FENCED-1", "ARCH-A"):
                with self.subTest(shape=shape, fid=fid):
                    self.assertRefused(self.FIXED, "id-not-found", fid=fid)

    def test_refuses_two_matching_rows(self) -> None:
        for shape, text in self.SHAPES:
            with self.subTest(shape=shape):
                self.ledger.write_text(text.replace("[OPEN-C]", "[OPEN-A]"), encoding="utf-8")
                self.assertRefused(self.FIXED, "id-ambiguous (line 14)")

    def test_refuses_invalid_id(self) -> None:
        for shape, text in self.SHAPES:
            self.ledger.write_text(text, encoding="utf-8")
            for fid in ("a b", "[OPEN-A]"):
                with self.subTest(shape=shape, fid=fid):
                    self.assertRefused(self.FIXED, "id-invalid", fid=fid)

    def test_refuses_invalid_disposition(self) -> None:
        for shape, text in self.SHAPES:
            self.ledger.write_text(text, encoding="utf-8")
            for cell in ("FIXED d44d9b2b", "FIXED (pending merge)", "ROUTED pending-decisions"):
                with self.subTest(shape=shape, cell=cell):
                    self.assertRefused(cell, "disposition-invalid")

    def test_refuses_fixed_without_class_attestation(self) -> None:
        for shape, text in self.SHAPES:
            self.ledger.write_text(text, encoding="utf-8")
            for cell, code in (("FIXED #2800 (f2a53df9f)", "class-unattested"),
                               ("FIXED #2800 [class-exempt: too-hard]", "class-bad-exempt"),
                               ("FIXED #2800 [class-exempt: singleton] [class-exempt: singleton]", "class-multi")):
                with self.subTest(shape=shape, code=code):
                    self.assertRefused(cell, code)

    def test_refuses_target_row_the_tool_would_not_write(self) -> None:
        # The whole changed row is checked (the RESIDUES): the target's own Found date, severity and
        # column count, whatever the new cell says.
        for shape, text in self.SHAPES:
            for edit, code in (
                    (("| 2026-10-02 | warning | [OPEN-A]", "| 2026-10-32 | warning | [OPEN-A]"), "found-not-iso"),
                    (("| warning | [OPEN-A]", "| warn | [OPEN-A]"), "severity-unknown"),
                    (("[OPEN-A] first open | probe |", "[OPEN-A] first open | probe | extra |"), "malformed-columns"),
                    (("[OPEN-A] first open | probe |", "[OPEN-A] first open |"), "malformed-columns")):
                with self.subTest(shape=shape, edit=edit[1]):
                    self.assertIn(edit[0], text)
                    self.ledger.write_text(text.replace(edit[0], edit[1]), encoding="utf-8")
                    self.assertRefused(self.FIXED, code)

    def test_backstops_on_each_row_shape(self) -> None:
        # splice-mismatch, misfiled-grew and merge-guard-regressed are not reachable from a well-formed
        # cell, so each is forced in process, as the row-adding modes' backstop tests force theirs.
        from unittest import mock
        mod = load_linter_module("tools/open-findings-row.py", "_ofr_sd_backstops")
        hook = mod.load_hook(REPO_ROOT)
        real_verify = mod.verify_replace
        real_misfiled = hook.misfiled_finding_rows

        def changed_parse(hook, before, after, lines, kinds, old, parsed, at, section):
            parsed = (*parsed[:2], parsed[2] + " changed", parsed[3])
            return real_verify(hook, before, after, lines, kinds, old, parsed, at, section)

        def misfiled(text):
            rows = list(real_misfiled(text))
            if "#2800" in text:
                rows.append((1, "error", "synthetic misfiled row"))
            return rows

        for shape, text in self.SHAPES:
            with self.subTest(shape=shape, code="splice-mismatch"):
                with mock.patch.object(mod, "verify_replace", side_effect=changed_parse):
                    codes, _, new = mod.evaluate_disposition(hook, text, self.FIXED, "OPEN-A")
                self.assertEqual(codes, ["splice-mismatch"])
                self.assertIsNone(new)
            with self.subTest(shape=shape, code="misfiled-grew"):
                with mock.patch.object(hook, "misfiled_finding_rows", side_effect=misfiled), \
                        mock.patch.object(hook, "decide_exit", return_value=0):
                    codes, _, new = mod.evaluate_disposition(hook, text, self.FIXED, "OPEN-A")
                self.assertEqual(codes, ["misfiled-grew"])
                self.assertIsNone(new)
            with self.subTest(shape=shape, code="merge-guard-regressed"):
                with mock.patch.object(hook, "decide_exit",
                                       side_effect=lambda rows, t: 2 if "#2800" in t else 0) as guard:
                    codes, report, new = mod.evaluate_disposition(hook, text, self.FIXED, "OPEN-A")
                self.assertEqual(guard.call_count, 2)
                self.assertEqual(codes, ["merge-guard-regressed"])
                self.assertIn("merge-guard: before allow, after block", report)
                self.assertIsNone(new)

    def test_splice_mismatch_from_read_back_on_each_row_shape(self) -> None:
        # The first splice-mismatch source: the Disposition read back from the spliced row is not the
        # requested cell. Only replace_last_cell is patched, to splice a different valid cell; verify_replace
        # runs unpatched and agrees with the spliced row, so the code can come from the read-back alone.
        from unittest import mock
        mod = load_linter_module("tools/open-findings-row.py", "_ofr_sd_read_back")
        hook = mod.load_hook(REPO_ROOT)
        real_replace = mod.replace_last_cell
        spliced = self.FIXED.replace("#2800", "#2801")

        def other_cell(line, cell):
            return real_replace(line, cell.replace("#2800", "#2801"))

        for shape, text in self.SHAPES:
            with self.subTest(shape=shape):
                with mock.patch.object(mod, "replace_last_cell", side_effect=other_cell) as splice:
                    codes, _, new = mod.evaluate_disposition(hook, text, self.FIXED, "OPEN-A")
                self.assertEqual(splice.call_count, 1)
                self.assertEqual(codes, ["splice-mismatch"])
                self.assertIsNone(new)
                with mock.patch.object(mod, "replace_last_cell", side_effect=other_cell):
                    codes, _, new = mod.evaluate_disposition(hook, text, spliced, "OPEN-A")
                self.assertEqual(codes, [])
                self.assertIn(self.OPEN_A + spliced, new)

    def test_refuses_pipe_in_cell(self) -> None:
        # Checked before the row's shape is looked at: on a row with no trailing border pipe,
        # `ROUTED 3b330 |` refused as splice-mismatch and `|` as disposition-empty (3b678 r2).
        for shape, text in (("bordered", self.LEDGER), ("unbordered", self.UNBORDERED)):
            self.ledger.write_text(text, encoding="utf-8")
            for cell in ("ROUTED 3b330 | x", "ROUTED 3b330 |", "|", "| ROUTED 3b330"):
                with self.subTest(shape=shape, cell=cell):
                    self.assertRefused(cell, "malformed-columns")
                    self.assertEqual(self.run_tool(cell, "OPEN-A")[2].count("refused: "), 1)
            with self.subTest(shape=shape, cell="escaped"):
                rc, out, err = self.run_tool("ROUTED 3b330 \\| x", "OPEN-A", "--dry-run")
                self.assertEqual(rc, 0, out + err)

    def test_stdin_refusals_on_each_row_shape(self) -> None:
        for shape, text in (("bordered", self.LEDGER), ("unbordered", self.UNBORDERED)):
            self.ledger.write_text(text, encoding="utf-8")
            for cell, code in ((b"ROUTED \xff 3b330\n", "not-utf8"),
                               ("ROUTED 3b330\nx", "multiline"), ("ROUTED\r3b330", "bad-line-char"),
                               ("ROUTED\u20283b330", "bad-line-char")):
                with self.subTest(shape=shape, code=code):
                    self.assertRefused(cell, code)

    def test_cell_spacing_on_each_row_shape(self) -> None:
        # Bordered: one space, the cell, one space, the border pipe. Unbordered: one space and the cell,
        # then the row's own trailing whitespace, with no space added.
        old = self.OPEN_A + "ROUTED 3b330 |"
        for shape, row, want in (
                ("bordered", old, self.OPEN_A + self.FIXED + " |"),
                ("bordered, trailing spaces", old + "  ", self.OPEN_A + self.FIXED + " |  "),
                ("unbordered", self.OPEN_A + "ROUTED 3b330", self.OPEN_A + self.FIXED),
                ("unbordered, trailing spaces", self.OPEN_A + "ROUTED 3b330  ", self.OPEN_A + self.FIXED + "  ")):
            with self.subTest(shape=shape):
                self.ledger.write_text(self.LEDGER.replace(old, row), encoding="utf-8")
                rc, out, err = self.run_tool(self.FIXED, "OPEN-A")
                self.assertEqual(rc, 0, out + err)
                self.assertEqual(self.ledger.read_text(encoding="utf-8").splitlines()[11], want)

    def test_docstring_and_reference_state_each_row_shape(self) -> None:
        import ast
        doc = ast.get_docstring(ast.parse(OpenFindingsRowTests.TOOL.read_text(encoding="utf-8")))
        section = " ".join(doc.split("SET DISPOSITION.", 1)[1].split("\n\nREFUSALS (exit 1).", 1)[0].split())
        for phrase in (
                "before the target row's shape is looked at, so on every row shape it refuses as "
                "malformed-columns",
                "on a row with a trailing border pipe, the text between its last two unescaped pipes, "
                "written as one space, the cell, one space;",
                "on a row with no trailing border pipe, the text after its last unescaped pipe, written as "
                "one space and the cell, then the row's own trailing whitespace, with no space added",
                "Its refusals (exit 1) are the stdin ones listed under REFUSALS below (not-utf8, multiline, "
                "bad-line-char)"):
            with self.subTest(phrase=phrase[:40]):
                self.assertIn(phrase, section)
        for stale in ("the stdin ones above", "is replaced, written as one space, the cell, one space"):
            with self.subTest(stale=stale):
                self.assertNotIn(stale, section)
        reference = (REPO_ROOT / "references" / "hook-open-findings-guard.md").read_text(encoding="utf-8")
        bullet = " ".join(reference.split("- **Setting a disposition", 1)[1].split("\n- **", 1)[0]
                          .split("\n## ", 1)[0].split())
        for phrase in ("an unescaped pipe in the cell (`malformed-columns`, on every row shape, checked before "
                       "the row is looked at)",
                       "one space, the cell, one space before a trailing border pipe",
                       "one space and the cell with no space after it on a row with no trailing border pipe"):
            with self.subTest(reference=phrase[:40]):
                self.assertIn(phrase, bullet)

    def test_refuses_empty_cell_and_other_modes_flags(self) -> None:
        for shape, text in self.SHAPES:
            self.ledger.write_text(text, encoding="utf-8")
            for cell in ("", "  "):
                with self.subTest(shape=shape, cell=cell):
                    self.assertRefused(cell, "disposition-empty")
        self.ledger.write_text(self.LEDGER, encoding="utf-8")
        for extra in (("--open",), ("--append",), ("--after", "OPEN-B"), ("--delivery", "x.md")):
            with self.subTest(extra=extra):
                rc, out, err = self.run_tool(self.FIXED, "OPEN-A", *extra)
                self.assertEqual(rc, 2, out + err)
                self.assertEqual(self.ledger.read_text(encoding="utf-8"), self.LEDGER)

    def test_usage_and_help_document_the_mode(self) -> None:
        import ast
        doc = ast.get_docstring(ast.parse(OpenFindingsRowTests.TOOL.read_text(encoding="utf-8")))
        usage = doc.split("Usage:", 1)[1].split("\n\n", 1)[0]
        self.assertIn("--set-disposition --id ID [--ledger PATH] [--dry-run] < cell", usage)
        section = " ".join(doc.split("SET DISPOSITION.", 1)[1].split("\n\nREFUSALS (exit 1).", 1)[0].split())
        for phrase in ("id-not-found", "id-ambiguous", "disposition-empty", "malformed-columns",
                       "the same atomic_replace transaction", "RESIDUES, stated:"):
            self.assertIn(phrase, section)
        result = run_linter("tools/open-findings-row.py", "--help")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("--set-disposition", result.stdout)


class OpenFindingsRowDeliveryTests(unittest.TestCase):
    """tools/open-findings-row.py --delivery (3b544, mistakes register 312): one report-only line with
    the delivery's last FINDINGS totals beside the ledger rows whose Source cell leads with the
    delivery's own review key (family, item, round and sha; round 2 narrowed it from item and sha).
    CLAUDE_SAMPLE and GEMINI_DELIVERY keep the shapes of the staged 3b544 samples, abbreviated: a
    markdown FINDINGS tail after fenced probe output and a table, and the same tail after a fenced
    SARIF JSON block. Neither staged sample carries a round heading. CLAUDE_DELIVERY is CLAUDE_SAMPLE
    plus one line the staged sample lacks, a round heading after the progress line (the shape of the
    round-2 Claude review of 3b544), so the tests that count from the delivery's own key use a shape
    the staged Claude sample does not have; test_staged_claude_shape_needs_a_source_key runs the
    sample's own shape (round 2 NOTE-2). Every ledger is a temp-dir file; the live ledger is never
    read.

    Mutation map, a killing test per clause: the line not wired into _run and a delivery fence that
    never closes by both sample-shape tests; WARN/NOTE swapped by the SARIF-shape test (the markdown
    sample's 0/1/1 cannot show it); LF-only splitting by the CRLF subtest;
    no fence skipping, the first FINDINGS line kept and the column order by
    test_last_findings_line_outside_fences_in_column_order; a silent zero, a fallback to an earlier
    parseable line and a dropped label check by test_findings_less_delivery_is_unverifiable_never_zero;
    the old item-and-sha match, a narrower row scope, counting the ledger as read and with_row always
    true by test_row_count_against_fixture_ledger; a key without the family, a key without the round, a
    case-folded match, a match not anchored at the cell's start and a dropped key-end check by
    test_key_counts_only_the_delivery_own_review; a broad count when a part is missing, a dropped
    disagreement check, a round heading not bound to the item and --source-key not passed on by _run by
    test_key_needs_every_part_or_a_source_key; the last parseable VPR-COMPLETE line kept (r1 M22) and
    its code renamed (r1 M24) by test_malformed_last_vpr_complete_line_is_unverifiable; a dropped
    row-count catch-all (r1 M25) by test_row_count_failure_is_unverifiable; a backtick line holding a
    backtick after its run opening a fence, and str.splitlines line ends, by
    test_inline_code_line_and_non_lf_breaks_do_not_flip_the_tail; the reference's usage or delivery
    bullet dropped by test_reference_documents_delivery_beside_class_count; a blocking open, a
    dropped missing or not-UTF-8 handler, and that plus a narrowed catch-all (which changes the exit
    code) by test_unreadable_delivery_is_unverifiable_and_the_write_lands; a dropped divergence check by
    test_source_cell_divergence_is_unverifiable_not_a_count; a dropped residue sentence by
    test_usage_documents_delivery_and_its_residue; a round taken from a heading that is not the
    delivery's first (r2 NOTE-1), a dropped quoted-heading residue sentence, and the reference's
    first-heading parenthetical and round-heading-ambiguous sentence dropped (r3 NOTE-1) by
    test_quoted_round_heading_is_not_the_delivery_round; the reference's errs-low sentence dropped (r3
    NOTE-2) by test_reference_documents_delivery_beside_class_count; the reference's no-heading and
    --source-key sentences dropped (r2 NOTE-2) by test_staged_claude_shape_needs_a_source_key; the
    family from a later WORKER_STATUS line (B1), more than one family= value (B2), headings read inside
    fences (B3), --source-key matched as a prefix (B4), the heading's item matched as a substring (B5),
    any heading level (B9), blockquoted headings (B10) and the VPR-COMPLETE code overriding the family
    code (B11), r2 NOTE-3, by test_key_parts_parse_as_documented, one subtest each; heading levels 3 to
    6 not counted, no indent allowed, no space or tab needed after the #, fenced ATX lines counted and
    a round heading not counted as a heading, r3 NOTE-3, by
    test_first_heading_rule_parses_as_documented, one subtest each; two rounds read as ambiguous only
    beside a round heading of its own, the reference's ambiguity sentence narrowed back to that case
    (r4 NOTE-1), the residue worded apart in the docstring and the reference (r4 NOTE-2) and either one
    dropping its clause on the delivery's own later headings (r4 NOTE-3 U5) by
    test_quoted_round_heading_is_not_the_delivery_round; no tab taken after the # (U1), a bare # run
    not a heading (U2), any indent allowed (U3) and seven or more # taken (U4), r4 NOTE-3, by
    test_first_heading_rule_parses_as_documented, one subtest each; the ambiguity check moved before
    the part codes (P1), the headings matched against the delivery's item even with a key (P2 with a
    key) or against every heading when no item is known (P2), and the reference's ambiguity sentence
    or review_key's docstring not stating that order, r5 NOTE, by
    test_quoted_round_heading_is_not_the_delivery_round, one subtest per case; the source-key-invalid
    check moved before the part codes (r6 M4), a WORKER_STATUS first line with no family= value read as
    no family (W1), the whole-line UNVERIFIABLE skipped beside a --source-key (F1), and the reference's
    whole-line sentence or its narrowed no-WORKER_STATUS sentence dropped, 3b556, by
    test_quoted_round_heading_is_not_the_delivery_round, one subtest per case; a WORKER_STATUS envelope
    read with optional parentheses (E1) or a status of any case (E2), a byte-order mark stripped before
    the WORKER_STATUS test (E3), a first line holding WORKER_STATUS: anywhere read as a WORKER_STATUS
    first line (E4), and the envelope or byte-order-mark wording dropped from the reference or the tool
    docstring, 3b556 r2 (claude 3b556 round-1 NOTE-1), by
    test_quoted_round_heading_is_not_the_delivery_round, one subtest per case; a status of digits or
    underscores (X1) or an empty status (X2) read as parsing, a first line starting WORKER_STATUS with
    no colon (X3) or after leading whitespace (X4) read as a WORKER_STATUS first line, and the
    first-line definition or the ASCII status wording dropped from the reference or the tool
    docstring, 3b556 r3 (claude 3b556 round-2 NOTE-1 and NOTE-2), and a case-folded prefix read as a
    WORKER_STATUS first line (X5), by test_quoted_round_heading_is_not_the_delivery_round, one subtest
    per case; a tab indent stripped before the prefix and envelope tests (M1), a status of any letters
    but a to z read as parsing, so an accented or full-width one (M2), and a one-letter status read as
    not parsing (M3), 3b556 r4 (claude 3b556 round-3 NOTE-1), by
    test_quoted_round_heading_is_not_the_delivery_round, one subtest per case; a heading's item found
    by searching its whole remainder (3b578 W1, codex 3b544 post-merge WARN), so that a first heading
    of another item that mentions the item later gives its round, with or without a key, or a later
    one makes the rounds ambiguous; a heading with no item field giving the delivery's round; the
    ambiguity backstop dropped, so a column-0 quote of round 1 before the delivery's own round-2 heading
    with no item field (S1) or a later round-3 heading with no item field (S2) counts, with or without
    a key, 3b578 r2 (claude 3b578 round-1 W1); a first heading with no item field read as disagreeing
    with a key of another round (S3), and a lowercase, comma-less, backticked, empty or no-break-space
    field read as the item alone or left out of the ambiguity check after the own heading, 3b578 r2
    (round-1 N2); and the item-field rule, its narrowings or the one wording dropped from the tool
    docstring or the reference, or the looser round-1 sentence kept, 3b578 r2 (round-1 N3); and a
    heading with no item field read as naming the item by a substring match (M3) or with the whole-token
    lookbehind (M4) or lookahead (M5) dropped, the ambiguity backstop skipped for the delivery's first
    heading (M13), text allowed before (REFUTE (M14), and the (REFUTE...) closed by its last ) instead of
    its first (M15), 3b578 r3 (claude 3b578 round-2 N1), by
    test_round_heading_names_only_its_leading_item, one subtest per case; and _ and - dropped from the
    whole-token lookbehind (X1) or lookahead (X2), a ) allowed inside the (REFUTE parentheses (X3) and no space
    or tab needed before (REFUTE (X4), 3b578 r4 (claude 3b578 round-3 N1), and the other survivors of the
    round-4 clause table: a round heading read when indented, case-folded or after a lone CR or U+2028, a tab
    or a second space refused before (REFUTE, a space allowed before the colon or required after it (LS3), the
    item field case-folded, spaces and tabs around the item not stripped or a no-break space after it stripped,
    a ., _ or - refused inside the item, an item starting or ending with punctuation or holding a non-ASCII
    letter or digit, each letter case, digit, _ and - beside a whole token on either side, and a . beside it
    stopping it, by test_round_heading_names_only_its_leading_item, and a setext, HTML, block-quoted or
    list-item heading stopping a first-heading quote (the stated residue) by
    test_first_heading_rule_parses_as_documented, one subtest per case; and the CR kept on heading lines only,
    a ; ending the item field, the heading's literal spaces loosened (none, two or a tab at each), the item not
    escaped (ESC) and the whole-token lookarounds widened to non-ASCII letters (UNI), 3b578 r5 (claude 3b578
    round-4 W1 and N1, codex 3b578 round-4 ERROR), by test_round_heading_names_only_its_leading_item, one
    subtest per case, and the tool docstring's column-0, CR and first-heading clauses or the reference's
    first-heading clause dropped (round-4 N3) by test_usage_documents_delivery_and_its_residue and
    test_quoted_round_heading_is_not_the_delivery_round; and a round number read with a leading zero (H9) or as 0, an
    empty item read when there is no VPR-COMPLETE line (P2), a non-ASCII letter after the key stopping it, and the
    tool docstring's two-rounds, inline-code and --source-key residue clauses (DT15, DT17, DT21), the round-number
    wording or the ASCII key-end wording dropped, 3b578 r6 (the round-5 clause table), by
    test_round_heading_names_only_its_leading_item, test_quoted_round_heading_is_not_the_delivery_round,
    test_key_counts_only_the_delivery_own_review and test_usage_documents_delivery_and_its_residue, one subtest or
    phrase per case."""

    REVIEW = "claude 3b540 /validate-pr round 2 @ f2a53df9f"
    CLAUDE_SAMPLE = (
        "WORKER_STATUS: PASS (account=a, rc=0, family=claude, advisory=true)\n"
        "All three hashes match. Reading inputs.\n"
        "## Scratch probes\n"
        "\n"
        "Brief probe (TMPDIR form):\n"
        "```\n"
        "created /scratch/tmpupwfxkic\n"
        "read True\n"
        "```\n"
        "\n"
        "## What I ran\n"
        "\n"
        "| Run | Result |\n"
        "|---|---|\n"
        "| The 3 new tests | Ran 3, OK |\n"
        "\n"
        "## SARIF-lite findings\n"
        "\n"
        "- **WARN-1** (pre-existing) at `tools/check-todo-floor-monotonic-on-pr.py:350`.\n"
        "- **NOTE-1** (residual race) at `tools/check-todo-floor-monotonic-on-pr.py:102`.\n"
        "\n"
        "FINDINGS: 0 ERROR, 1 WARN, 1 NOTE\n"
        "VERDICT: SHIP\n"
        "VPR-COMPLETE 3b540 f2a53df9f\n"
    )
    ROUND_2_HEADING = "# /validate-pr round 2 (REFUTE): 3b540, commit f2a53df9f, branch tooling/3b540-d12-error-paths"
    CLAUDE_DELIVERY = CLAUDE_SAMPLE.replace("\n## Scratch probes", f"\n{ROUND_2_HEADING}\n\n## Scratch probes", 1)
    GEMINI_DELIVERY = (
        "WORKER_STATUS: PASS (account=b, rc=0, family=gemini, advisory=true)\n"
        "# Static Review Report: PR 3b546\n"
        "\n"
        "## SARIF-Lite Findings\n"
        "\n"
        "```json\n"
        "[\n"
        "  {\n"
        '    "ruleId": "refute/static-analysis-limitation",\n'
        '    "level": "note",\n'
        '    "message": {\n'
        '      "text": "Digest computation is UNVERIFIABLE statically."\n'
        "    }\n"
        "  },\n"
        "  {\n"
        '    "ruleId": "refute/executed-qa",\n'
        '    "level": "note",\n'
        '    "message": {\n'
        '      "text": "EXECUTED QA is UNVERIFIED."\n'
        "    }\n"
        "  }\n"
        "]\n"
        "```\n"
        "\n"
        "FINDINGS: 0 ERROR, 0 WARN, 6 NOTE\n"
        "VERDICT: SHIP\n"
        "VPR-COMPLETE 3b546 2ba4b9847\n"
    )
    # Rows leading with the claude round-2 key: R2-W1, R2-N1 (text after the key), R2-W2 (an escaped
    # pipe after it) and R2-N2 (the archive). Never FENCED-1, G2-N1 (the gemini leg of the same round
    # and sha, which round 1 counted), R1-N1 (another round at the same sha), SHORT-1 (a shorter sha),
    # OTHER-1 (another item) or OTHER-2 (the item joined).
    LEDGER = (
        "# Open findings\n"
        "\n"
        "## Disposition values\n"
        "```\n"
        f"| 2026-10-01 | warning | [FENCED-1] a fenced example | {REVIEW} |  |\n"
        "```\n"
        "\n"
        "## Open\n"
        "\n"
        "| Found | Severity | Finding | Source | Disposition |\n"
        "| --- | --- | --- | --- | --- |\n"
        f"| 2026-10-20 | warning | [R2-W1] named | {REVIEW} | ROUTED 3b330 |\n"
        f"| 2026-10-20 | note | [R2-N1] text after the key | {REVIEW} (NOTE-1) |  |\n"
        "| 2026-10-20 | note | [G2-N1] another family | gemini 3b540 /validate-pr round 2 @ f2a53df9f |  |\n"
        "| 2026-10-20 | note | [R1-N1] an earlier round | claude 3b540 /validate-pr round 1 @ f2a53df9f |  |\n"
        "| 2026-10-20 | note | [SHORT-1] a shorter sha | claude 3b540 /validate-pr round 2 @ f2a53df |  |\n"
        "| 2026-10-20 | note | [OTHER-1] another item | claude 3b5400 /validate-pr round 2 @ f2a53df9f |  |\n"
        "| 2026-10-21 | note | [OTHER-2] the item joined | claude 3b540-r2 /validate-pr round 2 @ f2a53df9f |  |\n"
        "\n"
        "## Closed today\n"
        "\n"
        "| Found | Severity | Finding | Source | Disposition |\n"
        "| --- | --- | --- | --- | --- |\n"
        f"| 2026-10-20 | warning | [R2-W2] closed | {REVIEW} \\| WARN-2 "
        "| FIXED #2700 [class-exempt: singleton] |\n"
        "\n"
        "## 2026-10-19 archive\n"
        "\n"
        f"| 2026-10-19 | note | [R2-N2] archived | {REVIEW} | FIXED #2600 [class-exempt: singleton] |\n"
    )

    def setUp(self) -> None:
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        self.dir = Path(self._tmp.name)
        self.ledger = self.dir / "open-findings.md"
        self.ledger.write_text(self.LEDGER, encoding="utf-8")
        self.delivery = self.dir / "delivery.md"

    def row(self, fid: str) -> str:
        return f"| 2026-10-22 | note | [{fid}] appended | {self.REVIEW} |  |"

    def run_tool(self, delivery, *args: str, fid: str = "R2-N3") -> tuple[int, str, list[str]]:
        done = subprocess.run(
            [sys.executable, "-I", str(OpenFindingsRowTests.TOOL), "--ledger", str(self.ledger),
             "--id", fid, "--append", "--delivery", str(delivery), *args],
            input=(self.row(fid) + "\n").encode("utf-8"), capture_output=True, cwd=str(REPO_ROOT),
            timeout=60)
        out = done.stdout.decode("utf-8", "replace") + done.stderr.decode("utf-8", "replace")
        return done.returncode, out, [ln for ln in out.splitlines() if ln.startswith("delivery-findings:")]

    def test_totals_from_markdown_delivery(self) -> None:
        for eol in ("\n", "\r\n"):
            with self.subTest(eol=repr(eol)):
                self.delivery.write_bytes(self.CLAUDE_DELIVERY.replace("\n", eol).encode("utf-8"))
                rc, out, lines = self.run_tool(self.delivery, "--dry-run")
                self.assertEqual(rc, 0, out)
                self.assertIn("result: WOULD-WRITE", out)
                self.assertEqual(len(lines), 1, out)
                self.assertTrue(lines[0].startswith(
                    "delivery-findings: reported 0 ERROR, 1 WARN, 1 NOTE (2 in all); "), lines)

    def test_totals_from_gemini_delivery_with_sarif_json(self) -> None:
        self.delivery.write_text(self.GEMINI_DELIVERY, encoding="utf-8")
        head = "delivery-findings: reported 0 ERROR, 0 WARN, 6 NOTE (6 in all); "
        rc, out, lines = self.run_tool(self.delivery, "--dry-run")
        self.assertEqual(rc, 0, out)
        # The sample carries no round heading, so without --source-key the count is UNVERIFIABLE.
        self.assertEqual(lines, [head + "ledger rows UNVERIFIABLE (no-round-heading) (report only)"])
        rc, out, lines = self.run_tool(self.delivery, "--dry-run", "--source-key",
                                       "gemini 3b546 /validate-pr round 3 @ 2ba4b9847")
        self.assertEqual(rc, 0, out)
        # A key no row leads with is a counted zero, not UNVERIFIABLE.
        self.assertEqual(lines, [
            head + "0 ledger row(s) lead with its review key (key from --source-key; ledger with this "
            "row); WARNING fewer rows than reported findings (a combined row counts once) (report only)"])

    def test_last_findings_line_outside_fences_in_column_order(self) -> None:
        mod = load_linter_module("tools/open-findings-row.py", "_ofr_delivery_parse")
        text = ("FINDINGS: 1 ERROR, 0 WARN, 0 NOTE\n"
                "VPR-COMPLETE 3b540 b0a2e71cf\n"
                "FINDINGS: 3 ERROR, 5 WARN, 7 NOTE\n"
                "VERDICT: HOLD\n"
                "VPR-COMPLETE 3b540 F2A53DF9F\n"
                "~~~\n"
                "FINDINGS: 9 ERROR, 9 WARN, 9 NOTE\n"
                "VPR-COMPLETE 9z999 999999999\n"
                "~~~\n")
        totals, parts = mod.parse_delivery(mod.load_hook(REPO_ROOT), text)
        self.assertEqual((totals, parts["item"], parts["sha"], parts["bad"]),
                         ((3, 5, 7), "3b540", "F2A53DF9F", None))

    def test_row_count_against_fixture_ledger(self) -> None:
        def findings(line):
            self.delivery.write_text(self.CLAUDE_DELIVERY.replace("FINDINGS: 0 ERROR, 1 WARN, 1 NOTE", line),
                                     encoding="utf-8")
        head = "delivery-findings: reported "
        findings("FINDINGS: 1 ERROR, 2 WARN, 3 NOTE")
        rc, out, lines = self.run_tool(self.delivery, "--dry-run")
        self.assertEqual((rc, lines), (0, [
            head + "1 ERROR, 2 WARN, 3 NOTE (6 in all); 5 ledger row(s) lead with its review key (key from "
            "the delivery; ledger with this row); WARNING fewer rows than reported findings (a combined "
            "row counts once) (report only)"]), out)
        findings("FINDINGS: 0 ERROR, 2 WARN, 3 NOTE")
        rc, out, lines = self.run_tool(self.delivery)
        self.assertEqual((rc, lines), (0, [
            head + "0 ERROR, 2 WARN, 3 NOTE (5 in all); 5 ledger row(s) lead with its review key (key from "
            "the delivery; ledger with this row); rows equal the reported total (coverage, not "
            "faithfulness) (report only)"]), out)
        self.assertIn("result: WROTE", out)
        self.assertIn(self.row("R2-N3"), self.ledger.read_text(encoding="utf-8").splitlines())
        findings("FINDINGS: 0 ERROR, 1 WARN, 1 NOTE")
        rc, out, lines = self.run_tool(self.delivery, "--dry-run")
        self.assertEqual((rc, lines), (1, [
            head + "0 ERROR, 1 WARN, 1 NOTE (2 in all); 5 ledger row(s) lead with its review key (key from "
            "the delivery; ledger as read, nothing written); more rows than reported findings (report "
            "only)"]), out)
        self.assertIn("refused: duplicate-id", out)
        for token in ("3b540", "f2a53df9f", "R2-N3", "claude", "round 2"):
            self.assertNotIn(token, out)

    def test_unreadable_delivery_is_unverifiable_and_the_write_lands(self) -> None:
        fifo = self.dir / "fifo.md"
        os.mkfifo(fifo)
        not_utf8 = self.dir / "latin1.md"
        not_utf8.write_bytes(b"FINDINGS: 0 ERROR, 1 WARN, 1 NOTE\n\xff\nVPR-COMPLETE 3b540 f2a53df9f\n")
        cases = [("missing", self.dir / "absent.md", "delivery-missing"),
                 ("directory", self.dir, "delivery-not-regular"),
                 ("fifo", fifo, "delivery-not-regular"),
                 ("not utf-8", not_utf8, "delivery-not-utf8")]
        if os.geteuid() != 0:
            locked = self.dir / "locked.md"
            locked.write_text(self.CLAUDE_DELIVERY, encoding="utf-8")
            os.chmod(locked, 0)
            cases.append(("no read permission", locked, "delivery-unreadable"))
        for n, (name, path, code) in enumerate(cases, start=10):
            with self.subTest(case=name):
                rc, out, lines = self.run_tool(path, fid=f"R2-N{n}")
                self.assertEqual(rc, 0, out)
                self.assertIn("result: WROTE", out)
                self.assertIn(self.row(f"R2-N{n}"), self.ledger.read_text(encoding="utf-8").splitlines())
                self.assertEqual(lines, [f"delivery-findings: UNVERIFIABLE ({code}); nothing compared "
                                         "(report only)"])

    def test_findings_less_delivery_is_unverifiable_never_zero(self) -> None:
        unverifiable = "delivery-findings: UNVERIFIABLE ({}); nothing compared (report only)"
        tail = "VERDICT: SHIP\nVPR-COMPLETE 3b540 f2a53df9f\n"
        for name, text, want in (
                ("draft delivery", "Draft written.\nDRAFT-COMPLETE 3b544\n",
                 unverifiable.format("no-findings-line")),
                ("only a fenced FINDINGS line", "```\nFINDINGS: 0 ERROR, 1 WARN, 1 NOTE\n```\n" + tail,
                 unverifiable.format("no-findings-line")),
                ("the contract placeholder", "FINDINGS: <n> ERROR, <n> WARN, <n> NOTE\n" + tail,
                 unverifiable.format("findings-line-unparseable")),
                ("a malformed last line after a good one",
                 "FINDINGS: 0 ERROR, 1 WARN, 1 NOTE\nFINDINGS: 0 ERRORS, 1 WARN, 1 NOTE\n" + tail,
                 unverifiable.format("findings-line-unparseable")),
                ("a truncated last line after a good one",
                 "FINDINGS: 0 ERROR, 1 WARN, 1 NOTE\nFINDINGS: 0 ERROR, 1 WARN\n" + tail,
                 unverifiable.format("findings-line-unparseable")),
                ("no VPR-COMPLETE line", "FINDINGS: 0 ERROR, 1 WARN, 1 NOTE\nVERDICT: SHIP\n",
                 "delivery-findings: reported 0 ERROR, 1 WARN, 1 NOTE (2 in all); ledger rows "
                 "UNVERIFIABLE (no-vpr-complete-line) (report only)")):
            with self.subTest(case=name):
                self.delivery.write_text(text, encoding="utf-8")
                rc, out, lines = self.run_tool(self.delivery, "--dry-run")
                self.assertEqual(rc, 0, out)
                self.assertIn("result: WOULD-WRITE", out)
                self.assertEqual(lines, [want])

    def test_source_cell_divergence_is_unverifiable_not_a_count(self) -> None:
        import types
        mod = load_linter_module("tools/open-findings-row.py", "_ofr_delivery_divergence")
        hook = mod.load_hook(REPO_ROOT)
        fake = types.SimpleNamespace(**vars(hook))
        fake.parse_open_rows_full = lambda text: [(f, s, fi + " (moved)", d)
                                                  for f, s, fi, d in hook.parse_open_rows_full(text)]
        self.delivery.write_text(self.CLAUDE_DELIVERY, encoding="utf-8")
        head = "delivery-findings: reported 0 ERROR, 1 WARN, 1 NOTE (2 in all); "
        self.assertEqual(mod.delivery_report(hook, self.LEDGER, self.delivery, with_row=False),
                         head + "4 ledger row(s) lead with its review key (key from the delivery; ledger "
                         "as read, nothing written); more rows than reported findings (report only)")
        self.assertEqual(mod.delivery_report(fake, self.LEDGER, self.delivery, with_row=False),
                         head + "ledger rows UNVERIFIABLE (source-cell-divergence) (report only)")

    def test_usage_documents_delivery_and_its_residue(self) -> None:
        import ast
        doc = ast.get_docstring(ast.parse(OpenFindingsRowTests.TOOL.read_text(encoding="utf-8")))
        usage = doc.split("Usage:", 1)[1].split("\n\nROW INPUT.", 1)[0]
        self.assertEqual(usage.count("[--delivery PATH [--source-key KEY]] < row"), 2)
        section = " ".join(doc.split("DELIVERY FINDINGS (report only, 3b544).", 1)[1]
                           .split("\n\nENVIRONMENT (exit 2).", 1)[0].split())
        # 3b578 r5 (claude 3b578 round-4 N3): the line model's column-0 and CR clauses, not only its last words.
        for phrase in ("MATCHING RULE:", "never changes the exit code", "never a zero",
                       "a row count shows coverage, not faithfulness",
                       "a combined row recording several findings counts once",
                       "two deliveries with one key (the same family re-run for one item, round and sha) "
                       "share their rows",
                       "fence reading does not model container blocks or HTML blocks",
                       "FINDINGS, VPR-COMPLETE and heading lines count at column 0 outside code fences",
                       "delivery lines end at LF only, a CR before it dropped, so a lone CR or U+2028 starts no line",
                       # 3b578 r6: the two-rounds, inline-code and --source-key residue clauses (DT15, DT17, DT21).
                       "round-heading-ambiguous when headings naming the item state two rounds",
                       "except that a backtick run whose remaining text holds a backtick opens no fence (CommonMark "
                       "reads it as inline code)",
                       "and with --source-key that case is UNVERIFIABLE (source-key-disagrees) instead"):
            self.assertIn(phrase, section)
        result = run_linter("tools/open-findings-row.py", "--help")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("--delivery PATH", result.stdout)
        self.assertIn("--source-key KEY", result.stdout)

    def tool(self, name: str):
        mod = load_linter_module("tools/open-findings-row.py", name)
        return mod, mod.load_hook(REPO_ROOT)

    def test_key_counts_only_the_delivery_own_review(self) -> None:
        # WARN-1 of round 1 (probes P3 and P4): rows of another leg or round at the same sha.
        mod, hook = self.tool("_ofr_delivery_key")
        key = self.REVIEW
        for cell, counted in (
                (key, True),
                (key + "; WARN-1", True),
                ("gemini 3b540 /validate-pr round 2 @ f2a53df9f", False),
                ("3b540 /validate-pr round 2 @ f2a53df9f", False),
                ("claude 3b540 /validate-pr round 4 @ f2a53df9f", False),
                ("claude 3b540 /validate-pr @ f2a53df9f", False),
                ("Claude 3B540 /validate-pr round 2 @ F2A53DF9F", False),
                ("seen in " + key, False),
                (key + "0", False),
                (key + "-r3", False),
                # 3b578 r6: only an ASCII letter or digit, _ or - after the key stops it, so a non-ASCII letter
                # (U+00E9) does not.
                (key + "\u00e9", True)):
            with self.subTest(cell=cell):
                text = ("## Open\n\n| Found | Severity | Finding | Source | Disposition |\n| --- | --- | --- | --- "
                        f"| --- |\n| 2026-10-20 | note | [K-1] a row | {cell} |  |\n")
                lines = text.splitlines()
                self.assertEqual(mod.review_rows(hook, lines, mod.classify(hook, lines), key), int(counted))
        for delivery, want in (
                (self.CLAUDE_DELIVERY, "4 ledger row(s)"),
                (self.CLAUDE_DELIVERY.replace("family=claude", "family=gemini"), "1 ledger row(s)"),
                (self.CLAUDE_DELIVERY.replace("round 2 (REFUTE)", "round 1 (REFUTE)"), "1 ledger row(s)")):
            with self.subTest(delivery=want):
                self.delivery.write_text(delivery, encoding="utf-8")
                got = mod.delivery_report(hook, self.LEDGER, self.delivery, with_row=False)
                self.assertIn("; " + want + " lead with its review key (key from the delivery;", got)
        import ast
        doc = ast.get_docstring(ast.parse(OpenFindingsRowTests.TOOL.read_text(encoding="utf-8")))
        section = " ".join(doc.split("DELIVERY FINDINGS (report only, 3b544).", 1)[1]
                           .split("\n\nENVIRONMENT (exit 2).", 1)[0].split())
        for name, text in (("tool docstring", section), ("reference", self.delivery_bullet())):
            with self.subTest(key_end=name):
                self.assertIn("is not followed by an ASCII letter or digit, `_` or `-`", text)

    def test_key_needs_every_part_or_a_source_key(self) -> None:
        mod, hook = self.tool("_ofr_delivery_parts")
        head = "delivery-findings: reported 0 ERROR, 1 WARN, 1 NOTE (2 in all); "
        no_family = self.CLAUDE_DELIVERY.split("\n", 1)[1]
        no_round = self.CLAUDE_DELIVERY.replace("# /validate-pr round 2", "# Review round 2")
        other_item = self.CLAUDE_DELIVERY.replace(
            "\n## Scratch probes", "# /validate-pr round 3 (REFUTE): 3b541, commit f2a53df9f\n\n## Scratch probes")
        two_rounds = other_item.replace("3b541, commit", "3b540, commit")
        given = "claude 3b540 /validate-pr round 2 @ f2a53df9f"
        counted = head + "4 ledger row(s) lead with its review key (key from {}; ledger as read, nothing "
        counted += "written); more rows than reported findings (report only)"
        for name, delivery, key, want in (
                ("no family", no_family, None, "no-worker-status-family"),
                ("no round heading", no_round, None, "no-round-heading"),
                ("two rounds", two_rounds, None, "round-heading-ambiguous"),
                ("two rounds, with a key", two_rounds, given, "round-heading-ambiguous"),
                ("a family without a value", self.CLAUDE_DELIVERY.replace("family=claude", "family="), given,
                 "worker-status-family-unparseable"),
                ("a key not in the form", self.CLAUDE_DELIVERY, "claude 3b540 round 2 @ f2a53df9f",
                 "source-key-invalid"),
                ("a key of another family", self.CLAUDE_DELIVERY, given.replace("claude", "gemini"),
                 "source-key-disagrees"),
                ("a key of another round", no_family, given.replace("round 2", "round 1"),
                 "source-key-disagrees"),
                ("a key of another sha", no_round, given.replace("f2a53df9f", "f2a53df9e"),
                 "source-key-disagrees"),
                ("a heading of another item is not its round", other_item, None, None),
                ("the key supplies the family", no_family, given, None),
                ("the key supplies the round", no_round, given, None)):
            with self.subTest(case=name):
                self.delivery.write_text(delivery, encoding="utf-8")
                got = mod.delivery_report(hook, self.LEDGER, self.delivery, with_row=False, source_key=key)
                if want is None:
                    want_line = counted.format("the delivery" if key is None else "--source-key")
                else:
                    want_line = head + f"ledger rows UNVERIFIABLE ({want}) (report only)"
                self.assertEqual(got, want_line)
        self.delivery.write_text(no_round, encoding="utf-8")
        rc, out, lines = self.run_tool(self.delivery, "--dry-run", "--source-key", given)
        self.assertEqual((rc, lines), (0, [counted.format("--source-key").replace(
            "4 ledger row(s)", "5 ledger row(s)").replace("ledger as read, nothing written", "ledger with this row")]),
            out)
        done = subprocess.run(
            [sys.executable, "-I", str(OpenFindingsRowTests.TOOL), "--ledger", str(self.ledger), "--id", "R2-N3",
             "--append", "--source-key", given], input=(self.row("R2-N3") + "\n").encode("utf-8"),
            capture_output=True, cwd=str(REPO_ROOT), timeout=60)
        self.assertEqual(done.returncode, 2)
        self.assertIn(b"--source-key needs --delivery", done.stderr)
        self.assertEqual(self.ledger.read_text(encoding="utf-8"), self.LEDGER)

    def test_malformed_last_vpr_complete_line_is_unverifiable(self) -> None:
        # Round 1 NOTE-2, mutations M22 and M24: an earlier parseable line never stands in for it.
        tail = "VPR-COMPLETE 3b540 f2a53df9f\n"
        quoted = self.CLAUDE_DELIVERY.replace("\n## What I ran", "\n" + tail + "\n## What I ran")
        own = quoted.rindex(tail)
        for name, line in (("not hex", "VPR-COMPLETE 3b540 f2a53dfzz\n"), ("no sha", "VPR-COMPLETE 3b540\n"),
                           ("a short sha", "VPR-COMPLETE 3b540 f2a53d\n")):
            for key in (None, self.REVIEW):
                with self.subTest(case=name, source_key=key):
                    self.delivery.write_text(quoted[:own] + line + quoted[own + len(tail):], encoding="utf-8")
                    args = ["--dry-run"] + ([] if key is None else ["--source-key", key])
                    rc, out, lines = self.run_tool(self.delivery, *args)
                    self.assertEqual((rc, lines), (0, [
                        "delivery-findings: reported 0 ERROR, 1 WARN, 1 NOTE (2 in all); ledger rows "
                        "UNVERIFIABLE (vpr-complete-line-unparseable) (report only)"]), out)

    def test_row_count_failure_is_unverifiable(self) -> None:
        # Round 1 NOTE-2, mutation M25: an unexpected failure while counting is said, never raised.
        import types
        mod, hook = self.tool("_ofr_delivery_count_failure")
        fake = types.SimpleNamespace(**vars(hook))

        def broken(_text):
            raise RuntimeError("probe")
        fake.parse_open_rows_full = broken
        self.delivery.write_text(self.CLAUDE_DELIVERY, encoding="utf-8")
        self.assertEqual(mod.delivery_report(fake, self.LEDGER, self.delivery, with_row=True),
                         "delivery-findings: reported 0 ERROR, 1 WARN, 1 NOTE (2 in all); ledger rows "
                         "UNVERIFIABLE (row-count-failed) (report only)")

    def test_inline_code_line_and_non_lf_breaks_do_not_flip_the_tail(self) -> None:
        # Round 1 NOTE-1, probes P5 and P6.
        mod, hook = self.tool("_ofr_delivery_fences")
        quote = "```\nFINDINGS: 4 ERROR, 0 WARN, 0 NOTE\nVPR-COMPLETE 3b540 b0a2e71cf\n```\n"
        own = "FINDINGS: 0 ERROR, 1 WARN, 1 NOTE\nVERDICT: HOLD\nVPR-COMPLETE 3b540 f2a53df9f\n"
        for name, text in (
                ("inline code at column 0", "```inline``` code, not a fence\n" + quote + own),
                ("a four-backtick code span", "```` ``` ```` spans a run\n" + quote + own),
                ("U+2028 after the tail", own + "prose FINDINGS: 7 ERROR, 0 WARN, 0 NOTE\n"),
                ("a lone CR after the tail", own + "prose\rFINDINGS: 7 ERROR, 0 WARN, 0 NOTE\n"),
                ("U+2028 before a VPR-COMPLETE", own + "prose VPR-COMPLETE 3b540 b0a2e71cf\n"),
                ("CRLF line ends", (quote + own).replace("\n", "\r\n"))):
            with self.subTest(case=name):
                totals, parts = mod.parse_delivery(hook, text)
                self.assertEqual((totals, parts["item"], parts["sha"]), ((0, 1, 1), "3b540", "f2a53df9f"))

    def test_reference_documents_delivery_beside_class_count(self) -> None:
        # Round 1 NOTE-3: the reference's Writing rows section, held to the tool.
        reference = (REPO_ROOT / "references" / "hook-open-findings-guard.md").read_text(encoding="utf-8")
        writing = reference.split("## Writing rows (`tools/open-findings-row.py`, 3b334)", 1)[1].split("\n## ", 1)[0]
        usage = writing.split("```text\n", 1)[1].split("\n```", 1)[0]
        self.assertIn("[--delivery PATH [--source-key KEY]] < row", usage)
        normalized = " ".join(writing.split())
        class_count = normalized.index("**Class count (report only).**")
        delivery = normalized.index("**Delivery findings (report only, 3b544).**")
        self.assertLess(class_count, delivery)
        for phrase in ("`delivery-findings:`", "`<family> <item> /validate-pr round <n> @ <sha>`",
                       "`--source-key`", "`UNVERIFIABLE`", "never changes the exit code",
                       "is not counted, so the count errs low, toward the warning"):
            self.assertIn(phrase, normalized[delivery:])

    def delivery_bullet(self) -> str:
        reference = (REPO_ROOT / "references" / "hook-open-findings-guard.md").read_text(encoding="utf-8")
        normalized = " ".join(reference.split())
        start = normalized.index("**Delivery findings (report only, 3b544).**")
        return normalized[start:normalized.index("- **Environment (exit 2).**", start)]

    def test_quoted_round_heading_is_not_the_delivery_round(self) -> None:
        # Round 2 NOTE-1: a delivery with no round heading of its own that quotes another round's heading
        # took that round's key, so a round-1 row at the same sha read as this delivery's coverage.
        mod, hook = self.tool("_ofr_delivery_quoted_heading")
        quote = "# /validate-pr round 1 (REFUTE): 3b540, commit f2a53df9f, branch tooling/3b540-d12-error-paths\n"
        one = self.CLAUDE_SAMPLE.replace("FINDINGS: 0 ERROR, 1 WARN, 1 NOTE", "FINDINGS: 0 ERROR, 0 WARN, 1 NOTE")
        quoted = one.replace("\n## What I ran", "\nThe round-1 review opened:\n" + quote + "\n## What I ran", 1)
        leading = one.replace("\n## Scratch probes", "\n" + quote + "\n## Scratch probes", 1)
        # Round 4 NOTE-1: two quoted rounds and no round heading of its own (the reviewer's probe C).
        round_3 = quote.replace("round 1", "round 3")
        two_quotes = quoted.replace("\n## SARIF-lite", "\n" + round_3 + "\n## SARIF-lite", 1)
        head = "delivery-findings: reported 0 ERROR, 0 WARN, 1 NOTE (1 in all); "
        for name, delivery, key, want in (
                ("a quote after another heading", quoted, None, "ledger rows UNVERIFIABLE (no-round-heading)"),
                ("the round from --source-key", quoted, self.REVIEW,
                 "4 ledger row(s) lead with its review key (key from --source-key; ledger as read, nothing "
                 "written); more rows than reported findings"),
                ("stated residue: a quote as the first heading", leading, None,
                 "1 ledger row(s) lead with its review key (key from the delivery; ledger as read, nothing "
                 "written); rows equal the reported total (coverage, not faithfulness)"),
                ("--source-key catches that residue", leading, self.REVIEW,
                 "ledger rows UNVERIFIABLE (source-key-disagrees)"),
                ("two quoted rounds", two_quotes, None, "ledger rows UNVERIFIABLE (round-heading-ambiguous)"),
                ("two quoted rounds, with a correct key", two_quotes, self.REVIEW,
                 "ledger rows UNVERIFIABLE (round-heading-ambiguous)")):
            with self.subTest(case=name):
                self.delivery.write_text(delivery, encoding="utf-8")
                got = mod.delivery_report(hook, self.LEDGER, self.delivery, with_row=False, source_key=key)
                self.assertEqual(got, head + want + " (report only)")
        # Round 5 NOTE (probes P1 and P2): beside two quoted rounds, a part that does not parse, a key not in
        # the form and, without --source-key, a missing VPR-COMPLETE line print their own code; a correct key
        # supplies the item, so the ambiguity stands; no WORKER_STATUS first line does not change the code. Each
        # case is held to the reference clause that states it. 3b556 (claude 3b544 round-6 notes): the part code
        # comes before a key not in the form (M4), and a WORKER_STATUS first line with no family= value is a part
        # that does not parse (W1).
        bullet = self.delivery_bullet()
        part = ("a part the delivery carries that does not parse prints its code (for example "
                "`worker-status-family-unparseable` for an empty `family=`), with or without `--source-key`")
        no_value = ("a `WORKER_STATUS` first line without exactly one valid `family=` value (none, two, or an "
                    "empty one) is a part that does not parse")
        invalid_key = "claude 3b540 round 2 @ f2a53df9f"
        empty_family = two_quotes.replace("family=claude", "family=", 1)
        no_family_value = two_quotes.replace("rc=0, family=claude, ", "rc=0, ", 1)
        no_vpr = two_quotes.replace("VPR-COMPLETE 3b540 f2a53df9f\n", "", 1)
        # 3b578 r6: the same two quoted rounds as headings with no item field; with no VPR-COMPLETE line and no key no
        # item is known, so neither names one (P2 read an empty item, which every heading holds); a key supplies it.
        no_vpr_no_field = no_vpr.replace(" (REFUTE): 3b540,", ": 3b540,", 2)
        # 3b556 r2 (claude 3b556 round-1 NOTE-1): the reviewer's two envelope shapes, each with one valid
        # family=, are parts that do not parse (E1, E2); a byte-order mark before WORKER_STATUS leaves no
        # WORKER_STATUS first line, so no family (E3, E4).
        envelope = ("and so is one whose envelope, `WORKER_STATUS: <STATUS> (...)`, does not parse, even with one "
                    "valid `family=` value: for example one with no parentheses, or one whose status is not one or "
                    "more ASCII uppercase letters (A to Z)")
        # 3b556 r3 (claude 3b556 round-2 NOTE-2): a digit, an underscore or no status at all does not parse
        # either (X1, X2).
        status = ("such as an empty status or one holding a digit, `_`, or a letter outside A to Z (lowercase, "
                  "accented or full-width)")
        bom = ("A byte-order mark before `WORKER_STATUS` makes the first line not a `WORKER_STATUS` first line, so "
               "such a delivery has no family")
        no_parens = "WORKER_STATUS: PASS family=claude\n" + two_quotes.split("\n", 1)[1]
        lower_status = "WORKER_STATUS: pass (family=claude)\n" + two_quotes.split("\n", 1)[1]
        digit_status = "WORKER_STATUS: PASS2 (family=claude)\n" + two_quotes.split("\n", 1)[1]
        underscore_status = "WORKER_STATUS: NOT_RUN (family=claude)\n" + two_quotes.split("\n", 1)[1]
        empty_status = "WORKER_STATUS:  (family=claude)\n" + two_quotes.split("\n", 1)[1]
        # 3b556 r4 (claude 3b556 round-3 NOTE-1): nor does an accented status (a precomposed U+00C9) or a
        # full-width one (U+FF30, U+FF21, U+FF33, U+FF33) (M2).
        accented_status = "WORKER_STATUS: PASSÉ (family=claude)\n" + two_quotes.split("\n", 1)[1]
        full_width_status = "WORKER_STATUS: ＰＡＳＳ (family=claude)\n" + two_quotes.split("\n", 1)[1]
        own = one.replace("\n## Scratch probes", f"\n{self.ROUND_2_HEADING}\n\n## Scratch probes", 1)
        bom_status = "\ufeff" + own
        for name, delivery, key, code, clause in (
                ("P1 an empty family=", empty_family, None, "worker-status-family-unparseable", part),
                ("P1 an empty family=, with a correct key", empty_family, self.REVIEW,
                 "worker-status-family-unparseable", part),
                ("P1 an empty family=, with a key not in the form", empty_family, invalid_key,
                 "worker-status-family-unparseable", part),
                ("no family= value", no_family_value, None, "worker-status-family-unparseable", no_value),
                ("no family= value, with a key not in the form", no_family_value, invalid_key,
                 "worker-status-family-unparseable", no_value),
                ("E1 no parentheses", no_parens, None, "worker-status-family-unparseable", envelope),
                ("E1 no parentheses, with a correct key", no_parens, self.REVIEW, "worker-status-family-unparseable",
                 envelope),
                ("E1 no parentheses, with a key not in the form", no_parens, invalid_key,
                 "worker-status-family-unparseable", envelope),
                ("E2 a lowercase status", lower_status, None, "worker-status-family-unparseable", envelope),
                ("E2 a lowercase status, with a correct key", lower_status, self.REVIEW,
                 "worker-status-family-unparseable", envelope),
                ("E2 a lowercase status, with a key not in the form", lower_status, invalid_key,
                 "worker-status-family-unparseable", envelope),
                ("X1 a status with a digit", digit_status, None, "worker-status-family-unparseable", status),
                ("X1 a status with a digit, with a correct key", digit_status, self.REVIEW,
                 "worker-status-family-unparseable", status),
                ("X1 a status with a digit, with a key not in the form", digit_status, invalid_key,
                 "worker-status-family-unparseable", status),
                ("X1 a status with an underscore", underscore_status, None, "worker-status-family-unparseable",
                 status),
                ("X1 a status with an underscore, with a correct key", underscore_status, self.REVIEW,
                 "worker-status-family-unparseable", status),
                ("X1 a status with an underscore, with a key not in the form", underscore_status, invalid_key,
                 "worker-status-family-unparseable", status),
                ("X2 an empty status", empty_status, None, "worker-status-family-unparseable", status),
                ("X2 an empty status, with a correct key", empty_status, self.REVIEW,
                 "worker-status-family-unparseable", status),
                ("X2 an empty status, with a key not in the form", empty_status, invalid_key,
                 "worker-status-family-unparseable", status),
                ("M2 an accented status", accented_status, None, "worker-status-family-unparseable", status),
                ("M2 an accented status, with a correct key", accented_status, self.REVIEW,
                 "worker-status-family-unparseable", status),
                ("M2 an accented status, with a key not in the form", accented_status, invalid_key,
                 "worker-status-family-unparseable", status),
                ("M2 a full-width status", full_width_status, None, "worker-status-family-unparseable", status),
                ("M2 a full-width status, with a correct key", full_width_status, self.REVIEW,
                 "worker-status-family-unparseable", status),
                ("M2 a full-width status, with a key not in the form", full_width_status, invalid_key,
                 "worker-status-family-unparseable", status),
                ("E3 E4 a byte-order mark before WORKER_STATUS", bom_status, None, "no-worker-status-family", bom),
                ("P2 no VPR-COMPLETE line", no_vpr, None, "no-vpr-complete-line",
                 "without `--source-key`, a delivery with no `VPR-COMPLETE` line prints `no-vpr-complete-line`, "
                 "since no item is known"),
                ("P2 no VPR-COMPLETE line, with a correct key", no_vpr, self.REVIEW, "round-heading-ambiguous",
                 "headings naming the item (the key's, with `--source-key`)"),
                ("P2 no VPR-COMPLETE line, two headings with no item field", no_vpr_no_field, None,
                 "no-vpr-complete-line",
                 "without `--source-key`, a delivery with no `VPR-COMPLETE` line prints `no-vpr-complete-line`, "
                 "since no item is known"),
                ("P2 no VPR-COMPLETE line, two headings with no item field, with a correct key", no_vpr_no_field,
                 self.REVIEW, "round-heading-ambiguous", "headings naming the item (the key's, with `--source-key`)"),
                ("a key not in the form", two_quotes, "claude 3b540 round 2 @ f2a53df9f", "source-key-invalid",
                 "a `--source-key` not in the key's form prints `source-key-invalid`"),
                ("no WORKER_STATUS line", two_quotes.split("\n", 1)[1], None, "round-heading-ambiguous",
                 "A delivery with no `WORKER_STATUS` first line, so no family, or with no own round heading does "
                 "not;")):
            with self.subTest(precedence=name):
                self.delivery.write_text(delivery, encoding="utf-8")
                got = mod.delivery_report(hook, self.LEDGER, self.delivery, with_row=False, source_key=key)
                self.assertEqual(got, head + f"ledger rows UNVERIFIABLE ({code}) (report only)")
                self.assertIn(clause, bullet)
        with self.subTest(precedence="the missing-family sentence narrowed"):
            self.assertNotIn("A missing family or own round heading does not.", bullet)
        # 3b556 r3 (claude 3b556 round-2 NOTE-1): a WORKER_STATUS first line starts with WORKER_STATUS: at column 0,
        # case and colon exact, so a first line with no colon, a space before the colon, an indent or a lowercase
        # prefix is no WORKER_STATUS first line: no family without a key, the key's count with a correct key and
        # source-key-invalid with a key not in the form, never worker-status-family-unparseable (X3, X4).
        first_line = ("A `WORKER_STATUS` first line is a first line that starts with `WORKER_STATUS:` at column 0, "
                      "case and colon exact: an indented first line, a lowercase one (`worker_status:`), and one with "
                      "no colon or a space before the colon (`WORKER_STATUS PASS`, `WORKER_STATUS : PASS`) are not "
                      "`WORKER_STATUS` first lines, whatever follows, so such a delivery has no family")
        status_line, rest = own.split("\n", 1)
        counted = ("4 ledger row(s) lead with its review key (key from {}; ledger as read, nothing written); more "
                   "rows than reported findings")
        with self.subTest(first_line="the control"):
            self.delivery.write_text(own, encoding="utf-8")
            self.assertEqual(mod.delivery_report(hook, self.LEDGER, self.delivery, with_row=False, source_key=None),
                             head + counted.format("the delivery") + " (report only)")
        # 3b556 r4 (claude 3b556 round-3 NOTE-1): a one-letter status parses, so it counts like the control (M3).
        one_letter = status_line.replace("WORKER_STATUS: PASS", "WORKER_STATUS: P", 1)
        for key, want in ((None, counted.format("the delivery")), (self.REVIEW, counted.format("--source-key")),
                          (invalid_key, "ledger rows UNVERIFIABLE (source-key-invalid)")):
            with self.subTest(status="M3 a one-letter status", source_key=key):
                self.delivery.write_text(one_letter + "\n" + rest, encoding="utf-8")
                got = mod.delivery_report(hook, self.LEDGER, self.delivery, with_row=False, source_key=key)
                self.assertEqual(got, head + want + " (report only)")
                self.assertIn(envelope, bullet)
        # 3b556 r4: a tab-indented first line is no WORKER_STATUS first line either (M1).
        for name, line in (
                ("X3 no colon", status_line.replace("WORKER_STATUS:", "WORKER_STATUS", 1)),
                ("X3 a space before the colon", status_line.replace("WORKER_STATUS:", "WORKER_STATUS :", 1)),
                ("X4 an indented first line", " " + status_line),
                ("M1 a tab-indented first line", "\t" + status_line),
                ("X5 a lowercase first line", status_line.replace("WORKER_STATUS: PASS", "worker_status: pass", 1))):
            for key, want in ((None, "ledger rows UNVERIFIABLE (no-worker-status-family)"),
                              (self.REVIEW, counted.format("--source-key")),
                              (invalid_key, "ledger rows UNVERIFIABLE (source-key-invalid)")):
                with self.subTest(first_line=name, source_key=key):
                    self.delivery.write_text(line + "\n" + rest, encoding="utf-8")
                    got = mod.delivery_report(hook, self.LEDGER, self.delivery, with_row=False, source_key=key)
                    self.assertEqual(got, head + want + " (report only)")
                    self.assertIn(first_line, bullet)
        # 3b556: an unreadable delivery or a missing or unparseable last FINDINGS line prints the whole-line
        # UNVERIFIABLE and compares nothing, before every code above, even with a key not in the form (F1).
        whole = ("A delivery that cannot be read (missing, unreadable, not a regular file or not UTF-8), that has "
                 "no column-0 `FINDINGS:` line outside fences, or whose last such line does not parse prints "
                 "`delivery-findings: UNVERIFIABLE (<code>)` and compares nothing, whatever its other parts and "
                 "`--source-key`; the codes below apply only beside parsed totals.")
        own_findings = "FINDINGS: 0 ERROR, 0 WARN, 1 NOTE\n"
        for name, path, delivery, code in (
                ("an unparseable last FINDINGS line", self.delivery,
                 empty_family.replace(own_findings, "FINDINGS: <n> ERROR, <n> WARN, <n> NOTE\n", 1),
                 "findings-line-unparseable"),
                ("no FINDINGS line", self.delivery, empty_family.replace(own_findings, "", 1), "no-findings-line"),
                ("a missing delivery", self.dir / "absent.md", None, "delivery-missing")):
            for key in (None, invalid_key, self.REVIEW):
                with self.subTest(precedence=name, source_key=key):
                    if delivery is not None:
                        self.delivery.write_text(delivery, encoding="utf-8")
                    self.assertEqual(mod.delivery_report(hook, self.LEDGER, path, with_row=False, source_key=key),
                                     f"delivery-findings: UNVERIFIABLE ({code}); nothing compared (report only)")
        with self.subTest(precedence="the whole-line sentence before the three cases"):
            self.assertIn(whole, bullet)
            self.assertLess(bullet.index(whole), bullet.index("Three cases print another code instead"))
        with self.subTest(precedence="review_key docstring"):
            self.assertIn("so without --source-key a delivery with no VPR-COMPLETE line names no item and gets "
                          "no-vpr-complete-line", " ".join(mod.review_key.__doc__.split()))
        import ast
        doc = ast.get_docstring(ast.parse(OpenFindingsRowTests.TOOL.read_text(encoding="utf-8")))
        section = " ".join(doc.split("DELIVERY FINDINGS (report only, 3b544).", 1)[1]
                           .split("\n\nENVIRONMENT (exit 2).", 1)[0].split())
        # 3b578 r5 (claude 3b578 round-4 N3): with the first-heading clause in the docstring and the reference.
        for phrase in ("only when it is the delivery's first heading (3b544 r3): a round heading after another heading "
                       "is a quote, never the delivery's round",
                       "the orchestrator should pass --source-key when it knows the round"):
            self.assertIn(phrase, section)
        for phrase in ("heading whose item field is the item and that is the delivery's first heading",
                       "a round heading after another heading is a quote and gives no round",
                       "`UNVERIFIABLE (source-key-disagrees)`",
                       "two column-0 `# /validate-pr round <n>` headings naming the item (the key's, with "
                       "`--source-key`) with different rounds, own or quoted, wherever they stand, make the count "
                       "`UNVERIFIABLE (round-heading-ambiguous)`, even with a correct `--source-key`. Three cases "
                       "print another code instead, the first that applies in this order:"):
            self.assertIn(phrase, bullet)
        self.assertNotIn("other than the one in the delivery's own round heading", bullet)
        # Round 4 NOTE-2: the docstring and the reference state the remaining first-heading residue in one
        # wording, and round 4 NOTE-3 (U5): neither drops its clause on the delivery's own later headings.
        residue = ("a delivery whose first heading quotes another round's heading for the same item at column 0 "
                   "still takes that round's key, even when its own headings follow the quote (only an unfenced "
                   "ATX heading before the quote stops it; a setext, HTML, block-quoted or list-item heading does "
                   "not)")
        for name, text in (("tool docstring", section), ("reference", bullet)):
            with self.subTest(residue=name):
                self.assertIn(residue, text)
                self.assertNotIn("with no heading of its own", text)
        # 3b556 r2: the docstring states the family rule in the reference's words, envelope and byte-order mark
        # included; 3b556 r3: the ASCII status examples and the first-line definition too.
        family = ("a `WORKER_STATUS` first line without exactly one valid `family=` value (none, two, or an empty "
                  "one) is a part that does not parse, " + envelope + ", " + status + ". " + first_line + ". " + bom)
        for name, text in (("tool docstring", section), ("reference", bullet)):
            with self.subTest(family=name):
                self.assertIn(family, text)

    def test_staged_claude_shape_needs_a_source_key(self) -> None:
        # Round 2 NOTE-2: the staged Claude sample carries no round heading, so its own shape gets no count
        # from the delivery, only from --source-key; the reference must not read as if a heading were usual.
        self.delivery.write_text(self.CLAUDE_SAMPLE, encoding="utf-8")
        head = "delivery-findings: reported 0 ERROR, 1 WARN, 1 NOTE (2 in all); "
        rc, out, lines = self.run_tool(self.delivery, "--dry-run")
        self.assertEqual((rc, lines), (0, [head + "ledger rows UNVERIFIABLE (no-round-heading) (report only)"]),
                         out)
        rc, out, lines = self.run_tool(self.delivery, "--dry-run", "--source-key", self.REVIEW)
        self.assertEqual((rc, lines), (0, [
            head + "5 ledger row(s) lead with its review key (key from --source-key; ledger with this row); "
            "more rows than reported findings (report only)"]), out)
        bullet = self.delivery_bullet()
        for phrase in ("neither sample delivery staged for 3b544", "`UNVERIFIABLE (no-round-heading)`",
                       "The orchestrator should pass `--source-key` when it knows the round"):
            self.assertIn(phrase, bullet)
        self.assertNotIn("the round from its copy of the brief heading", bullet)

    def test_key_parts_parse_as_documented(self) -> None:
        # Round 2 NOTE-3: a killing subtest for each key-part clause no test killed (its B1-B5, B9-B11).
        mod, hook = self.tool("_ofr_delivery_clauses")
        head = "delivery-findings: reported 0 ERROR, 1 WARN, 1 NOTE (2 in all); "
        counted = head + ("4 ledger row(s) lead with its review key (key from the delivery; ledger as read, "
                          "nothing written); more rows than reported findings (report only)")

        def unverifiable(code: str) -> str:
            return head + f"ledger rows UNVERIFIABLE ({code}) (report only)"

        def led_by(lead: str) -> str:
            # The staged Claude shape with ``lead`` before its first section heading.
            return self.CLAUDE_SAMPLE.replace("\n## Scratch probes", "\n" + lead + "\n## Scratch probes", 1)

        gemini_status = "WORKER_STATUS: PASS (account=b, rc=0, family=gemini, advisory=true)\n"
        round_1 = "# /validate-pr round 1 (REFUTE): 3b540, commit f2a53df9f\n"
        round_2 = self.ROUND_2_HEADING + "\n"
        no_status = self.CLAUDE_DELIVERY.split("\n", 1)[1]
        for clause, runs in (
                ("B1 the family of the first line only", [
                    (self.CLAUDE_DELIVERY.replace("\n## SARIF-lite", "\n" + gemini_status + "\n## SARIF-lite", 1),
                     None, counted),
                    (no_status.replace("\n## SARIF-lite", "\n" + gemini_status + "\n## SARIF-lite", 1), None,
                     unverifiable("no-worker-status-family"))]),
                ("B2 one family= value", [
                    (self.CLAUDE_DELIVERY.replace("family=claude", "family=claude, family=gemini"), None,
                     unverifiable("worker-status-family-unparseable"))]),
                ("B3 no heading inside a fence", [
                    (self.CLAUDE_DELIVERY.replace("\n## What I ran", "\n~~~\n" + round_1 + "~~~\n\n## What I ran", 1),
                     None, counted),
                    (led_by("```\n" + round_1 + "```\n"), None, unverifiable("no-round-heading"))]),
                ("B4 the whole --source-key", [
                    (self.CLAUDE_DELIVERY, self.REVIEW + "; WARN-1", unverifiable("source-key-invalid"))]),
                ("B5 the heading's item as a whole token", [
                    (led_by(round_2.replace(" 3b540,", f" {item},")), None, unverifiable("no-round-heading"))
                    for item in ("3b5400", "3b540-r2", "v3b540")]),
                ("B9 a level-1 heading only", [(led_by("#" + round_2), None, unverifiable("no-round-heading"))]),
                ("B10 no blockquoted heading", [(led_by("> " + round_2), None, unverifiable("no-round-heading"))]),
                ("B11 the family code before the VPR-COMPLETE code", [
                    (self.CLAUDE_DELIVERY.replace("family=claude", "family=").replace(
                        "VPR-COMPLETE 3b540 f2a53df9f", "VPR-COMPLETE 3b540"), None,
                     unverifiable("worker-status-family-unparseable"))])):
            with self.subTest(clause=clause):
                for delivery, key, want in runs:
                    self.delivery.write_text(delivery, encoding="utf-8")
                    self.assertEqual(
                        mod.delivery_report(hook, self.LEDGER, self.delivery, with_row=False, source_key=key), want)

    def test_first_heading_rule_parses_as_documented(self) -> None:
        # Round 3 NOTE-3: a killing subtest for each first-heading clause no test killed (its five survivors);
        # round 4 NOTE-3: the same for the four neighbouring ATX clauses (its U1 to U4).
        mod, hook = self.tool("_ofr_delivery_first_heading")
        head = "delivery-findings: reported 0 ERROR, 1 WARN, 1 NOTE (2 in all); "
        counted = head + ("4 ledger row(s) lead with its review key (key from the delivery; ledger as read, "
                          "nothing written); more rows than reported findings (report only)")
        stopped = head + "ledger rows UNVERIFIABLE (no-round-heading) (report only)"
        round_1 = "# /validate-pr round 1 (REFUTE): 3b540, commit f2a53df9f\n"
        other_item = "# /validate-pr round 3 (REFUTE): 3b541, commit f2a53df9f\n"

        def led_by(lead: str) -> str:
            # The staged Claude shape with ``lead`` before its first section heading.
            return self.CLAUDE_SAMPLE.replace("\n## Scratch probes", "\n" + lead + "\n## Scratch probes", 1)

        def own_led_by(lead: str) -> str:
            # CLAUDE_DELIVERY with ``lead`` before its own round heading.
            return self.CLAUDE_DELIVERY.replace("\n" + self.ROUND_2_HEADING, "\n" + lead + self.ROUND_2_HEADING, 1)

        for clause, runs in (
                ("a level 3 to 6 heading before a quote stops it", [
                    (led_by(level + " Inputs\n" + round_1), stopped) for level in ("###", "######")]),
                ("a heading indented one to three spaces stops a quote", [
                    (led_by(indent + "## Inputs\n" + round_1), stopped) for indent in (" ", "   ")]),
                ("a line with no space or tab after its # is not a heading", [
                    (own_led_by("#2959 merged\n"), counted)]),
                ("a fenced ATX line is not a heading", [(own_led_by("```sh\n# comment\n```\n"), counted)]),
                ("a first round heading naming another item stops a quote", [
                    (led_by(other_item + round_1), stopped)]),
                ("a heading with a tab after its # stops a quote", [(led_by("##\tInputs\n" + round_1), stopped)]),
                ("a bare # run stops a quote", [(led_by(run + "\n" + round_1), stopped) for run in ("#", "##")]),
                ("a line indented four spaces is not a heading", [(own_led_by("    # Inputs\n"), counted)]),
                ("a line with seven # is not a heading", [(own_led_by("####### Inputs\n"), counted)])):
            with self.subTest(clause=clause):
                for delivery, want in runs:
                    self.delivery.write_text(delivery, encoding="utf-8")
                    self.assertEqual(mod.delivery_report(hook, self.LEDGER, self.delivery, with_row=False), want)
        # 3b578 r4 (the round-4 clause table): the stated residue, a first-heading quote the delivery still takes,
        # holds after a setext, HTML, block-quoted or list-item heading, none of which stops it (R1 to R4).
        quoted = head + ("1 ledger row(s) lead with its review key (key from the delivery; ledger as read, nothing "
                         "written); WARNING fewer rows than reported findings (a combined row counts once) "
                         "(report only)")
        for residue, lead in (("setext", "Inputs\n======\n"), ("HTML", "<h2>Inputs</h2>\n"),
                              ("block-quoted", "> ## Inputs\n"), ("list-item", "- ## Inputs\n")):
            with self.subTest(residue=residue):
                self.delivery.write_text(led_by(lead + round_1), encoding="utf-8")
                self.assertEqual(mod.delivery_report(hook, self.LEDGER, self.delivery, with_row=False), quoted)

    def test_round_heading_names_only_its_leading_item(self) -> None:
        # 3b578 W1 (codex 3b544 post-merge WARN): the heading's whole remainder was searched for the item, so a
        # first heading of another item that mentions this one later gave its round, and a ledger row of that
        # round read as this delivery's coverage.
        mod, hook = self.tool("_ofr_delivery_leading_item")
        head = "delivery-findings: reported 0 ERROR, 0 WARN, 1 NOTE (1 in all); "
        one = self.CLAUDE_SAMPLE.replace("FINDINGS: 0 ERROR, 1 WARN, 1 NOTE", "FINDINGS: 0 ERROR, 0 WARN, 1 NOTE")

        def led_by(lead: str) -> str:
            # The staged Claude shape with one finding and ``lead`` as its first heading.
            return one.replace("\n## Scratch probes", "\n" + lead + "\n\n## Scratch probes", 1)

        # The reviewer's reproduction: a round-3 row for the item, which a round-3 key would count.
        ledger = self.LEDGER.replace("\n\n## Closed today", "\n| 2026-10-21 | note | [R3-N1] round 3 | claude 3b540 "
                                     "/validate-pr round 3 @ f2a53df9f |  |\n\n## Closed today", 1)
        other = "# /validate-pr round 3 (REFUTE): 3b541, commit f2a53df9f, previous item 3b540"
        own_2 = led_by(self.ROUND_2_HEADING).replace("\n## What I ran", "\n" + other + "\n\n## What I ran", 1)
        item_leads = other.replace("3b541", "3b540").replace("item 3b540", "item 3b541")
        stopped = "ledger rows UNVERIFIABLE (no-round-heading)"
        round_3 = ("1 ledger row(s) lead with its review key (key from the delivery; ledger as read, nothing written); "
                   "rows equal the reported total (coverage, not faithfulness)")
        round_2 = ("4 ledger row(s) lead with its review key (key from {}; ledger as read, nothing written); more rows "
                   "than reported findings")
        # 3b578 r2 (claude 3b578 round-1 W1): a heading with no item field gives no round but still counts toward
        # the ambiguity check, so a column-0 quote of round 1 before the delivery's own round-2 heading (S1), or a
        # later round-3 heading after it (S2), is ambiguous with or without a key, as before 3b578.
        bare_2 = "# /validate-pr round 2: 3b540, commit f2a53df9f"
        bare_3 = bare_2.replace("round 2", "round 3")
        s1 = led_by(self.ROUND_2_HEADING.replace("round 2", "round 1") + "\n\n" + bare_2)
        s2 = led_by(self.ROUND_2_HEADING).replace("\n## What I ran", "\n" + bare_3 + "\n\n## What I ran", 1)
        ambiguous = "ledger rows UNVERIFIABLE (round-heading-ambiguous)"
        # 3b578 r3 (claude 3b578 round-2 N1): the documented clauses no subtest pinned, one delivery shape each. A
        # heading with no item field names the item only as a whole token, so a later one holding 3b5400 (M3 a
        # substring match, M5 no lookahead) or v3b540 (M3, M4 no lookbehind) leaves the own round 2; one that leads
        # (a quote of round 1) still counts toward the ambiguity, so a round-1 key does not count (M13 the backstop
        # skipped for the first heading); and text before (REFUTE (M14), or an item field after a later ) than the
        # first (M15), gives no round.
        digit_after = s2.replace(bare_3, "# /validate-pr round 3: 3b5400, commit f2a53df9f", 1)
        letter_before = s2.replace(bare_3, "# /validate-pr round 3: v3b540, commit f2a53df9f", 1)
        quote_first = led_by(bare_2.replace("round 2", "round 1") + "\n\n" + self.ROUND_2_HEADING)
        text_before = led_by("# /validate-pr round 3 of 3b541 (REFUTE): 3b540, commit f2a53df9f")
        closed_late = led_by("# /validate-pr round 3 (REFUTE): 3b541, then (REFUTE): 3b540")
        for name, delivery, key, want in (
                ("another item leads, this one later", led_by(other), None, stopped),
                ("another item leads, this one later, with a correct key", led_by(other), self.REVIEW,
                 round_2.format("--source-key")),
                ("another item leads a later heading", own_2, None, round_2.format("the delivery")),
                ("no (REFUTE...): field", led_by("# /validate-pr round 3: 3b540, commit f2a53df9f"), None, stopped),
                ("a (REFUTE) field with no colon", led_by("# /validate-pr round 3 (REFUTE) 3b540, commit f2a53df9f"),
                 None, stopped),
                ("the item leads, another later", led_by(item_leads), None, round_3),
                ("the item leads a longer (REFUTE...):", led_by("# /validate-pr round 3 (REFUTE, re-run): 3b540"), None,
                 round_3),
                ("S1 a quoted round 1 first, its own round 2 with no item field", s1, None, ambiguous),
                ("S1 the same, with a correct key", s1, self.REVIEW, ambiguous),
                ("S2 its own round 2 first, a round 3 with no item field later", s2, None, ambiguous),
                ("S2 the same, with a correct key", s2, self.REVIEW, ambiguous),
                # 3b578 r2 (round-1 N2): a first heading with no item field gives no round, so a key of another
                # round supplies it instead of disagreeing (S3; source-key-disagrees before 3b578).
                ("S3 no item field first, a key of another round", led_by(bare_3), self.REVIEW,
                 round_2.format("--source-key")),
                ("a later heading with no item field holding 3b5400", digit_after, None,
                 round_2.format("the delivery")),
                ("a later heading with no item field holding v3b540", letter_before, None,
                 round_2.format("the delivery")),
                ("a quoted round 1 with no item field first, its own round 2 later, a round-1 key", quote_first,
                 self.REVIEW.replace("round 2", "round 1"), ambiguous),
                ("text before (REFUTE", text_before, None, stopped),
                ("the (REFUTE...) closed by its first )", closed_late, None, stopped)):
            with self.subTest(case=name):
                self.delivery.write_text(delivery, encoding="utf-8")
                got = mod.delivery_report(hook, ledger, self.delivery, with_row=False, source_key=key)
                self.assertEqual(got, head + want + " (report only)")
        # 3b578 r2 (round-1 N2): the forms 3b578 stopped reading as the item give no round alone (no-round-heading,
        # where 3b544 gave round 3), and after the delivery's own round-2 heading they count toward the ambiguity.
        for form, lead in (
                ("a lowercase (refute)", "# /validate-pr round 3 (refute): 3b540, commit f2a53df9f"),
                ("no comma after the item", "# /validate-pr round 3 (REFUTE): 3b540 commit f2a53df9f"),
                ("a backticked item", "# /validate-pr round 3 (REFUTE): `3b540`, commit f2a53df9f"),
                ("an empty field", "# /validate-pr round 3 (REFUTE): , 3b540, commit f2a53df9f"),
                ("a no-break space before the item", "# /validate-pr round 3 (REFUTE):\u00a03b540, commit f2a53df9f")):
            later = led_by(self.ROUND_2_HEADING).replace("\n## What I ran", "\n" + lead + "\n\n## What I ran", 1)
            for where, delivery, want in (("alone", led_by(lead), stopped),
                                          ("after its own round 2", later, ambiguous)):
                with self.subTest(form=form, where=where):
                    self.delivery.write_text(delivery, encoding="utf-8")
                    got = mod.delivery_report(hook, ledger, self.delivery, with_row=False)
                    self.assertEqual(got, head + want + " (report only)")
        # 3b578 r4 (claude 3b578 round-3 N1, then the round-4 clause table): subtests for the heading mutants that
        # table found surviving, in this loop and the next (its residue rows are in
        # test_first_heading_rule_parses_as_documented). That table did not reach every heading clause: the r5 block
        # below adds subtests for five mutants the round-4 reviews found surviving (the CR kept on heading lines only,
        # FE3, H8, ESC and UNI). Alone, a first heading gives no round with no space or tab before (REFUTE (X4), a )
        # inside its parentheses (X3), a space before the colon, an item field or heading of another case, an indent,
        # a lone CR or U+2028 before it, or a no-break space after the item; it gives its round with a tab or two
        # spaces before (REFUTE, no space after the colon (LS3), or spaces and tabs around the item.
        r3 = "# /validate-pr round 3"
        for name, lead, want in (
                ("X4 no space or tab before (REFUTE", r3 + "(REFUTE): 3b540, commit f2a53df9f", stopped),
                ("X3 a ) inside the (REFUTE parentheses", r3 + " (REFUTE (scoped)): 3b540, commit f2a53df9f", stopped),
                ("a space before the colon", r3 + " (REFUTE) : 3b540, commit f2a53df9f", stopped),
                ("an item field of another case", r3 + " (REFUTE): 3B540, commit f2a53df9f", stopped),
                ("a heading of another case", "# /Validate-PR Round 3 (REFUTE): 3b540, commit f2a53df9f", stopped),
                ("an indented heading", " " + r3 + " (REFUTE): 3b540, commit f2a53df9f", stopped),
                ("a lone CR before the heading", "Quoted:\r" + r3 + " (REFUTE): 3b540, commit f2a53df9f", stopped),
                ("U+2028 before the heading", "Quoted:\u2028" + r3 + " (REFUTE): 3b540, commit f2a53df9f", stopped),
                ("a no-break space after the item", r3 + " (REFUTE): 3b540\u00a0, commit f2a53df9f", stopped),
                ("a tab before (REFUTE", r3 + "\t(REFUTE): 3b540, commit f2a53df9f", round_3),
                ("two spaces before (REFUTE", r3 + "  (REFUTE): 3b540, commit f2a53df9f", round_3),
                ("no space after the colon", r3 + " (REFUTE):3b540, commit f2a53df9f", round_3),
                ("spaces and tabs around the item", r3 + " (REFUTE): \t3b540 \t, commit f2a53df9f", round_3)):
            with self.subTest(r4_alone=name):
                self.delivery.write_text(led_by(lead), encoding="utf-8")
                got = mod.delivery_report(hook, ledger, self.delivery, with_row=False)
                self.assertEqual(got, head + want + " (report only)")
        # After the delivery's own round 2, a later field that is another item with a ., _ or - inside names no item,
        # so the own round stands (T1 to T3); a field starting or ending with a - or holding a non-ASCII letter or digit
        # is no item field, so its later mention makes the rounds ambiguous (T4 to T7). A heading with no item field
        # holds the item as a whole token only with no letter of either case, digit, _ or - beside it (X1, X2), and a
        # . beside it does not stop that.
        own_round = round_2.format("the delivery")
        later = r3 + " (REFUTE): {}, previous item 3b540"
        for name, heading, want in (
                ("T1 another item with a .", later.format("3b541.2"), own_round),
                ("T2 another item with a _", later.format("3b541_2"), own_round),
                ("T3 another item with a -", later.format("3b541-2"), own_round),
                ("T4 a field starting with a -", later.format("-3b541"), ambiguous),
                ("T5 a field ending with a -", later.format("3b541-"), ambiguous),
                ("T6 a field with a non-ASCII letter", later.format("3b54\u00e91"), ambiguous),
                ("T7 a field with a full-width digit", later.format("3b54\uff11"), ambiguous),
                *((f"no item field holding {text}", f"{r3}: {text}, commit f2a53df9f", own_round)
                  for text in ("V3b540", "13b540", "x_3b540", "x-3b540", "3b540x", "3b540X", "3b540_x", "3b540-x")),
                *((f"no item field holding {text}", f"{r3}: {text}, commit f2a53df9f", ambiguous)
                  for text in ("x.3b540", "3b540.x"))):
            with self.subTest(r4_later=name):
                self.delivery.write_text(s2.replace(bare_3, heading, 1), encoding="utf-8")
                got = mod.delivery_report(hook, ledger, self.delivery, with_row=False)
                self.assertEqual(got, head + want + " (report only)")
        # 3b578 r5 (claude 3b578 round-4 W1 and N1, codex 3b578 round-4 ERROR): the shapes the round-4 reviews found
        # unpinned. Alone, a first heading gives its round when CRLF ends every line and the item field ends the
        # heading (the CR is dropped from heading lines too), and gives no round when a ; ends the item field where
        # the documents say a comma, or when the heading has no space, two spaces or a tab in place of any of its
        # three literal spaces.
        words = ("#", "/validate-pr", "round", "3 (REFUTE): 3b540, commit f2a53df9f")
        for name, delivery, want in (
                ("CRLF line ends, the item field ending the heading",
                 led_by(r3 + " (REFUTE): 3b540").replace("\n", "\r\n"), round_3),
                ("a ; ending the item field", led_by(r3 + " (REFUTE): 3b540; commit f2a53df9f"), stopped),
                *((f"the space after {words[n]} as {gap!r}",
                   led_by(" ".join(words[:n + 1]) + gap + " ".join(words[n + 1:])), stopped)
                  for n in range(3) for gap in ("", "  ", "\t"))):
            with self.subTest(r5_alone=name):
                self.delivery.write_bytes(delivery.encode("utf-8"))
                got = mod.delivery_report(hook, ledger, self.delivery, with_row=False)
                self.assertEqual(got, head + want + " (report only)")
        # After the delivery's own round 2: for the dotted item 3b540.2 (its own heading, VPR-COMPLETE line and one
        # ledger row), a later heading with no item field holding 3b540a2 does not hold the item, since a . in the
        # item is matched literally, so the own round counts that one row (the line round_3 also reads); one
        # holding 3b540.2 makes the rounds ambiguous. Only an ASCII letter or digit, _ or - beside the item stops a
        # whole token, so a later heading with no item field holding 3b540 beside a non-ASCII letter (U+00E9) makes
        # the rounds ambiguous.
        dotted_ledger = ledger.replace("\n\n## Closed today", "\n| 2026-10-21 | note | [D2-N1] a dotted item | claude "
                                       "3b540.2 /validate-pr round 2 @ f2a53df9f |  |\n\n## Closed today", 1)
        dotted = s2.replace(" 3b540,", " 3b540.2,", 1).replace("VPR-COMPLETE 3b540 ", "VPR-COMPLETE 3b540.2 ", 1)
        for name, delivery, rows, want in (
                ("the dotted item, a later heading holding 3b540a2", dotted.replace(bare_3, f"{r3}: 3b540a2", 1),
                 dotted_ledger, round_3),
                ("the dotted item, a later heading holding 3b540.2", dotted.replace(bare_3, f"{r3}: 3b540.2", 1),
                 dotted_ledger, ambiguous),
                ("a non-ASCII letter before the item", s2.replace(bare_3, f"{r3}: \u00e93b540, commit f2a53df9f", 1),
                 ledger, ambiguous),
                ("a non-ASCII letter after the item", s2.replace(bare_3, f"{r3}: 3b540\u00e9, commit f2a53df9f", 1),
                 ledger, ambiguous)):
            with self.subTest(r5_later=name):
                self.delivery.write_text(delivery, encoding="utf-8")
                got = mod.delivery_report(hook, rows, self.delivery, with_row=False)
                self.assertEqual(got, head + want + " (report only)")
        # 3b578 r6: the round number is a positive integer with no leading zero, so alone, a first heading with round
        # 03 (H9) or round 0 gives no round.
        for name in ("round 03", "round 0"):
            with self.subTest(r6_alone=name):
                self.delivery.write_text(led_by(f"# /validate-pr {name} (REFUTE): 3b540, commit f2a53df9f"),
                                         encoding="utf-8")
                got = mod.delivery_report(hook, ledger, self.delivery, with_row=False)
                self.assertEqual(got, head + stopped + " (report only)")
        import ast
        doc = ast.get_docstring(ast.parse(OpenFindingsRowTests.TOOL.read_text(encoding="utf-8")))
        section = " ".join(doc.split("DELIVERY FINDINGS (report only, 3b544).", 1)[1]
                           .split("\n\nENVIRONMENT (exit 2).", 1)[0].split())
        # 3b578 r2 (round-1 N3): the rule as the code applies it and the narrowings it leaves, in one wording in the
        # docstring and the reference (backticks aside); the looser round-1 sentence is gone.
        rules = (
            "A heading's item field is read exactly so (3b578): after the round number, one or more spaces or tabs, "
            "then (REFUTE in uppercase, closed by its first ), which a : must follow; then the text up to the first "
            "comma or the line end, spaces and tabs stripped, which must be one item token (ASCII letters, digits, "
            "., _ or -, starting and ending with a letter or digit, as in VPR-COMPLETE).",
            "A heading whose item field is another item names no item, even when it mentions the item later.",
            "A heading with no item field (for example (refute), text before (REFUTE, a ) inside its parentheses, no "
            "colon after them, or a field that is empty, backticked, or holds a space or a no-break space) gives no "
            "round, but it names the item when it holds it as a whole token (not next to an ASCII letter or digit, _ "
            "or -), so it still counts toward round-heading-ambiguous",
            "item field narrows two checks (3b578): a heading whose item field is another item never counts toward "
            "round-heading-ambiguous, even when it mentions the item later, and a heading with no item field gives "
            "no round, so with --source-key it cannot disagree with the key's round and only counts toward "
            "round-heading-ambiguous",
            # 3b578 r6: the round number's shape (H9).
            "The round number <n> is a positive integer in ASCII digits with no leading zero, so a heading with "
            "round 0 or round 03 is not a round heading.")
        for name, text in (("tool docstring", section), ("reference", self.delivery_bullet())):
            plain = text.replace("`", "")
            for n, rule in enumerate(rules, start=1):
                with self.subTest(rule=name, sentence=n):
                    self.assertIn(rule, plain)
            with self.subTest(rule=name, sentence="the round-1 sentence gone"):
                self.assertNotIn("A heading names the item only by the field right after its", plain)


class ProvisionIndexTests(LinterTestCase):
    """tools/provision_citations.py, tools/build-provision-index.py and
    tools/audit-provision-siblings.py (advisory; P-TODO from the #2649 retro).

    Mutation map, one killing test per extractor branch: the subsection
    continuation by test_continuation_subsection_attaches, and its
    parent-preserving replacement rule by
    test_nested_subsection_continuation_keeps_parent;
    longest-alias-first by test_longest_alias_wins (both cases);
    prefix-over-postfix order by
    test_prefix_alias_wins_over_bracketed_postfix; the possessive prefix
    tail by test_possessive_prefix_alias_is_explicit and its colon by
    test_colon_prefix_tail_is_explicit; the conjoined-prefix chain by
    test_conjoined_prefix_aliases_cite_each_instrument (with the
    other-family drop) and its comma exclusion by
    test_comma_chain_does_not_extend_adjacency; the bracket-gloss
    downgrade by test_alias_led_bracket_gloss_downgrades; the explicit
    known-instrument rule by test_ambiguous_alias_unresolved_jurisdiction
    and test_agency_acronym_postfix_never_explicit; the
    jurisdiction-contradiction refusal by
    test_contradicted_jurisdiction_refuses_mention, the alias-span
    exclusion by test_jurisdiction_word_inside_alias_is_not_context, and
    the last-word rule and window bound by
    test_last_jurisdiction_word_wins_within_window; the postfix alias by
    test_postfix_alias, its bracket-close rule by
    test_postfix_bracket_alias_must_close and its jurisdiction window by
    test_postfix_alias_jurisdiction_from_full_line; range expansion and the
    unit guard by test_range_expansion_and_unit_guard,
    test_percent_and_hyphenated_unit_not_absorbed,
    test_duration_units_not_absorbed (the day unit and the decimal
    backtrack), test_unit_shorthand_and_magnitude_not_absorbed (the 24h
    shorthand and the magnitude words),
    test_thousands_separator_not_a_list, test_range_span_bound and
    test_lettered_endpoints_not_expanded; the branch-number fold by
    test_hyphenated_branch_article_not_split and
    test_inner_paragraph_marker_not_a_new_section; the year guard by
    test_year_not_absorbed_as_continuation; list separators by
    test_slash_list_expands and test_en_dash_range_expands; section letter
    suffixes by test_letter_suffix_sections_preserved, and digit-letter and
    roman subdivisions by test_digit_letter_subdivision_kept and
    test_inner_paragraph_marker_not_a_new_section; the CITE_RE lookbehind
    by test_marker_requires_word_boundary; the marker-family guard by
    test_marker_family_mismatch_refuses (all four cases); the line tier by
    test_line_tier, test_line_tier_requires_single_instrument and
    test_foreign_citation_poisons_line_inference; the heading / section /
    document tiers by their test_*_tier cases,
    test_heading_line_citation_uses_parent_heading,
    test_heading_line_citation_ignores_own_heading_instrument,
    test_conflicting_heading_and_body_context_refuses,
    test_heading_naming_two_instruments_refuses and
    test_document_title_naming_two_instruments_refuses; the
    heading-over-body precedence by test_heading_beats_earlier_body_mention;
    the inference refusals by test_foreign_prefix_refuses_inference,
    test_law_word_with_number_refuses_inference,
    test_law_word_eu_qualifier_refuses_inference,
    test_year_prefix_does_not_refuse_inference,
    test_acronym_year_statute_refuses_inference,
    test_comma_after_foreign_identifier_refuses (its second,
    bare-identifier case; the first is doubly refused and documents the
    corpus shape),
    test_of_that_instrument_refuses_inference,
    test_of_such_instrument_refuses_inference,
    test_of_other_instrument_refuses_inference,
    test_trailing_instrument_word_refuses_inference,
    test_trailing_directive_word_refuses_inference and
    test_anaphoric_reference_refuses_inference (with
    test_whose_reference_refuses_inference for the ``whose`` alternative);
    the explicit-only Section/§ rule by test_internal_section_refs_ignored;
    parse_key's explicit-only rule by
    test_parse_key_requires_explicit_adjacency; the jurisdiction resolution
    by test_ambiguous_alias_*; the adjectival-compound guard by
    test_adjectival_compound_is_not_a_mention (both cases); the phrase
    channel by the test_phrase_* cases (the after-alias fallback by
    test_phrase_needs_the_instrument_context's last case),
    test_phrase_not_matched_on_heading_line,
    test_phrase_context_excludes_section_body and its suppression flag by
    test_unresolved_citation_does_not_suppress_phrase; the unique_rows
    tier term by test_unique_rows_keeps_distinct_tiers; EXCLUDED_FILES by
    test_excluded_generated_artefacts_not_scanned; the explicit/candidate
    split in the tools by the test_build_* and test_siblings_* fixture
    cases, and the audit tool's both-sides-trusted rule by
    test_siblings_own_heading_citation_is_trusted (the own-side heading
    trust, and the sibling side held to --min-tier),
    test_siblings_own_line_or_section_citation_keeps_candidates (the
    own-side line and section distrust, and the own_trusted gate) and
    test_siblings_own_phrase_only_citation_stays_unverified.

    Round 4 (each killing test was run against its mutant in memory): the
    decimal-range endpoint, its interior list and zero padding by
    test_abbreviated_decimal_range_endpoint, the doubtful-endpoint rule and
    its continuation by test_doubtful_decimal_range_endpoint_unresolved, the
    endpoint pinpoints by test_range_endpoints_keep_cited_pinpoints; the
    prefix branch's tail refusal and each of its three alternatives by
    test_prefix_alias_refused_when_tail_names_another_instrument; the
    subordinate-instrument refusal by
    test_postfix_alias_of_subordinate_instrument_refused; the conjoined
    known-instrument rule by test_conjoined_unknown_member_dropped (the
    round-3 map credited it to two tests that kill only the adjacent-alias
    checks), and SHARED_NUMBERING, the numbering test and the explicit-only
    member filter by test_conjoined_prefix_aliases_cite_each_instrument; the
    gloss check's bracket-close bound by
    test_bracket_gloss_check_stops_at_bracket_close and the gloss lead's
    exclusion from the inferred tiers by
    test_alias_led_bracket_gloss_downgrades; the prefix tail's comma by
    test_comma_prefix_tail_is_explicit; the body-name skip by
    test_body_name_is_not_a_citation; the postfix claim by
    test_postfix_claimed_alias_not_reused_by_line_tier (and its
    postfix-only scope) and test_point_designation_does_not_defeat_postfix;
    the point designation in the postfix lead and in the "of <Name>" refusal
    by test_point_designation_does_not_defeat_postfix; the month words by
    test_day_of_month_not_absorbed; the quantity adjective and the widened
    shorthand list by test_unit_after_quantity_adjective_not_absorbed;
    parse_key's canonical-name branch and its family check by
    test_parse_key_accepts_printed_keys, test_build_accepts_printed_key and
    test_every_printed_corpus_key_round_trips; the sorted unresolved bucket
    by test_build_unresolved_listing_is_sorted.

    Round 5 (each killing test was run against its mutant in memory): the
    contiguity filter on range interiors and the unresolved-interior skip
    by test_range_interior_only_for_contiguous_numbering; restoring a
    decimal range's interior (the round-4 interior list and its zero
    padding, now removed), flagged as interior or not, by
    test_abbreviated_decimal_range_endpoint; a misspelt canonical name in
    CONTIGUOUS_NUMBERING or SELF_NOUNS by
    test_numbering_and_self_noun_tables_name_known_instruments; the
    structural qualifier in the tail lead, its possessive match, the
    SELF_NOUNS exemption, its title-continuation guard and the Code of
    Conduct lookahead by
    test_structural_or_self_noun_tail_keeps_prefix_alias; the lowercase
    subordinate descriptors, their lowercase intervening words, the
    clause-word stop and the verb stop by
    test_lowercase_subordinate_instrument_refused; the bound-postfix
    conflict refusal and its same-instrument exception by
    test_bound_postfix_alias_conflicting_heading_refuses; the body-name
    trim, its whole-body keep and the Data Protection spelling by
    test_body_name_drops_only_its_29; the point designation in the
    "of this <Word>" refusal by test_point_designation_before_of_this_refuses
    and the branch fold's certainty by test_branch_fold_keeps_endpoint_doubt
    (the two round-5 survivors); parse_key's bare-key rule by
    test_parse_key_canonical_branch_needs_bare_key.
    """

    BUILD = "tools/build-provision-index.py"
    SIBLINGS = "tools/audit-provision-siblings.py"
    CANDIDATE_LABEL = "unverified candidates (inferred instrument)"

    @classmethod
    def setUpClass(cls) -> None:
        # provision_citations defines dataclasses, which need their module in sys.modules, so it is
        # imported by name (tools/ is on sys.path) rather than through load_linter_module.
        import importlib
        if str(REPO_ROOT / "tools") not in sys.path:
            sys.path.insert(0, str(REPO_ROOT / "tools"))
        cls.pc = importlib.import_module("provision_citations")

    def scan(self, text: str, rel: str = "x.md") -> list:
        return [(c.key, c.pinpoint, c.tier) for c in self.pc.scan_text(rel, text)]

    def test_explicit_prefix_keys_at_section_level(self) -> None:
        self.assertEqual(self.scan("PIPEDA s. 10.1(3)"), [("PIPEDA s. 10.1", "10.1(3)", "explicit")])

    def test_continuation_subsection_attaches(self) -> None:
        got = self.scan("under PIPEDA (s. 10.1(2) and (6)), and promptly")
        self.assertEqual([p for _k, p, _t in got], ["10.1(2)", "10.1(6)"])
        self.assertEqual(set(k for k, _p, _t in got), set(("PIPEDA s. 10.1",)))

    def test_nested_subsection_continuation_keeps_parent(self) -> None:
        # Kills reverting the bare-continuation rule to append-to-section: "Article
        # 53(1)(a) and (b)" means 53(1)(b), not 53(b) (ai/framework-ai-model-
        # documentation-and-transparency.md:132; privacy/template-dpa-article-28.md:25).
        got = self.scan("EU AI Act Article 53(1)(a) and (b)")
        self.assertEqual([p for _k, p, _t in got], ["53(1)(a)", "53(1)(b)"])
        got = self.scan("Article 28(3)(a) to (h) of the GDPR")
        self.assertEqual([p for _k, p, _t in got], ["28(3)(a)", "28(3)(h)"])

    def test_longest_alias_wins(self) -> None:
        self.assertEqual(self.scan("UK GDPR Art. 33(1)")[0][0], "UK GDPR Art. 33")
        # Kills removing the longest-first sort in ALIAS_RE: "NIS 2" would match first and
        # leave "Directive" to refuse the inference.
        self.assertEqual(self.scan("NIS 2 Directive Article 4")[0][0], "NIS2 Art. 4")

    def test_postfix_alias(self) -> None:
        self.assertEqual(self.scan("Article 33 of the GDPR")[0][:2], ("GDPR Art. 33", "33"))

    def test_possessive_prefix_alias_is_explicit(self) -> None:
        # Kills removing "(?:'s)?" from _PREFIX_TAIL_RE (the documented "the GDPR's
        # Article" shape would fall back to the line tier).
        self.assertEqual(self.scan("the GDPR's Article 33 duty"),
                         [("GDPR Art. 33", "33", "explicit")])

    def test_range_expansion_and_unit_guard(self) -> None:
        self.assertEqual([k for k, _p, _t in self.scan("GDPR Arts. 33 to 35")],
                         ["GDPR Art. 33", "GDPR Art. 34", "GDPR Art. 35"])
        self.assertEqual(self.scan("GDPR Arts. 25 to 39")[8], ("GDPR Art. 33", "25 to 39", "explicit"))
        self.assertEqual(len(self.scan("GDPR Art. 33 and 72 hours")), 1)

    def test_duration_units_not_absorbed(self) -> None:
        # Kills removing "days?|" from _UNIT, and kills letting _NUM backtrack out of a
        # decimal so the unit guard passes on ".5 days" ("and 1.5 days" gained a false
        # Art. 1; the guard now rejects the decimal tail too).
        self.assertEqual(self.scan("GDPR Art. 33 and 7 days"), [("GDPR Art. 33", "33", "explicit")])
        self.assertEqual(self.scan("GDPR Art. 33 and 1.5 days"), [("GDPR Art. 33", "33", "explicit")])

    def test_line_tier(self) -> None:
        self.assertEqual(self.scan("| **GDPR (EU)** | unless no risk (Art. 33(1)) |")[0][2], "line")

    def test_heading_tier(self) -> None:
        text = "## Operational requirements (PIPEDA)\n\n- **Breach (s. 10.1):** report.\n"
        self.assertEqual(self.scan(text), [("PIPEDA s. 10.1", "10.1", "heading")])

    def test_heading_line_citation_uses_parent_heading(self) -> None:
        text = "# MiCA Implementation Annex\n\n## Title II offers (Arts 4-5)\n"
        self.assertEqual(self.scan(text)[0], ("MiCA Art. 4", "4", "heading"))

    def test_heading_beats_earlier_body_mention(self) -> None:
        text = "## Bill C-36 (PPCDA)\n\nUntil enacted, PIPEDA governs.\n\n- Duties (s. 7).\n"
        self.assertEqual(self.scan(text)[0][0], "PPCDA s. 7")

    def test_section_tier(self) -> None:
        text = "## Breach\n\nThe GDPR applies.\n\nArticle 33 governs.\n"
        self.assertEqual(self.scan(text)[0], ("GDPR Art. 33", "33", "section"))

    def test_document_tier(self) -> None:
        text = "**Document Title:** DPA Template (GDPR Article 28)\\\n\n## Terms\n\nArticle 33 help.\n"
        self.assertEqual(self.scan(text)[1], ("GDPR Art. 33", "33", "document"))

    def test_heading_naming_two_instruments_refuses(self) -> None:
        # Kills replacing the heading _single(...) with the last alias: a heading naming
        # two instruments governs nothing (docstring: "names exactly one instrument").
        self.assertEqual(self.scan("## GDPR and PIPEDA duties\n\n- Erasure duty (s. 7).\n"),
                         [(None, "7", "unresolved")])

    def test_document_title_naming_two_instruments_refuses(self) -> None:
        # Kills replacing the Document Title _single(...) with the last alias.
        text = ("**Document Title:** GDPR to PIPEDA Breach Crosswalk\\\n\n## Terms\n\n"
                "Notify without delay (s. 33).\n")
        self.assertEqual(self.scan(text), [(None, "33", "unresolved")])

    def test_foreign_prefix_refuses_inference(self) -> None:
        text = "## Under PIPEDA\n\nSee [Ley Art 33.3], CCR s. 7001 and Article 5 of this Law.\n"
        self.assertEqual(set(t for _k, _p, t in self.scan(text)), set(("unresolved",)))

    def test_year_and_domain_acronym_do_not_refuse_inference(self) -> None:
        text = "# MiCA Implementation Annex\n\nIn force on 29 June 2023 (Art 149(1)); an EMI (Art 48(1)).\n"
        self.assertEqual([k for k, _p, _t in self.scan(text)], ["MiCA Art. 149", "MiCA Art. 48"])

    def test_internal_section_refs_ignored(self) -> None:
        self.assertEqual(self.scan("## PIPEDA\n\nSee Section 4.2 and §6.3.\n"), [])

    def test_fenced_code_ignored(self) -> None:
        self.assertEqual(self.scan("## PIPEDA\n\n```\nPIPEDA s. 10.1\n```\n"), [])

    def test_ambiguous_alias_prose_jurisdiction(self) -> None:
        self.assertEqual(self.scan("Singapore PDPA s. 26D(2)")[0][0], "PDPA (Singapore) s. 26D")

    def test_ambiguous_alias_path_jurisdiction(self) -> None:
        rel = "privacy/jurisdictions/annex-privacy-thailand.md"
        self.assertEqual(self.scan("PDPA s. 26D", rel)[0][0], "PDPA (Thailand) s. 26D")

    def test_ambiguous_alias_unresolved_jurisdiction(self) -> None:
        # Kills removing _known from the explicit prefix and postfix branches: an
        # ambiguous alias whose jurisdiction never resolves is not a known instrument
        # (round-3 QA: "the section 1798.155 CPPA administrative fine" is the
        # California AGENCY, and its explicit record collided with Canadian Bill C-27
        # rows under the shared "CPPA (jurisdiction unresolved)" key), so adjacency
        # to it is unresolved, never explicit — while a line-tier mention still
        # surfaces the "(jurisdiction unresolved)" key as an unverified candidate.
        self.assertEqual(self.scan("PDPA s. 26D"), [(None, "26D", "unresolved")])
        self.assertEqual(self.scan("| PDPA | porting duty (s. 26D) |"),
                         [("PDPA (jurisdiction unresolved) s. 26D", "26D", "line")])

    def test_adjectival_compound_is_not_a_mention(self) -> None:
        got = self.scan("the LFPDPPP has no GDPR-style basis (Articles 21 to 22)")
        self.assertEqual([k for k, _p, _t in got], ["LFPDPPP Art. 21", "LFPDPPP Art. 22"])
        # Kills narrowing the compound guard back to a lowercase letter after the hyphen
        # (privacy/template-joint-controller-arrangement.md:25, "GDPR-Article-26-style").
        got = self.scan("the LGPD has no GDPR-Article-26-style duty: Article 5 defines the controller")
        self.assertEqual(got, [("LGPD Art. 5", "5", "line")])

    def test_marker_family_mismatch_refuses(self) -> None:
        # Kills removing the marker-family guard: an Art-marker citation resolving to an
        # s.-style instrument is the wrong instrument's ("CCPA Article 10" is 11 CCR
        # Article 10, not Cal. Civ. Code s. 10; the round-2 QA found this family at the
        # explicit, line, heading and section tiers), so it is refused at every tier.
        self.assertEqual(self.scan("CCPA Article 10 requires a risk assessment"),
                         [(None, "10", "unresolved")])
        self.assertEqual(self.scan("| CCPA | ADMT pre-use notice (Art 11) |"),
                         [(None, "11", "unresolved")])
        self.assertEqual(self.scan("## CPRA\n\n- Risk assessments (Article 10).\n"),
                         [(None, "10", "unresolved")])
        # A family match is untouched.
        self.assertEqual(self.scan("CCPA s. 1798.100")[0],
                         ("Cal. Civ. Code s. 1798.100", "1798.100", "explicit"))

    def test_inner_paragraph_marker_not_a_new_section(self) -> None:
        # privacy/template-joint-controller-arrangement.md:163: "Article 42 s.1(II)" is
        # LGPD Art. 42 with a paragraph designation, not a second LGPD section; the
        # s.-marker resolution to an Art.-style instrument is refused, and the roman
        # subdivision "(II)" is kept in the pinpoint.
        self.assertEqual(self.scan("LGPD Art. 42 s.1(II) makes controllers jointly liable"),
                         [("LGPD Art. 42", "42", "explicit"), (None, "1(II)", "unresolved")])

    def test_hyphenated_branch_article_not_split(self) -> None:
        # Kills reverting the branch-number fold: "Art 24-2" is one branch-numbered
        # article (privacy/jurisdictions/annex-privacy-south-korea.md:48/:54 emitted a
        # spurious Art. 2), and "s. 6-1-1306" is one Colorado section, not three.
        self.assertEqual(self.scan("South Korea PIPA Art 24-2(1) governs resident registration numbers"),
                         [("PIPA (South Korea) Art. 24-2", "24-2(1)", "explicit")])
        self.assertEqual(self.scan("cure periods (s. 6-1-1306) apply"),
                         [(None, "6-1-1306", "unresolved")])
        # An ascending hyphen pair is still a range.
        self.assertEqual([k for k, _p, _t in self.scan("GDPR Arts. 33-35")],
                         ["GDPR Art. 33", "GDPR Art. 34", "GDPR Art. 35"])

    def test_digit_letter_subdivision_kept(self) -> None:
        # Kills reverting _SUB's digit-letter branch: "(6a)" was dropped from the
        # pinpoint (ai/jurisdictions/annex-ai-european-union.md:114, "Article 99(6a)").
        self.assertEqual(self.scan("EU AI Act Article 99(6a)")[0],
                         ("EU AI Act Art. 99", "99(6a)", "explicit"))

    def test_phrase_candidate_on_uncited_line(self) -> None:
        got = self.scan("| PIPEDA | breach notification (real risk of significant harm) |")
        self.assertEqual(got, [("PIPEDA s. 10.1", "(uncited)", "phrase")])

    def test_phrase_suppressed_on_cited_line(self) -> None:
        got = self.scan("| PIPEDA | real risk of significant harm (PIPEDA s. 10.1(1)) |")
        self.assertEqual(got, [("PIPEDA s. 10.1", "10.1(1)", "explicit")])

    def test_unresolved_citation_does_not_suppress_phrase(self) -> None:
        # Kills forcing resolved_here to True: only a RESOLVED citation suppresses the
        # phrase channel; a refused one on the same line must not.
        got = self.scan("| PIPEDA | notify on a real risk of significant harm (Ley Art 33) |")
        self.assertEqual(got, [(None, "33", "unresolved"),
                               ("PIPEDA s. 10.1", "(uncited)", "phrase")])

    def test_phrase_needs_the_instrument_context(self) -> None:
        self.assertEqual(self.scan("| PPCDA | a real risk of significant harm |"), [])
        self.assertEqual(self.scan("## Breach\n\nA real risk of significant harm.\n"), [])
        self.assertEqual(self.scan("## Canada (PIPEDA)\n\nA real risk of significant harm.\n"),
                         [("PIPEDA s. 10.1", "(uncited)", "phrase")])
        # Kills disabling the first-alias-after-the-phrase fallback (round-3 QA: no
        # test reached it; the phrase here starts the line, so only "after" can name
        # the instrument).
        self.assertEqual(self.scan("A real risk of significant harm triggers PIPEDA reporting."),
                         [("PIPEDA s. 10.1", "(uncited)", "phrase")])

    def test_parse_key(self) -> None:
        self.assertEqual(self.pc.parse_key("PIPEDA s.10.1(3)"), "PIPEDA s. 10.1")
        self.assertEqual(self.pc.parse_key("GDPR art 33"), None)
        self.assertEqual(self.pc.parse_key("GDPR Art 33"), "GDPR Art. 33")
        self.assertIsNone(self.pc.parse_key("Article 12(5)"))

    def test_parse_key_requires_explicit_adjacency(self) -> None:
        # Kills parse_key accepting any tier: "GDPR duties: Art. 33" resolves only at
        # the line tier, and a typed --key must name its instrument adjacently.
        self.assertIsNone(self.pc.parse_key("GDPR duties: Art. 33"))

    def test_marker_requires_word_boundary(self) -> None:
        # Kills removing the CITE_RE lookbehind: the "s." inside "regulators." would
        # start a citation ("regulators. 33" gained a record).
        self.assertEqual(self.scan("GDPR notices go to regulators. 33 controllers responded"), [])

    def test_year_not_absorbed_as_continuation(self) -> None:
        # Kills removing _NOT_YEAR from CITE_RE ("2018" would read as a section).
        self.assertEqual(self.scan("GDPR Arts. 33 and 2018"), [("GDPR Art. 33", "33", "explicit")])

    def test_range_span_bound(self) -> None:
        # Kills removing the MAX_RANGE_SPAN cap: only the endpoints of a too-wide range index.
        self.assertEqual(len(self.scan("GDPR Arts. 1 to 99")), 2)

    def test_lettered_endpoints_not_expanded(self) -> None:
        # Kills replacing expand_body's isdigit() guards with True (int("22A") would raise).
        got = self.scan("UK GDPR Arts. 22A-22D")
        self.assertEqual([k for k, _p, _t in got], ["UK GDPR Art. 22A", "UK GDPR Art. 22D"])

    def test_letter_suffix_sections_preserved(self) -> None:
        # Kills reverting _NUM's letter suffixes: LGPD Art. 55-A is not Art. 55
        # (privacy/jurisdictions/annex-privacy-brazil.md:29), and Art. 4a is not Art. 4
        # (privacy/jurisdictions/annex-privacy-european-union.md:38).
        self.assertEqual(self.scan("LGPD Article 55-A")[0][0], "LGPD Art. 55-A")
        self.assertEqual(self.scan("Article 4a of the GDPR")[0][:2], ("GDPR Art. 4a", "4a"))

    def test_slash_list_expands(self) -> None:
        # Kills removing "/" from _SEP (compliance/financial-services/
        # annex-financial-services-sector-requirements.md:77 lost SOX s. 404).
        self.assertEqual([k for k, _p, _t in self.scan("Sarbanes-Oxley Act Section 302/404")],
                         ["SOX s. 302", "SOX s. 404"])

    def test_en_dash_range_expands(self) -> None:
        # Kills removing the en-dash from _SEP and _BODY_TOKEN_RE's range token.
        self.assertEqual([k for k, _p, _t in self.scan("GDPR Arts. 44–49")],
                         ["GDPR Art. %d" % n for n in range(44, 50)])

    def test_percent_and_hyphenated_unit_not_absorbed(self) -> None:
        # Kills reverting _UNIT's boundary: "\b" never matched after "%", and a
        # hyphenated duration ("72-hour") was absorbed as a section.
        self.assertEqual(len(self.scan("GDPR Art. 33 and 20% of revenue")), 1)
        self.assertEqual(len(self.scan("GDPR Art. 33 and 72-hour notice")), 1)

    def test_prefix_alias_wins_over_bracketed_postfix(self) -> None:
        # Kills restoring postfix-before-prefix resolution order.
        self.assertEqual(self.scan("GDPR Art. 33 (UK GDPR)")[0][0], "GDPR Art. 33")

    def test_postfix_bracket_alias_must_close(self) -> None:
        # Kills removing _POSTFIX_CLOSE_RE: in "section 3.9 (MiCA Article 35(1))" the bracket
        # opens a SEPARATE citation, and the internal "section 3.9" keyed to MiCA as explicit
        # (crypto/standard-crypto-asset-reserve-and-prudential-requirements.md:73).
        got = self.scan("calculated per the fixed-overheads method of section 3.9 (MiCA Article 35(1)).")
        self.assertEqual(got, [("MiCA Art. 35", "35(1)", "explicit")])
        # Kills removing the bracket lead itself (the shape at privacy/
        # annex-privacy-jurisdiction-index.md:120; a jurisdiction word supplies the
        # context, since an unresolved-jurisdiction alias no longer keys an explicit
        # record).
        self.assertEqual(self.scan("UAE Cabinet decision under Art 26 (PDPL)")[0],
                         ("PDPL (UAE) Art. 26", "26", "explicit"))

    def test_postfix_alias_jurisdiction_from_full_line(self) -> None:
        # Kills resolving a postfix alias against the post-citation substring only, which
        # discarded the jurisdiction words before the citation. (An s.-family marker:
        # Singapore's PDPA is an s.-style statute, so an Article marker would be refused
        # by the marker-family guard before reaching this branch.)
        self.assertEqual(self.scan("Singapore: section 26 of the PDPA")[0][0], "PDPA (Singapore) s. 26")

    def test_line_tier_requires_single_instrument(self) -> None:
        # Kills reverting the line tier to the last earlier alias: a row naming two
        # instruments is refused, not keyed to the second one (governance/
        # register-document-index-and-classification.md:160 and the "GDPR / UK GDPR" rows).
        self.assertEqual(self.scan("| GDPR / UK GDPR | processor terms (Article 28) |"),
                         [(None, "28", "unresolved")])
        self.assertEqual(self.scan("EU GDPR Art 5/6 (UK GDPR: no Art 88 equivalent)"),
                         [("GDPR Art. 5", "5", "explicit"), ("GDPR Art. 6", "6", "explicit"),
                          (None, "88", "unresolved")])

    def test_law_word_with_number_refuses_inference(self) -> None:
        # Kills dropping the optional number after a law word in _FOREIGN_PREFIX_RE
        # (privacy/jurisdictions/annex-privacy-vietnam.md:69: "Decree 356 Art. 20" is not PDPL).
        got = self.scan("- **Updating (PDPL Art. 22; Decree 356 Art. 20):**",
                        "privacy/jurisdictions/annex-privacy-vietnam.md")
        self.assertEqual(got, [("PDPL (Vietnam) Art. 22", "22", "explicit"),
                               (None, "20", "unresolved")])

    def test_year_prefix_does_not_refuse_inference(self) -> None:
        # Kills removing the letter/slash lookahead from _FOREIGN_PREFIX_RE's identifier
        # branch (a bare year before the marker is not a foreign identifier).
        self.assertEqual(self.scan("## PIPEDA\n\nIn 2018 s. 5 was amended.\n"),
                         [("PIPEDA s. 5", "5", "heading")])

    def test_acronym_year_statute_refuses_inference(self) -> None:
        # Kills dropping the optional year from the acronym branch: "DUAA 2025 s.80"
        # cites an unaliased statute, and the bare year before the marker slipped past
        # the identifier branch (privacy/register-automated-decision-making.md:130
        # became UK GDPR Art. 80).
        self.assertEqual(self.scan("## PIPEDA\n\nDUAA 2025 s.80 sets the new erasure duty.\n"),
                         [(None, "80", "unresolved")])

    def test_comma_after_foreign_identifier_refuses(self) -> None:
        # "Regulation (EU) 2025/1140, Article 4" names the delegated regulation, and
        # the comma bypassed the whitespace-only refusal (crypto/
        # standard-digital-asset-custody.md:41 became MiCA Art. 4 from an earlier
        # MiCA mention). That corpus shape is ALSO refused by the law-word branch
        # ("Regulation (EU) 2025/1140" through the comma tail), so it kills nothing
        # alone (round-3 QA); the bare-identifier case ("125(I)/2018, Article 15",
        # no law word) is what kills dropping the comma-identifier branch.
        got = self.scan("MiCA custody rules; Commission Delegated Regulation (EU) 2025/1140, "
                        "Article 4 applies.")
        self.assertEqual(got, [(None, "4", "unresolved")])
        self.assertEqual(self.scan("under GDPR standards; 125(I)/2018, Article 15 applies"),
                         [(None, "15", "unresolved")])

    def test_of_that_instrument_refuses_inference(self) -> None:
        # Kills narrowing _OF_THIS_RE back to "this" (crypto/standard-crypto-asset-reserve-
        # and-prudential-requirements.md:73: "Article 36 of that Regulation" is the CRR).
        got = self.scan("MiCA Article 35(1) applies the deductions pursuant to Article 36 of that Regulation.")
        self.assertEqual(got, [("MiCA Art. 35", "35(1)", "explicit"), (None, "36", "unresolved")])

    def test_of_such_instrument_refuses_inference(self) -> None:
        # Kills narrowing _OF_THIS_RE to "this|that": "of such/said <Word>" also names
        # another instrument.
        got = self.scan("GDPR Article 6 permits it; Article 12 of said Regulation sets fees")
        self.assertEqual(got, [("GDPR Art. 6", "6", "explicit"), (None, "12", "unresolved")])

    def test_of_other_instrument_refuses_inference(self) -> None:
        # Kills removing the _OF_OTHER_RE refusal ("of the Charter" names the
        # instrument). The heading must be an Art.-family instrument: under an
        # s.-style one (## PIPEDA) the marker-family guard refuses "Article 5"
        # anyway and masks the mutation (round-3 QA).
        self.assertEqual(self.scan("## GDPR\n\nArticle 5 of the Charter applies.\n"),
                         [(None, "5", "unresolved")])

    def test_trailing_instrument_word_refuses_inference(self) -> None:
        # Kills removing _POST_INSTRUMENT_RE (governance/register-canonical-citations.md:140:
        # "Article 29(7) Regulation (EU) 2018/1725" is not the GDPR named earlier).
        got = self.scan("SCCs under Article 28(7) GDPR and Article 29(7) Regulation (EU) 2018/1725")
        self.assertEqual(got, [("GDPR Art. 28", "28(7)", "explicit"), (None, "29(7)", "unresolved")])

    def test_trailing_directive_word_refuses_inference(self) -> None:
        # Kills narrowing _POST_INSTRUMENT_RE to "Regulation": "Article 5 Directive
        # 2013/40/EU" names its instrument after the citation too.
        got = self.scan("NIS2 Article 21 mandates measures; Article 5 Directive 2013/40/EU differs")
        self.assertEqual(got, [("NIS2 Art. 21", "21", "explicit"), (None, "5", "unresolved")])

    def test_anaphoric_reference_refuses_inference(self) -> None:
        # Kills removing _ANAPHOR_RE (crypto/...:73 "of its Articles 46 and 48" is the CRR;
        # ai/jurisdictions/annex-ai-us-california.md:25 "whose Article 11" is 11 CCR).
        got = self.scan("MiCA Article 35(1); the CRR applies without the threshold exemptions "
                        "of its Articles 46 and 48.")
        self.assertEqual(got, [("MiCA Art. 35", "35(1)", "explicit"),
                               (None, "46", "unresolved"), (None, "48", "unresolved")])

    def test_whose_reference_refuses_inference(self) -> None:
        # Kills narrowing _ANAPHOR_RE to "its": the docstring's own "whose Article 11"
        # shape must also refuse.
        got = self.scan("The GDPR aligns; the eIDAS Regulation, whose Article 16 sets QTSP duties, differs.")
        self.assertEqual(got, [(None, "16", "unresolved")])

    def test_foreign_citation_poisons_line_inference(self) -> None:
        # Kills removing the poisoned flag (privacy/template-dsar-workflow.md:87: bare
        # "(s. 7026(f))" is an 11 CCR section, not the CCPA / CPRA named earlier on the row).
        got = self.scan("| CCPA / CPRA | 45 days (11 CCR s. 7021), while an opt-out of sale "
                        "(s. 7026(f)) runs shorter |")
        self.assertEqual(got, [(None, "7021", "unresolved"), (None, "7026(f)", "unresolved")])

    def test_conflicting_heading_and_body_context_refuses(self) -> None:
        # Kills reverting _context to innermost-body-before-outer-heading (privacy/
        # template-dpa-article-28.md:27: a bare "Article 28(9)" under a GDPR document
        # heading read as PIPEDA s. 28 from a body mention).
        text = ("# Data Processing Agreement Template (GDPR Article 28)\n\n## Purpose\n\n"
                "It also accommodates PIPEDA equally.\n\nIt must be in writing (Article 28(9)).\n")
        self.assertEqual(self.scan(text)[-1], (None, "28(9)", "unresolved"))
        text = ("# Data Processing Agreement Template (GDPR Article 28)\n\n## Purpose\n\n"
                "It implements the GDPR contract duty.\n\nIt must be in writing (Article 28(9)).\n")
        self.assertEqual(self.scan(text)[-1], ("GDPR Art. 28", "28(9)", "heading"))

    def test_heading_line_citation_ignores_own_heading_instrument(self) -> None:
        # Kills passing the full stack (instead of the parents) for a heading-line citation.
        text = "# PIPEDA Annex\n\n## Breach duties (s. 10.1) and PPCDA alignment\n"
        self.assertEqual(self.scan(text), [("PIPEDA s. 10.1", "10.1", "heading")])

    def test_phrase_not_matched_on_heading_line(self) -> None:
        # Kills removing the not-heading guard on the phrase channel.
        self.assertEqual(self.scan("## Canada (PIPEDA)\n\n### A real risk of significant harm\n"), [])

    def test_phrase_context_excludes_section_body(self) -> None:
        # Kills removing body=False from the phrase-channel context lookup.
        self.assertEqual(self.scan("## Breach\n\nPIPEDA applies.\n\nA real risk of significant harm.\n"), [])

    def test_conjoined_prefix_aliases_cite_each_instrument(self) -> None:
        # Kills removing the _CONJ_RE chain walk (round-3 QA: "GDPR / UK GDPR
        # Article 21" keyed only to UK GDPR, so the GDPR key missed the surface
        # entirely; privacy/template-employee-monitoring-notice.md:110 and
        # supply-chain/register-subprocessor-template.md:31).
        self.assertEqual(self.scan("GDPR / UK GDPR Article 21(4)"),
                         [("GDPR Art. 21", "21(4)", "explicit"),
                          ("UK GDPR Art. 21", "21(4)", "explicit")])
        self.assertEqual([k for k, _p, _t in self.scan("Under GDPR and UK GDPR Article 28, terms apply")],
                         ["GDPR Art. 28", "UK GDPR Art. 28"])
        # Kills widening the family drop to the whole chain (a conjoined member of
        # the OTHER marker family is an enumeration entry, not a co-citation, and
        # must not refuse the adjacent alias's record).
        self.assertEqual(self.scan("SOX and GDPR Articles 5(2) and 24 set accountability"),
                         [("GDPR Art. 5", "5(2)", "explicit"), ("GDPR Art. 24", "24", "explicit")])
        # Round-4 QA (gemini): the chain indexed the citation under EVERY conjoined
        # instrument, explicitly, whether or not the prose meant it. Only a member
        # sharing the adjacent alias's article numbering (SHARED_NUMBERING: GDPR and
        # UK GDPR, above) is explicit; any other member is an inference, keyed at
        # the line tier ("the LGPD and GDPR Article 20" is GDPR portability, not
        # LGPD Art. 20). Kills treating every member as explicit (this case) and
        # kills emptying SHARED_NUMBERING (the first case drops GDPR to the line
        # tier).
        self.assertEqual(self.scan("the LGPD and GDPR Article 20 portability right"),
                         [("LGPD Art. 20", "20", "line"), ("GDPR Art. 20", "20", "explicit")])
        # Kills dropping the explicit-only filter on conjoined members: a Section
        # marker keeps only its explicit records, so the line-tier member goes.
        self.assertEqual(self.scan("Alberta PIPA and BC PIPA section 5 duties"),
                         [("BC PIPA s. 5", "5", "explicit")])

    def test_comma_chain_does_not_extend_adjacency(self) -> None:
        # Kills adding a comma to _CONJ_RE: "UK GDPR, LGPD Art 37" enumerates
        # frameworks (governance/register-document-index-and-classification.md:151),
        # and chaining it would misattribute LGPD's article to UK GDPR.
        self.assertEqual(self.scan("GDPR Art 30, UK GDPR, LGPD Art 37 apply"),
                         [("GDPR Art. 30", "30", "explicit"), ("LGPD Art. 37", "37", "explicit")])

    def test_alias_led_bracket_gloss_downgrades(self) -> None:
        # Kills removing the gloss check on a bracket-lead prefix (round-3 QA:
        # compliance/financial-services/annex-mica-implementation.md:122, where
        # "DORA (Art 68(7), citing DORA Arts 11-12)" made MiCA's Art 68(7) an
        # EXPLICIT DORA record; the re-named alias inside the bracket shows the
        # lead is a gloss, so the citation falls to the line tier — an unverified
        # candidate — while the inner "DORA Arts 11-12" stays explicit).
        # Round-4 QA (gemini): the downgraded citation then fell to the LINE tier,
        # whose nearest earlier alias is the same DORA lead, so it was still keyed
        # DORA Art. 68. The lead is now excluded from the inferred tiers too: in a
        # bare row the citation is unresolved, and under the MiCA annex's own
        # heading it resolves to MiCA. Kills removing the gloss check (first case
        # explicit DORA) and kills not excluding the lead (both cases line DORA).
        got = self.scan("| ICT continuity per DORA (Art 68(7), citing DORA Arts 11-12) | annex |")
        self.assertEqual(got, [(None, "68(7)", "unresolved"),
                               ("DORA Art. 11", "11", "explicit"),
                               ("DORA Art. 12", "12", "explicit")])
        text = ("# MiCA Implementation Annex\n\n"
                "| ICT continuity per DORA (Art 68(7), citing DORA Arts 11-12) | annex |\n")
        self.assertEqual(self.scan(text)[0], ("MiCA Art. 68", "68(7)", "heading"))
        # A bracket-lead prefix whose bracket re-names nothing stays explicit.
        self.assertEqual(self.scan("under PIPEDA (s. 10.1(2) and (6)), and promptly")[0][2], "explicit")

    def test_agency_acronym_postfix_never_explicit(self) -> None:
        # Round-3 QA corpus regression (privacy/annex-privacy-jurisdiction-index.md:107):
        # "the section 1798.155 CPPA administrative fine" read the California agency
        # as an instrument and keyed an explicit "CPPA (jurisdiction unresolved)"
        # record. The Section marker is explicit-only, so the refused citation is
        # dropped, not misattributed; a jurisdiction word still resolves the alias.
        self.assertEqual(self.scan("escalating the section 1798.155 CPPA administrative fine tier",
                                   "privacy/annex-privacy-jurisdiction-index.md"), [])
        self.assertEqual(self.scan("Canada's CPPA Section 63(3) sets administrative penalties"),
                         [("CPPA (Canada) s. 63", "63(3)", "explicit")])

    def test_contradicted_jurisdiction_refuses_mention(self) -> None:
        # Kills reverting resolve_alias to "an unmapped jurisdiction falls through
        # to the next candidate": near "California" (or on a California path), CPPA
        # is the state agency, not Canada's Bill C-27, so the MENTION names no
        # instrument at all — the section-body and line contexts it would otherwise
        # seed stay empty and the bare citations refuse (an ADJACENT contradicted
        # alias is already refused by the explicit known-instrument rule;
        # ai/jurisdictions/annex-ai-us-california.md, round-3 QA).
        text = ("## Enforcement\n\nThe California CPPA enforces the rules.\n\n"
                "Penalties (s. 7150) apply.\n")
        self.assertEqual(self.scan(text), [(None, "7150", "unresolved")])
        self.assertEqual(self.scan("| CPPA | fines (s. 7150) |",
                                   "ai/jurisdictions/annex-ai-us-california.md"),
                         [(None, "7150", "unresolved")])

    def test_jurisdiction_word_inside_alias_is_not_context(self) -> None:
        # Kills removing the alias-span exclusion in resolve_alias: the "EU" of
        # "EU GDPR" describes GDPR, not a later ambiguous alias, so it neither
        # resolves nor contradicts it (privacy/register-automated-decision-making.md:25
        # mentions CPPA within the window of "EU GDPR").
        text = "## Breach\n\nUnder the EU GDPR and the CPPA, breach duties apply.\n\nReports (s. 63(3)) follow.\n"
        self.assertEqual(self.scan(text), [("CPPA (jurisdiction unresolved) s. 63", "63(3)", "section")])

    def test_last_jurisdiction_word_wins_within_window(self) -> None:
        # Kills replacing words[-1] with words[0] in resolve_alias (the NEAREST
        # jurisdiction word governs) and kills unbounding JURISDICTION_WINDOW (a
        # jurisdiction word further back than the window is not context, so the
        # unresolved-jurisdiction alias refuses the explicit record).
        self.assertEqual(self.scan("transfers from Singapore may rely on Thailand PDPA s. 26")[0][0],
                         "PDPA (Thailand) s. 26")
        padding = "the transfer impact assessment framework in this annex covers onward transfers generally"
        self.assertEqual(self.scan("Singapore " + padding + " PDPA s. 26D"),
                         [(None, "26D", "unresolved")])

    def test_colon_prefix_tail_is_explicit(self) -> None:
        # Kills removing the ":" from _PREFIX_TAIL_RE (round-3 QA: no test reached
        # it; "GDPR: Article 33" would silently fall to the line tier).
        self.assertEqual(self.scan("GDPR: Article 33 notice duty"),
                         [("GDPR Art. 33", "33", "explicit")])

    def test_law_word_eu_qualifier_refuses_inference(self) -> None:
        # Kills dropping the "(EU)"-style qualifier from _FOREIGN_PREFIX_RE's
        # law-word branch (round-3 QA: no test reached it; with a slashless number
        # neither the identifier nor the comma branch fires, so without the
        # qualifier the citation would fall to the line tier as GDPR).
        self.assertEqual(self.scan("GDPR applies; Regulation (EU) 1024 Article 4 differs"),
                         [(None, "4", "unresolved")])

    def test_unit_shorthand_and_magnitude_not_absorbed(self) -> None:
        # Kills removing _NOT_SHORTHAND ("and 24h" gained Art. 24h) and kills
        # dropping the magnitude words from _UNIT ("and 20 million" gained Art. 20);
        # both latent shapes from the round-3 QA, no corpus hit today.
        self.assertEqual(self.scan("GDPR Art. 33 and 24h"), [("GDPR Art. 33", "33", "explicit")])
        self.assertEqual(self.scan("GDPR Art. 33 and 72 h"), [("GDPR Art. 33", "33", "explicit")])
        self.assertEqual(self.scan("GDPR Art. 83 and 20 million euro"),
                         [("GDPR Art. 83", "83", "explicit")])

    def test_thousands_separator_not_a_list(self) -> None:
        # Kills removing _NOT_THOUSANDS ("and 1,000 users" gained Art. 1 and
        # Art. 000; round-3 QA latent shape). A spaced list is untouched.
        self.assertEqual(self.scan("GDPR Art. 6 and 1,000 users"), [("GDPR Art. 6", "6", "explicit")])
        self.assertEqual([k for k, _p, _t in self.scan("GDPR Arts. 33, 34")],
                         ["GDPR Art. 33", "GDPR Art. 34"])

    def test_unique_rows_keeps_distinct_tiers(self) -> None:
        # Kills dropping c.tier from the unique_rows identity (round-3 QA: no test
        # reached it): the same pinpoint on one line can resolve at two tiers, and
        # the trusted/candidate split must see both rows.
        rows = self.pc.unique_rows(self.pc.scan_text("x.md", "GDPR Art. 33; notify (Art. 33)"))
        self.assertEqual([c.tier for c in rows], ["explicit", "line"])

    def test_excluded_generated_artefacts_not_scanned(self) -> None:
        # Kills removing entries from EXCLUDED_FILES (round-3 QA: no test reached
        # it): generated artefacts derive from sources already in scope, so a hit
        # there is not a sibling. The names are spelled here, not read from the
        # constant, so shrinking the constant cannot shrink the check.
        paths = [self.pc.display_path(f) for f in self.pc.corpus_files(["docs"])]
        self.assertTrue(any(p.startswith("docs/") for p in paths))
        for excluded in ("docs/portal.md", "docs/maturity-scorecard.md",
                         "docs/reference-acquisition-manifest.md"):
            self.assertTrue((self.pc.REPO_ROOT / excluded).is_file())
            self.assertNotIn(excluded, paths)

    def test_abbreviated_decimal_range_endpoint(self) -> None:
        # Round-4 QA (claude 1, codex 1): compliance/healthcare/annex-healthcare-sector-
        # requirements.md:237, "HIPAA §164.400 to 414", keyed a false EXPLICIT
        # "HIPAA (45 CFR) s. 414". Kills reverting expand_body's decimal-range branch
        # (the endpoint keeps its shorthand form). Round-5 QA (claude F1): the interior
        # it then listed (164.401 ... 164.413) keyed seven sections 45 CFR does not have
        # (Part 164 Subpart D numbers only the even ones), so a range from a decimal
        # section indexes its endpoints only. Kills restoring the interior list,
        # flagged as interior (the PIPEDA case: PIPEDA is in CONTIGUOUS_NUMBERING) or
        # not (the HIPAA cases).
        self.assertEqual(self.scan("HIPAA §164.400 to 414"),
                         [("HIPAA (45 CFR) s. 164.400", "164.400", "explicit"),
                          ("HIPAA (45 CFR) s. 164.414", "164.414", "explicit")])
        self.assertEqual([k for k, _p, _t in self.scan("HIPAA §§ 160.001 to 003")],
                         ["HIPAA (45 CFR) s. 160.001", "HIPAA (45 CFR) s. 160.003"])
        # A whole-section endpoint (it ascends from s. 10 within MAX_RANGE_SPAN and
        # lacks the start's sub-number width) stays whole, and a same-section
        # decimal endpoint is kept as written; neither range lists an interior.
        self.assertEqual([k for k, _p, _t in self.scan("PIPEDA ss. 10.1 to 12")],
                         ["PIPEDA s. 10.1", "PIPEDA s. 12"])
        self.assertEqual([k for k, _p, _t in self.scan("PIPEDA ss. 10.1 to 10.3")],
                         ["PIPEDA s. 10.1", "PIPEDA s. 10.3"])

    def test_doubtful_decimal_range_endpoint_unresolved(self) -> None:
        # Kills resolving a doubtful endpoint either way (the "abbreviated ==
        # whole_end" test in _decimal_end): "ss. 3.1 to 5" is s. 3.5 or s. 5, and
        # "ss. 10.5 to 3" is neither, so the endpoint is recorded unresolved, never
        # keyed, while the start stays explicit; a bare continuation of a doubtful
        # endpoint inherits the doubt.
        self.assertEqual(self.scan("PIPEDA ss. 3.1 to 5"),
                         [("PIPEDA s. 3.1", "3.1", "explicit"), (None, "5", "unresolved")])
        self.assertEqual(self.scan("PIPEDA ss. 10.5 to 3"),
                         [("PIPEDA s. 10.5", "10.5", "explicit"), (None, "3", "unresolved")])
        self.assertEqual(self.scan("PIPEDA ss. 3.1 to 5(1) and (2)"),
                         [("PIPEDA s. 3.1", "3.1", "explicit"), (None, "5(1)", "unresolved"),
                          (None, "5(2)", "unresolved")])

    def test_range_endpoints_keep_cited_pinpoints(self) -> None:
        # Round-4 QA (gemini) read the endpoints' pinpoints as dropped range context.
        # That is by design (docstring rule 1): an endpoint is cited directly, with
        # its own subdivisions; only the interior sections, which the text never
        # names, carry the range. Kills giving the endpoints the range pinpoint.
        got = self.scan("GDPR Arts. 25 to 39(2)")
        self.assertEqual((got[0], got[1], got[-1]),
                         (("GDPR Art. 25", "25", "explicit"), ("GDPR Art. 26", "25 to 39", "explicit"),
                          ("GDPR Art. 39", "39(2)", "explicit")))

    def test_prefix_alias_refused_when_tail_names_another_instrument(self) -> None:
        # Round-4 QA (claude 2): the explicit prefix branch returned before looking at
        # what FOLLOWS the citation, so "Unlike the GDPR, Article 12 of the Data Act"
        # keyed GDPR Art. 12 explicitly. Kills dropping other_tail from the prefix
        # branch, and each of its three alternatives ("of the <Name>", "of that
        # <Word>", a trailing instrument word). A tail naming an alias resolves the
        # citation to THAT instrument through the postfix branch.
        self.assertEqual(self.scan("Unlike the GDPR, Article 12 of the Data Act applies"),
                         [(None, "12", "unresolved")])
        self.assertEqual(self.scan("Unlike the GDPR, Article 12 of that Regulation applies"),
                         [(None, "12", "unresolved")])
        self.assertEqual(self.scan("GDPR, Article 12 Regulation (EU) 2023/2854"),
                         [(None, "12", "unresolved")])
        self.assertEqual(self.scan("as under the GDPR, Article 12 of PIPL requires"),
                         [("PIPL Art. 12", "12", "explicit")])

    def test_postfix_alias_of_subordinate_instrument_refused(self) -> None:
        # Round-4 QA (claude 2): a postfix alias that modifies a subordinate
        # instrument names THAT instrument ("Article 12 of the DORA RTS" is an RTS
        # article, not DORA Art. 12). Kills removing the _SUBORDINATE_RE refusal. The
        # section marker is explicit-only, so its refused citation is dropped. A
        # singular instrument word after the alias is the aliased instrument itself.
        self.assertEqual(self.scan("Article 12 of the DORA RTS"), [(None, "12", "unresolved")])
        self.assertEqual(self.scan("s. 7012 CCPA Regulations"), [(None, "7012", "unresolved")])
        self.assertEqual(self.scan("Article 4 of the NIS2 Implementing Regulation"),
                         [(None, "4", "unresolved")])
        self.assertEqual(self.scan("section 3 of the PIPEDA Breach of Security Safeguards Regulations"), [])
        self.assertEqual(self.scan("Article 21 of the NIS2 Directive"), [("NIS2 Art. 21", "21", "explicit")])
        self.assertEqual(self.scan("§164.308 of the HIPAA Security Rule"),
                         [("HIPAA (45 CFR) s. 164.308", "164.308", "explicit")])

    def test_conjoined_unknown_member_dropped(self) -> None:
        # Round-4 QA (claude 3a): kills dropping _known from the conjoined-member loop
        # (the mutant survived all round-3 tests): "AI Act / EU AI Act Art. 50" would
        # add an "AI Act (jurisdiction unresolved)" record, a key rule 4 reserves for
        # alias MENTIONS, never for an adjacency.
        self.assertEqual(self.scan("AI Act / EU AI Act Art. 50"),
                         [("EU AI Act Art. 50", "50", "explicit")])

    def test_bracket_gloss_check_stops_at_bracket_close(self) -> None:
        # Round-4 QA (claude 3b): kills widening the gloss check past the bracket
        # close (post[:close] -> post; the mutant survived). dev-security/
        # standard-security-baseline-and-standards-reference.md:198, one of the four
        # #2649 trusted siblings, names Quebec Law 25 AFTER the bracket closes, which
        # is not a gloss, so the PIPEDA records stay explicit.
        self.assertEqual(self.scan("under PIPEDA (s. 10.1(2) and (6)), and promptly under Quebec Law 25"),
                         [("PIPEDA s. 10.1", "10.1(2)", "explicit"),
                          ("PIPEDA s. 10.1", "10.1(6)", "explicit")])

    def test_comma_prefix_tail_is_explicit(self) -> None:
        # Round-4 QA (claude 3c): kills removing the "," from _PREFIX_TAIL_RE (the
        # mutant survived; the colon had a test, the comma none). The first case is
        # compliance/public-sector/annex-eidas-requirements.md:123, which the mutant
        # turns into an unresolved comma-identifier refusal; the second demotes to a
        # line-tier candidate.
        self.assertEqual(self.scan("| GDPR | Regulation (EU) 2016/679, Article 17 | erasure |"),
                         [("GDPR Art. 17", "17", "explicit")])
        self.assertEqual(self.scan("Under the LGPD, Article 18 grants access"),
                         [("LGPD Art. 18", "18", "explicit")])

    def test_body_name_is_not_a_citation(self) -> None:
        # Round-4 QA (claude): "Article 29 Working Party" names the EDPB's predecessor,
        # and was keyed GDPR Art. 29 at the section and line tiers (governance/
        # register-canonical-citations.md:385-394, privacy/
        # standard-pseudonymization-and-anonymization.md:150); next to an alias it
        # came out explicit. Kills removing the _BODY_NAME_RE skip.
        self.assertEqual(self.scan("GDPR Article 29 Working Party guidance applies"), [])
        self.assertEqual(self.scan("## GDPR\n\nThe Art. 29 WP opinion on anonymisation.\n"), [])
        self.assertEqual(self.scan("GDPR Article 29 binds the processor"),
                         [("GDPR Art. 29", "29", "explicit")])

    def test_postfix_claimed_alias_not_reused_by_line_tier(self) -> None:
        # Round-4 QA (claude): ai/jurisdictions/annex-ai-european-union.md:68 keyed the
        # AI Act's "Article 27(4)" as GDPR Art. 27 at the line tier because "Article 35
        # GDPR" came earlier on the prose line. A postfix alias binds to its own
        # citation, so the line tier skips it. Kills removing the claimed set, and
        # kills claiming PREFIX aliases too (the last case: a prefix alias still
        # seeds the line tier).
        self.assertEqual(self.scan("Where the DPIA under Article 35 GDPR already meets it, Article 27(4) applies."),
                         [("GDPR Art. 35", "35", "explicit"), (None, "27(4)", "unresolved")])
        self.assertEqual(self.scan("GDPR Art. 33 governs; notify (Art. 34)"),
                         [("GDPR Art. 33", "33", "explicit"), ("GDPR Art. 34", "34", "line")])

    def test_point_designation_does_not_defeat_postfix(self) -> None:
        # Round-4 QA (gemini): privacy/jurisdictions/annex-privacy-european-union.md:38,
        # "under Article 9(2), point (g), of the GDPR", fell to the line tier as EU AI
        # Act Art. 9 because the point designation broke the postfix lead. Kills
        # removing _POINT from _POSTFIX_LEAD_RE (first two cases; in the first, the
        # claimed GDPR alias also lets the second "Article 4a" resolve) and from
        # _OF_OTHER_RE (third: crypto/standard-crypto-asset-reserve-and-prudential-
        # requirements.md:39, "Article 2, point (9), of Regulation (EU) 2017/1131",
        # was MiCA Art. 2 at the line tier).
        self.assertEqual(self.scan("The EU AI Act's new Article 4a supplies a basis under Article 9(2), "
                                   "point (g), of the GDPR, within the limits Article 4a sets out"),
                         [("EU AI Act Art. 4a", "4a", "line"), ("GDPR Art. 9", "9(2)", "explicit"),
                          ("EU AI Act Art. 4a", "4a", "line")])
        self.assertEqual(self.scan("Article 6(1), first subparagraph, point (f), of the GDPR"),
                         [("GDPR Art. 6", "6(1)", "explicit")])
        self.assertEqual(self.scan("MiCA Article 36(11) applies; mark-to-model as defined in Article 2, "
                                   "point (9), of Regulation (EU) 2017/1131"),
                         [("MiCA Art. 36", "36(11)", "explicit"), (None, "2", "unresolved")])

