class DirectRunFixtureTests(unittest.TestCase):
    """A late-defined class for checking direct script discovery."""

    def test_test_module_exists(self):
        self.assertTrue((REPO_ROOT / "tests" / "test_linters.py").is_file())


class DirectRunTests(unittest.TestCase):
    @staticmethod
    def _is_main_guard(node):
        import ast
        return (isinstance(node, ast.If) and
                ast.dump(node.test) in {
                    ast.dump(ast.parse(expr, mode="eval").body)
                    for expr in ('__name__ == "__main__"', '"__main__" == __name__')
                })

    def test_late_class_runs_from_neutral_directory(self):
        with tempfile.TemporaryDirectory() as cwd:
            result = subprocess.run(
                [sys.executable, str(REPO_ROOT / "tests" / "test_linters.py"),
                 "DirectRunFixtureTests"],
                cwd=cwd, env={}, capture_output=True, text=True, timeout=60,
            )
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        count = re.search(r"\bRan ([1-9][0-9]*) tests?\b", result.stdout + result.stderr)
        self.assertIsNotNone(count, result.stdout + result.stderr)

    def test_direct_run_imports_repository_tests_package(self):
        with tempfile.TemporaryDirectory() as cwd:
            shadow = Path(cwd) / "site-packages"
            (shadow / "tests").mkdir(parents=True)
            (shadow / "tests" / "__init__.py").write_text("", encoding="utf-8")
            code = (
                "import sys\n"
                "from pathlib import Path\n"
                "root, shadow = map(Path, sys.argv[1:])\n"
                "sys.path = [str(root / 'tests'), str(shadow), *sys.path[1:]]\n"
                "import test_linters\n"
                "import tests\n"
                "print(tests.__file__)\n"
            )
            result = subprocess.run(
                [sys.executable, "-c", code, str(REPO_ROOT), str(shadow)],
                cwd=cwd, env={}, capture_output=True, text=True, timeout=60,
            )
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        self.assertEqual(Path(result.stdout.strip()).resolve(),
                         REPO_ROOT / "tests" / "__init__.py")

    def test_main_guard_is_last_top_level_statement(self):
        import ast
        tree = ast.parse((REPO_ROOT / "tests" / "test_linters.py").read_text(encoding="utf-8"))
        guards = [node for node in tree.body if self._is_main_guard(node)]
        self.assertEqual(len(guards), 1)
        self.assertIs(guards[0], tree.body[-1])

    def test_main_guard_recognizes_both_operand_orders(self):
        import ast
        for expression in ('__name__ == "__main__"', '"__main__" == __name__'):
            with self.subTest(expression=expression):
                self.assertTrue(self._is_main_guard(ast.parse(f"if {expression}: pass").body[0]))


class ModuleFixtureOwnershipTests(unittest.TestCase):
    """setUpModule and tearDownModule never delete fixtures they do not own (P-1.86 PR 1).

    Every fixture under tests/tmp belongs to the test instance that created it
    (a unique mkdtemp directory removed by addCleanup), and DirectRunTests
    launches this very module as a child process, so a module-level sweep of
    top-level *.md, or a removal of the retired fixed
    "synthetic-claude-rules-sync" name, could only ever delete another live
    instance's files. This test holds a sentinel in each formerly-swept
    location inside a private fixture root (a unique mkdtemp directory
    outside the repository, so two live instances of this test never share
    a directory and nothing is written under the real tests/tmp) while a
    child process imports the module, points its FIXTURE_DIR at that root,
    and calls setUpModule and (if present) tearDownModule, then asserts
    both sentinels survive unchanged. Restoring either sweep or the
    retired-name removal makes it fail."""

    SENTINEL_BODY = "# foreign fixture owned by a concurrent run; must survive\n"

    def _make_sentinel(self, directory: Path) -> Path:
        fd, name = tempfile.mkstemp(
            suffix=".md", prefix="ownership-sentinel-", dir=directory
        )
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(self.SENTINEL_BODY)
        return Path(name)

    def test_module_setup_and_teardown_leave_foreign_fixtures_alone(self) -> None:
        private_root = Path(tempfile.mkdtemp(prefix="ownership-root-"))
        self.addCleanup(shutil.rmtree, private_root, ignore_errors=True)
        top_sentinel = self._make_sentinel(private_root)
        retired_dir = private_root / "synthetic-claude-rules-sync"
        retired_dir.mkdir()
        retired_sentinel = self._make_sentinel(retired_dir)
        code = (
            "import sys\n"
            "from pathlib import Path\n"
            "sys.path.insert(0, str(Path(sys.argv[1]) / 'tests'))\n"
            "import test_linters\n"
            "test_linters.FIXTURE_DIR = Path(sys.argv[2])\n"
            "test_linters.setUpModule()\n"
            "getattr(test_linters, 'tearDownModule', lambda: None)()\n"
        )
        with tempfile.TemporaryDirectory() as cwd:
            result = subprocess.run(
                [sys.executable, "-c", code, str(REPO_ROOT), str(private_root)],
                cwd=cwd, env={}, capture_output=True, text=True, timeout=60,
            )
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        for sentinel in (top_sentinel, retired_sentinel):
            with self.subTest(sentinel=str(sentinel)):
                self.assertTrue(
                    sentinel.exists(),
                    f"module setup/teardown deleted a fixture it does not own: {sentinel}",
                )
                self.assertEqual(
                    sentinel.read_text(encoding="utf-8"), self.SENTINEL_BODY
                )


class MakeFixtureUniquenessTests(unittest.TestCase):
    """make_fixture isolates instances: the same basename from two
    LinterTestCase instances lands in two distinct unique directories, and
    cleaning one instance leaves the other's fixture intact (P-1.86 PR 1)."""

    def test_same_basename_from_two_instances_does_not_collide(self) -> None:
        class Probe(LinterTestCase):
            def test_placeholder(self) -> None:
                pass

        first = Probe("test_placeholder")
        second = Probe("test_placeholder")
        self.addCleanup(first.doCleanups)
        self.addCleanup(second.doCleanups)
        path_a = first.make_fixture("collision-probe.md", "first instance\n")
        path_b = second.make_fixture("collision-probe.md", "second instance\n")
        self.assertNotEqual(path_a, path_b)
        self.assertEqual(path_a.name, path_b.name)
        self.assertEqual(path_a.read_text(encoding="utf-8"), "first instance\n")
        self.assertEqual(path_b.read_text(encoding="utf-8"), "second instance\n")
        first.doCleanups()
        self.assertFalse(path_a.exists())
        self.assertTrue(path_b.exists())
        self.assertEqual(path_b.read_text(encoding="utf-8"), "second instance\n")


class ToolingBacklogRefsTests(LinterTestCase):
    """tools/lint-tooling-backlog-refs.py (the tooling backlog-reference gate)."""

    GATE = "tools/lint-tooling-backlog-refs.py"

    TODO_INDEX = (
        "# TODO\n\n## Priority 1\n\n"
        "| ID | Item | Tags |\n"
        "| --- | --- | --- |\n"
        "| 3.50 | Live fixture item | `[build]` |\n"
    )

    PRIVATE_MINIMAL = {"TODO-REFERENCE.md": "# reference detail\n"}

    def make_repo(self, tool_text: str, *, private: dict[str, str] | None = None,
                  hook_text: str = "", todo: str | None = None) -> Path:
        """A fixture repo root (TODO.md, tools/, .claude/hooks/) with an optional
        grc_library_private sibling next to it, matching the gate's --root layout."""
        base = Path(tempfile.mkdtemp(prefix="tbr-", dir=FIXTURE_DIR))
        self.addCleanup(shutil.rmtree, base, ignore_errors=True)
        root = base / "repo"
        (root / "tools").mkdir(parents=True)
        (root / ".claude" / "hooks").mkdir(parents=True)
        if todo is None:
            todo = self.TODO_INDEX
        if todo:
            (root / "TODO.md").write_text(todo, encoding="utf-8")
        (root / "tools" / "sample.py").write_text(tool_text, encoding="utf-8")
        if hook_text:
            (root / ".claude" / "hooks" / "sample-hook.py").write_text(
                hook_text, encoding="utf-8")
        if private is not None:
            priv = base / "grc_library_private"
            priv.mkdir()
            for name, content in private.items():
                (priv / name).write_text(content, encoding="utf-8")
        return root

    def check(self, root: Path, *flags: str) -> subprocess.CompletedProcess:
        return run_linter(self.GATE, "--root", root, *flags)

    def test_stale_todo_ref_flagged_when_private_reachable(self) -> None:
        root = self.make_repo(
            "# Shaped by the apply plan (TODO 3.99): see the sweep record.\n",
            private=self.PRIVATE_MINIMAL,
        )
        result = self.check(root)
        self.assertLinterFails(result, "3.99")

    def test_live_public_id_not_flagged(self) -> None:
        root = self.make_repo(
            "# Adopter degradation shape (TODO 3.50) stays open.\n",
            private=self.PRIVATE_MINIMAL,
        )
        result = self.check(root)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_live_private_heading_not_flagged(self) -> None:
        # A redirect stub held only as a heading in the private reference file
        # keeps its number live (the gate-90 pair's grammar).
        root = self.make_repo(
            "# Provenance (TODO 3.99) of the redirect stub.\n",
            private={"TODO-REFERENCE.md": "## Priority 1\n\n### 3.99 Redirect stub\n"},
        )
        result = self.check(root)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_wrapped_reference_detected(self) -> None:
        root = self.make_repo(
            "# The scan shape was set by (TODO\n"
            "# section 3.99) in the plan round.\n",
            private=self.PRIVATE_MINIMAL,
        )
        result = self.check(root)
        self.assertLinterFails(result, "TODO section 3.99")

    def test_quoted_and_backticked_literals_ignored(self) -> None:
        root = self.make_repo(
            'PROBE = "an example string holding TODO 3.99 for a self-test"\n'
            "# A doc mention of `TODO 3.99` stays illustrative.\n",
            private=self.PRIVATE_MINIMAL,
        )
        result = self.check(root)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_markdown_quoted_pointer_flagged(self) -> None:
        # r26 D-4: a double-quoted span in Markdown prose is quotation, not an
        # illustrative literal, so a quoted stale pointer in a scanned .md file
        # is checked; a backticked span there stays illustrative.
        root = self.make_repo("# A clean tool file.\n", private=self.PRIVATE_MINIMAL)
        (root / "tools" / "notes.md").write_text(
            'Provenance: "shaped by TODO 3.99" per the sweep record.\n'
            "An illustrative `TODO 3.98` span stays silent.\n",
            encoding="utf-8")
        result = self.check(root)
        self.assertLinterFails(result, "3.99")
        self.assertNotIn("3.98", result.stdout + result.stderr)

    def test_markdown_fenced_block_blanked_and_prose_after_fence_scanned(self) -> None:
        # r2 F1: a fence delimiter's backtick run (here mispaired by a stray
        # backtick inside the block) paired into the prose around the block,
        # hiding a pointer after the fence. Fenced blocks are blanked first
        # through the shared fence predicate, so the fence can never shift the
        # inline pairing, and a pointer inside the fence is code, not prose.
        root = self.make_repo("# A clean tool file.\n", private=self.PRIVATE_MINIMAL)
        (root / "tools" / "notes.md").write_text(
            "Intro prose for the fixture.\n\n"
            "```\n"
            "code with a stray ` backtick and TODO 3.98 inside\n"
            "```\n\n"
            "See `a` then TODO 3.99 then `b` in the sweep record.\n",
            encoding="utf-8")
        result = self.check(root)
        self.assertLinterFails(result, "3.99")
        self.assertNotIn("3.98", result.stdout + result.stderr)

    def test_pr_anchored_reference_passes(self) -> None:
        root = self.make_repo(
            "# Shaped by TODO 3.99 (closing PR #1312) in the sweep.\n",
            private=self.PRIVATE_MINIMAL,
        )
        result = self.check(root)
